window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["26851515"]={"book":{"id":26851515,"title":"细节","author":"[美]史蒂夫·马丁","translator":"苏西","publisher":"中信出版社","pubdate":"2016-7","isbn":"9787508660578","tags":["心理学","影响力","沟通","思维","行为","说服","个人管理","逻辑思维"],"memCount":38},"np":1,"pb":[47],"idx":[{"i":17633,"t":"如何在重新设定目标后干劲儿更足","l":"TF2-1","c":"马子喻","g":1,"p":1},{"i":13851,"t":"承诺和一致性原则","l":"TF2-2","c":"黑碳包","g":1,"p":1},{"i":13063,"t":"如何提升自己的个人影响力","l":"TF1-1","c":"邓小米Jocelyn","g":1,"p":1},{"i":12198,"t":"如何通过细节设计影响选择力","l":"TF1-1","c":"邓小米Jocelyn","g":1,"p":1},{"i":11960,"t":"如何在重拾目标后干劲儿更足？","l":"TF2-1","c":"马子喻","g":1,"p":1},{"i":11555,"t":"细节","l":"TF2-3","c":"NAP君","g":1,"p":1},{"i":11221,"t":"承诺和一致性原则","l":"TF2-2","c":"黑碳包","g":1,"p":1},{"i":9359,"t":"如何有效表达感激","l":"3-1","c":"武小茉","g":1,"p":1},{"i":7968,"t":"如何设定更容易长久落地的目标？","l":"TF2-1","c":"马子喻","g":1,"p":1},{"i":7202,"t":"轻松影响他人的细节","l":"TF2-2","c":"刘天宇","g":1,"p":1},{"i":6787,"t":"试一试两部法，让你的建议更容易接受","l":"TF2-1","c":"刘天宇","g":1,"p":1},{"i":6670,"t":"回应感谢的方式","l":"TF2-2","c":"小新","g":1,"p":1},{"i":6443,"t":"如何在重拾目标后干劲更足","l":"TF2-1","c":"马子喻","g":1,"p":1},{"i":6371,"t":"目标设的好，干劲儿会更足。","l":"TF2-1","c":"小新","g":1,"p":1},{"i":6031,"t":"为互助留余地","l":"TF1-2","c":"静儿","g":1,"p":1},{"i":6001,"t":"影响力的方法论","l":"TF3-1","c":"肖策遥","g":1,"p":1},{"i":5822,"t":"如何通过“社会认同原理”的方法，更好地影响他人","l":"TF2-1","c":"静儿","g":1,"p":1},{"i":5442,"t":"细节：如何轻松影响他人","l":"TF2-4","c":"肖策遥","g":1,"p":1},{"i":5365,"t":"从他人的错误中汲取教训","l":"TF1-2","c":"静儿","g":1,"p":1},{"i":5364,"t":"鲜明生动的细节","l":"TF1-1","c":"静儿","g":1,"p":1},{"i":5326,"t":"如何提升说服力","l":"TF3-1","c":"杨硕","g":1,"p":1},{"i":5041,"t":"如何劝服对方做出符合自己期望的行为","l":"TF3-2","c":"刘小惠","g":1,"p":1},{"i":4699,"t":"科学地设置目标","l":"TF1-2","c":"邱小猫","g":1,"p":1},{"i":4348,"t":"执行意向","l":"TF3-1","c":"Shirley雪莉","g":0,"p":1},{"i":4251,"t":"为互助留出余地","l":"TF1-2","c":"杨帅","g":1,"p":1},{"i":4229,"t":"让你的建议更受欢迎，试一试“增强版主动选择”法","l":"TF2-1","c":"刘天宇","g":0,"p":1},{"i":4201,"t":"如何劝说他人做出有效承诺","l":"TF1-1","c":"杨帅","g":1,"p":1},{"i":4081,"t":"承诺要行动，要公开","l":"TF1-2","c":"刘天宇","g":1,"p":1},{"i":3976,"t":"抓住TA心中的“非常态”，让语言更有说服力","l":"TF1-1","c":"刘天宇","g":1,"p":1},{"i":3909,"t":"运用“潜质打败现实”的策略，在先天弱势的情况下，取得成功。","l":"TF3-1","c":"抗抗","g":1,"p":1},{"i":3627,"t":"如何在帮助他人时，拔高定位，为互助留有余地。","l":"TF2-2","c":"徐雪艳","g":1,"p":1},{"i":3562,"t":"学习后，学习者能运用先发制人和精确细节2步，提高谈判掌控力","l":"TF3-2","c":"抗抗","g":1,"p":1},{"i":3429,"t":"如何在重拾目标后干劲儿更足","l":"TF2-1","c":"马子喻","g":1,"p":1},{"i":3286,"t":"《细节：如何轻松影响他人》为互助留有余地","l":"TF1-1","c":"孟君婷","g":1,"p":1},{"i":3198,"t":"如何提高说服他人改变某些行为的可行性","l":"TF2-3","c":"刘小惠","g":1,"p":1},{"i":3023,"t":"从容通过反面劝说他人","l":"TF2-1","c":"徐雪艳","g":1,"p":1},{"i":2911,"t":"关于口头承诺的约束力","l":"TF1-1","c":"帅气的叶叔叔","g":1,"p":1},{"i":2878,"t":"如何促进行动的落实","l":"TF1-1","c":"阿柒lsh","g":1,"p":1},{"i":2749,"t":"如何快速取得对方的支持和信任","l":"TF1-1","c":"刘小惠","g":1,"p":1},{"i":2522,"t":"如何让会议更高效？会前三步不能少","l":"TF3-1","c":"王任映","g":1,"p":1},{"i":2521,"t":"如何送出一份完美礼物？","l":"TF2-4","c":"王任映","g":1,"p":1},{"i":2067,"t":"巧用“未来绑定法”，有效说服别人","l":"TF3-1","c":"抗抗","g":1,"p":1},{"i":2065,"t":"把握神奇的细节，敦促对方履行承诺","l":"TF2-4","c":"抗抗","g":0,"p":1},{"i":2063,"t":"把握神奇的细节","l":"TF2-4","c":"抗抗","g":1,"p":1},{"i":1975,"t":"潜质的说服力","l":"TF3-1","c":"洋洋得意","g":1,"p":1},{"i":1972,"t":"峰终效应","l":"TF3-2","c":"洋洋得意","g":1,"p":1},{"i":1892,"t":"如何才能化干戈为玉帛","l":"TF3-1","c":"王小琦","g":1,"p":1}],"ms":[{"id":17633,"topic":"如何在重新设定目标后干劲儿更足","learn_goal":"","remark":"当你没达到目标，\n想重新开始之前的目标时，\n通过将单一具体的数字\n改成一个上下浮动的数字范围，\n可以更加有干劲儿的重新投入。\n你可能因为出租车司机主动的问候认可他的服务，\n你曾经因为附赠的漂亮赠品，\n买了一个根本没打算买的商品，\n这些都是被细节影响的结果，\n那如何做好更多的细节以及识别细节的陷阱的，\n这本书你一定不要错过。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"马子喻","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>【开场】\u003c/p>\u003cp>大家晚上好，我是马子喻，欢迎大家来到今天我的TF2-1的拆书分享，首先做一个自我介绍，我是一名从业11年的国际教育规划老师；同时我认为自己也是一名学生，因为热爱学习，所以加入了拆书帮；再有，我是一名传统文化爱好和推广人，欢迎有同样爱好的伙伴和我交流。\u003cbr>\u003cbr>在跟随我完成本次RIA现场学习后，学习者能够学会重拾目标后干劲儿更足，而不是在重拾目标后，在落地目标的过程中坚持还不如以前。\u003cbr>\u003cbr>【书籍介绍】\u003c/p>\u003cp>今天我要拆的片段来自这本书《细节：如何轻松影响他人》，\u003c/p>\u003cp>【F】这本《细节》作者是罗伯特·西奥迪尼、史蒂夫·马丁、诺厄·戈尔茨坦3个知名说服力与影响力的研究权威，书里讲了52个“四两拨千斤”改变细节的套路。\u003c/p>\u003cp>【A】这是一本令人惊奇、强大、具有深刻内涵的实用型人生工具书，完整且细致地揭示了失败和成功之间存在着的细节差别，它3个月内就达到了近10W册的销量，并获得英国皇家学会奖。\u003c/p>\u003cp>【B】 如果你曾经设立了小目标在执行的过程中中断，你重拾目标后仍然没有干劲儿，那这本书就从一个细小的细节改变可以让你在重拾目标后干劲儿更足。同时在职场沟通、员工激励、商业谈判、家庭教育等工作和生活领域对你产生持续且深远的超级影响力。\u003c/p>\u003cp>【分组】现在我们按座位每3个人一组\u003c/p>\u003cp>接下来请大家用2分钟时间阅读手中的片段，看完的小伙伴可以举手示意我。\u003c/p>","ratings_count":2,"texts":[{"id":21833,"quote":"\u003cp>【原文片段】\u003c/p>\u003cp>1919年，在《堪萨斯城星报》（Kansas City Star）画政治漫画的沃尔特·迪士尼（Walt Disney）被解雇了，报纸编辑的话是：“他不是太有创意。”\u003c/p>\u003cp>2012年，英国生物学家约翰·戈登爵士（Sir John Gurdon）因对生理学和药学的杰出贡献获得了诺贝尔奖。可当年他在伊顿公学的校长却在成绩单上这样写道：“我相信戈登想当个科学家，可照他现在的表现看，这想法颇为荒谬。”\u003c/p>\u003cp>好莱坞有个传说，弗雷德·阿斯泰尔（Fred Astaire）去雷电华影业（RKO Pictures）试镜时，一个制片经理把他刷了下来，理由是：“（他）不会表演，不会唱歌，有秃顶迹象，会跳一点儿舞。”\u003c/p>\u003cp>令人欣慰的是，这些早期的挫折都没能阻拦他们追求自己的目标。上述三人全部获得了惊人的成就。但有些时候，人们的确会分心，会忘记目标——不是未来的诺奖得主和好莱坞偶像心目中那种宏伟的、一辈子只有一次的、梦工厂式的目标，而是虽然小一点儿却依旧十分重要的、日常生活中的目标，比如多存一点儿钱，减掉几斤肉，还掉信用卡，或是达到这个月的销售目标。\u003c/p>\u003cp>人们往往需要重新拾起之前为自己设定的目标。同样，管理者、团队带头人、老师甚至是父母，有时候也需要帮助员工、学生和孩子鼓起干劲儿，再次为了原先的目标而努力。按常理，当我们为自己或他人设定新目标的时候，经验总是告诉我们，要把目标设定的非常具体。比如，每周减掉2磅（约1.8斤）体重，1小时跑6英里（约9.6公里），或是每个月存下100美元，作为来年的度假基金。但是，当我们说服自己或他人重拾目标的时候，这个常识是否正确呢？\u003c/p>\u003cp>营销学教授毛拉·斯科特（Maura Scott）和斯蒂芬·诺里斯（Stephen Nowlis）认为，虽然人们在直觉上感到，在首次制订目标时，应当把他量化为单一而具体的数字，但是，在重拾先前的目标时，这样做就未必最好了。相反，这两位学者认为，比起单一的具体数字[比如每周减掉3磅（约2.7斤）体重]，把目标改成一个上下浮动的数字范围[但平均值跟原先的数字一样，比如每周减掉2-4磅（约1.8~3.6斤）]，会更加有助于人们鼓起干劲儿，重新投入。\u003c/p>","explains":"\u003cp>好，大家都看好了，内容不多，且非常容易理解。我们都有那些虽然小一点却依旧十分重要的、日常生活中的目标。首次在设定目标的时候，经验总是告诉我们，把目标量化为一个具体的数字，但在目标执行落地的过程中，我们往往需要重拾目标，这种时候，想要重新投入后更加有干劲儿，要怎么办呢？\u003c/p>\u003cp>【第一步】保证平均值和原先一样，\u003c/p>\u003cp>【第二步】把目标改成一个上下浮动的数字范围，这样会有助于我们鼓起干劲儿，重新投入。\u003c/p>\u003cp>【不这么做的坏处】\u003c/p>\u003cp>如果不这么做的话，在我们执行这些虽然小但是很重要的目标的过程中，目标一旦中断，我们还按照以前的具体的数字重拾目标时，会越来越没有干劲儿，不但丢掉了这些虽然小但很重要的目标，而且还会产生负面情绪，影响自己的生活和工作。\u003c/p>\u003cp>【拆书家个人十里讲解】\u003c/p>\u003cp>这里分享一个自己的经历。半年前，我和一个伙伴约定好，每周跑步3次，坚持了快一个月的时间，这个习惯就彻底丢掉了。本着爱美和健康的目标，没过多久，我们再次约定好，重拾目标，重新开始行动，结果情境几乎和之前一模一样，坚持了还不到一个月就再次丧失了跑步的干劲儿，而且两个人甚至要开始自我怀疑，产生了负面情绪。\u003c/p>\u003cp>直到我遇到了这个拆页，在读了《细节》这本书的这个拆页以后，我和伙伴重拾之前的目标，第一步在平均值和之前的数字一样的前提下，保持平均值是每周3次，第二步，我们把目标改成一个上下浮动的数字范围，调整为每周2-4次的目标。就这样，我们重拾目标，每周跑步2次的这个小目标，很轻松的就达到了，每周跑步4次，在偶尔两个人工作都不太忙的阶段也能实现。不论是跑2次，3次还是4次，因为都属于在目标范围内，可以都算作是我们实现了当周的目标，我们比之前更加干劲十足的重新投入到了目标中。现如今，我们调整目标以后，已经执行了新的目标快两个月的时间，而且热情丝毫不减。\u003c/p>\u003cp>正如拆页的建议中所说，生活中这些虽然小但仍然十分重要的小目标，在重拾目标时，在平均值和原来的数字一致的情况下，把一个具体数字的目标调整为一个上下浮动的范围的目标，可以让我们更加有干劲儿。\u003c/p>","interaction":"\u003cp>【拆书家提问设计】：\u003c/p>\u003cp>【显像提问】：\u003c/p>\u003cp>下面请大家回忆一下，你有没有遇到这类似工作或生活的场景，例如：你曾经设立了每天背20个单词的目标、或者每天走1W步、每天写工作日志等，但是总是坚持了一段时间就中断了，内心明明知道这目标对自己有意义有帮助，可是你发现，中断后再重新开始，还是类似的情况，坚持了没几天就又没有了干劲儿？\u003c/p>\u003cp>请把曾经设定了具体的目标，但是执行过程中，重拾目标后来干劲不足这样的场景简单地写到便签上，1分钟时间，写好的请举手示意。好，现在开始 \u003c/p>\u003cp>【学习者案例记录】：\u003c/p>\u003cp>金莲：之前设定的目标是天天写日记，后来就陆续断掉了，日记就变成了周记，一直就这么陆续的没坚持下来，但是还是希望把这个目标重新捡起来。\u003c/p>\u003cp>【拆书家提问设计】：好，如果让你乘坐时光机，穿越回刚刚提到的A1重拾目标的场景，根据刚才拆页的建议，最好怎样设定刚刚大家写下的曾经的目标？1分钟的时间给大家书写，写好后给大家3分钟时间在小组内分享一下你们的案例。\u003c/p>\u003cp>（4分钟后）好，请一位伙伴分享。\u003c/p>\u003cp> 【学习者案例记录】：\u003cbr>\u003cbr>金莲：通过今天的学习，再把目标捡起来，把目标设定到之前的均值。我之前坚持的时候也就是一周两三篇，现在调整为1-4篇，这样只要在范围内就是完成目标，动力十足。今天就开始写起来。\u003c/p>\u003cp>感谢这位伙伴的分享，那生活中我们经常设立一些虽然小但很重要的目标，我们往往把这个目标设立为具体的数字，在重拾目标的时候，第一步保证平均值和原先一样，第二步我们把目标改成一个上下浮动的数字范围，这样会有助于我们鼓起干劲儿，重新投入。\u003c/p>\u003cp>今天我的TF2-1拆书分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1716283037000,"updated_at":1718961445000,"ria":true},{"id":13851,"topic":"承诺和一致性原则","learn_goal":"","remark":"你还在用摆事实讲道理的方式说服人吗？你还在用苦口婆心喋喋不休的方式影响人吗？其实你只需要做个小小的设计，就能轻松影响他人，让他们做出行为上的改变。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"黑碳包","city":"宁波市"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>各位小伙伴下午好！\u003c/p>\u003cp>我是包子，用三个标签介绍我自己。我是一名新手教练、是一名二级拆书家也是一枚终生学习践行者。\u003c/p>\u003cp>今天我带来的拆页出自西奥迪尼《细节》这本书中的“承诺和一致性”原则。\u003cbr> F：《细节》这本书的作者叫西奥迪尼，是世界最有名的说服力和影响力专家，他之前写过一本著名的书叫《影响力》，畅销全球30年，是《财富》杂志评选的75本必读书之一。这本《细节》是《影响力》的续篇，它主要从心理学、营销学角度，告诉你影响别人的“理论”。\u003c/p>\u003cp>A：它不讲干巴巴的理论，而是直接用52个套路，告诉你具体该怎么操作。有人开玩笑说，西奥迪尼的书，就是那种你只想自己读，生怕别人读的书。\u003c/p>\u003cp> B1：俗话说，细节决定成败！那些被我们忽略的细节，往往有着一锤定音的效果。这本《细节》中分享了一些细节影响他人决策的案例。\u003c/p>\u003cp> B2：如果你还在用摆事实讲道理的方式说服人或是用苦口婆心喋喋不休的方式影响人的话？相信通过本片段的学习，你会了解影响一个人只需要做个小小的设计，就能轻松地让他人做出行为上的改变。\u003c/p>","ratings_count":2,"texts":[{"id":17869,"quote":"\u003cp> 【学习目标】通过本拆页的分享，能让现场的小伙伴能运用“承诺和一致性”原则，给自己设定一个下一周需要达成的目标。\u003c/p>\u003cp> 社会影响的基本原理之一就是承诺和一致性之间的关系。这个原理说的是，咱们绝大多数人都有跟自己许下的承诺保持一致的强烈愿望，如果这个承诺是我们主动做出的、需要我们花力气参与而且被公之于众的，那就更是如此。\u003c/p>\u003cp>举个例子，研究者曾扮成海滩游客，把一条浴巾和一个收音机放在某个正在晒太阳的人身旁，然后下海去游泳。一种情况下，研究者会请那位晒太阳的人（其实是受试对象）帮忙照看一下收音机。绝大多数人都同意了，并且很友善地做出了口头承诺：“没问题。”第二种情况下，研究者没有请晒太阳的人照看物品就径直游泳去了。此时，真正的实验开始了。另一个研究人员假扮成顺手牵羊的小贼，跑过来一把抓起收音机就跑。获得对方口头承诺的小小举动对结果（瞧见这一幕的晒太阳的人是否会起身去追）造成了巨大影响。在研究者没有要求口头承诺的情况下，20个人里只有4人阻止；在研究者提出请求的情况下，20个人里有19个都采取了行动。为什么？因为他们已经答应要遵守承诺，起身追小偷是完全符合刚才那个口头承诺的。\u003c/p>\u003cp>如果像“请求口头承诺”这么小的一个改变就能这么明显地遏制海滩上的盗窃行为\u003c/p>\u003cp>任何一个想劝说他人做出多重并互相关联的行为改变的人，可以通过一个简单的两步法把成果最大化。第一步，确保最初的承诺是具体明确的。第二步，确保在实践该承诺的环境中，放置一个“提示”，这个提示应该完全符合第一步中的具体承诺，并且能够引发出另外一些与此承诺相关的、符合你期望的行为。\u003c/p>\u003cp>咱们来看一个例子。比如说，你是个办公室经理，你面对的问题是不仅要倡导员工更加积极地回收利用物品，还要降低办公室的总能耗。上述发现，你应该首先请员工们做出一个针对某项行为的具体承诺（比如每天晚上下班后把废纸放进回收纸篓）。然后，你应该在一个能够提醒大家节约能源的地方放上一个“提示”（比如把回收纸篓放在电灯开关的附近）。这样做很可能会有一箭双雕的效果。如果你把一张写着“勿忘环保承诺，请随手关灯”的小卡片放在灯旁边，还能进一步取得更好的效果。事实上，在兑现承诺这件事上，还有两点也很关键：这个承诺是否以行动为导向；该组织或个人做承诺时的公开程度如何。\u003c/p>","explains":"\u003cp>（what）相信在座的小伙伴都被放过“鸽子”吧？就是说好的事没有做到。虽然“放鸽子”大多都不算什么大事，但会严重影响我们的情绪。有没有一种办法可以让他人说到做到呢？拆页中给我们的建议是想办法让对方主动做出个承诺。这个承诺并不一定要正式的书面承诺，哪怕是口头上的承诺或是做一个选择。\u003c/p>\u003cp>（why）因为绝大多数人都有跟自己许下的承诺保持一致的强烈愿望，特别是当这个承诺是他们主动做出的或是公之于众的话就更是如此，这就是承诺和一致性的原理。之所以这个原理有用，是因为外部的舆论让人不想做一个背信弃义者，而来自人内心“自我”和“超我”的约束则令人对承诺极为重视。\u003c/p>\u003cp>（how）因此，在我们寻求他人做某事时，就要想办法让对方主动做出个承诺。\u003c/p>\u003cp>【可能出现的异议】\u003c/p>\u003cp>1.可能有小伙伴会有疑问，那承诺一致和服从有什么区别呢？\u003c/p>\u003cp>承诺一致性的关键在于主动承诺，而服从是被迫的承诺。它们之间的内在动力是不同的。\u003c/p>\u003cp>举个我们家女儿的例子，上周我很我女儿说，“你觉得自己的桌面乱吗？”她回答：“我觉得挺乱的。”“那你觉得，怎样能让桌面整洁点吗？”她说“我每天做完作业就整理桌面，这样就不会乱了。”我说：“太棒了！我很期待你的效果哦！”这周她的桌面一直保持的很干净。\u003c/p>\u003cp>2.可能还有朋友会说，有些人即使做了承诺还是会有做不到的情况出现，这时该怎么办呢？\u003c/p>\u003cp>首先，让这个承诺指向具体的行动。然后，确保在实践该承诺的环境中，放置一个“提示”，这个提示应该完全符合第一步中的具体承诺，并且能够引发出另外一些与此承诺相关的、符合你期望的行为。\u003c/p>\u003cp>还以我女儿整桌面为例，在她做了整理书桌的承诺后，我拍了张桌面整洁的照片，然后打印出来贴在她的书桌上方，以此来提醒她。\u003c/p>","interaction":"\u003cp> 接下来，我们先来分个小组，我左手边的小伙伴为一组，右手边的小伙伴为一组。\u003c/p>\u003cp> 现在请大家想一下，未来一周你有什么事需要他人帮忙完成，或是让别人接受你的请求或者提议的场景？比如工作中遇到的问题需要同事或领导出面处理的，生活中希望另一半帮忙多干点家务，让孩子改掉某个坏习惯啊等等。给大家1分钟的时间思考下。\u003c/p>\u003cp>\u003cbr> 现在你学习了新技能，你可以怎样应用刚才学到的方法让对方比较容易接受并能达到预期的目标？请用便签记录，时间是2分钟，完成请举手示意，然后用3分钟左右的时间在小组内分享。\u003c/p>\u003cp>学习者宁宁分享：\u003c/p>\u003cp>我想让我妈能够少给我打电话将的给我打电话的频率。我会用这次学习到的步骤，首先，我会跟我妈讲为什么不要给我打电话的原因，然后，请妈妈主动承诺降低打电话的频率，比如，答应从原来的一天三次到一周三四次。为了提升效果我还会请我外婆等家人在场。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1659000816000,"updated_at":1659096787000,"ria":true},{"id":13063,"topic":"如何提升自己的个人影响力","learn_goal":"","remark":"略","level":"TF1-1","duration":60,"status":30,"type":0,"chaishujia":{"username":"邓小米Jocelyn","city":"无锡市"},"club":{"name":"无锡太湖分舵","city":"无锡"},"prologue":"\u003cp>大家好，我叫邓娇，微信名为邓小米，大家可以叫我小米或英文名Jocelyn。\u003cbr>说起我的三个标签：第一，我是一名心理学专业爱好者，大学专业就是应用心理学，从TVB的推理片《迷情家族》结下情缘，到09年第一次入门后，对这门学科有着发自内心的热爱；第二，我是一名工作12年的HR老鸟，职场兜兜转转从外企到民营再到国企，依旧在HR的这个赛道里挣扎；第三，我是一名佛系的自我端水大师，这个端水体现在用生活的感性去平衡工作中的理性，用生活中的慵懒去中和工作的繁忙，换句话说就是不苛求自己，随性而为。\u003cbr>\u003cbr>认识拆书帮是一次机缘巧合，源自于对好友陈燕方朋友圈的关注，她每日的深度分享让我不禁好奇，是什么样的神奇组织可以让人掌握如此快速阅读和提炼知识的能力，秉承与好友一同学习进步的理念，我加入了拆书帮。\u003cbr>“拆书帮”是基于拆书法的学习爱好者社群,各地均有拆书帮分舵的设立，这是一个良心的公益性组织,其使命是帮助更多学习爱好者成长为拆书家。\u003cbr>拆书帮的核心方法论就是“拆书“，这是一种以学习者为中心的学习方法，主要有个人学习的拆书法和组织学习的拆书法两种；个人学习主要应用RIA便签法，组织学习就是一位拆书家拿一本书中一个片段加工出一场现场学习活动，引导和促进一群人把知识拆为己用。\u003cbr>我们成年人学习中经常会遇到这样的场景，平常工作已够忙了，根本没时间看完厚厚的一本书，或者书看完后记不住里面的内容，甚至是尽管我看过了书但我们根本就不会用。其实，成年人的学习最关注的便是学以致用，若我们能学会使用一两个的观点或技巧来改善工作或生活，那么这本书的价值已发挥出来了。\u003cbr>接下来我将运用RIA便签法来拆一个片段，下面请大家花2分钟时间看一下我们今天的片段。看完的小伙伴可以举手向我示意一下。\u003c/p>","ratings_count":1,"texts":[{"id":17038,"quote":"\u003cp>研究人员发现，通过一个两步走的方法，就能够增强默认策略的效果。他们把这个方法叫做“增强版主动选择”。“增强版主动选择”第一步是对默认设置做个小调整：人们面对的不再是“要么接受，要么放弃”，而是可以在两个选择中真正挑选出一个。\u003c/p>\u003cp>在一个实验中，凯乐和同事们把一组教职员工分成两组。两组人得到了一个打流感疫苗的机会，这不仅能保护他们的健康，还能替他们节省每个月的健康保险费用。\u003c/p>\u003cp>第一组（“接受或放弃”组），面对的要求很简单：“如果今年秋天你想打流感疫苗，就在此处打钩。”但第二组面对的不是一个替他们做好了的默认选择，而是一个主动二选一的机会：“今年秋天我要打流感疫苗”，或者“今年秋天我不打流感疫苗”。\u003c/p>\u003cp>结果显示，比起“接受或放弃”组（愿打疫苗的人占42%），主动选择组有更多人（62%）愿意打疫苗。这个实验提供了明确的证据：虽然接受或放弃的方法有道理而且有效，但再做一个小小的调整——请人们主动做出选择——能够带来更大的成效。\u003c/p>\u003cp>但研究者们并不满足，他们还想知道，能否把主动选择的方法在提再升级一下？他们在说服科学的另一个基本原则中找到了答案，这个原则就是损失规避。也就是说，人们有避免失去的强烈倾向。研究者们把这个倾向运用起来，测试了主动选择的升级版：向人们指出，如果他们不采取行动，就会损失什么。\u003c/p>\u003cp>这一组的受试对象需要在以下两个选项中挑一个：“今年秋天我会打流感疫苗，因为我想降低得流感的风险，并且节省50美元。”或者“今年秋天我不打流感疫苗，即便者意味着我得流感的风险可能会提高，而且无法节省50美元。”\u003c/p>\u003cp>把主动选择跟具体的损失结合起来，这么一个小小的举动造成了极大的差异：75%的人要求打疫苗。\u003c/p>\u003cp>无论你的目的是什么，两步法的关键都是一样的。首先迈出一小步，构思两个选择，让受众从中主动挑一个。然后，再多往前迈一小步，把你想让他们选的那个选项包装一下——向他们指出，如果不这么做的话就会损失什么。\u003c/p>","explains":"\u003cp>我看到大部分的小伙伴都阅读完毕了，那么接下来的时间我将使用RIA便签读书法来讲解一下我的理解、经验及规划应用。\u003c/p>\u003cp>本片段介绍了一种通过细节设置从而影响他人选择的方法，学名叫做“增强版主动选择”。\u003c/p>\u003cp>在这个个人IP盛行的自媒体时代，每个人都想提升自己的个人影响力，从而积累更多的人脉、创造更多的价值。然而在这个多元价值观的社会，想要影响一个人、尤其是影响一个人的选择，可不是件容易的事儿。假设你是一个网红主播，像李佳琪这样的大咖，虽然已经有这么多年的粉丝积累及IP品牌沉淀，在产品介绍和推广的时候依旧会反复推敲文案细节，并且会不断通过复盘去验证这些细节设置对营销结果的有效性。\u003c/p>\u003cp>所以，想要影响其他人的选择是需要进行精心的细节设计的，倘若只是给出单一的非此即彼的选项，对方一经选择就已经结束了此次链接，结果无法更改，他的选择是否是你想要的结果只能全凭“缘分”，这如果是在商业推销中根本无法保证业绩的达成，为此销售员会被老板责备没有目标感，甚至因为销售技巧能力不足、业绩不佳被淘汰。\u003c/p>\u003cp>利用“增强版主动选择”这种技巧，可以帮助我们理清引导的方向，并通过有目的的设计选项，让对方陷入我们的“圈套”中，从而选择我们期待的结果。\u003c/p>\u003cp>那怎么来进行设计引导呢？主要有两个步骤：\u003c/p>\u003cp>1、以双代一，即用“两个选项”代替“唯一的选项”。这样做是为了缓解非此即彼带来的“逼迫感”，在感官上建立“你不是只有一种选择”的认知，从而降低选择者的窘境和排斥感，并且将对方引导入“两个选项中到底哪个更好”的比较中，从而促成主动选择。\u003c/p>\u003cp>2、强调损失：人性本能会趋向规避损失，若倾向于希望对方达成A项选择，则可在A项选择中加入一些额外的利益点，在B选项中说明如果不选择A/选择B，则还会有一些利益损失点。当人们认识到如果不选择A，他将会失去什么的时候，自然会趋向选择A选项。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】\u003c/strong>\u003c/p>\u003cp>增强版主动选择这种方法其实是金融的惯用技巧，我的车险是每年4月初到期，从2月初就有保险销售人员开始给我打电话了，今年也不例外，其中有位车险销售人员的电话是这样的“邓女士，您好，我看您的车险马上就要到期了，不知道您这次是想购买100万还是200万的三者险？“看，她并没有问我要不要买，而是根据她的目的直接让我在她设置的选项中做二选一的选择，看似给了我做主的权利，实际上已经给我的选择范围画了个框。\u003c/p>\u003cp>接着推销员又说“如果您购买两百万的商业险，现在正好搞活动，可以有个返现优惠，最后价格可以达到跟100万的差不多，但是享受的权益肯定是比100万多很多的；如果你购买一百万的商业险，则不享受任何优惠返现的活动。”哦，趋利避害的设计，请问若是你听了你会做何选择？听了肯定瞬间被引导选择200万商业险。\u003c/p>\u003cp>\u003cstrong>【A2】\u003c/strong>\u003c/p>\u003cp>这个方法我觉得除了在商业推销中屡试不爽，在需要引导他人协助或者做决定方法也是非常好用的，目前呀，基于我们公司5年规划，有着业务轻资产输出的需求，董事长对学院有着很高的期望，希望我们能够在今年提炼沉淀出属于自己的知识体系，于是我们打算开展一个内训师项目，希望在6月30日前让景区运营管理人员参与内训师课程开发，目标至少5门课。\u003c/p>\u003cp>\u003cstrong>【行动步骤】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、\u003c/strong> \u003cstrong>用“两个选项”代替“唯一的选项”\u003c/strong>\u003c/p>\u003cp>根据与景区总经理沟通的课程体系框架，确定重点课题，并与五大部门负责人去沟通，让他们选择是自行带队开发还是指派人员开发课程，从而确保重点课程有人开发，不会开天窗。\u003c/p>\u003cp>\u003cstrong>2、\u003c/strong> \u003cstrong>强调损失\u003c/strong>\u003c/p>\u003cp>课程开发结束通过评审后，将课程开发师的荣誉与管理晋升挂钩、并告知如果选择不进行课程开发，可能将错失管理梯队中欧培训的机会，再次引导他们去进行课程开发。\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>\u003c/p>\u003cp>以上就是我今天分享的内容，下面让我们再次来回顾下“增强版主动选择“的两个步骤，1、以双代一，2、强调损失。希望通过今天的学习分享，大家都能学习到如果通过细节设计影响他人选择的小技巧，或者能在日常生活中识别这种技巧，帮助自己做更客观理智的判断。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1645451922000,"updated_at":1646792053000,"ria":true},{"id":12198,"topic":"如何通过细节设计影响选择力","learn_goal":"","remark":"在这个IP盛行的自媒体时代，想知道如何提升自己的个人影响力，从而积累更多的人脉、创造更多的价值？\n欢迎参加TF1-1 邓娇拆书片段，与你分享如何利用“增强版主动选择”，通过有目的的设计引导，让你想要影响的人陷入“圈套”，从而达成我们期待的结果。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"邓小米Jocelyn","city":"无锡市"},"club":{"name":"无锡太湖分舵","city":"无锡"},"prologue":"\u003cp>大家好，我叫邓娇，微信名为邓小米，大家可以叫我小米或英文名Jocelyn。\u003c/p>\u003cp>说起我的三个标签：第一，我是一名心理学专业爱好者，大学专业就是应用心理学，从TVB的推理片《迷情家族》结下情缘，到09年第一次入门后，对这门学科有着发自内心的热爱；第二，我是一名工作12年的HR老鸟，职场兜兜转转从外企到民营再到国企，依旧在HR的这个赛道里挣扎；第三，我是一名佛系的自我端水大师，这个端水体现在用生活的感性去平衡工作中的理性，用生活中的慵懒去中和工作的繁忙，换句话说就是不苛求自己，随性而为。\u003c/p>\u003cp>认识拆书帮是一次机缘巧合，源自于对好友陈燕方朋友圈的关注，她每日的深度分享让我不禁好奇，是什么样的神奇组织可以让人掌握如此快速阅读和提炼知识的能力，秉承与好友一同学习进步的理念，我加入了拆书帮。\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群,各地均有拆书帮分舵的设立，这是一个良心的公益性组织,其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp> 拆书帮的核心方法论就是“拆书“，这是一种以学习者为中心的学习方法，主要有个人学习的拆书法和组织学习的拆书法两种；个人学习主要应用RIA便签法，组织学习就是一位拆书家拿一本书中一个片段加工出一场现场学习活动，引导和促进一群人把知识拆为己用。\u003c/p>\u003cp>我们成年人学习中经常会遇到这样的场景，平常工作已够忙了，根本没时间看完厚厚的一本书，或者书看完后记不住里面的内容，甚至是尽管我看过了书但我们根本就不会用。其实，成年人的学习最关注的便是学以致用，若我们能学会使用一两个的观点或技巧来改善工作或生活，那么这本书的价值已发挥出来了。\u003c/p>\u003cp>接下来我将运用RIA便签法来拆一个片段，下面请大家花2分钟时间看一下我们今天的片段。看完的小伙伴可以举手向我示意一下。\u003c/p>","ratings_count":1,"texts":[{"id":16113,"quote":"\u003cp>研究人员发现，通过一个两步走的方法，就能够增强默认策略的效果。他们把这个方法叫做“增强版主动选择”。“增强版主动选择”第一步是对默认设置做个小调整：人们面对的不再是“要么接受，要么放弃”，而是可以在两个选择中真正挑选出一个。\u003c/p>\u003cp>在一个实验中，凯乐和同事们把一组教职员工分成两组。两组人得到了一个打流感疫苗的机会，这不仅能保护他们的健康，还能替他们节省每个月的健康保险费用。\u003c/p>\u003cp>第一组（“接受或放弃”组），面对的要求很简单：“如果今年秋天你想打流感疫苗，就在此处打钩。”但第二组面对的不是一个替他们做好了的默认选择，而是一个主动二选一的机会：“今年秋天我要打流感疫苗”，或者“今年秋天我不打流感疫苗”。\u003c/p>\u003cp>结果显示，比起“接受或放弃”组（愿打疫苗的人占42%），主动选择组有更多人（62%）愿意打疫苗。这个实验提供了明确的证据：虽然接受或放弃的方法有道理而且有效，但再做一个小小的调整——请人们主动做出选择——能够带来更大的成效。\u003c/p>\u003cp>但研究者们并不满足，他们还想知道，能否把主动选择的方法在提再升级一下？他们在说服科学的另一个基本原则中找到了答案，这个原则就是损失规避。也就是说，人们有避免失去的强烈倾向。研究者们把这个倾向运用起来，测试了主动选择的升级版：向人们指出，如果他们不采取行动，就会损失什么。\u003c/p>\u003cp>这一组的受试对象需要在以下两个选项中挑一个：“今年秋天我会打流感疫苗，因为我想降低得流感的风险，并且节省50美元。”或者“今年秋天我不打流感疫苗，即便者意味着我得流感的风险可能会提高，而且无法节省50美元。”\u003c/p>\u003cp>把主动选择跟具体的损失结合起来，这么一个小小的举动造成了极大的差异：75%的人要求打疫苗。\u003c/p>\u003cp>无论你的目的是什么，两步法的关键都是一样的。首先迈出一小步，构思两个选择，让受众从中主动挑一个。然后，再多往前迈一小步，把你想让他们选的那个选项包装一下——向他们指出，如果不这么做的话就会损失什么。\u003c/p>","explains":"\u003cp>我看到大部分的小伙伴都阅读完毕了，那么接下来的时间我将使用RIA便签读书法来讲解一下我的理解、经验及规划应用。\u003c/p>\u003cp>本片段介绍了一种通过细节设置从而影响他人选择的方法，学名叫做“增强版主动选择”。\u003c/p>\u003cp>在这个个人IP盛行的自媒体时代，每个人都想提升自己的个人影响力，从而积累更多的人脉、创造更多的价值。然而在这个多元价值观的社会，想要影响一个人、尤其是影响一个人的选择，可不是件容易的事儿。假设你是一个网红主播，像李佳琪这样的大咖，虽然已经有这么多年的粉丝积累及IP品牌沉淀，在产品介绍和推广的时候依旧会反复推敲文案细节，并且会不断通过复盘去验证这些细节设置对营销结果的有效性。\u003c/p>\u003cp>所以，想要影响其他人的选择是需要进行精心的细节设计的，倘若只是给出单一的非此即彼的选项，对方一经选择就已经结束了此次链接，结果无法更改，他的选择是否是你想要的结果只能全凭“缘分”，这如果是在商业推销中根本无法保证业绩的达成，为此销售员会被老板责备没有目标感，甚至因为销售技巧能力不足、业绩不佳被淘汰。\u003c/p>\u003cp>利用“增强版主动选择”这种技巧，可以帮助我们理清引导的方向，并通过有目的的设计选项，让对方陷入我们的“圈套”中，从而选择我们期待的结果。\u003c/p>\u003cp>那怎么来进行设计引导呢？主要有两个步骤：\u003c/p>\u003cp>1、以双代一，即用“两个选项”代替“唯一的选项”。这样做是为了缓解非此即彼带来的“逼迫感”，在感官上建立“你不是只有一种选择”的认知，从而降低选择者的窘境和排斥感，并且将对方引导入“两个选项中到底哪个更好”的比较中，从而促成主动选择。\u003c/p>\u003cp>2、强调损失：人性本能会趋向规避损失，若倾向于希望对方达成A项选择，则可在A项选择中加入一些额外的利益点，在B选项中说明如果不选择A/选择B，则还会有一些利益损失点。当人们认识到如果不选择A，他将会失去什么的时候，自然会趋向选择A选项。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】\u003c/strong>\u003c/p>\u003cp>增强版主动选择这种方法其实是金融的惯用技巧，我的车险是每年4月初到期，今年3月份我接到了这样一位车险推销员的电话，电话的套路就是用的这一招。\u003c/p>\u003cp>不管是什么公司的车险推销员，打电话来大多都是这么说的“邓女士，您目前是想购买100万还是200万的三者险？“看，她在让我做二选一的选择，看似给了我做主的权利，实际上已经给我的选择范围画了个框。\u003c/p>\u003cp>接着推销员又说“如果您购买两百万的商业险，现在正好搞活动，可以有个返现优惠，最后价格可以达到跟100万的差不多，但是享受的权益肯定是比100万多很多的；如果你购买一百万的商业险，则不享受任何优惠返现的活动。”哦，趋利避害的设计，请问若是你听了你会做何选择？听了肯定瞬间被引导选择200万商业险。\u003c/p>\u003cp>\u003cstrong>【A2】\u003c/strong>\u003c/p>\u003cp>这个方法我觉得在需要引导他人协助或者做决定方法还是非常好用的，目前呀，基于我们公司5年规划，有着业务轻资产输出的需求，董事长对学院有着很高的期望，希望我们能够在今年提炼沉淀出属于自己的知识体系，于是我们打算开展一个内训师项目，希望在8月20日前让景区运营管理人员参与内训师课程开发，目标至少5门课。\u003c/p>\u003cp>\u003cstrong>【行动步骤】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1、\u003c/strong> \u003cstrong>用“两个选项”代替“唯一的选项”\u003c/strong>\u003c/p>\u003cp>根据与景区总经理沟通的课程体系框架，确定重点课题，并与五大部门负责人去沟通，让他们选择是自行带队开发还是指派人员开发课程，从而确保重点课程有人开发，不会开天窗。\u003c/p>\u003cp>\u003cstrong>2、\u003c/strong> \u003cstrong>强调损失\u003c/strong>\u003c/p>\u003cp>课程开发结束通过评审后，将课程开发师的荣誉与管理晋升挂钩、并告知如果选择不进行课程开发，可能将错失管理梯队中欧培训的机会，再次引导他们去进行课程开发。\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>\u003c/p>\u003cp>以上就是我今天分享的内容，下面让我们再次来回顾下“增强版主动选择“的两个步骤，1、以双代一，2、强调损失。希望通过今天的学习分享，大家都能学习到如果通过细节设计影响他人选择的小技巧，或者能在日常生活中识别这种技巧，帮助自己做更客观理智的判断。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1629869317000,"updated_at":1629871557000,"ria":true},{"id":11960,"topic":"如何在重拾目标后干劲儿更足？","learn_goal":"","remark":"《细节：如何轻松影响他人》，【F】大家一定都听说过畅销全球的书籍《影响力》。这本书就是《影响力》的作者罗伯特·西奥提尼的又一力作。这是一本提供了一套能够“四两拨千斤”的工具的致用类书籍【A】里面包含了52个改变细节的小工具，可以说是套路满满，因此这本书在3个月内就达到了近10W册的销量，【B】如果说《影响力》为我们影响他人和改变自己提供了理论指导。那这本书就是《影响力》的实操训练手册，你可能因为出租车司机主动的问候认可他的服务，你曾经因为附赠的漂亮赠品买了一个根本没打算买的商品，这些都是被细节影响的结果，那如何做好更多的细节以及识别细节的陷阱的，这本书你一定不要错过。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"马子喻","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>大家晚上好，我是马文丽，欢迎大家来到今天我的TF2-1的拆书分享，在跟随我完成本次RIA现场学习后，学习者能够学会重拾目标后干劲儿更足，而不是在重拾目标后，在落地目标的过程中坚持还不如以前。\u003c/p>","ratings_count":1,"texts":[{"id":15914,"quote":"\u003cp>拆书级别：TF2-1\u003c/p>\u003cp>拆书家：马文丽\u003c/p>\u003cp>书目：《细节》作者：史蒂夫·马丁，诺厄·戈尔茨坦，罗伯特·西奥迪尼\u003c/p>\u003cp>页码：P98-P99\u003c/p>\u003cp>1919年，在《堪萨斯城星报》（Kansas City Star）画政治漫画的沃尔特·迪士尼（Walt Disney）被解雇了，报纸编辑的话是：“他不是太有创意。”\u003c/p>\u003cp>2012年，英国生物学家约翰·戈登爵士（Sir John Gurdon）因对生理学和药学的杰出贡献获得了诺贝尔奖。可当年他在伊顿公学的校长却在成绩单上这样写道：“我相信戈登想当个科学家，可照他现在的表现看，这想法颇为荒谬。”\u003c/p>\u003cp>好莱坞有个传说，弗雷德·阿斯泰尔（Fred Astaire）去雷电华影业（RKO Pictures）试镜时，一个制片经理把他刷了下来，理由是：“（他）不会表演，不会唱歌，有秃顶迹象，会跳一点儿舞。”\u003c/p>\u003cp>令人欣慰的是，这些早期的挫折都没能阻拦他们追求自己的目标。上述三人全部获得了惊人的成就。但有些时候，人们的确会分心，会忘记目标——不是未来的诺奖得主和好莱坞偶像心目中那种宏伟的、一辈子只有一次的、梦工厂式的目标，而是虽然小一点儿却依旧十分重要的、日常生活中的目标，比如多存一点儿钱，减掉几斤肉，还掉信用卡，或是达到这个月的销售目标。\u003c/p>\u003cp>人们往往需要重新拾起之前为自己设定的目标。同样，管理者、团队带头人、老师甚至是父母，有时候也需要帮助员工、学生和孩子鼓起干劲儿，再次为了原先的目标而努力。按常理，当我们为自己或他人设定新目标的时候，经验总是告诉我们，要把目标设定的非常具体。比如，每周减掉2磅（约1.8斤）体重，1小时跑6英里（约9.6公里），或是每个月存下100美元，作为来年的度假基金。但是，当我们说服自己或他人重拾目标的时候，这个常识是否正确呢？\u003c/p>\u003cp>营销学教授毛拉·斯科特（Maura Scott）和斯蒂芬·诺里斯（Stephen Nowlis）认为，虽然人们在直觉上感到，在首次制订目标时，应当把他量化为单一而具体的数字，但是，在重拾先前的目标时，这样做就未必最好了。相反，这两位学者认为，比起单一的具体数字[比如每周减掉3磅（约2.7斤）体重]，把目标改成一个上下浮动的数字范围[但平均值跟原先的数字一样，比如每周减掉2-4磅（约1.8~3.6斤）]，会更加有助于人们鼓起干劲儿，重新投入。\u003c/p>","explains":"\u003cp>今天我要拆的片段来自这本书《细节：如何轻松影响他人》，\u003c/p>\u003cp>【F】这本《细节》作者是罗伯特·西奥迪尼、史蒂夫·马丁、诺厄·戈尔茨坦3个知名说服力与影响力的研究权威，书里讲了52个“四两拨千斤”改变细节的套路。\u003c/p>\u003cp>【A】这是一本令人惊奇、强大、具有深刻内涵的实用型人生工具书，完整且细致地揭示了失败和成功之间存在着的细节差别，它3个月内就达到了近10W册的销量，并获得英国皇家学会奖。\u003c/p>\u003cp>【B】 如果你曾经设立了小目标在执行的过程中中断，你重拾目标后仍然没有干劲儿，那这本书就从一个细小的细节改变可以让你在重拾目标后干劲儿更足。同时在职场沟通、员工激励、商业谈判、家庭教育等工作和生活领域对你产生持续且深远的超级影响力\u003c/p>\u003cp>【分组】现在我们按座位每3个人一组\u003c/p>\u003cp>【I】\u003c/p>\u003cp>好，大家都看好了，内容不多，且非常容易理解。我们都有那些虽然小一点却依旧十分重要的、日常生活中的目标。首次在设定目标的时候，经验总是告诉我们，把目标量化为一个具体的数字，但在目标执行落地的过程中，我们往往需要重拾目标，这种时候，想要重新投入后更加有干劲儿，要怎么办呢？第一步保证平均值和原先一样，第二步把目标改成一个上下浮动的数字范围，这样会有助于我们鼓起干劲儿，重新投入。\u003c/p>\u003cp>如果不这么做的话，在我们执行这些虽然小但是很重要的目标的过程中，目标一旦中断，我们还按照以前的具体的数字重拾目标时，会越来越没有干劲儿，不但丢掉了这些虽然小但很重要的目标，而且还会产生负面情绪，影响自己的生活和工作。\u003c/p>\u003cp>这里分享一个自己的经历。半年前，我和一个伙伴约定好，每周跑步3次，坚持了快一个月的时间，这个习惯就彻底丢掉了。本着爱美和健康的目标，没过多久，我们再次约定好，重拾目标，重新开始行动，结果情境几乎和之前一模一样，坚持了还不到一个月就再次丧失了跑步的干劲儿，而且两个人甚至要开始自我怀疑，产生了负面情绪。\u003c/p>\u003cp>直到我遇到了这个拆页，在读了《细节》这本书的这个拆页以后，我和伙伴重拾之前的目标，第一步在平均值和之前的数字一样的前提下，保持平均值是每周3次，第二步，我们把目标改成一个上下浮动的数字范围，调整为每周2-4次的目标。就这样，我们重拾目标，每周跑步2次的这个小目标，很轻松的就达到了，每周跑步4次，在偶尔两个人工作都不太忙的阶段也能实现。不论是跑2次，3次还是4次，因为都属于在目标范围内，可以都算作是我们实现了当周的目标，我们比之前更加干劲十足的重新投入到了目标中。现如今，我们调整目标以后，已经执行了新的目标快两个月的时间，而且热情丝毫不减。\u003c/p>\u003cp>正如拆页的建议中所说，生活中这些虽然小但仍然十分重要的小目标，在重拾目标时，在平均值和原来的数字一致的情况下，把一个具体数字的目标调整为一个上下浮动的范围的目标，可以让我们更加有干劲儿。\u003c/p>","interaction":"\u003cp>【拆书家提问设计】：下面请大家回忆一下，你有没有遇到这类似工作或生活的场景，例如：你曾经设立了每天背20个单词的目标、或者每天走1W步、每天写工作日志等，但是你发现坚持了没几天就又没有了干劲儿？\u003c/p>\u003cp>请把曾经设定了具体的目标，但是执行过程中，重拾目标后来干劲不足这样的场景简单地写到便签上，1分钟时间，写好的请举手示意。\u003c/p>\u003cp>【学习者案例记录1】\u003c/p>\u003cp>驰驰：虽然跑步我一直坚持，但今年有件事做的不太好。就是当时立目标每天坚持，而且每次都在认真写稿子、准备开场、录音这样。但是只坚持了7天，到了第8天，就因为种种原因没坚持下来，再后来就是断断续续，没有做到每天去坚持录短视频，而且质量也大不如前，数量目标和质量目标都没实现。\u003c/p>\u003cp>【学习者案例记录2】\u003c/p>\u003cp>李老师：去年我一直坚持跟着Keep运动，目标是每周至少5次。结果后来天气慢慢转冷，坚持的特别难，每周慢慢的就变成了只能运动4次、3次……\u003c/p>\u003cp>【拆书家提问设计】：好，如果让你乘坐时光机，穿越回刚刚提到的A1重拾目标的场景，根据刚才拆页的建议，最好怎样设定刚刚大家写下的曾经的目标？你会如何重新调整当时设定的目标呢？1分钟的时间给大家书写，写好后给大家3分钟时间在小组内分享一下你们的案例。\u003c/p>\u003cp>【学习者案例记录1】\u003c/p>\u003cp>宋老师：我陪着女儿练古筝，以前的目标是每周都都练至少1小时以上，每周五天，后来就发现，作业一多，就很难坚持练习了。从一周5次变成4次，3次，甚至有时候会2次，如果这样下去就很难跟上老师的节奏。今天学了这个以后，决定帮她把目标改成每周3-5次，这样就可以比较容易坚持下来了。\u003c/p>\u003cp>【学习者案例记录2】\u003c/p>\u003cp>吴老师：我以前立目标，每天坚持晚上11：30前睡觉，但是最后真的很难坚持。不能做到每天。今天学习了这个便签，我觉得把天数和睡眠时间都调整一下，设成每周5-7天，每天坚持晚上11：00-12：00之间睡觉，这样肯定就会很容易坚持下来了。\u003c/p>\u003cp>感谢几伙伴的分享，那生活中我们经常设立一些虽然小但很重要的目标，但又往往很难坚持。我们因为把这个目标设立为具体的数字，在重拾目标的时候，保证目标平均值和原先一样，然后我们把目标改成一个上下浮动的数字范围，这样会有助于我们鼓起干劲儿，重新投入。\u003c/p>\u003cp>今天我的TF2-1拆书分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1626905382000,"updated_at":1627993590000,"ria":true},{"id":11555,"topic":"细节","learn_goal":"","remark":"如何通过改变细节更容易实现目标","level":"TF2-3","duration":20,"status":30,"type":0,"chaishujia":{"username":"NAP君","city":"宁波市"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>通过今天的拆书学习，我希望大家在\u003cstrong>推动他人达成目标时\u003c/strong>（\u003cstrong>场景\u003c/strong>），可以运用\u003cstrong>确定目标、对现状进行评估、确定行动步骤\u003c/strong>（\u003cstrong>how\u003c/strong>）三步，\u003cstrong>降低实现目标的难度\u003c/strong>（\u003cstrong>行为结果\u003c/strong>）。大家好，我是今天的拆书家NAP君\u003c/p>\u003cp>\u003cstrong>【F】特征，核心为书，好奇：\u003c/strong>\u003c/p>\u003cp>我今天要介绍的这本书呢，书名叫做《细节：如何轻松影响他人》。这本书是一本联合著作的书，在他的三位作者中的有一位是非常著名的，他的名字叫伯特·西奥迪尼。他呢，有一本非常著名的作品就是《影响力》，我相信大家都一定听到过这本书。在这本书发表之后，罗伯特·西奥迪尼一举成为影响力和说服力的行业代言。由此可见我们今天这本书的分量。\u003c/p>\u003cp>\u003cstrong>【A】优势，比较：\u003c/strong>\u003c/p>\u003cp>这本书和同类书比起来，有什么不一样的地方呢？这本书他讲了52个影响他人的细节。而这52个细节都是科学实验得出来的结果，我们以往的大量的沟通力的书籍基本上就是讲案例讲心得。但是这本书不一样，他做得非常科学，他是怎么做的，他会在一个场景里面把所有的细节都控制好只改变其中的一个细节，然后讲结果进行数据对比，最后得出一个结论，表达哪个细节影响了销售量，决策，或是认同度。所以这是一本类似教科书级别的科学著作，和市面同类作品是不同的。\u003c/p>\u003cp>\u003cstrong>【B】利益：\u003c/strong>学习这本书的好处很多\u003c/p>\u003cp>\u003cstrong>【B1】：\u003c/strong>\u003c/p>\u003cp>比如和同事合作如何让他做出承诺并有效兑现，比如给领导做回报什么时候用数字什么时候用%更有说服力，比如说如何在定价的时候提高价格却又让顾客不反感。这些书里都有讲，有兴趣的小伙伴可以去看这本书。\u003c/p>\u003cp>\u003cstrong>【B2】：\u003c/strong>\u003c/p>\u003cp>今天我们的这个拆页选自《细节》的“如何提高客户忠诚度”这一篇。科学家们通过实验得出了一个结论：我们只需要改变某些细节就能更容易达到某些的目标。\u003c/p>","ratings_count":2,"texts":[{"id":15481,"quote":"\u003cp>\u003cstrong>TF2-3拆页选自《细节》如何提高客户忠诚度\u003c/strong>\u003c/p>\u003cp>\u003cstrong>主题：如何通过一个细节更好（让自己或他人）达到目标\u003c/strong>\u003c/p>\u003cp>当选择相对简单，完成任务的动力很足的时候，灵活性比固定顺序更有助于实现目标。但是，\u003cstrong>如果人们需要做出较为困难的改变，或是动力比较低的时候，严格的顺序和结构就会更有帮助\u003c/strong>。\u003c/p>\u003cp>对于想设计客户忠诚计划和奖励计划的公司，这个研究有清晰的借鉴意义。但除了这些之外，还有些东西也值得思考。假设一名经理想说服鼓励下属参与一个新项目。在琢磨“\u003cstrong>是让大家灵活行动还是按规定顺序执行\u003c/strong>” 之前，这位经理需要先问自己一个虽然很小却意义重大的问题:“\u003cstrong>我面临的主要问题是说服大家认同这项工作呢，还是鼓励他们坚持到底?\u003c/strong>”如果答案是\u003cstrong>先得说服大家接受这项工作\u003c/strong>，那么接下来要做的就很清楚了：\u003cstrong>必需的行动顺序应当越灵活越好，并且在宣布这项工作时就要强调这份灵活性\u003c/strong>。\u003c/p>\u003cp>但是，如果\u003cstrong>问题出在执行阶段\u003c/strong>，虽然做法完全不同，但照样很清楚：\u003cstrong>制订一个结构清晰、按部就班的行动计划，并且对大家强调，一旦行动开始，这个项目就会以明确的方式一直往前推进\u003c/strong>。\u003c/p>\u003cp>结构化的顺序能够帮助人们完成既定目标，这个方法对医药公司也很有用。这类机构面临的挑战是说服人们按照疗程服药。这项研究结果表明，医药公司可以把泡罩包装的药片分成不同的颜色，并做出清晰的标识，告诉患者何时该吃什么药丸，这对患者和专业医护人员都有好处。例如，疗程的头三天，患者需要吃白色药片，接下来的三天吃蓝色药片，最后吃红色的。虽然药物成分没有任何改变，但这个“分步骤服用”的小改变能让患者更容易遵照医嘱吃药。\u003c/p>","explains":"\u003cp>\u003cstrong>【WHAT】：\u003c/strong>\u003c/p>\u003cp>那我来解析一下我对这个拆页的理解。核心观点是：在达成困难目标的过程中，严格的规定能更好得帮你实现目标。\u003c/p>\u003cp>\u003cstrong>【WHY】【WHERE】：\u003c/strong>\u003c/p>\u003cp>为什么呢？在决定是否要追求一个目标的时候，人们一般会思考两件事情：\u003cstrong>这件事情有多大价值，以及有没有可能做到。\u003c/strong>\u003c/p>\u003cp>所以呢，当目标越远大的时候，我们会遇到的困难往往就会越多。当目标越简单的时候，我们更希望灵活得完成目标。\u003c/p>\u003cp>在学习这个拆页之前，我是个很细节控的人，所有的目标我都会很细化，以便于我达成。学习这个拆页之后我找到了制定目标和步骤的一个边界，就是你根据自己的情况决定给予的灵活度和步骤的细化程度，来提高你目标的达成度。\u003c/p>\u003cp>\u003cstrong>【案例意译】：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“假设一名经理想说服鼓励下属参与一个新项目。”\u003c/strong>就拿我们21天训练营举例。我站在组织者的角度来分析一下这个活动啊。\u003c/p>\u003cp>首先我们作为活动的组织者当然希望身边有更多的小伙伴来参加21天的训练营，并且能够坚持下来。\u003c/p>\u003cp>然后我要问自己，“\u003cstrong>我们是要说服大家认同这个事情呢？还是要坚持下来？\u003c/strong>”\u003c/p>\u003cp>作为组织者我觉得既然能来参加这次的活动大家一定对这个活动本身比较任可了，我们要关注的是如何让小伙伴们坚持下来。\u003c/p>\u003cp>所以“\u003cstrong>是让大家灵活行动还是按规定顺序执行\u003c/strong>”那么我要怎么选择呢？\u003c/p>\u003cp>我选择让大家按更复杂的顺序执行。\u003c/p>\u003cp>我们提出了25天每天先学习，再做作业打卡，然后对每个小伙伴的点评，最后每周进行一次复盘。\u003c/p>\u003cp>\u003cstrong>【HOW】：\u003c/strong>\u003c/p>\u003cp>首先，确定目标。设定出一个清晰的目标（SMART法则）\u003c/p>\u003cp>其次，对现状进行评估。我实现目标的过程中可能会遇到两大障碍，第一个障碍呢，就是我没有意愿做，就是我要不要做好，这是意愿的问题，那么第二个呢，就是说我能不能坚持做下去。问自己两个问题我们是要提高积极性？还是拆分目标以便于达成？\u003c/p>\u003cp>最后，确定行动步骤。当我没有意愿做这件事情的时候，你可以提高灵活度，让我有意愿做这个事情；当我有意愿做这个事情，但做不下去的时候，我们可以细化步骤让我坚持做下去。对于简单目标我们提高灵活度，对于复杂问题我们尽量细化步骤。\u003c/p>","interaction":"\u003cp>【A3】\u003cstrong>拆书家设计场景进行讨论或演练：\u003c/strong>\u003c/p>\u003cp>我给大家设计了一个场景。一位新手拆书家和他的一位师傅。徒弟在参加完全国21天拆书训练营之后的2个月内都没有开始拆书过级。师父感到有些担忧，决定跟徒弟进行一次沟通，希望徒弟在后面的半年内完成拆书家的9个关卡，达到三级。师父现在要通过“1.确定目标。2.对现状进行评估。3.确定行动步骤。”三步来让弟子更好得去完成目标。\u003c/p>\u003cp>现在给大家5分钟时间借用今天的这个拆页的知识点讨论我们如何制定计划、评估、确定步骤。今天人比较多，我们分成2组。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>师父：师傅给你设定了一个目标半年过完三级，你觉得这个目标怎么样？\u003c/p>\u003cp>徒弟：我觉得我完不成。\u003c/p>\u003cp>师父：是什么原因让你觉得你完不成这个目标呢？是因为没有想法去做这个事情呢？还是你觉得这个目标太难了？\u003c/p>\u003cp>徒弟：我觉得这个有点难度，我觉得我半年完不成这个目标。\u003c/p>\u003cp>师父：对你来说你的难点是什么呢？\u003c/p>\u003cp>徒弟：我现在还没有参加过拆书，完全不了解这个事情该如何去做。\u003c/p>\u003cp>师父：那我们看看如何把这个问题拆分了。你觉得如果你现在看是拆，你要去做些什么？\u003c/p>\u003cp>徒弟：我觉得我要开始看书找拆页。然后开始学习技能点。再写稿子。\u003c/p>\u003cp>师父：那我们从1-1开始，每周找3个拆页，写一篇稿子，先做1个星期。如果这个节奏可以，我们就坚持下去。如果坚持不了，我们再做调整，比如2周出一篇稿子，你觉得可以么？\u003c/p>\u003cp>徒弟：好的师父，我现在有信心完成目标了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1621409466000,"updated_at":1628583961000,"ria":true},{"id":11221,"topic":"承诺和一致性原则","learn_goal":"","remark":"你还在用摆事实讲道理的方式说服人吗？你还在用苦口婆心喋喋不休的方式影响人吗？其实你只需要做个小小的设计，就能轻松影响他人，让他们做出行为上的改变。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"黑碳包","city":"宁波市"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>各位小伙伴下午好！\u003c/p>\u003cp>我是包子，用三个标签介绍我自己。我是一名新手教练、是一名二级拆书家也是一枚终生学习践行者。\u003c/p>\u003cp>今天我带来的拆页出自西奥迪尼《细节》这本书中的“承诺和一致性”原则。\u003cbr>F：《细节》这本书的作者叫西奥迪尼，是世界最有名的说服力和影响力专家，他之前写过一本著名的书叫《影响力》，畅销全球30年，是《财富》杂志评选的75本必读书之一。这本《细节》是《影响力》的续篇，它主要从心理学、营销学角度，告诉你影响别人的“理论”。\u003c/p>\u003cp>A：它不讲干巴巴的理论，而是直接用52个套路，告诉你具体该怎么操作。有人开玩笑说，西奥迪尼的书，就是那种你只想自己读，生怕别人读的书。\u003c/p>\u003cp>B：如果你还在用摆事实讲道理的方式说服人或是用苦口婆心喋喋不休的方式影响人的话？相信通过本片段的学习，你会了解影响一个人只需要做个小小的设计，就能轻松地让他人做出行为上的改变。\u003c/p>","ratings_count":2,"texts":[{"id":15134,"quote":"\u003cp> 社会影响的基本原理之一就是承诺和一致性之间的关系。这个原理说的是，咱们绝大多数人都有跟自己许下的承诺保持一致的强烈愿望，如果这个承诺是我们主动做出的、需要我们花力气参与而且被公之于众的，那就更是如此。\u003c/p>\u003cp> 举个例子，研究者曾扮成海滩游客，把一条浴巾和一个收音机放在某个正在晒太阳的人身旁，然后下海去游泳。一种情况下，研究者会请那位晒太阳的人（其实是受试对象）帮忙照看一下收音机。绝大多数人都同意了，并且很友善地做出了口头承诺：“没问题。”第二种情况下，研究者没有请晒太阳的人照看物品就径直游泳去了。此时，真正的实验开始了。另一个研究人员假扮成顺手牵羊的小贼，跑过来一把抓起收音机就跑。获得对方口头承诺的小小举动对结果（瞧见这一幕的晒太阳的人是否会起身去追）造成了巨大影响。在研究者没有要求口头承诺的情况下，20个人里只有4人阻止；在研究者提出请求的情况下，20个人里有19个都采取了行动。为什么？因为他们已经答应要遵守承诺，起身追小偷是完全符合刚才那个口头承诺的。\u003c/p>\u003cp> 如果像“请求口头承诺”这么小的一个改变就能这么明显地遏制海滩上的盗窃行为\u003c/p>\u003cp> 任何一个想劝说他人做出多重并互相关联的行为改变的人，可以通过一个简单的两步法把成果最大化。第一步，确保最初的承诺是具体明确的。第二步，确保在实践该承诺的环境中，放置一个“提示”，这个提示应该完全符合第一步中的具体承诺，并且能够引发出另外一些与此承诺相关的、符合你期望的行为。\u003c/p>\u003cp> 咱们来看一个例子。比如说，你是个办公室经理，你面对的问题是不仅要倡导员工更加积极地回收利用物品，还要降低办公室的总能耗。上述发现，你应该首先请员工们做出一个针对某项行为的具体承诺（比如每天晚上下班后把废纸放进回收纸篓）。然后，你应该在一个能够提醒大家节约能源的地方放上一个“提示”（比如把回收纸篓放在电灯开关的附近）。这样做很可能会有一箭双雕的效果。如果你把一张写着“勿忘环保承诺，请随手关灯”的小卡片放在灯旁边，还能进一步取得更好的效果。事实上，在兑现承诺这件事上，还有两点也很关键：这个承诺是否以行动为导向；该组织或个人做承诺时的公开程度如何。\u003c/p>","explains":"\u003cp>（what）相信在座的小伙伴都被放过“鸽子”吧？就是说好的事没有做到。虽然“放鸽子”大多都不算什么大事，但会严重影响我们的情绪。有没有一种办法可以让他人说到做到呢？拆页中给我们的建议是想办法让对方主动做出个承诺。这个承诺并不一定要正式的书面承诺，哪怕是口头上的承诺或是做一个选择。\u003c/p>\u003cp>（why）因为绝大多数人都有跟自己许下的承诺保持一致的强烈愿望，特别是当这个承诺是他们主动做出的或是公之于众的话就更是如此，这就是承诺和一致性的原理。之所以这个原理有用，是因为外部的舆论让人不想做一个背信弃义者，而来自人内心“自我”和“超我”的约束则令人对承诺极为重视。\u003c/p>\u003cp>（how）因此，在我们寻求他人做某事时，就要想办法让对方主动做出个承诺。\u003c/p>\u003cp>【可能出现的异议】\u003c/p>\u003cp>1.可能有小伙伴会有疑问，那承诺一致和服从有什么区别呢？\u003c/p>\u003cp>承诺一致性的关键在于主动承诺，而服从是被迫的承诺。它们之间的内在动力是不同的。\u003c/p>\u003cp>举个我们家女儿的例子，上周我很我女儿说，“你觉得自己的桌面乱吗？”她回答：“我觉得挺乱的。”“那你觉得，怎样能让桌面整洁点吗？”她说“我每天做完作业就整理桌面，这样就不会乱了。”我说：“太棒了！我很期待你的效果哦！”这周她的桌面一直保持的很干净。\u003c/p>\u003cp>2.可能还有朋友会说，有些人即使做了承诺还是会有做不到的情况出现，这时该怎么办呢？\u003c/p>\u003cp>首先，让这个承诺指向具体的行动。然后，确保在实践该承诺的环境中，放置一个“提示”，这个提示应该完全符合第一步中的具体承诺，并且能够引发出另外一些与此承诺相关的、符合你期望的行为。\u003c/p>\u003cp>还以我女儿整桌面为例，在她做了整理书桌的承诺后，我拍了张桌面整洁的照片，然后打印出来贴在她的书桌上方，以此来提醒她。\u003c/p>","interaction":"\u003cp>接下来，请大家想一下，未来一周你有什么事需要他人帮忙完成，或是让别人接受你的请求或者提议的场景？比如工作中遇到的问题需要同事或领导出面处理的，生活中希望另一半帮忙多干点家务，让孩子改掉某个坏习惯啊等等。给大家1分钟的时间思考下。\u003c/p>\u003cp>\u003cbr>现在你学习了新技能，你可以怎样应用刚才学到的方法让对方比较容易接受并能达到预期的目标？请用便签记录，时间是2分钟，完成请举手示意，然后用3分钟左右的时间在小组内分享。\u003c/p>\u003cp>学习者宁宁分享：\u003c/p>\u003cp>我想让我妈能够少给我打电话将的给我打电话的频率。我会用这次学习到的步骤，首先，我会跟我妈讲为什么不要给我打电话的原因，然后，请妈妈主动承诺降低打电话的频率，比如，答应从原来的一天三次到一周三四次。为了提升效果我还会请我外婆等家人在场。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1616475785000,"updated_at":1621058879000,"ria":true},{"id":9359,"topic":"如何有效表达感激","learn_goal":"","remark":"《细节：如何轻松影响他人》是世界百万级畅销书《影响力》作者罗伯特·西奥迪尼的全新力作，书中列举了52个微小却重大的影响力提升技巧，告诉你如何在如今这个充满“套路”的时代里用最小的细节改变成就结果上面的差异变化，并成功影响他人。","level":"3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"武小茉","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"\u003cp>活动开始前分组，坐对面的人两两一组。\u003c/p>\u003cp>&lt;开场&gt;大家好，我是陈茉，今天要分享的内容来自这本书——《细节：如何轻松影响他人》。\u003c/p>\u003cp>\u003cstrong>&lt;场景介绍法&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>事件：\u003c/strong>在我们的日常工作和生活中，经常有被人帮助的时候，比如你最近对早起赖床这个问题感到无语，想着怎么解决一下，然后小王同学知道后分享了不赖床的方法给你，然后你经过实践，顺利的解决了这个问题。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>受到了他人的帮助，这种情况你一般都是怎么去做的呢？你会说些什么，做些什么，结果又是怎么样的呢？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>我们每个人都会有帮助别人和被人帮助的时候，如果被人帮助了，心里很感激，却没有真诚的表达出来，别人可能会想这个人在敷衍我，或者是想这个人不知道感恩，以后再遇到需要帮助的情况，就要慎重考虑下了。长期下去，会直接影响到他人对我们的评价，对我们的升职加薪、人际关系都有影响。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>这本书提到的有效表达感激的方法，在感谢时只需要作出一点小改变，就能帮你达到有效表达感激的效果。\u003c/p>\u003cp>\u003cstrong>&lt;学习目标&gt;\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够使用选择表达方式+描述具体行为+描述感受的步骤（澄清）来有效的表达（行为）自己对他人的感激（界定）。\u003c/p>","ratings_count":1,"texts":[{"id":13152,"quote":"\u003cp>但值得追问的是，在实验室之外，在快节奏的、真实的职场环境中，这些令人印象深刻的发现是否仍能再现？格兰特和吉诺觉得应该可以，因此他们打算测试一下，真诚的感谢是否能对员工的工作积极性产生正面影响。他们把实验地点选在了一个募集资金的呼叫中心，因为他们知道，筹集资金的工作得到的感谢格外少，工作人员往往得到的是拒绝和消极的反应。\u003c/p>\u003cp>实验中，一半员工照常上班，没受到任何干预，这是对照组。但是，另一半员工上班的时候，筹款项目的主任来到呼叫中心，感谢他们所做的工作。主任特别表明，“\u003cstrong>我非常感激各位的辛勤工作。我们真诚地感谢大家对学校做出的贡献。\u003c/strong>”就这么多。没有握手，没有拥抱，没有答谢礼物——只有这几句大白话，区区几十个字而已。\u003c/p>\u003cp>研究人员记录了干预发生前后这些员工们呼出的电话数量。在接下来的一周里，对照组的员工拨出的电话与往常持平，而得到感谢的那一组拨出的电话比平常多了一半还多。想想这个微小却重要的改变造成的影响吧。就算这些多打的电话成功率跟平常一样高，但光是数量的增加，也能提升捐款的数额了。\u003c/p>\u003cp>这项研究告诉我们，小小的一个\u003cstrong>表达感激\u003c/strong>的举动，看似不起眼，却能造成如此积极的影响。虽然说表达感激似乎是应该的，但想想看，你是不是经常机械地说一句“谢谢”，却没有把感激的程度真诚地表达出来？或者是不曾解释你感谢的缘由？有多少次你想要给别人写一张致谢的便条，却不知为何总是忘掉？你不仅错过了\u003cstrong>真诚感谢\u003c/strong>别人的机会，也错过了在日后更容易影响他人的机会。\u003c/p>","explains":"\u003cp>\u003cstrong>&lt;why&gt;\u003c/strong>当我们真诚的向帮助我们的人表达感激时，对方就能感受到这种价值感，也会获得一些成就感，更加愿意去帮助他人，因为每个人都希望自己是有价值的，是对他人有用的人。而且表达感激也能拉近彼此之间的距离，使人际关系更加和谐美好，想象一下，假如我们收到了他人对我们的感激，我们是不是也会非常高兴的。\u003c/p>\u003cp>&lt;what&gt;片段中主任对员工感谢带来好的改变，在于主任真诚的表达感激这种行为，是对员工付出的一种肯定和认可，能为员工带来价值感、好的情绪和积极的影响。所以我们要真诚的向他人表达出自己的感激之情。\u003c/p>\u003cp>\u003cstrong>&lt;概念对比&gt;\u003c/strong>\u003c/p>\u003cp>为了更好的理解普通的表达感激与有效的表达感激，我们看一下以下的例子：\u003c/p>\u003cp>1、小A帮了你打印了一份紧急文件，你在心里觉得很感激他对你的帮助。\u003c/p>\u003cp>大家觉得这是有效表达感激吗？不是，你虽然感激他但是并没有表达出来，对方根本不知道你是有感激之情的。\u003c/p>\u003cp>2、小A在你不在公司时，帮你发了快递，你对他说“谢谢你帮我发快递”。\u003c/p>\u003cp>这个是有效表达感激吗？不是，更多的是在陈述事实，对方确实帮我们做了这件事情，但是然后呢？就没有然后了，加上行为之后显然比单说一个谢谢要好很多，因为对方能够清楚的知道我们感谢的是他的哪些行为。而且平时对帮助我们的陌生人，我们也会说“谢谢”，但更多的是一种礼貌行为，所以这是普通的感激，而不是在有效的表达感激。\u003c/p>\u003cp>3、小A有一个很好的学习资料分享给了你，你对他说：“谢谢你分享资料给我，真开心你能想到我，我最近也正想学习这方面内容。”\u003c/p>\u003cp>这是一个有效表达感激的例子，把对方帮助我们的具体行为、自己的感受、心情表达给对方。\u003c/p>\u003cp>通过上述的小例子，可以看出有效表达感激有三个要点，表达，描述行为，描述我们的感受。有效表达感激相比普通的感激，是清晰的说明了对方帮助我们的具体行为和我们的感受的表达方式，能够让对方更加容易的感受到，我们是在事实的基础上表达感激，对方会更容易感受到我们的真诚。\u003c/p>\u003cp>\u003cstrong>&lt;how&gt;\u003c/strong>\u003c/p>\u003cp>如何有效表达感激？\u003c/p>\u003cp>1、选择表达方式，如果我们不表达出来，对方怎么能知道呢？表达的方式可以是口头或文字两种，口头是直接告诉对方，文字可以通过微信或短信、邮件发送给对方。\u003c/p>\u003cp>2、描述对方帮助我们的行为，对方做了哪些事帮助了我。\u003c/p>\u003cp>3、描述感受，我的心情、感受是怎么样的，向对方传达积极的情绪，显出你的真诚。\u003c/p>\u003cp>只有真诚的表达出我们的感激之情，才能使对方知道他的付出是有价值的，是对我们很有用的，才会让他更加有可能去帮助更多的人。\u003c/p>\u003cp>&lt;正面案例&gt;\u003c/p>\u003cp>前段时间年会的时候，第一天晚上卧谈会结束的很晚，当时天刚降温，还有点下小雨，我本来没有预定住宿，后来娟娟说你一个人太晚了就别回去了，跟我们一起住吧，当时就觉得很暖心，而且我后来也确实不太想自己回去了，就一起住下了。之后发微信告诉她：“谢谢你收留我，特别开心能跟你一起住。”现在回想起来也很感激她。\u003c/p>\u003cp>\u003cstrong>&lt;适用边界&gt;\u003c/strong>\u003c/p>\u003cp>适用于对方帮助了你，让你觉得有感动和触动的时候，无论是领导对下属还是亲人、朋友都可以使用。\u003c/p>\u003cp>\u003cstrong>&lt;预防异议&gt;\u003c/strong>\u003c/p>\u003cp>听到这里，大家可能对到底什么时候使用还是会有点疑问哈，比如恋人、家人可能每天都会帮你做一些事情，是不是都要这样去表达呢？看具体情况，建议在对方帮你做了一些你很感动的事情上，一定要积极表达，把对方的具体行为和我们的感受大胆的传达给对方，对方收到了，也会很开心的。\u003c/p>","interaction":"\u003cp>\u003cstrong>拆家提问设计：\u003c/strong>\u003c/p>\u003cp>接下来请大家设想一下，在未来的一周或一月内，你可能会遇到别人帮助了你的场景：比如你有很多的工作要忙，同事在忙完自己的事情之后过来帮你一起做，或者跟朋友一起参加活动，住的比较近，回家打车时载你到家等等。把你想到的场景编成一个剧本。在什么时间、什么地点、都有哪些人物、发生了什么事情，要有起因、经过、结果的对话。给大家7分钟时间。\u003c/p>\u003cp>\u003cstrong>要求：\u003c/strong>在对话中用到选择表达方式+描述具体行为+描述感受的步骤表达感激。\u003c/p>\u003cp>谢谢两位小伙伴的分享，通过小伙伴的伙伴，我们平时表达感谢可能更多的是一句“谢谢”，对方就不是很能感受到我们感谢的点，像这样有步骤的表达感谢就会让对方更加清楚具体的明白。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1575037082000,"updated_at":1576460514000,"ria":true},{"id":7968,"topic":"如何设定更容易长久落地的目标？","learn_goal":"学习者能够学会调整目标设定方式，达到长久落地坚持目标的效果。","remark":"","level":"TF2-1","duration":30,"status":29,"type":0,"chaishujia":{"username":"马子喻","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家晚上好，我是马文丽，欢迎大家来到今天我的TF2-1的拆书分享，在跟随我完成本次RIA现场学习后，学习者能够学会调整目标设定方式，达到长久落地坚持目标的效果。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>今天我要拆的片段来自这本书《细节：如何轻松影响他人》，【F】这本《细节》作者是罗伯特·西奥迪尼、史蒂夫·马丁、诺厄·戈尔茨坦3个知名说服力与影响力的研究权威，书里讲了52个“四两拨千斤”改变细节的套路。\u003c/p>\u003cp>【A】这是一本令人惊奇、强大、具有深刻内涵的实用型人生工具书，完整且细致地揭示了失败和成功之间存在着的细节差别，它3个月内就达到了近10W册的销量，并获得英国皇家学会奖。\u003c/p>\u003cp>【B】 如果你曾经设立了小目标在执行的过程中中断，你重拾目标后仍然没有干劲儿，那这本书就从一个细小的细节改变可以让你在重拾目标后干劲儿更足。同时在职场沟通、员工激励、商业谈判、家庭教育等工作和生活领域对你产生持续且深远的超级影响力\u003c/p>\u003cp>【分组】现在我们按座位每3个人一组\u003c/p>","ratings_count":1,"texts":[{"id":11529,"quote":"\u003cp>书目：《细节》作者：史蒂夫·马丁，诺厄·戈尔茨坦，罗伯特·西奥迪尼\u003c/p>\u003cp>页码：P98-P99\u003c/p>\u003cp>1919年，在《堪萨斯城星报》（Kansas City Star）画政治漫画的沃尔特·迪士尼（Walt Disney）被解雇了，报纸编辑的话是：“他不是太有创意。”\u003c/p>\u003cp>2012年，英国生物学家约翰·戈登爵士（Sir John Gurdon）因对生理学和药学的杰出贡献获得了诺贝尔奖。可当年他在伊顿公学的校长却在成绩单上这样写道：“我相信戈登想当个科学家，可照他现在的表现看，这想法颇为荒谬。”\u003c/p>\u003cp>好莱坞有个传说，弗雷德·阿斯泰尔（Fred Astaire）去雷电华影业（RKO Pictures）试镜时，一个制片经理把他刷了下来，理由是：“（他）不会表演，不会唱歌，有秃顶迹象，会跳一点儿舞。”\u003c/p>\u003cp>令人欣慰的是，这些早期的挫折都没能阻拦他们追求自己的目标。上述三人全部获得了惊人的成就。但有些时候，人们的确会分心，会忘记目标——不是未来的诺奖得主和好莱坞偶像心目中那种宏伟的、一辈子只有一次的、梦工厂式的目标，而是虽然小一点儿却依旧十分重要的、日常生活中的目标，比如多存一点儿钱，减掉几斤肉，还掉信用卡，或是达到这个月的销售目标。\u003c/p>\u003cp>人们往往需要重新拾起之前为自己设定的目标。同样，管理者、团队带头人、老师甚至是父母，有时候也需要帮助员工、学生和孩子鼓起干劲儿，再次为了原先的目标而努力。按常理，当我们为自己或他人设定新目标的时候，经验总是告诉我们，要把目标设定的非常具体。比如，每周减掉2磅（约1.8斤）体重，1小时跑6英里（约9.6公里），或是每个月存下100美元，作为来年的度假基金。但是，当我们说服自己或他人重拾目标的时候，这个常识是否正确呢？\u003c/p>\u003cp>营销学教授毛拉·斯科特（Maura Scott）和斯蒂芬·诺里斯（Stephen Nowlis）认为，虽然人们在直觉上感到，在首次制订目标时，应当把他量化为单一而具体的数字，但是，在重拾先前的目标时，这样做就未必最好了。相反，这两位学者认为，比起单一的具体数字[比如每周减掉3磅（约2.7斤）体重]，把目标改成一个上下浮动的数字范围[但平均值跟原先的数字一样，比如每周减掉2-4磅（约1.8~3.6斤）]，会更加有助于人们鼓起干劲儿，重新投入。\u003c/p>","explains":"\u003cp>好，大家都看好了，内容不多，且非常容易理解。我们都有那些虽然小一点却依旧十分重要的、日常生活中的目标。首次在设定目标的时候，经验总是告诉我们，把目标量化为一个具体的数字，但在目标执行落地的过程中，我们往往难以坚持，以为具体的数字看似简单，实则没那么容易每次都达到。这种时候，想要重新投入后更加有干劲儿，要怎么办呢？我们需要调整一下目标的设定方式。第一步保证平均值和原先一样，第二步把目标改成一个上下浮动的数字范围，这样会有助于我们鼓起干劲儿，重新投入。\u003c/p>\u003cp>\u003cstrong>【不做这么做的坏处】\u003c/strong>如果不这么做的话，在我们执行这些虽然小但是很重要的目标的过程中，目标一旦中断，我们还按照以前的具体的数字重拾目标时，会越来越没有干劲儿，不但丢掉了这些虽然小但很重要的目标，而且还会产生负面情绪，影响自己的生活和工作。\u003c/p>\u003cp>【A1】\u003c/p>\u003cp>这里分享一个自己的经历。半年前，我和一个伙伴约定好，每周跑步3次，坚持了快一个月的时间，这个习惯就彻底丢掉了。本着爱美和健康的目标，没过多久，我们再次约定好，重拾目标，重新开始行动，结果情境几乎和之前一模一样，坚持了还不到一个月就再次丧失了跑步的干劲儿，而且两个人甚至要开始自我怀疑，产生了负面情绪。\u003c/p>\u003cp>【A1+】\u003c/p>\u003cp>直到我遇到了这个拆页，在读了《细节》这本书的这个拆页以后，我和伙伴重新调整了目标的设定方式，第一步在平均值和之前的数字一样的前提下，保持平均值是每周3次，第二步，我们把目标改成一个上下浮动的数字范围，调整为每周2-4次的目标。就这样，我们重新投入，每周跑步2次的这个小目标，很轻松的就达到了，每周跑步4次，在偶尔两个人工作都不太忙的阶段也能实现。不论是跑2次，3次还是4次，因为都属于在目标范围内，可以都算作是我们实现了当周的目标，我们比之前更加容易实现设定的目标。现如今，我们调整目标以后，已经执行了新的目标快两个月的时间，而且热情丝毫不减。\u003c/p>\u003cp>正如拆页的建议中所说，生活中这些虽然小但仍然十分重要的小目标，在重拾目标时，在平均值和原来的数字一致的情况下，把一个具体数字的目标调整为一个上下浮动的范围的目标，可以让我们更容易坚持和实现自己的目标。\u003c/p>","interaction":"\u003cp>【A1激活经验（显像提问）】：\u003c/p>\u003cp>拆书家提问设计（逐字稿）：下面请大家回忆一下，你有没有遇到这类似工作或生活的场景，例如：你曾经设立了每天背20个单词的小目标、每天步行1W步、每天写工作日志等，但是发现坚持了没几天就又没有了干劲儿？\u003cbr>\u003c/p>\u003cp>请把曾经设定了具体的目标，但是执行过程中，重拾目标后来干劲不足这样的场景简单地写到便签上，1分钟时间，写好的请举手示意。好，现在开始&nbsp;\u003c/p>\u003cp>【学习者案例记录】：\u003c/p>\u003cp>仇玉娟：6月底7月初，天刚热的时候，大家也知道男的也想减肥，女的也想瘦身。我和我老公计划减肥，怎么办呢，健身房不方便，于是在手机上下载了APP，keep健身，根据自己的体型和工作时间，去下载了适合自己的运动，一开始我还蛮好的，每天在手机上坚持20分钟就可以了，在室内不需要器械的运动。结果他坚持了一个星期多，我坚持了四五天就放弃了。然后APP每天提醒我，但是提醒我我也是无视它。\u003c/p>\u003cp>【A1+，反思加工】\u003c/p>\u003cp>拆书家提问设计（逐字稿）：好，感谢这位伙伴的分享，那现在的话呢，如果让你乘坐时光机，穿越回刚刚提到的A1重拾目标的场景，根据刚才拆页的建议，最好怎样设定刚刚大家写下的曾经的目标？1分钟的时间给大家书写，写好后给大家3分钟时间在小组内分享一下你们的案例。\u003c/p>\u003cp>（4分钟后）好，时间到，我们请一位伙伴进行一下目标调整后的分享。\u003c/p>\u003cp>【学习者案例记录】：\u003c/p>\u003cp>李朋三：以前我背单词，后来就停下来了，原来定的单一而具体的目标是100个，现在觉得50个比较合适，后来定了50个，有时候因为时间关系坚持不了，于是定了45-60之间，这个比较适合我。\u003c/p>\u003cp>秦琰旻：我以前给自己定的目标每天走一万步，像我今天就没有完成，然后学了这个拆页，我想可能我可以把目标订成平均的一个状态，今天没有完成，明天可以多走一点，，接下来我会这样调整。\u003c/p>\u003cp>好，感谢两位伙伴的分享，那生活中我们经常设立一些虽然小但很重要的目标，我们往往把这个目标设立为具体的数字，在重拾目标的时候，有些时候我们会经常没有干劲儿。第一步保证平均值和原先一样，第二步我们把目标改成一个上下浮动的数字范围，这样会有助于我们鼓起干劲儿，重新投入。\u003c/p>\u003cp>今天我的TF2-1拆书分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1558687502000,"updated_at":1558687581000,"ria":true},{"id":7202,"topic":"轻松影响他人的细节","learn_goal":"学习者通过细节的改变来提升自己的影响力","remark":"有没有发现，身边的老人对于公众号的文章观点特别相信；\r\n          我们也很容易被公知大V的理论影响\r\n          这是什么原因吗？同样的方法我们可以如何运用到我们的工作生活中呢？\r\n          本次继续和老牛一起，拆解《细节》第23章——亮出专家身份\r\n          继续学习通过细微的方法改变提升影响力的小妙招","level":"TF2-2","duration":20,"status":29,"type":0,"chaishujia":{"username":"刘天宇","city":"深圳"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"大家好，我是@老牛老刘，现在在一家IT私企公司的担任部门负责人，主要负责公司的品牌传播和品牌管理工作。今天拆解的这本书叫《细节-如何轻松影响他人》，这本书的作者是写《影响力》的罗伯特·西奥迪尼，一个专门研究影响力和说服力的专家。这本书在国内也是非常畅销，仅仅是在《罗辑思维》平台，3个月就卖了10万册。与其他这种讲说服的书很多理论性很强不同的是，这本书中通过52个微小改变的实际案例来阐述“四两拨千斤”的小改变就可以大大提升影响的效果。书中的案例都是基于研究实验的结果，理论有理有据，通俗易懂，每个片段都相对独立，可以集中阅读，也可以利用零散时间阅读。通过阅读这本书，我们可以很轻松的掌握一些影响他人效果更好的一些小技巧。今天带来的这个片段是来自书的第23个片段，讲述的是“专家身份”对于说服对方所起到的重要作用以及可以如何运用。","ratings_count":1,"texts":[{"id":10612,"quote":"\u003cp>研究人员要求受试者做出一系列他们并不熟悉的财务选择，其中有些附带有专家建议（一位著名的经济学家）。当专家建议出现的时候，受试者的选择就会受到明显影响。他们的大脑活动模式揭示了原因。每当专家建议出现的时候，受试者大脑中负责批判性思考和反驳的区域就平静下来，变得不活跃了。\u003c/p>\u003cp>这些发现有助于解释，为什么专家的话总是那么管用。这并不是因为人们会把权威人物的话当作一个普通的重要因素，然后与其他重要因素结合起来考虑，最后做出选择。相反，人们会允许权威的意见统领余下的所有因素（尤其是对自己不太确信的时候）。实际上，人们甚至把认知的渠道都关闭了，根本就不会考虑其他因素。该研究的作者之一这样描述他的发现是如何挑战人们对理性决策过程的传统看法的：“在传统看法中，人们听取建议，然后把它跟自己掌握的信息结合起来，最终做出决策。如果过程真是这样，那我们就应该能看到负责决策的脑区有活动。可我们的发现是，当某人接受了专家建议之后，那个脑区的活动就停止了。”\u003c/p>\u003cp>这些研究给予我们两点启发、沟通者在构思信息时应该兼顾。\u003cstrong>首先，由于人们经常在看到专家建议之后就不再进行批判性思考，反驳的力度也降低了，所以，如果有相关的专家意见可以使用，那就把它们早早摆出来，\u003c/strong>要是不这样做的话，可就有点儿傻了。\u003cstrong>另外，如果目标受众与你团队的其他成员也有交流，那你一定要凸显出这些成员的专业性。\u003c/strong>虽然这个做法很简单，但有多少原本十分精明的沟通者在影响他人时，都忘了强调自己和同事们的专业性啊。\u003c/p>\u003cp>但是，当她们记得这样做的时候，效果往往好的惊人。\u003c/p>\u003cp>举个例子吧。许多医疗中心都面临一个问题：患者太多，可医院的容量不够，没法满足他们的需求。和全世界的许多同行们一样，英国那些新近取得行医资格的医生在毕业之后，会到各种医院和医疗中心里实习轮岗。这种轮岗制度显著提高了医疗机构的服务容量，可患者往往不愿意找这些资历尚浅的医生问诊，他们更愿意等着见住院医师。可问题就在这儿。鉴于这些新医生网刚从国内最顶尖的医学院毕业不久，他们掌握的技能和知识是最新、最前沿的，找他们看病才是好选择一这是很有道理的。为了恢复均衡，不少医疗中心采取了这样的实验做法：重点强调这些新医生的专业资质和前沿知识，往往还在一旁附上他们的照片。前台的接待人员也要发探作用，他们改掉了常见的答复，比如“我可以为你安排一位实习医生”（在医院里，“实习医生”这个词儿给人的印象就跟“代课老师”差不多），代之以凸显新医生专业性的说法，“我可以为你安排一位水准很高的新医生，刚刚从某某医学院过来的。”使用了这些不起眼儿、成本相对低廉的做法之后，供需状况出现了喜剧性改变。有些医院等候时间减少了，往往能缩短50%之多，而这不是由于大规模的系统改革，只是因为一个小小的做法调整。\u003c/p>","explains":"\u003cp>我们说人啊是个特别矛盾的动物，我们总是希望听听别人的建议，但最后的决定却都是我们自己结合各个方面的信息作出判断说服自己的过程。但是，在我们不擅长不确信的领域，研究人员就发现专家建议能够极大影响人们的判断。\u003c/p>\u003cp>咱们现场感受一下，在座有没有炒股的朋友，没有哈，那就好办了。那今天在现场，相逢即是缘分，我给大家推荐一只股票，肯定会涨，这个股票名字是深X服，股票代码是[3XX454]。好了，我想问一下现场的朋友你听完我的推荐你的想法和判断是什么。好，那我再换一种说法，大家有没有听说过美国有一个股神，他叫巴菲特，他在最近的一次采访中说道他最近一直在关注一支中国的股票，这个股票名字是深X服，股票代码是[3XX454]，觉得这个公司近期增长势头非常好。好的，各位伙伴现在你的感受是啥。发现了没有，就是在我们不是很擅长的领域，我们很容易受到该领域专业人士的建议的影响。这就是专家身份的厉害之处。所以让对方感受到专业性在影响对方决策的过程中变得尤为重要。\u003c/p>\u003cp>如何运用，片段中给出2个使用的建议：\u003c/p>\u003cp>（1）在我们沟通的时候，可以尽可能的先收集行业的专家意见，降低反驳的力度，提升我们的内容方面的说服力\u003c/p>\u003cp>（2）有的时候对方可能不仅仅会和你接触，还会和你的团队你身边的人接触或者到你身处的环境中，所以不仅我们自身准备要专业，我们身边的人和事物，能体现整体专业性的，我们都可以加以改进。\u003c/p>\u003cp>说到这个可能有小伙伴就有疑问了，我就最烦那种专家的意见，现在满大街都是各种专家，各种平台上，都是专家一样的人在推荐你买东西，我一看到这种我就直接跳过了，这个方法是不是没有效果？这个考虑非常好，其实这也揭示了这个方法的一个大前提，就是我们在包装自己专家身份的同时，我们首先真的要有这样的专业基础，否则装出来的东西总会被人识破，那以后就再没人会相信你了，失去的就是以后所有的行为被人都不会再信了。像刚才提到了那些大家不喜欢的所谓的专家，更多的是有了专家的样子，但没有大家公认的实力。所以提升内在专业性是我们业务上需要提升的，告知专家身份是锦上添花帮助你更快速获得认可小技巧。\u003c/p>\u003cp>当然我还是要和大家说明，这个方法是提升说服有效性的一个小技巧，提升你被认可的概率，不是100%用了就说服对方的方法，大家可以举一反三，看看可以如何应用。\u003c/p>\u003cp>-------------------------------------------------------------------------------------------------------------------\u003c/p>\u003cp>其实可能在大家身边有用到这样的方法，可能大家并没有注意。我举个例子，在我们公司的销售团队中，新来的销售经过公司的产品和技术培训后，不是像有些公司进来的员工先是从专员开始，印名片的职位title都是经理，在商务场合交换名片的时候潜移默化的提升了对方愿意与你交谈的机会。试想一下，如果在座的各位同时接到2个名片，一个是A公司的经理，一个是B公司的专员，在公司专业性相差不大的情况下，你更愿意与谁沟通。\u003c/p>\u003cp>大家再看这个内容片断，其实也很有心机的运用了这个方法。先用一个实验告诉你这个结论的可信性，接下来让大家接受这个方法也就更容易了\u003c/p>","interaction":"\u003cp>刚才我们通过我的讲解和大家的互动对这个小技巧有了比较深刻的理解，那接下来，就需要大家开动脑筋了。首先我们确定的是我们自己在自己工作的领域或者自己的特长上已经是有一些经验，我们算有一定专业性了，和那些伪专家不一样。我们还是会遇到一些场景在我们的专业领域需要说服对方的？我们想一想有没有遇到过类似这样的情景：可能是在工作上，我们想为对方推荐一款产品，但对方一直很犹豫，迟迟不买；可能你在行业多年，你的老客户却只愿意和你谈生意，但不愿意和你的团队其他成员谈，让他们很困扰，甚至还有点嫉妒你；亦或者是在生活中，有朋友咨询你的意见，碰巧你又是这方面很了解，你在脑海中正在构思如何组织我们的语言来给对方建议，能让对方接受我们的建议，或者你接下来要写一篇自媒体稿件，你希望你写的内容大家都很认同你的观点。大家想想看有没有类似的场景，我们接下来把你想到的要解决的事情在小组内分享一下，给大家4分钟时间。\u003c/p>\u003cp>\u003cstrong>学习者分享：我是做培训的，也兼职做健康管理，主要向朋友或者客户推荐营养品。有一个朋友身体有点亚健康，就想向他推荐我代理的营养品。我一开口就被否决了。他觉得这个药物对他来说缺乏公信力，觉得医生推荐的才专业，沟通了三句就失败了。\u003c/strong>\u003c/p>\u003cp>\u003cb>\u003cbr>\u003c/b>\u003c/p>\u003cp>\u003cb>拆书家确认：这位伙伴，我和您确认下，您说的这个场景，也就是向别人推荐营养品是不是您接下来也会经常发生的场景？（学习者确认是的）好的，那也就是说刚才这位学习者不但想到了一个具体应用的场景，还分享了一个之前不是很成功的案例\u003c/b>\u003c/p>\u003cp>好的。那今天学习的这个方法我们继续回顾一下：第一个是在你专业的领域如果有一些知名专家的言论，我们可以引用作为专业性的佐证；那还有一个就是对我们身边的人也好，事物也好进行专业化的包装打造，从细节让对方感受专业性。那我们在座的各位，可以怎么运用这个方法，应用到大家写的场景中呢？我们还是邀请刚才的伙伴分享一下。\u003cbr>\u003c/p>\u003cp>\u003cstrong>学习者分享：如果让对方能够认知我，要提高产品的高度，提前找到专家的指导建议和名人的使用效果影响力，来提高说服力。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cb>拆书家引导：在个人方面，我们也可以在更多的展现自身健康身体的一方面，让对方能够感受到您做健康管理，您本人就很健康，这样对方就会更信任您的产品。\u003c/b>\u003c/p>\u003cp>\u003cb>\u003cbr>\u003c/b>\u003c/p>\u003cp>好的，本次分享就到这里。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1549793306000,"updated_at":1549793306000,"ria":true},{"id":6787,"topic":"试一试两部法，让你的建议更容易接受","learn_goal":"试一试两部法，让你的建议更容易接受","remark":"工作，生活中，我们有很多需要说服别人的场景，有的人可以很轻松的实现。\r\n\r\n而有的人费了九牛二虎之力也没有让对方接受自己的建议。\r\n\r\n两种结果，可能只是因为缺乏了一个小小的技巧。\r\n\r\n如何提升自己说服别人的概率，和老牛一起来了解一下\"两步法\"。","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"刘天宇","city":"深圳"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"大家好，我是@老牛老刘，现在在一家IT私企公司的担任部门负责人，主要负责公司的品牌传播和品牌管理工作。今天我带给大家的这本书叫《细节-如何轻松影响他人》，这本书的作者是写《影响力》的罗伯特·西奥迪尼，一个专门研究影响力和说服力的专家。这本书在国内也是非常畅销，仅仅是在《罗辑思维》平台，3个月就卖了10万册。这本书不是一本理论型教科书，这本书通过52个实际案例来传递通过细微的改变可以起到“四两拨千斤”的、提升影响的效果。书中有案例，有实验，有方法论，可以说是有理有据，通俗易懂。而且这本书还有一个好处，就是每个片段都相对独立，可以集中阅读，也可以利用零散时间阅读。通过阅读这本书，我们可以学习到原来我们只需要在我们以往的情境中做一些小小的改变就可以提升个人的影响效果。今天带来的这个片段是来自书的第17个片段，来看看如果我们想要更容易的让对方接受你的建议我们可以如何来改变我们的提出建议的方法。","ratings_count":1,"texts":[{"id":10142,"quote":"\u003cp>研究人员发现，通过一个两步走的方法，就能够增强默认策略的效果。他们把这个方法叫做“增强版主动选择”。“增强版主动选择”第一步是对默认设置做个小调整：\u003cstrong>人们面对的不再是“要么接受，要么放弃”，而是可以在两个选择中真正挑选出一个。\u003c/strong>\u003c/p>\u003cp>在一个实验中，凯乐和同事们把一组教职员工分成两组。两组人得到了一个打流感疫苗的机会，这不仅能保护他们的健康，还能替他们节省每个月的健康保险费用。\u003c/p>\u003cp>第一组（“接受或放弃”组），面对的要求很简单：“如果今年秋天你想打流感疫苗，就在此处打钩。”但第二组面对的不是一个替他们做好了的默认选择，而是一个主动二选一的机会：“今年秋天我要打流感疫苗”，或者“今年秋天我不打流感疫苗”。\u003c/p>\u003cp>结果显示，比起“接受或放弃”组（愿打疫苗的人占42%），主动选择组有更多人（62%）愿意打疫苗。这个实验提供了明确的证据：虽然接受或放弃的方法有道理而且有效，但再做一个小小的调整——\u003cstrong>请人们主动做出选择\u003c/strong>——能够带来更大的成效。\u003c/p>\u003cp>但研究者们并不满足，他们还想知道，能否把主动选择的方法在提再升级一下？他们在说服科学的另一个基本原则中找到了答案，这个原则就是损失规避。也就是说，人们有避免失去的强烈倾向。研究者们把这个倾向运用起来，测试了主动选择的升级版：\u003cstrong>向人们指出，如果他们不采取行动，就会损失什么\u003c/strong>。\u003c/p>\u003cp>这一组的受试对象需要在以下两个选项中挑一个：“今年秋天我会打流感疫苗，因为我想降低得流感的风险，并且节省50美元。”或者“今年秋天我不打流感疫苗，即便者意味着我得流感的风险可能会提高，而且无法节省50美元。”\u003c/p>\u003cp>把主动选择跟具体的损失结合起来，这么一个小小的举动造成了极大的差异：75%的人要求打疫苗。\u003c/p>\u003cp>\u003cstrong>无论你的目的是什么，两步法的关键都是一样的。首先迈出一小步，构思两个选择，让受众从中主动挑一个。然后，再多往前迈一小步，把你想让他们选的那个选项包装一下——向他们指出，如果不这么做的话就会损失什么。\u003c/strong>\u003c/p>\u003cp>这两个小小的改变会让结果大不一样。\u003c/p>","explains":"\u003cp>其实内容比较简单我们来看看如何理解。其实讲的就是我们在很多场合向别人推荐做选择时，一般都是希望达成一个你设定的结果的，但成功的概率不确定。这个不确定可能有很多因素决定，可能是内容本身不行，可能是需求不强烈，也有可能是对方都没完全了解你的推荐。但这个不是片段讨论的重点，重点是我们为了增加这个对方接受你的推荐的概率和效果，是有一个技巧的，就是”两步法“。\u003c/p>\u003cp>\u003cstrong>（1）构思两个选择，让受众可以从中主动挑一个。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（2）把你想让他们选的那个选项包装一下——向他们指出，如果不这么做的话就会损失什么\u003c/strong>\u003c/p>\u003cp>【考核点-不这么做的坏处】+【考核点-自身反例】\u003c/p>\u003cp>有的伙伴可能问，这个方法为什么有效，以往的方法有什么不好呢？\u003c/p>\u003cp>给举个大家常见的例子，就是片段第一句提到的默认策略的例子。我们去某一个网站注册会员，会弹出您已阅读该协议的界面，并且已经打够了，点击下一步就注册成功，取消勾选就无法通过。相信 90%以上的伙伴会选择同意。这个案例确实通过给对方设定了必选增加了注册的概率，但是这个过程中用户并没有主动选择主动承诺的参与感，对于自己同意的协议的内容也不是很上心的，最终的效果也是不理想的。所以就会有人注册了会员之后做出一些违反平台规定的事，比如发布了一些违规的内容。所以需要让对方有可以主动选择的感受。\u003c/p>\u003cp>再说一个我自己的案例。去年我家里的房子马上装修完了的时候 ，接下来要家电采购。老婆本身就在家电零售企业，我就想说服她去公司买优惠家电，我是这么说的：“老婆你帮我看看你们公司有没有优惠的家电，别忘了啊”。当时我得到的老婆的答复就是：“我们的都比较高端的，优惠我们也买不起”这个案例更极端一点，连选择这件事有什么好处都没和对方说，所以得到的当时的反馈就是拒绝。那我们想想为什么说会损失什么效果更好。这其实是人的一种心理——损失规避。人们都有避免失去的强烈意向。——大家感受一下“苹果手机只要998”和“苹果手机只要998，仅限3天”哪一个更能引起你掏钱买单。\u003c/p>\u003cp>\u003cstrong>所以这个事如果让我再处理一次，我可能会这样说：“咱们要买家电了，我们可以去你公司买，也可以去网上买。不去你们店买的话不能给你算一点销售业绩，就损失一些奖金了。&quot;\u003c/strong>\u003c/p>\u003cp>所以这个方法高明之处就在于让对方既参与进去感受到的是自己的选择，更容易重视自己的承诺，同时又利用了人的“损失规避”心理让对方更坚定的选择，我们期望得到的结果。这个方法我们可以用在商务谈判、家庭沟通、产品设计等等很多的需要“说服”对方选择我们设定好的方案的场景。&nbsp;\u003c/p>\u003cp>这里也和大家强调一下，片段提到的方法是提升成功的概率，并不是一个百分百行之有效的方法。\u003c/p>","interaction":"\u003cp>【考核点4-显像提问】我想讲到这里伙伴们可能脑海中都浮现出一些场景和经历了。那接下来，大家跟着我一起来回忆一下：最近3个月里，在公司的工作或者在家里与家人沟通时，在我们身边是否发生过我们希望别人按我们的建议的做但最终却没成功的场景呢？可能是我们给客户推销一个你公司的产品？可能是你想让朋友和你一起去看一场演出？抑或是你和供应商就产品价格僵持不下？当时的情况是怎么样的？我们每位伙伴先用1-2分钟自己在脑海中回想一下自己的经历，然后按照”时间+地点+人物+具体情形“这几部分复述出来当时情况是怎样的。\u003c/p>\u003cp>好的，看到好多个伙伴好像眼神一亮，可能是想到了一些场景哈。我们请两个伙伴分享一下她的经历\u003c/p>\u003cp>\u003cstrong>学习者A：之前，我想说服妈妈买一份保险，和他普及了很多保险的好处，说每个人都要有一份保险，以防万一。最后妈妈很排斥，没有接受我的建议。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者B：周末，我想自己带两个孩子去外面转转，好让妈妈可以在家收拾收拾家里，顺便也可以休息休息，带孩子很辛苦。就和孩子没说带他们出去玩，没说具体去哪里，女儿很痛快的答应了，儿子比较粘妈妈，就死活不去。最后说那你选吧，是出去还是宅在家里，最后儿子说在家，对话过程中没有提到出去的好处和不出去的损失。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>那我们既然学习了今天的方法，大家会如何利用它，在以后在遇到这个情况的时候，运用我们的这个两步法来让对方更容易接受你推荐的建议呢？（我们思考一分钟）可以把结论写在自己的纸上。写完之后我们再邀请刚才和我们分享经历的哪位伙伴说一下你的两步法是如何做的。\u003c/p>\u003cp>\u003cstrong>学习者A：我会和妈妈说，如果后期生病，花的钱会更多。那现在我们花200-300一个月做自我调养，用科学的方法检测，看看效果，可以省下一笔钱。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家：您的两步法，第一步没有说出来，其实是告诉妈妈可以选择买保险也可以选择不买，但是如果不选的话损失的就是后续的金钱投入会比较多。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者B：第一步还是给选择，可以选择出去或者不出去，第二步就会说一下出去的细节，我会带你们先去书城，吃冰淇淋，再去游乐园玩，要是不去的话，就都没有了。\u003c/strong>\u003c/p>\u003cp>好的谢谢，看来你已经掌握了今天的方法。\u003c/p>\u003cp>我们说拆书学习最大的价值在于学以致用，希望今天我们在座的小伙伴今天结束学习之后可以继续找寻这个方法应用的场景并且多多实践。当然您可以选择实践，也可以选择今天有收获就够了，可是如果您不去实践的话，您可能就失去了让自己变得更有影响力的机会。好，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1545027280000,"updated_at":1545027280000,"ria":true},{"id":6670,"topic":"回应感谢的方式","learn_goal":"学会回应感谢的方式，促进互助更多的发生","remark":"如果期望在遇到困难需要帮助的时候，周围的援手很多，可以在平时回应感谢的时候，恰当的使用巧妙的话语，给对方以暗示。","level":"TF2-2","duration":20,"status":29,"type":0,"chaishujia":{"username":"小新","city":"北京市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我是小新，目前正在读《细节》这本书，\r\n【F】它是罗伯特·西奥迪尼联合另外两大说服力专家一起写的一本关于如何提升自己影响力以及说服技巧的工具书，里面的52个方法经济高效又符合伦理。\r\n【A】和同类书相比，这本书里的方法简单、容易上手。\r\n【B1】比如，用书里的方法更改过的目标，我更乐意的去完成，我使用书里的方法做的提议，别人会积极响应、帮我完成。\r\n【B2】我也希望各位能用到书里的方法，在平时说话的时候，加、减几个关键词，让你的运气变更好。比如，当你需要帮助时，大家都乐意伸把手。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":10011,"quote":"\u003cp>如果在工作中做一个豪爽大方的给予者能够为我们赢得较高的社会地位，却同时也削弱了我们做分内工作的生产能力，我们应该怎么做才好？弗林的另一项研究给出了确定的答案。这项研究发现了一个不起眼的指标，却能够同时增强助人者的社会地位和生产力。这个指标不是帮忙的次数，而是“互助”的次数。先是为对方提供有益的帮助，然后得到对方回报过来的有益帮助，这会把给予的良好效益放大到最大程度--不但他们自己受益，有份参与的每个人都能受益，因为给予者的地位提高了，生产力也提高了。请记住，这个结果与互惠原理是高度一致的，互惠原理对所有成功的群体来说都至关重要，因为它促进互助互利的行为。\u003c/p>\u003cp>这些成果给了我们明确的启示。\u003cstrong>首先，我们应该大方主动地在工作中帮助他人。\u003c/strong>要注意，最重要的一点就是你要第一个行动。第一个出手相助会激活互惠原理，并因此增加未来的互助次数--对于职场中的共同成功，这个因素至关重要。&nbsp;&nbsp;\u003c/p>\u003cp>&nbsp;\u003cstrong>第二，要把你提供的帮助或有价值的信息做个定位，把日后对方可以全力回报你的可能性凸显出来\u003c/strong>。这就需要我们把平素的反应，也就是听到对方感谢我们时，我们所说的话，做个微小却重要的调整。这个调整能为你的未来合作和影响行为带来惊人的巨变。以下就是我们推荐的三种应答方式，用它们来回应对方对你的感谢：&nbsp;\u003c/p>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>、“能帮上你的忙我很高兴，因为我知道，当一个人需要帮忙的时候 ，别人的一双援手是多么有价值。”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>、“不客气。同事之间理当如此。”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>、 “没关系。因为我知道，如果需要帮助的是我，你也会这么做的。”\u003c/strong>&nbsp;\u003c/p>\u003cp>总结一下，想要从职场中的给予行为中得到最大的益处，关键的做法就是“为互助留出余地”，这需要两个很小却至关重要的步骤：率先提供帮助、信息或服务；一定要在回应对方时，明确地为你提供的帮助定位--这是一个自然的、平等的互惠行为，这样你就为日后的互助留出了机会。\u003c/p>","explains":"\u003cp>看大家基本读完了，原文片段告诉了我们：\u003cbr> 如果你想让你自己、你的团队得到的“帮助”越来越多，只要两步：\u003cbr> 1、率先提供帮助。\u003cbr> 2、在回应对方感谢时，强调帮助是相互的。\u003cbr> 特别是你如果想让你的帮助对象在未来，可能时，也提供给你些方便，那就在“不客气”之后，加上“相互帮助是应该的”这样的话。\u003cbr> 【预防异议】这样回应，可能你觉着矫情，或者我就不图回报。如果你认为原来的方式就可以了，那也很好。如果你想运气变更好，在你需要帮助时，乐意帮你的人变多，那么你不妨常用这方法。\u003cbr> 【举例】说个例子，前几天我帮邻居看了下暖气检修，他来说谢谢时，我除了说“应该的”之外，还用片段里的方法，补了句“邻里之间嘛，我需要时，你也会帮我的，不是吗？”这事情之后，他见我打招呼时，就会加上一句，“有需要，您说话。”他这样的回应，也让我感觉到温暖和善意。\u003cbr> 所以，在回应对方的感谢时，请清晰表达出帮助是相互的，在你说完不客气，小意思，之后，加上“相互帮忙理所当然”这样的话，会给你带来一些意想不到的收益。尤其是在工作中，也许你就会得到一些非常有用的关键信息。\u003cbr> 【适用边界】另外，我个人认为，在工作中，如果事情本来就是应该你做，别人就是跟你客气一下，说谢谢，这种情况就不用再说相互帮忙是应该的这类话了；还有，在不求回报的亲密关系中，这样回应也许会产生疏离，尽量不要使用\u003c/p>","interaction":"\u003cp>【分布催化】\u003c/p>\u003cp>那么么接下来，各位伙伴，你们在什么情况下会为别人提供帮助？\u003c/p>\u003cp>帮助邻居照顾孩子？帮同事拿快件？你会遇到什么样的场景？\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>在来拆书的路上会帮没有吃饭的小伙伴代吃的。\u003c/p>\u003cp>如果未来你碰到这样情况，结合今天的方法：别人感谢你的帮助，你在回答不客气后，明确的告诉对方，比如“相互帮助是应该的。”这样的话；你会怎么使用今天的办法呢？\u003cbr>\u003c/p>\u003cp>请大家在小组内分享一下\u003cbr>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：&nbsp; &nbsp;&nbsp;\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;1、我经常在来拆书的路上会帮没有吃饭的小伙伴带吃的。下一次，小伙伴跟我说谢谢后，我回说：不客气，我要是需要帮忙的话，你也会帮我的啊。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;2、我经常在朋友心情难过时开解朋友，朋友跟我说谢谢，我说不客气就过去了。如果以后遇到这样的情况，我会跟她说，没关系，大家都会遇到糟心的事情，朋友就是要这时候相互帮忙的。\u003c/p>\u003cp>【结尾】\u003c/p>\u003cp>用今天的方法，希望大家在未来都能获得好运气，在你需要帮助的时候，有人能给你搭把手。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1543928006000,"updated_at":1543928835000,"ria":true},{"id":6443,"topic":"如何在重拾目标后干劲更足","learn_goal":"重拾目标后干劲更足","remark":"","level":"TF2-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"马子喻","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家晚上好，我是马文丽，欢迎大家来到今天我的TF2-1的拆书分享，在跟随我完成本次RIA现场学习后，学习者能够学会重拾目标后干劲儿更足，而不是在重拾目标后，在落地目标的过程中坚持还不如以前。\r\n今天我要拆的片段来自这本书《细节：如何轻松影响他人》，\u003c/p>\u003cp>【F】这本《细节》作者是罗伯特·西奥迪尼、史蒂夫·马丁、诺厄·戈尔茨坦3个知名说服力与影响力的研究权威，书里讲了52个“四两拨千斤”改变细节的套路。\u003c/p>\u003cp>&nbsp;【A】这是一本令人惊奇、强大、具有深刻内涵的实用型人生工具书，完整且细致地揭示了失败和成功之间存在着的细节差别，它3个月内就达到了近10W册的销量，并获得英国皇家学会奖。\u003c/p>\u003cp>&nbsp;【B】 如果你曾经设立了小目标在执行的过程中中断，你重拾目标后仍然没有干劲儿，那这本书就从一个细小的细节改变可以让你在重拾目标后干劲儿更足。同时在职场沟通、员工激励、商业谈判、家庭教育等工作和生活领域对你产生持续且深远的超级影响力&nbsp;\u003c/p>\u003cp>【分组】现在我们按座位每3个人一组\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":9750,"quote":"\u003cp>书目：《细节》作者：史蒂夫·马丁，诺厄·戈尔茨坦，罗伯特·西奥迪尼\u003c/p>\u003cp>页码：P98-P99\u003c/p>\u003cp>1919年，在《堪萨斯城星报》（Kansas City Star）画政治漫画的沃尔特·迪士尼（Walt Disney）被解雇了，报纸编辑的话是：“他不是太有创意。”\u003c/p>\u003cp>2012年，英国生物学家约翰·戈登爵士（Sir John Gurdon）因对生理学和药学的杰出贡献获得了诺贝尔奖。可当年他在伊顿公学的校长却在成绩单上这样写道：“我相信戈登想当个科学家，可照他现在的表现看，这想法颇为荒谬。”\u003c/p>\u003cp>好莱坞有个传说，弗雷德·阿斯泰尔（Fred Astaire）去雷电华影业（RKO Pictures）试镜时，一个制片经理把他刷了下来，理由是：“（他）不会表演，不会唱歌，有秃顶迹象，会跳一点儿舞。”\u003c/p>\u003cp>令人欣慰的是，这些早期的挫折都没能阻拦他们追求自己的目标。上述三人全部获得了惊人的成就。但有些时候，人们的确会分心，会忘记目标——不是未来的诺奖得主和好莱坞偶像心目中那种宏伟的、一辈子只有一次的、梦工厂式的目标，而是虽然小一点儿却依旧十分重要的、日常生活中的目标，比如多存一点儿钱，减掉几斤肉，还掉信用卡，或是达到这个月的销售目标。\u003c/p>\u003cp>人们往往需要重新拾起之前为自己设定的目标。同样，管理者、团队带头人、老师甚至是父母，有时候也需要帮助员工、学生和孩子鼓起干劲儿，再次为了原先的目标而努力。按常理，当我们为自己或他人设定新目标的时候，经验总是告诉我们，要把目标设定的非常具体。比如，每周减掉2磅（约1.8斤）体重，1小时跑6英里（约9.6公里），或是每个月存下100美元，作为来年的度假基金。但是，当我们说服自己或他人重拾目标的时候，这个常识是否正确呢？\u003c/p>\u003cp>营销学教授毛拉·斯科特（Maura Scott）和斯蒂芬·诺里斯（Stephen Nowlis）认为，虽然人们在直觉上感到，在首次制订目标时，应当把他量化为单一而具体的数字，但是，在重拾先前的目标时，这样做就未必最好了。相反，这两位学者认为，比起单一的具体数字[比如每周减掉3磅（约2.7斤）体重]，把目标改成一个上下浮动的数字范围[但平均值跟原先的数字一样，比如每周减掉2-4磅（约1.8~3.6斤）]，会更加有助于人们鼓起干劲儿，重新投入。\u003c/p>","explains":"\u003cp>好，大家都看好了，内容不多，且非常容易理解。我们都有那些虽然小一点却依旧十分重要的、日常生活中的目标。首次在设定目标的时候，经验总是告诉我们，把目标量化为一个具体的数字，但在目标执行落地的过程中，我们往往需要重拾目标，这种时候，想要重新投入后更加有干劲儿，要怎么办呢？第一步保证平均值和原先一样，第二步把目标改成一个上下浮动的数字范围，这样会有助于我们鼓起干劲儿，重新投入。\u003c/p>\u003cp>如果不这么做的话，在我们执行这些虽然小但是很重要的目标的过程中，目标一旦中断，我们还按照以前的具体的数字重拾目标时，会越来越没有干劲儿，不但丢掉了这些虽然小但很重要的目标，而且还会产生负面情绪，影响自己的生活和工作。\u003c/p>\u003cp>这里分享一个自己的经历。半年前，我和一个伙伴约定好，每周跑步3次，坚持了快一个月的时间，这个习惯就彻底丢掉了。本着爱美和健康的目标，没过多久，我们再次约定好，重拾目标，重新开始行动，结果情境几乎和之前一模一样，坚持了还不到一个月就再次丧失了跑步的干劲儿，而且两个人甚至要开始自我怀疑，产生了负面情绪。\u003c/p>\u003cp>直到我遇到了这个拆页，在读了《细节》这本书的这个拆页以后，我和伙伴重拾之前的目标，第一步在平均值和之前的数字一样的前提下，保持平均值是每周3次，第二步，我们把目标改成一个上下浮动的数字范围，调整为每周2-4次的目标。就这样，我们重拾目标，每周跑步2次的这个小目标，很轻松的就达到了，每周跑步4次，在偶尔两个人工作都不太忙的阶段也能实现。不论是跑2次，3次还是4次，因为都属于在目标范围内，可以都算作是我们实现了当周的目标，我们比之前更加干劲十足的重新投入到了目标中。现如今，我们调整目标以后，已经执行了新的目标快两个月的时间，而且热情丝毫不减。\u003c/p>\u003cp>正如拆页的建议中所说，生活中这些虽然小但仍然十分重要的小目标，在重拾目标时，在平均值和原来的数字一致的情况下，把一个具体数字的目标调整为一个上下浮动的范围的目标，可以让我们更加有干劲儿。\u003c/p>","interaction":"\u003cp>【A1】激活经验（显像提问）\u003c/p>\u003cp>拆书家提问设计（逐字稿）：下面请大家回忆一下，你有没有遇到这类似工作或生活的场景，例如：你曾经设立了每天背20个单词的目标、或者每天走1W步、每天写工作日志等，但是你发现坚持了没几天就又没有了干劲儿？\u003c/p>\u003cp>请把曾经设定了具体的目标，但是执行过程中，重拾目标后来干劲不足这样的场景简单地写到便签上，1分钟时间，写好的请举手示意。好，现在开始&nbsp;\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>仇玉娟：6月底7月初，天刚热的时候，大家也知道男的也想减肥，女的也想瘦身。我和我老公计划减肥，怎么办呢，健身房不方便，于是在手机上下载了APP，keep健身，根据自己的体型和工作时间，去下载了适合自己的运动，一开始我还蛮好的，每天在手机上坚持20分钟就可以了，在室内不需要器械的运动。结果他坚持了一个星期多，我坚持了四五天就放弃了。然后APP每天提醒我，但是提醒我我也是无视它。\u003c/p>\u003cp>【A1+】（反思加工）\u003c/p>\u003cp>拆书家提问设计（逐字稿）：好，如果让你乘坐时光机，穿越回刚刚提到的A1重拾目标的场景，根据刚才拆页的建议，最好怎样设定刚刚大家写下的曾经的目标？1分钟的时间给大家书写，写好后给大家3分钟时间在小组内分享一下你们的案例。\u003c/p>\u003cp>（4分钟后）好，请两位伙伴分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>李朋三：以前我背单词，后来就停下来了，原来定的单一而具体的目标是100个，现在觉得50个比较合适，后来定了50个，有时候因为时间关系坚持不了，于是定了45-60之间，这个比较适合我。\u003c/p>\u003cp>秦琰旻：我以前给自己定的目标每天走一万步，像我今天就没有完成，然后学了这个拆页，我想可能我可以把目标订成平均的一个状态，今天没有完成，明天可以多走一点，，接下来我会这样调整。\u003c/p>\u003cp>感谢两位伙伴的分享，那生活中我们经常设立一些虽然小但很重要的目标，我们往往把这个目标设立为具体的数字，在重拾目标的时候，第一步保证平均值和原先一样，第二步我们把目标改成一个上下浮动的数字范围，这样会有助于我们鼓起干劲儿，重新投入。\u003c/p>\u003cp>今天我的TF2-1拆书分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1541946318000,"updated_at":1541946739000,"ria":true},{"id":6371,"topic":"目标设的好，干劲儿会更足。","learn_goal":"在制定带有明确数字的目标时，可以把单一数字调整为浮动区间","remark":"按通常的经验在设置目标时选择单一明确数字，但对于完成目标有时并没有帮助，如果调整这个方法，就可以增加，动力自己更愿意去完成目标。","level":"TF2-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"小新","city":"北京市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; 大家好，我是小新，目前正在读《细节》这本书，【F】是一本实用工具手册。作者是心理学家、说服术专家罗伯特西奥蒂尼，这本书主要讲如何用高效又符合伦理的方法来影响和说服他人。【A】书中的用语特别简练故事也很生动，主要提到了52个方法，每个方法，读起来不会超过10分钟，但通过这10分钟，你就可以了解到这方法背后的心理机制以及如何实际操作的步骤办法。【B】比如这本书给我带了的一些好处：当你打算影响他人行为的时候，比如让人说话算话，只要对你的方法做微小调整，比如请他做出承诺的方式，就能得到比较成效的反馈，让他乐意为你做出一些事情。这个就是这本书让我受益匪浅的地方。也期望能给大家带来这样的收益。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;接下啦我分享的片段来自书里的第16小节，目标设的好，干劲会更足。【学习目标】期望能够让大家通过接下来我的分享，可以在设定目标的时候，尝试使用应用这个办法，让你更乐意为你的目标付出努力。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;接下来请大家花1分钟阅读片段。&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":9671,"quote":"\u003cp>营销学教授毛拉.斯科特和斯蒂文.诺里斯认为，虽然人们在直觉上感到，在首次制定目标时，应当把它量化为单一而具体的数字，但是，在重拾先前的目标时，这样做就未必最好了。相反，这两位学者认为，比起单一具体的数字，把目标改成一个上下浮动的数字范围会更加有助于人们鼓起干劲儿，重新投入。\u003c/p>\u003cp>当我们想调动自己或他人的积极性时候，把制定目标的方式做一个小小的改变，就能得到巨大的成效。好比说有个老师，想让一个最近总是在拼写测验里做不好的孩子重新鼓起学习的劲头儿，那他可以把明天的考试目标指定为10个单词拼对7～9个，而不是10个里对8个。如果呼叫中心的经理希望让员工充满干劲儿，维持较高的呼叫数量，那他可以做个试验：让一组员工使用单一数字型目标，另一组使用浮动的范围型目标，然后看看这个小改动能带来多大差异。债务管理公司和储蓄公司会发现，如果让客户制定浮动范围型的还款（储蓄）目标，比如让客户每月还掉（存入）28～32美元，而不是每月固定30美元，客户就能更好地坚持这个还款（储蓄）计划。\u003c/p>","explains":"\u003cp>我看基本大家读完，原文片段告诉我们一个关于制定目标的方式，如果将目标中的单一数字改为浮动区间，会激发我们完成目标的意愿，促进我们实现目标。\u003c/p>\u003cp>在实际生活中，我们经常会根据经验把目标设定为一个明确数字，但通常如果付出努力后，不能达到这个数字，就会放弃整个目标。\u003c/p>\u003cp>原因是，乐意被实现的目标一般有两个特点：有挑战，和可实现。在设置目标时，我们常会挑一个带有挑战性的数字，要付出一定努力才能达到，如果实现，你会体验到成就感，哦！我太棒了我居然办到了。\u003c/p>\u003cp>【不这么做的坏处】\u003c/p>\u003cp>但一个有挑战性的明确数字会带给我们压力，压力让目标的可实现性降低。如果目标不能完成，你会不会怀疑自己的能力？我难道是个失败者？想要的成就感就会变成挫败感，压力和挫败感很容易让我们放弃掉整个目标。\u003c/p>\u003cp>【行动步骤】\u003c/p>\u003cp>其实我们只要把目标稍微调整一下，把单一的数字的目标改为带有浮动的区间数字的目标，就可以缓解这个压力，提高目标可实现性。\u003c/p>\u003cp>【举例】\u003c/p>\u003cp>举个例子，我年初设立要锻炼身体的目标，具体执行目标为每个月游泳1次，坚持一年，总共12次。1到4月，月月失败，于是，我想这太难了，可能不适合我，果断放弃。待到7月，读到这个方法，在回想游泳这件事，我就是要锻炼身体啊，只要把执行目标按方法调整下，也许我就乐意去做了呢。于是我把目标中两个数字点都做了微调，每个月1次，变为1整年12次，调了第一个数字，然后把12次，变成区间数字，10-12次。到10月现在，已经游泳10次，基本达成目标，实现了锻炼身体的初心。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>这个方法特别适合那些为培养习惯类而设定的目标。&nbsp;\u003c/p>","interaction":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>【显像提问】\u003c/p>\u003cp>那么么接下来，各位伙伴，你们有要实现的目标吗？\u003c/p>\u003cp>比如每个月要存2千块，要坚持运动1个月，或者每天读半个小时书，你有这样的生活中这类的小目标吗？\u003c/p>\u003cp>你的目标是什么？\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者A：这类目标可多了，我的目标是每天一次打坐。（你实现了吗？）没有。\u003c/p>\u003cp>学习者B：目标每周去跑3次步，但自从有个事情打断后，这事儿就断了。\u003c/p>\u003cp>学习者C：前段时间有个目标是每天写作2000字，尝试了一阵子，感觉好像订的太高了，然后就这样了。（你有挫败感吗？）相当有啊！\u003c/p>\u003cp>【A1+】\u003c/p>\u003cp>感谢大家的分享，接下来，请大家回想一下你刚刚想到的那个带有单一的数字的目标，然后用今天的方法把单一的数字改成一个上下浮动的区间的数字。大家可以分组讨论一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者A：我原来订的计划目标是每天跑步，目标是每周跑3次。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 考虑到冬天北京的雾霾天气，我改成了两周2-6次，最终实现的目标是一样的。但这样，如果第一周我没有跑够3次，我不会觉得自己是没完成目标。只要下周补齐就可以，心里压力小了很多。也相信自己一定能完成这个目标了。\u003c/p>\u003cp>学习者B：我原来订的目标是每天写作2000字，然后感觉压力太大了。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;调整后变为：每天改成每周写2-4次，每次的字数要求是700到1500。这样修改完，觉得写作压力小了很多。【拆书家：很棒，从单一数字目标2000字，变为两个浮动区间数字的目标】）\u003c/p>\u003cp>学习者C：我之前订的计划目标是每天打坐一个小时，但几乎是没有完成。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;现在目标变为：每天打坐15分钟-30分钟。先培养起习惯再努力达到原来的要求。 &nbsp;\u003c/p>\u003cp>【结尾】\u003c/p>\u003cp>好，我看大家基本都能够运用今天的方法，把自己生活中的单一数字的目标改成浮动区间数字的目标，减小了目标达成的压力，提高了目标达成的可能性。祝愿大家的目标都能实现。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1540958283000,"updated_at":1541139457000,"ria":true},{"id":6031,"topic":"为互助留余地","learn_goal":"学习者在以后工作生活中，主动帮人并做暗示以便他人更好的帮我","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"静儿","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>大家好，我叫杨静；用三个标签来介绍我自己。\u003c/p>\u003cp>第一个，升级打怪的拆书家一枚。\u003c/p>\u003cp>第二个，职业培训行业销售。\u003c/p>\u003cp>第三个，喜欢旅行的人。\u003c/p>\u003cp>为了方便稍后的拆书过程中的分享交流，我们先来分个小组~~，就近原则每3-4人为一组。\u003c/p>\u003cp>《细节—如何轻松影响他人》，书的作者之一是罗伯特·西奥迪尼，他曾经出版过《影响力》已被翻译成26种语言，在全球售出了200万册，并被《财富》杂志评选的75本必读的最睿智的图书之一。书中用了52个例子准确地告诉你，一些微小的改变能够带来巨大的成效。关键是这些微小的例子马上就能拿来使用。在职场沟通、员工激励、商业谈判、家庭教育、个人提升等各个领域帮助我们完成个人及集体影响力的终极提升，最终使你更易获得最后的成功。\u003c/p>","ratings_count":2,"texts":[{"id":9271,"quote":"\u003cp>为互助留出余地\u003c/p>\u003cp>如果在工作中做一个豪爽大方的给予者能够为我们赢得较高的社会地位,却同时也削弱了我们做分内工作的生产能力,我们应该怎么做才好?弗林的另一项研究给出了确定的答案。这项研究发现了一个不起眼的指标，却能够同时增强助人者的社会地位和生产力。这个指标不是帮忙的次数,而是“互助”的次数。先是为对方提供有益的帮助,然后得到对方回报过来的有益帮助,这会把给予的良好效益放大到最大程度——不但他们自己受益,有份参与的每个人都能受益,因为给予者的地位提高了,生产力也提高了。请记住,这个结果与互惠原理是高度一致的,互惠原理对所有成功的群体来说都至关重要,因为它促进了互助互利的行为。\u003c/p>\u003cp>这些成果给了我们明确的启示。\u003cstrong>首先\u003c/strong>\u003cstrong>,\u003c/strong>\u003cstrong>我们应该大方主动地在工作中帮助他人\u003c/strong>。要注意,最重要的一点就是你要第一个行动。第一个出手相助会激活互惠原理,并因此增加未来的互助次数——对于职场中的共同成功,这个因素至关重要。\u003c/p>\u003cp>\u003cstrong>第二,\u003c/strong>\u003cstrong>要把你提供的帮助或有价值的信息做个定位,\u003c/strong>\u003cstrong>把日后对方可以全力回报你的可能性凸显出来。\u003c/strong>这就需要我们把平素的反应,也就是听到对方感谢我们时,我们所说的话,做个微小却重要的调整。这个调整能为你的未来合作和影响行为带来惊人的巨变。以下就是我们推荐的三种应答方式,用它们来回应对方对你的感谢：\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 能帮上你的忙我很高兴,因为我知道,当一个人需要帮忙的时候,别人的一双援手是多么有价值。\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; “不客气。同事之间理当如此。”\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; “没关系。因为我知道,如果需要帮助的是我,你也会这么做的。\u003c/p>\u003cp>总结一下,想要从职场中的给予行为中得到最大的益处,关键的做法就是“为互助留出余地”,这需要两个很小却至关重要的步骤率先提供帮助、信息或服务;一定要在回应对方时,明确地为你提供的帮助定位——这是一个自然的、平等的互惠行为,这样你就为后的互助留出了机会。\u003c/p>","explains":"\u003cp>提问：在座的各位小伙伴觉得是乐于助人的人吗？\u003c/p>\u003cp>提问：有没有觉得我经常会帮助一些人，轮到我怎么没人帮我了呢？\u003c/p>\u003cp>自我反思：我哪里做的不够好？\u003c/p>\u003cp>自我怀疑：我的人缘为什么这么差呢？\u003c/p>\u003cp>甚至会有点责备的心态，他为什么就不能主动帮我这个忙呢？\u003c/p>\u003cp>举例：以前同事投标，我经常加班、或是周六来公司帮他们盖标书。清晰地记得在来公司的前两年五一假期时，我全部都是加了三天的班；当时是从事销售助理岗，除配合销售同事、还要配合产品部、客服部。我自认为给大家帮忙很多，等以后我有需要别人也会帮忙的。&nbsp; 可是后来，当我自己开始做销售，开始独立接一些案子，需要投标盖章时，经常是自己加班到深夜或是一夜。当时我也觉得很绝望、失望、付出没有得到同等回报。后来我还经常调侃自己说；我在公司没有朋友~~\u003c/p>\u003cp>所以当我看到这个片段时，就想起了这件事。\u003c/p>\u003cp>1.&nbsp; 首先，主动地帮助他人。\u003c/p>\u003cp>2.&nbsp; 第二，把你为别人提供的帮助做个暗示。比如说：\u003c/p>\u003cp>²&nbsp; 能帮上你的忙我很高兴,因为我知道,当一个人需要帮忙的时候,别人的一双援手是多么有价值。\u003c/p>\u003cp>²&nbsp; “不客气。同事之间理当如此。”\u003c/p>\u003cp>²&nbsp; “没关系。因为我知道,如果需要帮助的是我,你也会这么做的。\u003c/p>\u003cp>²&nbsp; ……\u003c/p>\u003cp>第一步我有做，主动帮助他人，但第二步，我没有把自己帮助别人的事做定位。\u003c/p>","interaction":"\u003cp>刚刚大家都说自己是乐于助人的哈，别人有需要请你帮助时，通常都会帮；但大家是否有想过，如果别人没有请你帮忙呢？他不好意思麻烦别人呢？这时，是否需要你来主动帮助他人呢？\u003c/p>\u003cp>聊到这里请大家回忆一下，曾经你看到某人在做某事时，想着当时主动帮忙一下好了，但是你却没有帮~\u003c/p>\u003cp>或是你想到了自己曾经虽然有帮助别人，但因为没有把自己帮助别人的事做暗示，做说明‘如果需要帮助的是我,你也会这么做的’，别人帮你的时候他就有点不情愿，或是没有帮你，有这样的时候吗？\u003c/p>\u003cp>每人1分钟组内分享，3分钟后请一位小伙伴上台分享。\u003c/p>\u003cp>\u003cstrong>学习者A:\u003c/strong>之前在深大附近组织线下拆书活动时,会场需要帮忙搬一下桌椅;有的时候现场来的小伙伴人数较多忙不过来,想请一位拆书家帮忙,当时他有点不情愿,可是我帮他看那么多次提示表,帮他找观察家,帮大家找拆书场地,如果当时他说谢谢的时候我多说一句,下次活动搬桌子就好啦这样的语言,会不会就好很多.\u003c/p>\u003cp>在拆书帮我们都讲把片段拆为己用，请大家思考你打算在什么时间什么地点来用一下这个方法呢？\u003c/p>\u003cp>生活中，主动帮朋友或室友做一些事情，收拾下房间洗个衣服~\u003c/p>\u003cp>工作中，当你不忙时，可以问问身边的小伙伴有哪些需要帮助的吗~\u003c/p>\u003cp>请大家写在自己的便签纸上，一会儿请一位小伙伴分享一下。\u003c/p>\u003cp>\u003cstrong>学习者B:\u003c/strong>最近深圳总是下雨,我家邻居经常不在家,帮他们收了几次衣服,等这几天再次下雨帮他们收衣服（主动激活互惠原理）,他们和我说谢谢时，我也要加个定位说明,不客气，下次下雨我不在家你帮我收下衣服就好啦。\u003c/p>\u003cp>感谢分享！\u003c/p>\u003cp>总结一下今天分享的主要内容。\u003c/p>\u003cp>首先，主动地去帮助他人。\u003c/p>\u003cp>第二，把你为别人提供的帮助做个暗示。谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1536590785000,"updated_at":1537522531000,"ria":true},{"id":6001,"topic":"影响力的方法论","learn_goal":"学会轻松影响他人","remark":"","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"肖策遥","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>开场： 大家好，我是拆书家策遥，今天来过3-1。今天的学习采取分组的方式，我们先来分一下组。从我的右手边，两两为一组。&nbsp; \u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>完成今天的拆书学习以后，大家能够学会有效表达感激的方法。【行为】+【界定】&nbsp; \u003c/p>\u003cp>【场景介绍法】 \u003c/p>\u003cp>场景：想象一下，在工作中，因为你生病了，落下了进度，你的同事小A加班帮你完成了本应该你去完成的任务，几天过后，你的病好了，然后你回到了工作的岗位，也遇到了小A，你很想向他表达感激，发挥自己的影响力使得和他的连接变得更紧密，从而和他一直成为一个很好的朋友，这个时候就会很考验你的表达感激的功力了。大家会不会遇到类似的情况，就是你有一个朋友或同事或家人，帮助你的经历。\u003c/p>\u003cp>提问：我相信每一个人都曾经遇到过这样的经历，在这个时候，你们一般是怎么样去做的呢？你们会说些什么，做些什么，结果又是怎么样的呢？\u003c/p>\u003cp> 影响：在当今这个时代，影响力其实是不可或缺的能力，而且发挥的作用也是越来越明显，会直接影响到我们的人际关系，试想一下，如果他人帮助了你，你内心感动，但却没能让对方感受到，对方觉得他付出了却没得到回应，可能之后就不会那么乐意再去帮助你了。\u003c/p>\u003cp>解决：所以我们今天选取了一本书，叫做《细节：如何轻松影响他人》，当你想要创造你的影响力的时候，去调整一些最微小的细节，往往就能取得显著的效果。我们今天就会去学习，如何通过改变一些细节从而创造影响力的其中一个方法：有效的表达感激。\u003c/p>","ratings_count":1,"texts":[{"id":9239,"quote":"\u003cp>现在我把拆页发给大家，大家阅读两分钟左右，阅读完毕请举手示意。\u003c/p>\u003cp>（《细节：如何轻松影响他人》184页）【未超过2页图书内页】\u003c/p>\u003cp>【原文片断】\u003c/p>\u003cp>小小的一个表达感激的举动，看似不起眼，却能造成如此积极的影响&nbsp;。虽然说表达感激似乎是应该的，但想想看，你是不是经常机械地说一句“谢谢”，却没有把感激的程度真诚地表达出来？或者是不曾解释你感谢的缘由？有多少次你想要给别人写一张致谢的便条，却不知为何总是忘掉？你不仅错过了真诚感谢别人的机会，也错了在日后更容易影响他人的机会。\u003c/p>\u003cp>这项研究建议，管理人员和组织机构应当积极地寻找机会，清楚地表达感谢。这样做有助于在组织中培养出感恩的文化，让成员变得更加文明有礼。\u003c/p>\u003cp>政策制定者和公务人员也能从表达感激这个小小的行为中获益。认可并感谢民众做出的努力，感谢他们保持市容整洁、维护社区安全、积极采用环保的生活方式，这样做的成本肯定比采用物质奖励手段或亡羊补牢要低得多。\u003c/p>\u003cp>这是否意味着你很快就会受到国税局或市政府寄来的“感谢您缴税”的卡片，这还尚待分晓。\u003c/p>\u003cp>但我们敢说，要是真收到了，你会挺高兴的。\u003c/p>","explains":"\u003cp>【拆书家提问设计】（逐字稿）\u003c/p>\u003cp>大家都阅读完毕了是吗？\u003c/p>\u003cp>正如原文拆页所说，小小的一个表达感激的举动，却能造成非常积极的影响。表达感激不仅仅是出自内心真诚的感谢别人，更是一个在日后可以影响他人的机会。既然表达感激好处多，那自然而然我们可以人际关系的相处中多多运用这个方法。\u003c/p>\u003cp>那么，怎么样说就是在表达感激呢？\u003c/p>\u003cp>其实所谓感激，就是让对方感受到你是真心的认可他的付出的一种方法。\u003c/p>\u003cp>【易混淆的情况】\u003c/p>\u003cp>如果对方帮了你一个忙，你和对方说，“谢谢”。大家觉得这个是不是感激？\u003c/p>\u003cp>这其实不是一种感激，这更像是一种客气。就是有礼貌。我们必须注意到，有礼貌和感激并不是一回事。因为你对餐厅的服务员也会说谢谢。有礼貌并不代表对方就能接收到你对他的感激。现实生活中其实很多人，混淆了这其中的概念。\u003c/p>\u003cp>【正确示范】\u003c/p>\u003cp>再举个例子，如果我说，“谢谢你这么大热天还跑来帮我搬家，有你这么好的朋友我真的感觉特别开心。”\u003c/p>\u003cp>这是不是感激呢？是的。很显然，这就是表达感激的一种方式。因为一定要让对方感受到你的真诚才是真正的感激，比如刚刚的这句话运用的的是表达细节，加表达感受的方式，细节：大热天，感受：开心，这样就在具体的情境之下，很容易让对方感受到你是在真诚的表达感激。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>表达感激，适用于对方给你提供了帮助的情况，可以让对方接受到好的反馈，从而在将来给到你更多的帮助。\u003c/p>\u003cp>那么，怎么样有效表达感激呢？有以下三个步骤。\u003c/p>\u003cp>【具体行动步骤】\u003c/p>\u003cp>第一步，选用方式。\u003c/p>\u003cp>感激的话，其实会有很多种的方式，比如我们面对面的去表达，我们也可以用一封信，一张贺卡，一个精美的礼物去表达我们的感激。\u003c/p>\u003cp>第二步：捕捉细节。\u003c/p>\u003cp>我们表达感激的时候，一定要说明感激的缘由，这个时候就可以用到一些细节的表达，这样就会显得更加的走心。\u003c/p>\u003cp>&nbsp;第三步，表达感受。\u003c/p>\u003cp>让对方知道，我们此时此刻的心情是什么，可能是很开心，可能是很感动，对方听了这些之后就会觉得你是很真诚的。因为你又有细节，又有自己的感受，他不觉得敷衍。\u003c/p>\u003cp>【正面案例】\u003c/p>\u003cp>前段时候，我身体不太好，生病了，在家休息了几天的时间，我有个同事，叫小李，他连续加了两天时间的班，帮我做了一个工作要用到的很重要的PPT，当时，这个事情特别的紧急，他就帮我完成了，我就觉得有这样的朋友，真的挺感动的，我觉得他是我特别值得信赖的朋友，我想发挥自己的影响力，去和他建立更深层次的连接，所以我上班之后是这么跟他去交流的。\u003c/p>\u003cp>第一步：我选用方式，因为我知道他是一个比较直爽的人，所以，我采取的方式是面对面和他交流，所以一到办公室，我就拍了拍他的肩膀，然后他就回过头来和我对了一下眼神，我确定是他，\u003c/p>\u003cp>第二步，我捕捉细节，我是这么说的，我说小李，我知道你平常是一个特别不喜欢加班的人，你基本上是从来不加班的，但是这两天你为了我，连续两天加班到12点钟，所以大家可以回顾一下我讲的，是不是有特别多的细节，无论是12点钟还是之前不加班，后来加班，这些都是一些细节，会让他感受到你真的有认可到他对你的付出。\u003c/p>\u003cp>&nbsp;第三步，我表达我的感受，我说，小李，我心里真的很感动，也感觉很开心，因为我能够有你这样的朋友。\u003c/p>\u003cp>我很明显的感觉到我和小李的关系又近了一步。当然没有近两步，原因是什么，原因是他是个男的。\u003c/p>\u003cp>所以我举的这个例子，大家有没有更明白有效表达感激到底是怎么回事。\u003c/p>\u003cp>（学习者：明白）\u003c/p>\u003cp>【预防异议】在有效表达感激的时候，可能有些人会说，朋友之间这么去表达是不是太客套了，是不是会显得有点假，但其实，每一个人的付出都是希望得到回报或者回应的，就拿我们在座的各位来说，其实也是一样的，当我们为别人做一些事情的时候，都是希望得到回应的，这样我们的内心也会觉得更加舒服一些。所以当这个时候你也运用了一些细节，你也说了一些自己内心里的感受的时候，对方是会感受到你的真诚的，对方感受到你的真诚之后，你们的关系就会有一个更深层的链接。\u003c/p>","interaction":"\u003cp>拆书家设计提问（逐字稿）：\u003c/p>\u003cp>所以我们今天学习了一下怎么样去表达感激，学习的目的，终究还是为了使用。\u003c/p>\u003cp>我们来想想，在未来一周或者一个月里，有可能遇到别人对自己的帮助会有哪些，比如你妈妈每天给你准备一日三餐，比如你的同事帮你完成了一项工作？在未来的生活中会有很多类似的场景出现，那你们的脑海中会不会有接受别人帮助的场景。面对那个场景，你们会怎么做呢怎么样去面对呢？那接下来就请每一个人运用有效表达感激的知识，按照三步法去编写一个有起因经过结果的剧本，请大家设计出相应的人物，对方是谁，然后情节是什么，剧本的主角就是你自己，以对话的形式编写出来。&nbsp;\u003c/p>\u003cp>现在给大家五分钟左右写，然后在组内两两讨论和分享自己的剧本。之后我会请一位小伙伴来分享。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>我的剧本感激妈妈每天做饭给我吃。\u003c/p>\u003cp>&nbsp;人物：我和。妈妈\u003c/p>\u003cp>地点：家里\u003c/p>\u003cp>起因：妈妈又给我做了一顿大餐\u003c/p>\u003cp>经过：\u003c/p>\u003cp>我：（面对面）妈妈，你今天又做了我最爱吃的土豆烧排骨，分量还这么多（细节），我真的太开心了。（感受）\u003c/p>\u003cp>妈妈：（笑）别吃太多了，吃太多就太胖了。\u003c/p>\u003cp>我：谁叫妈妈做的菜这么好吃呢。\u003c/p>\u003cp>【拆书家反馈】很感谢这位学习者的分享，她在这个过程中用到了我们有效表达感激的三个步骤，分享得很精彩，让我们给他一点掌声。\u003c/p>\u003cp>【结语】今天，我们学习了在有效表达感激的三个步骤，选用方式，捕捉细节，表达感受。希望大家以后都能灵活运用。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1536116423000,"updated_at":1539323667000,"ria":true},{"id":5822,"topic":"如何通过“社会认同原理”的方法，更好地影响他人","learn_goal":"通过“社会认同原理”的方法，达到更好的影响他人决定的目的。","remark":"","level":"TF2-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"静儿","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"F特征：\r\n这本书叫做《细节—如何轻松影响他人》，书的作者之一是罗伯特•西奥迪尼，他曾经出版过《影响力》已被翻译成26种语言，在全球售出了200万册，并被《财富》杂志评选的75本必读的最睿智的图书之一。\r\nA优势(与同类书相比优势)：\r\n书中用了52个例子准确地告诉你，一些微小的改变能够带来巨大的成效。关键是这些微小的例子马上就能拿来使用。 \r\nB利益：\r\nB1本书益处\r\n通过微小改变影响对方的实操训练，并将在职场沟通、员工激励、商业谈判、家庭教育、个人提升等各个领域帮助我们完成个人及集体影响力的终极提升，最终使你更易获得最后的成功。\r\nB2片段益处\r\n当你和客户打交道的时候，当你和家人朋友相处的时候，为什么通过摆事实讲道理的说服方式总是失败的经历呢？那么今天的片段会教我们通过“社会认同原理”的方法去影响他人。","ratings_count":1,"texts":[{"id":9033,"quote":"\u003cp>我们三人中的一个曾经参与了一档电视新闻节目,任务是协助查出在一系列日常情境(不是紧急状况)下,人们为什么能被说服去帮助他人。在纽约城一个繁忙的地铁站里,我们聘请了一些研究者来统计有多少上班族会在路过一名街头音乐家身旁时给他钱，不久之后,我们对这个情境做了一个小小的调整,效果马上就显现出来了,而且非常明显。就在一名毫不知情的上班族朝着这位音乐家走过来的时候,另一个人(我们请来的托儿)当着他的面,往音乐家面前的帽子里扔了几个硬币。结果如何?给钱的人数增加了8倍。事后我们访问了给钱的人们,结果没有一个人认为自己给钱是因才看见别人先给了。相反,他们提出了各式各样的理由:“我喜欢他正演奏的那支曲子”“我是个慷慨的人”还有“我挺同情那家伙的。人们一般都不大擅于辨别出影响自己行为的因素——无论是在事前还是事后,这给所有耗费时间、精力、往往还有不菲的金钱来询问顾客“是什么让你做出购买决定”的企业或组织机构提了个醒。尽管我们相信许多顾客都很乐意回答这种问题,但他们给出的答案是不是真实的原因,我们就没那么乐观了。结果就是,依据这些答案而做出的营销战略往往失败率很高。\u003c/p>\u003cp>所以,与其把你的影响策略建筑在那些人们自以为的影响因素之上,还不如马上做个小小的改变:如果你想让目标客户做某件事,那就简明而诚实地指出,大多数跟他们很类似的人已经在这样做了。\u003c/p>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>以上片段告诉我们，如果当你想要你的目标客户去做某件事情的时候，然后可以告诉他们同类的客户都在做这件事情，那有的小伙伴可能会说我不是销售，无需影响客户，大家可以思考下用同样的方法，我们可以影响周围的哪些人呢？（家人，朋友，同事等）\u003c/p>\u003cp>前段时间我们公司为了丰富大家的业余活动，想在周末的时候准备组织一场羽毛球活动。当时是由我和同事来负责这个事情，那么我们俩就在公司的微信群里面说明一下这个事儿，并告知大家时间地点以及报名的接龙形式。可是半天的时间过去了，我们发现并没有什么人报名，只有零星几位同事说周末时间不方便就不参加了。\u003c/p>\u003cp>后来我和同事去了解了一下情况，但是很多人都是在观望的状态，会觉得说现在报名的人太少了，担心过去了没几个人不好玩，如果人多他们就去。所以我和同事后来就想了一个办法，让这些有意向的，不管最终去还是不去的，就在群里面先报名，使这个群先热闹起来。\u003c/p>\u003cp>那大家觉得使用了这个方法最后我们取得了什么成效呢？（巴拉巴拉……）。是的，没错，那最后大家看见他去，他去，他们都去了，那我也要去玩一下。会觉得自己不去就没有和大家打成一片不团结似的。总之,在最后举办的那天去了很多同事，活动非常的成功。\u003c/p>\u003cp>那大家想一下，如果我当初没有用这样的方式，告诉大家很多的同事都这样做了，那有可能造成什么样的后果呀，是不是活动就组织不下去啊？\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>所以也请各位小伙伴思考一下，你有没有遇到过这样的情况。\u003c/p>\u003cp>想让父母朋友去做的一些事情，比如爬山，健身，出游，或希望他们有更好的生活习惯，明明是为了他们好，可是他们仍然不愿意去做去改变。最终你也没有说服的了他们。\u003c/p>\u003cp>或是说你想组织一些活动啊，人们响应不积极，在微信群里经常是组织者在尬聊。等等类似这样的事情。\u003c/p>\u003cp>大家经历过这样的事情吗，请在小组内互相分享。\u003c/p>\u003cp>学习者A：父母想让小朋友报一些兴趣班，小朋友说不喜欢兴趣班只想做普通人。父母便没有办法了。\u003c/p>\u003cp>学习者B：周末想出去打篮球，周围的朋友觉得人少都不肯出去。\u003c/p>\u003cp>学习者C：举办拆书帮活动有时报名人数不多，没有更好的影响更多的人。\u003c/p>\u003cp>刚才大家也互相交流了我们自己在影响他人时不太成功的经验，那接下来我们可以用原文中的方法去思考一下，如何影响他人。可以在你刚刚列举例子的基础上继续思考，延伸出更好的解决方案。\u003c/p>\u003cp>给大家4分钟的时间小组内讨论一下，一会儿会请到小伙伴分享一下学习了这个片段，你打算怎样去做呢？\u003c/p>\u003cp>时间到，有哪位小伙伴愿意分享一下呢？（如果时间充裕，可由两位小伙伴分享）\u003c/p>\u003cp>学习者A：以前向领导反馈提意见总是容易被驳回，下次汇报或许可以告诉领导公司有几个其它部门（或其它公司）用同样的方式已经在做了，效果还不错。\u003c/p>\u003cp>学习者B：以往在公司内部做培训，大家都是自愿参加，各忙各的参训人员有点少。下周公司再组织类似培训时，找一些托儿，在公司预热一下，让大家感知很多同事都已经报名参加了，这样人参训的人会多一些。\u003c/p>\u003cp>学习者C：在群里提议打篮球，总是人很少。下一次可以在群里按人名方式排号，这样大家看到别人都去参加，自己也更容易去；或是公司在组织一些活动的时候，都可以用报人名接龙的方式，达到影响大家去参与活动的目的。\u003c/p>\u003cp>感谢精彩这位小伙伴的分享！\u003c/p>\u003cp>最后再来总结一下今天分享的主要内容，那就是当我们在做一些影响他人决定的事情时，我们不妨告诉他们，绝大多数的人也是这么做的。\u003c/p>\u003cp>那我今天的分享就到这里，谢谢大家。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1534472938000,"updated_at":1534472965000,"ria":true},{"id":5442,"topic":"细节：如何轻松影响他人","learn_goal":"学会轻松影响他人","remark":"","level":"TF2-4","duration":30,"status":29,"type":0,"chaishujia":{"username":"肖策遥","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>&nbsp;大家好，我是今天的拆书家策遥。在通俗心理学领域有一本非常著名的书叫做《影响力》，大家有看过吗？我们今天要拆的书，是《影响力》的进阶版，叫做《细节》。为了更好的完成今天的拆书，我们先来分一个组，从我的右手边开始，大家两两一组。&nbsp;\u003c/p>\u003cp>【F】这本《细节：如何轻松影响他人》是罗伯特·西奥迪尼联合另外两大说服力权威专家一起创作的。是关于如何提升影响力的一本书，讲的是如何用经济高效又符合伦理的方法来影响和说服他人。\u003c/p>\u003cp>【A】这本书是通俗心理学类书籍中非常畅销的一本，和同类书籍相比，它的实操性非常强，一共52条细节建议，简单易行，看了立马就能用。&nbsp;\u003c/p>\u003cp>【B1】你有没有遇到过想说服别人，别人却无动于衷的经历？这本书能轻松增强你影响别人的能力。&nbsp;\u003c/p>\u003cp>【B2】而我们今天所选的这两个片段能迅速让你领会如何轻松说服他人，让他们更容易选择你的方案。\u003c/p>\u003cp>【学习目标】在跟随我完成本次RIA现场学习后，学习者能够学会在需要说服他人做决策时运用描述潜质、摆出事实的方法，从而达到让他人更信服的目的。\u003c/p>","ratings_count":2,"texts":[{"id":8610,"quote":null,"explains":"\u003cp>大家看完拆页了吗？\u003c/p>\u003cp>【What】\u003c/p>\u003cp>其实很多时候，我们都会遇到这样的情况，需要说服他人做一个决策，我们习惯了用事实、成就去证明，却忽略了对方的需求是什么，对方的期待是什么。对方希望的未来是什么。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>如果你只是强调过往的成功，此刻的优秀，可能并不足以打动别人。让别人足够的相信你。\u003c/p>\u003cp>【How】\u003c/p>\u003cp>当我们想要说服别人做决策的时候，我们可以可以遵循如下的步骤：\u003c/p>\u003cp>【1】\u003c/p>\u003cp>（描述潜质）用蓝图勾起人的兴趣。\u003c/p>\u003cp>【2】\u003c/p>\u003cp>（摆出事实）用事例证明自己的能力。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>可能有些小伙伴会有一些疑问，一开始描述潜质，画蓝图，会不会显得假。实际上，描述潜质并不等于自吹自擂，是把自己能带来的价值提前提炼出来，具象化，之后再以一些事实证明，这样反而更能打动人心。\u003c/p>","interaction":"\u003cp>【显像提问】\u003c/p>\u003cp>我们刚刚学习力这个片段，那你是不是也有一些类似的经历呢，比如说在求职、述职以及晋升会上，你在PPT上摆了大量的事实、数据证明过去的你有多努力，然而领导只关心未来的KPI目标达成吗？\u003c/p>\u003cp>比如说你在谈恋爱、相亲时，不停的表达自己的优点，甚至举例说明，然而对方却并不感冒，因为对方关心的只是未来和你在一起的状态真正会如何吗？会去马尔代夫冲浪吗？会去南极看企鹅吗？会有这些TA想要的幸福吗？\u003c/p>\u003cp>【问题】\u003c/p>\u003cp>请各位回想下，你是否曾经也有过类似的经历？想要说服别人做决策的时候只是摆事实，强调过往的成就。这件事情的来龙去脉是如何的呢？是什么时间，什么地点？请将这件事情跟你的小组伙伴分享，两人一组，每人1分钟，我们会请一个小伙伴来分享一下，只要分享自己想到的事件就可以了。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>A：我想到了我上次面试的经历，当时只顾着摆事实证明自己的优秀了。\u003c/p>\u003cp>【A1+】\u003c/p>\u003cp>如果现在时光倒流，我们回到那个时刻，我们可以怎么运用我们的2个步骤：描述潜质，摆出事实，从而让自己表现更优秀呢。\u003c/p>\u003cp>请各位带着你们重新梳理后的话语，跟组员分享。好的，我们现在请一个小伙伴分享一下，先分享原来情况是怎么样的，再分享时光倒流后你会怎么做。\u003c/p>\u003cp>【学习者案例分享】\u003c/p>\u003cp>A：我会这样去做，先跟面试官阐述自己能够给工作带来的价值，也就是把自己的潜质最大化的呈现出来，比如说我拥有出色的人际协调能力，能够带动团队的效率。然后我会举一些我过往的事例去加以证明，我在前一家公司，就曾因为出色的协调能力帮助公司提升了效率，收到了公司的嘉奖。\u003c/p>\u003cp>【回馈】这个小伙伴的分享非常棒，他先是联想到了自己过去求职面试的一个场景。以前只懂得摆事实证明自己优秀，现在他学到了新的方法，如果时间回溯，他会先描述自己的潜质，可以给公司带来价值，然后再用事例去证明，这样无疑会让面试官对他更感兴趣。\u003c/p>\u003cp>所以感谢小伙伴的热情分享，我们第一个片段的分享就暂时先到这里。&nbsp;\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":8611,"quote":"\u003cp>【片段间逻辑关系】\u003c/p>\u003cp>在第一个片段，对方尚未有明确的决策倾向，而我们想要说服对方做决策，片段中给大家提供了一个解决方案：两个步骤，第一步描述潜质，第二步摆出事实。\u003c/p>\u003cp>但是如果对方已经有了明显的决策倾向，而我们却想要改变对方的决策，也就是给对方推销一套新的解决方案，又该如何去做呢？第二个片段就给了我们答案。\u003c/p>\u003cp>【学习目标】&nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够学会在需要对方改变决策时合理运用构思、试探、认可、包装四个步骤的方法，从而让他人愿意改变决策。\u003c/p>\u003cp>我们现在大概花2分钟的时间把第2个拆页看一下。\u003c/p>","explains":"\u003cp>大家看完拆页了吗？\u003c/p>\u003cp>【What】\u003c/p>\u003cp>这个拆页带我们领略了如何运用细节引领改变对方选择倾向。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>很多时候，对方可能已经有了自己的选择倾向，而这个时候如果我们还想让对方改变选择。那么可能就需要用到这个拆页的方法。\u003c/p>\u003cp>【How】那到底该如何去做呢？我总结如下：\u003c/p>\u003cp>（1）&nbsp; 构思：确认自己倾向的选择。\u003c/p>\u003cp>（2）&nbsp; 试探：试探对方倾向的选择。\u003c/p>\u003cp>（3）&nbsp; 认可：无论对方的选择是什么，都给到认可，让对方卸下防备。\u003c/p>\u003cp>（4）&nbsp; 包装：强调不选自己倾向的选择的损失。\u003c/p>\u003cp>【适用边界】&nbsp;\u003c/p>\u003cp>当然这个方法会适用在对方的选择倾向和自己的选择倾向不一致的时候，如果对方的选择倾向和自己一样，那么就更加皆大欢喜，就不用进行到第四步，到第三步认可就可以了。\u003c/p>\u003cp>【不这么做的坏处】\u003c/p>\u003cp>一般来说，人们想要说服他人做另外一个选择的时候，总喜欢强调这个选择的优点，试图用优点来说服他人，但这往往反而会导致对方升起抵触情绪，更不愿意尝试另外的选择。\u003c/p>\u003cp>【举反例】\u003c/p>\u003cp>上个月我想说服一个朋友A周末不要老是宅在家里，我就直接跟他说，你不要老是待在家里啦，可以出去走走啊，参加一些活动，可以多认识一些人啊。朋友不为所动。\u003c/p>\u003cp>【反例变正例】【更贴近实际的例子】\u003c/p>\u003cp>上个星期学了这个片段的内容后，我尝试用新的方式去说服他尝试去参加活动。\u003c/p>\u003cp>我：先是自己（1）构思了一下周末除了待在家里完全可以有第2个选择：比如多参加活动，认识一些新的朋友。这是互动前自己的思考，接着我带着我自己的思考和他对话。\u003c/p>\u003cp>我：然后向A（2）试探：又到周末了，我们可以待在家里休息，也可以出去参加一下活动，这样可以认识到一些新的朋友。你会更喜欢周末干嘛呢？\u003c/p>\u003cp>A答复我说：当然是待在家里了，家里多舒服啊。\u003c/p>\u003cp>接着我（3）认可：是啊，待在家里是最舒服的。\u003c/p>\u003cp>A答复我说：对对对\u003c/p>\u003cp>我：最后说（4）包装:这周末的活动好像还挺多漂亮妹子的，可惜了，将来都要成为别人的女朋友了。\u003c/p>\u003cp>A快速答复：什么，漂亮妹子，我要去，待家里干嘛？\u003c/p>","interaction":"\u003cp>接下来让我们进入现场演练环节，我给大家设计了一个演练场景：\u003c/p>\u003cp>【A3场景设计】\u003c/p>\u003cp>你的朋友小天，你们很久没见面了，这次TA约你周末见面，说去天河城逛街，你觉得天河城去了很多次了，不太想去，你想去花城汇，因为你知道那里有很多帅哥/美女，你想说服小天去花城汇逛街。\u003c/p>\u003cp>【给出清晰指令】\u003c/p>\u003cp>现在，请大家按照刚才的分组，两人一组，运用刚才所学片段里我总结四步法：构思、试探、认可、包装。一个人扮演小天，一个人扮演你自己，演练时间6分钟，可能交流的方式会有很多，但我们演练就用我刚刚给大家总结的四步法来操练，6分钟后，我会邀请一到两组小伙伴到台前来表演，演练现在正式开始。\u003c/p>\u003cp>【角色扮演】案例记录\u003c/p>\u003cp>小B：构思：她先想好了自己是想去花城汇的。\u003c/p>\u003cp>小B：试探：小天，上次你说我们周末见面，你还提到了天河城，因为我们可选的地方挺多的，天河城、花城汇，你是想我们在哪里见面呢？\u003c/p>\u003cp>小天：我们在天河城见吧，那里近一些。\u003c/p>\u003cp>小B：认可：嗯，天河城确实近一些，也方便一些。\u003c/p>\u003cp>小天：对啊\u003c/p>\u003cp>小B：包装：我前两天听说花城汇那里有一家你最喜欢的XX品牌店打3.8折，可能就要错过啦。\u003c/p>\u003cp>小天：啊，真的吗，那我们还是去花城汇吧。\u003c/p>\u003cp>【A2-激活应用场景-显像提问】\u003c/p>\u003cp>请大家设想一下，如果在接下来一段时间，你会遇到什么样的需要引领改变对方选择倾向的问题呢？是在工作中让领导给你安排别的任务，说服同事换一个别的方案，还是在生活中给朋友一些别的建议，比如建议换家一家新的餐厅，或者去别的地方玩，你会想到什么呢？\u003c/p>\u003cp>请大家把想到的场景写下来，然后我们请小伙伴分享一下TA可能会遇到的场景。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>小C：我想到了我下周会和我的朋友碰面，我们会一起去吃饭。但他经常带我去吃粤菜，而我下次更想吃湘菜了。\u003c/p>\u003cp>【A2-规划行动步骤】\u003c/p>\u003cp>请大家想一下，如果运用刚刚学到的方法，你可以怎么做说服对方采纳你倾向的选择呢？请大家两两一组做讨论，要足够的具体。接着我们会请1个小伙伴来做分享。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>小C：我已经构思确认自己想吃湘菜，然后可以找个机会试探一下他是不是还想吃粤菜，可以这么问他：小D，好开心我们马上又能见面了，这次想约在哪里，我们能去的地方还挺多的，湘菜馆，粤菜馆等等。如果他选湘菜馆那当然就皆大欢喜了，不过我估计他还是会选粤菜馆，那么我就可以认可他，那家餐厅位置近。最后我再包装：有一些湘菜馆新出了龙虾新品，打2.8折，你之前不是特别喜欢吃龙虾吗，去粤菜馆的话就错过龙虾大餐啦。\u003c/p>\u003cp>【反馈】\u003c/p>\u003cp>好的，谢谢小伙伴的分享，这个小伙伴学以致用的能力非常强，他完全按照了我们今天第二个拆页所学的引领他人改变选择倾向四步法：构思、试探、认可、包装。我相信如果以这样的方式去沟通，达成我们沟通成功的几率一定会大大提升。\u003c/p>\u003cp>【强有力的结语】\u003c/p>\u003cp>感谢各位，今天我们学习了两个拆页的知识：说服他人做决策，以及引领他人改变决策倾向。我们一同回顾下\u003c/p>\u003cp>第一个片段，说服他人做决策，两步法：描述潜质，摆出事实。 \u003c/p>\u003cp>第二个片段，引领他人改变选择倾向，四步：构思、试探、认可、包装。 \u003c/p>\u003cp>最后，知易行难，希望大家可以多加刻意练习，抓住细节，锻炼影响力思维！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1530509916000,"updated_at":1533353009000,"ria":true},{"id":5365,"topic":"从他人的错误中汲取教训","learn_goal":"通过观察记录他人所做的错事清单，在每次做决定时参考一下，避免","remark":"本书通过52个微小改变影响对方的实操训练，并在职场沟通、员工激励、商业谈判、家庭教育、个人提升等各个领域帮助我们完成个人及集体影响力的终极提升，最终使你更易获得最后的成功。","level":"TF1-2","duration":30,"status":29,"type":0,"chaishujia":{"username":"静儿","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"自我介绍+图书介绍（1分钟）\r\n大家好，我叫杨静；用三个标签来介绍我自己。\r\n第一个，升级打怪的拆书家一枚。\r\n第二个，积极减肥的人。\r\n第三个，喜欢旅行的人。\r\n《细节-如何轻松影响他人》，本书通过52个微小改变影响对方的实操训练，并在职场沟通、员工激励、商业谈判、家庭教育、个人提升等各个领域帮助我们完成个人及集体影响力的终极提升，最终使你更易获得最后的成功。","ratings_count":2,"texts":[{"id":8517,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>【R】阅读原文拆页\u003c/strong>\u003c/p>\u003cp>\u003cstrong>片段选自《细节-如何轻松影响他人》之〈从他人的错误中汲取教训〉\u003c/strong>\u003c/p>\u003cp>扭转错误,让它开花结果,这样做的方法有很多。有些需要实打实地投人时间和资源,比如重新规 划商业模型,弥补系统中的漏洞,寻找新方法绕过不曾预料到的障碍。这些都是大动作,往往也至关重要。但小事情也很重要。有一个化险为夷的简单方法容易得令人吃惊,你甚至不需要去琢磨自己从前犯过什么错误。相反,我们的建议是,做个小小的改变去想想他人曾经犯过的错误。 查理芒格( Charlie &nbsp; munger)既聪明又睿智这些素质能给人带来巨大的回报。正是由于具备这些特点,他成了沃伦·巴菲特( Warren Buffett)在投资公司伯克希尔哈撒韦( Berkshire &nbsp; Hathaway)的合伙人与最信赖的顾问，这间公司自从在1964年创始以来,就取得了行业内前所未有的成功。有人曾经问芒格先生,他如何确保自己做出的每一个决定都是正确的。 &nbsp; 他简短地答道:“我会看一遍我的蠢事清单。”\u003c/p>\u003cp>（阅读后可抬头示意我一下）\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>分享I便签\u003c/strong>\u003c/p>\u003cp>本片段告诉我们，如何在他人的错误中汲取教训，那就是平时记录一下别人在做事中犯过的错误，在每次自己做决定的时候参考一下他人的“错误清单”。\u003c/p>\u003cp>或许我们不是企业家，不是公司经理不是老板不需要做太多的大的决策。那么我们仍然可以在平时的工作生活中列出他人的错误清单来避免自己犯错。\u003c/p>\u003cp>给大家举个我在工作中发生的例子，前两年的时候，我们部门经常会参与投标，那么在投标的过程当中就犯过不少错误，比如说有的同事忘记在报价单上盖章，封装不合格，忘记上传电子文档等等原因而造成废标。现在想来，如果我可以把不同同事在投标过程中犯过的错误都一一的记录下来。形成一份关于投标的“错误清单”。在每次投标的时候看一遍，就可以避免很多不必要的错误。\u003c/p>\u003cp>可能有的伙伴会问，为什么要用记录错误的方式而提醒自己呢？为什么不记录正确的示例呢？那是因为负面的信息、尤其是在导致一定的后果之后，更容易被人记住；\u003c/p>\u003cp>可能有的伙伴又会问，为什么要用记录别人所犯的错误而不是自己所犯的错误呢？那是因为别人犯过的错你反而更容易看出问题在哪。如果是自己犯过的错误，或许可能自己还没意识到，或是印象不够深刻。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>A1\u003c/strong>\u003cstrong>环节\u003c/strong>\u003c/p>\u003cp>接下来给大家3分钟时间分享一下自己过往经历的案例；\u003c/p>\u003cp>有哪些错误是你在别人犯过之后，你当时没有记录下来，而随后你把他所犯的错误又犯了一遍呢？\u003c/p>\u003cp>你在做事时是否也会出现一些失误，而这些失误明明你周围的人都出现过，而你却忘记了避免。\u003c/p>\u003cp>大家可以试想一下~~\u003c/p>\u003cp>OK时间到，接下来看哪位小伙伴愿意分享一下自己过往的案例呢？……\u003c/p>\u003cp>\u003cstrong>分享者A：\u003c/strong>\u003c/p>\u003cp>参加拆书家训练营，就是希望通过别人的错误及自己的错误来反思自己，希望下次更好的拆书。\u003c/p>\u003cp>\u003cstrong>分享者B：\u003c/strong>\u003c/p>\u003cp>两次误机的惨痛经历。因为等人、堵车等等原因，导致最终没有搭乘上航班。没有及时记录下来去往机场的路上可能遇到的突发现象。导致有2次的误机经历。\u003c/p>\u003cp>感谢分享！\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>A2\u003c/strong>\u003cstrong>环节\u003c/strong>\u003c/p>\u003cp>接下来请一位小伙伴用1分钟的时间来为我们分享下，你计划接下来的一段时间内，如何去运用我们今天所学的记录错误清单的方式呢？\u003c/p>\u003cp>\u003cstrong>分享者A：\u003c/strong>\u003c/p>\u003cp>由于最近在拆书帮练级，所以每次过级都容易出现一些状况，学习了这个片段，决定从当下开始，在参加拆书家训练营活动时，可以把每个人分享自己过级的失误记录下来，写在拆书手册上面，这样就可以通过记录他人的“错事清单”，避免自己犯同样的错误。\u003c/p>\u003cp>感谢分享！\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>结语\u003c/strong>\u003c/p>\u003cp>总结一下今天分享的主要内容。那就是使我们在工作生活中做事时更少的犯错误，去记录一下别人所犯过的错误吧，每当自己做这件事情或是做决策的时候，不妨把我们记录的“错误清单”拿出来参考一下。\u003c/p>\u003cp>最后，真心的希望大家可以通过记录“错误清单”的方式，在生活或职场中少犯错，把每件事都完成的漂漂亮亮的。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1529478738000,"updated_at":1529478738000,"ria":true},{"id":5364,"topic":"鲜明生动的细节","learn_goal":"当你所希望达成的目标需要别人帮助的时候，可以通过引导对方关注","remark":"本书通过52个微小改变影响对方的实操训练，并在职场沟通、员工激励、商业谈判、家庭教育、个人提升等各个领域帮助我们完成个人及集体影响力的终极提升，最终使你更易获得最后的成功。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"静儿","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>自我介绍\u003c/strong>\u003c/p>\u003cp>大家好，我叫杨静；用三个标签来介绍我自己。\u003c/p>\u003cp>第一个，升级打怪的拆书家一枚。最近也是刚刚在便签训练营结业，终于成为拆书帮深圳智荟分舵的会员。希望早日成为三级拆书家。\u003c/p>\u003cp>第二个， 积极减肥的人。减肥是我今年的目标之一，希望熟识的朋友再次见到我的时候，会让你们惊叹“哇、你瘦了好多吖~~~”\u003c/p>\u003cp>第三个，喜欢旅行的人。超喜欢在一个人旅途中感受不一样的风土人情。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>拆书帮介绍\u003c/strong>\u003c/p>\u003cp>“拆书”是一种成人学习的方法论，适用于以提升能力、解决问题为目标的成人学习，它强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。\u003c/p>\u003cp>分为个人学习的拆书法和组织学习的拆书法：个人学习应用的是便签法，让人读一本书就能达到参加同主题培训的效果；组织学习的应用就是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。从学习者学习效果来讲的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>“拆书帮”是基于拆书法的学习爱好者社群，表现为各地的拆书帮分舵。拆书帮分舵是公益性青年自组织，其使命是帮助更多的学习爱好者成为拆书家。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","ratings_count":1,"texts":[{"id":8516,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>【R】阅读原文拆页\u003c/strong>\u003c/p>\u003cp>\u003cstrong>本片段来自于《细节—如何轻松影响他人》之〈鲜明生动的细节〉\u003c/strong>\u003c/p>\u003cp>在他们主持的一项实验中,受试者被随机分成三组,访问一个为乐施会(Oxfam)捐款的网站。登录到“普通版”网站的那组受试者读到的是:“国际乐施会是世界上最高效的援助组织之一。它向全球人民提供种类众多的人道主义援助。如果你向乐施会捐款,你会捐多少?”\u003c/p>\u003cp>登录到第二种网站(我们称之为“高价值一细节版”)的受试者读到的内容跟上面一样,只不过多了这样一句话:“乐施会运用资金的一个例子是,它为人们送去清洁的水。”\u003c/p>\u003cp>最后,登录到“低价值一细节版”网站的受试者读到的话与第二个版本的一模一样,只是“清洁的水”换成了“瓶装水”。这两个版本之所以这样命名,是因为实验之前所做的测试表明,人们认为,比起“瓶装水”,“清洁的水”对援助对象的帮助力度更大,更有价值。\u003c/p>\u003cp>这些措辞方面的改动可谓是非常不起眼,但它对结果的影响绝不能用不起眼来形容。看到“普通版”网站的那组受试者平均捐出了7.5美元,而看到“高价值一细节版”的那组受试者(他们看到了细节信息,知道了善款的用途)的平均捐款额增加了37%。小小一个改动就能产生这样的成效,可谓是令人印象深刻。因此,如果你想申请额外的资源,不管你想要的是信息,还是时间、金钱,甚至是人手,你都应该在提案中添加一点儿细节,描述一个清晰又具体的干预手段。\u003c/p>\u003cp>当你需要说服别人为你提供资源,来帮助你达成某个目标的时候,这些“四两拨千斤”的方法表明,你应该引导对方去关注这两个方面:形象鲜明的受益对象以及清晰具体的干预手段。\u003c/p>\u003cp>（阅读后可抬头示意我一下）\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>分享I便签\u003c/strong>\u003c/p>\u003cp>\u003cstrong>解决问题\u003c/strong>\u003c/p>\u003cp>需要通过别人的帮助更好地达成目标。\u003c/p>\u003cp>\u003cstrong>解决步骤\u003c/strong>\u003c/p>\u003cp>我们想达成某个目标需要人们提供资源帮助的时候，我们需要告诉对方此事真正的受益人是谁，以及向对方描述一下这件事情是怎么操作的。\u003c/p>\u003cp>比如，小明在地铁站发现忘了带地铁卡，身上又没有现金，他如果乘车就需要借现金再转账给帮助他的人。此时，你觉得他怎么说人们才会更愿意借钱给他呢？\u003c/p>\u003cp>第一种“您好，可以借10块钱吗”\u003c/p>\u003cp>第二种“您好，我今天忘了带地铁卡，身上又没有现金，您借我10元现金，我微信转账给您可以吗？”\u003c/p>\u003cp>很显然，一定是第二种的说法我们更容易给他兑现金。明确了受益人是我，又清晰的告诉对方操作方式。\u003c/p>\u003cp>大家试想一下我们生活中，一定都会有需要帮忙配合的时候吧，忘带现金啊，拿不动快递啊，手机钥匙钱包丢了啊等等，或是在工作中，你需要跨部门沟通推进某项工作，或是需要同事下属以及上司配合的地方，我们都可以试一下这个方法，明确受益人（在工作中，受益人很可能不单单只是自己哦，有可能是部门人或是整个公司），以及清晰描述这件事情是怎么操作的。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>分享A1便签\u003c/strong>\u003c/p>\u003cp>之前有一次来宝体游泳，身上只带了50元现金，门票35元，柜子押金需要20元，我就缺了5块钱。我问身边大哥“可以借我点现金吗”，他说“不好意思我现金也没多少”。借钱失败。。。后来是门口保安大哥看见我在那拿着15块没办法，掏出5元借我了。\u003c/p>\u003cp>后来在泳池遇见没借我钱的哥哥，他和打招呼，后来一聊才知道，他最开始以为我一点现金没有缺几十块呢，他当时身上也就剩十几块。他说要早知道是这样就直接给我了。好吧，是我没有说清楚细节。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>分享A2便签\u003c/strong>\u003c/p>\u003cp>下周想协调产品部同事丹丹直接和我的客户对接，帮忙客户做很多H5，不用想也知道他们内心一定是拒绝的，一是因为需要做的数量太多，二是因为通常他们所做材料只和正在执行项目相关，素材丰富做起来方便。三是公司规定销售不可指定产品部门某同事来为你做方案。\u003c/p>\u003cp>读到这个片段，我计划下周这样去和产品部主管去谈，在我上一个项目完成后我们给客户产出的H5客户觉得超级赞，真是太棒了。他们人力部最近在做各项政策的宣贯资料，看完我们做的这个客户也想通过这样的方式在公司内部宣传，与以往不同的是，这个需求，是单独收费的，项目完成我可以在公司为你们申请奖金的。\u003c/p>\u003cp>那你看这件事情的执行者，可否是上次项目的执行者丹丹呢，因为这次收费对制作质量就有要求了，不像以往是免费的，丹丹的制作水平大家都是了解的，所以你看是否可以让他来做。而且这次我不再干预过程，需要他直接和客户对接，按客户的要求制作并修改内容，达到客户满意效果。\u003c/p>\u003cp>通过描述生动的细节，让同事了解到自己的工作做的足够优秀，帮公司拿了额外需求，而且告诉她完成这件事情最终的受益人不仅仅是公司还有她自己；相信这样的通过细节的描述方式，同事会更愿意接过这个需求从而更好地完成此项任务。\u003c/p>\u003cp>\u003cstrong>结语（1分钟）\u003c/strong>\u003c/p>\u003cp>总结一下我今天分享的主要内容。当你需要别人的帮助才能达到你的目标时，记得描述形象鲜明的受益对象以及清晰具体干预手段。希望各位也能将此方法应用于实际的工作生活中，更好地达到自己的目标。\u003c/p>\u003cp>我今天的片段拆解到此结束，谢谢各位聆听。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1529476346000,"updated_at":1529476404000,"ria":true},{"id":5326,"topic":"如何提升说服力","learn_goal":"发掘自身潜质，提升沟通中的说服力","remark":" 生活中那些细节的改变所产生的巨大影响往往超乎人们的想象，《细节：如何轻松影响他人》通过对近百例经典案例的讲述与分析，带我们探索那些微小却重大的影响力提升技巧，告诉我们如何在这个信息超载的时代，用最小的力量撬动结果最大的变化，提升沟通中的说服力，并且成功影响他人。","level":"TF3-1","duration":25,"status":29,"type":0,"chaishujia":{"username":"杨硕","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"学习目标：在完成本次的RIA现场学习后，学习者可以区分现实和潜质，设计一个剧本，运用提升潜质说服力的3个步骤，使对方接受你的意见。","ratings_count":1,"texts":[{"id":8472,"quote":"\u003cp>\u003cstrong>图书介绍：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>场景\u003c/strong>-我们都知道，机会是不会等人准备好了，很多时候都是仓促上场。我有个新方案要提给老板，这个方案在硬件条件上有些不足，但是本身很有潜质，未来可能会达到比较高的水准，会超过目前的方案30%甚至更多。\u003c/p>\u003cp>\u003cstrong>提问\u003c/strong>-假如是你，要怎样要描述方案才能让老板更容易接受？在缺乏一些现实条件的情况下，老板会因为这个方案本身具有的潜质而同意你的提案？\u003c/p>\u003cp>\u003cstrong>影响\u003c/strong>-如果我们因为当前的现实条件有所不足，就裹足不前，会错过很多机会。如果我们没有一个好的表达方式，即便你勇敢的去争取了，别人也可能听不进去，或者你说了别人也不信，还是把握不住机会。\u003c/p>\u003cp>\u003cstrong>解决\u003c/strong>-在现实生活中，很多时候我们都需要提升说服力，让自己说的话更有力量。《细节》这本书告诉我们，怎么用微小的改变，撬动更大的效果，来提升说服力。即便是在现实条件不足的前提下，把潜质更好的表达出来，表达的有画面感，这样老板听我们的方案后更容易同意，朋友听了我们的推荐后会很感兴趣，他人也会更尊重我们的意见。\u003c/p>\u003cp>潜质到底是指什么？我们带着问题先来看一下拆页。\u003c/p>\u003cp>\u003cstrong>R\u003c/strong>\u003c/p>\u003cp>在后续的跟进研究中，托马拉发现了相同的结果：当受试者必须在两个条件相同，但在潜质与实际成就方面有差异的人选中挑一个的时候，他们总是选择有潜质的那一个。\u003c/p>\u003cp>原来，“潜质的说服力胜过现实”的现象不仅发生在招聘的时候。托马拉和同事们在一个更以消费者为主导的环境中也发现了这种情况。在该项研究中，Facebook的用户们看到了一些对一位喜剧演员的评语。一半人看到的评语强调的是这位喜剧演员的潜质，比如“这家伙能成为下一个大腕儿”，以及“到明年，人人都会谈论这位喜剧演员了”。另一半人看到的评论强调的是这个喜剧演员已经取得的成就，比如“评论家们说，他已经成为大腕儿了”“人人都在谈论这家伙”。\u003c/p>\u003cp>Facebook的用户们表现出了更重视潜质的倾向：当评论强调的是喜剧演员的潜质而不是实际取得的成就时，用户表现出更大的兴趣和喜爱之情。\u003c/p>\u003cp>但这是为什么呢?\u003c/p>\u003cp>研究者认为，为何潜质总是比现实更吸引人，一个潜在的原因就是现实已经发生了，完全是确定的。当人们在评估一个具备“潜质”的候选人时，虽然这两个字会为信息或沟通带来明显的不利意味，但它给人带来的那种不确定的感觉却是相当有利的因素，换句话说，它激起了人们的兴趣。\u003c/p>","explains":"\u003cp>\u003cstrong>（概念辨析）\u003c/strong>\u003c/p>\u003cp>我们有时候是默认现实条件满足才能去做事情，觉得实际的成就才更吸引人。但是作者却说有的人更注重潜质的，甚至觉得潜质比现实更重要。\u003c/p>\u003cp>这里提到了两个概念，“潜质”和“现实”\u003c/p>\u003cp>概念1：我们先来看什么是现实，其实就是拆页里提到的一个词——实际成就。在拆页中指的是成绩、经验、资历之类比较具体的条件，是实打实的。\u003c/p>\u003cp>例子1：比如说小A去应聘一个公司运营经理的职位，她在相关行业有5年的从业经历，独立策划完成过**项目，这就是“现实”，它是客观存在的，不管你喜不喜欢，反正她就是有这些经验。\u003c/p>\u003cp>概念2：那什么是潜质呢？在拆页中指的是我们具备的某种能力，但还没完全发挥出来。不能用这种具体的经验经历来表示。但是未来可能会达到或者超过现实的成就。就好像是隐藏在海水下面的冰山，看起来不大，但不是全部，还有发挥的空间。\u003c/p>\u003cp>例子2：再举个例子，我也想应聘运营这个职位，我没有从业经历，专业也不对口，压根没接触过这行。但是我比较擅长写作，各个平台都有专栏，靠写作吸引了1万个粉丝，都是活人，没有僵尸粉。因为我要应聘的这个运营职位，写作能力很重要，HR可能会觉得我具备成为运营的潜质。\u003c/p>\u003cp>\u003cstrong>（步骤）\u003c/strong>\u003c/p>\u003cp>即便我拥有这个潜质，也不一定会得到这个职位。潜质不如现实那么一目了然，这是潜质的先天弱势。所以我们需要换一种表达方式来描述潜质，把抽象一些的潜质变得更有画面感，让人更直观的感受。在应聘时、谈判时、申请预算时，当现实条件不那么充分的情况下，把潜质表达的更吸引人，提升我们说服力，达到到我们沟通的目的。\u003c/p>\u003cp>怎样描述潜质，才能让它更吸引人呢？\u003c/p>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>，选择你的潜质。\u003c/strong>不管是应聘还是提方案，你脑子里肯定有了一些潜质，但是在表达的时候，建议大家选1-2个。如果选一个就选你觉得最有内容可说的。如果选两个，你还要选择一下优先顺序，先说的通常要是更容易引起对方兴趣的。\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>，说说将来能为对方带来哪些好处。\u003c/strong>这一步其实就是给你的潜质赋予画面感。就像我们写A2一样，会说未来在什么场景下会用到。这也是在对潜质进行场景化描述，你描述的越真实，就越容易打动对方，对方越可以明显的感受到这个好处。可以运用时间+效果的方式，到未来的某个时间可以达到什么效果，（比如1个月后，掌握该类产品的文案写作特点，写出自己独特风格的文案）\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>，提升潜质可信度。\u003c/strong>你怎么证明你具有这个潜质，说出你的体验或经历。可以举你以前的成功案例，提升潜质的可实现性。即便是一个小案例，也可以有以小见大的效果。（比如你要说自己团队协作能力强，可以说你曾经和分舵小伙伴一起成功组织了第四五六届宇宙中心杯拆书家技能大赛，大赛非常成功）\u003c/p>\u003cp>\u003cstrong>（适用边界）\u003c/strong>\u003c/p>\u003cp>说了这么多，像作者说的那样让潜质比现实更重要，其实是很难达到的，潜质变不成现实。我们不能一味的夸大潜质的好处，那样对方可能会觉得我们言过其实。而且我们说的潜质也得真有这么回事，要不然侥幸成功了也禁不起时间考验。\u003c/p>\u003cp>\u003cstrong>（例子）\u003c/strong>\u003c/p>\u003cp>我之前听过一个人的职业生涯分享，这个人是给得到哪些大咖现场演讲做ppt的，但他并不是做设计做传媒的，他原来就在机关工作，做的工作也完全不相关。\u003c/p>\u003cp>他是怎么争取这个机会的呢？他说我表现力特别强，我有做好这个工作的潜质，（步骤1）如果我来给您下个月的演讲做ppt，我不会用之前大家都用那种简洁商务风，我会用自己的风格，比较多的运用图像和色彩，起到一个和观众能互动的效果，更好的辅助您演讲。（步骤2）然后他就举了两个例子，去年逻辑思维做跨年演讲的时候，他同步做出了ppt版分享，有10w+的阅读量，被罗振宇本人转发。他刚工作不久用1个下午的时间给大领导做出一个很重要的路演的ppt，因为效果不错还获得了升职。（步骤3）\u003c/p>\u003cp>虽然他没有相关经历，依然获得了这份工作。\u003c/p>","interaction":"\u003cp>A3\u003c/p>\u003cp>接下来我们做个小练习，看看怎样才能把这个方法用起来。请大家在刚刚分好的小组里，和你的小组成员一起编一个小故事。具体要求如下：\u003c/p>\u003cp>1要\u003cstrong>设\u003c/strong>定一个场景、分配好角色，有起因经过结果。\u003c/p>\u003cp>2你选的是潜质而不是现实。\u003c/p>\u003cp>3讲故事的时候要让大家感受到提升说服力的三个步骤，并且最后推荐成功了。\u003c/p>\u003cp>\u003cstrong>（学习者分享）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我们分享的场景是面试，我们想招收的人是计算机领域的，面试者是物理学专业，但是我们被他的潜质打动，最后录取了他，过程是这样的：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>面试官：我看到你的专业是物理学， 为什么会选择计算机领域的工作呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>应聘者：我非常喜欢编程，我的业余时间几乎全部用于学习计算机的相关知识，我\u003c/strong>\u003cstrong>学习能力很强\u003c/strong>\u003cstrong>，虽然不是计算机专业的，但是对各种计算机相关知识都有一定的了解。\u003c/strong>\u003cstrong>（步骤1）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>面试官：但是你是学物理学的，和计算机专业的毕业生在知识体系上有差异，是什么让你觉得你能胜任这份工作呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>应聘者：我觉得我就是为编程而生的。只要能从事这项工作我愿意少拿薪水，甚至加班都可以。如果我能争取到这份工作我会在1周内尽快适应，并且积极学习弥补基础上的不足。\u003c/strong>\u003cstrong>（步骤2）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>面试官：你能在工作之余还能自学甚至追赶上科班出身的人？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>应聘者：我在校期间在完成自己专业的课业任务之外，我曾经参加学校计算机系的比赛，获得第五名的成绩。\u003c/strong>\u003cstrong>（步骤3）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>面试官：面向计算机专业学生的比赛吗？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>应聘者：是的，因为我参加了所有的计算机类社团，有比赛的信息我第一时间就会去。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>面试官：可以看出你很热爱计算机，我们愿意给你一次机会。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>总结\u003c/strong>\u003c/p>\u003cp>今天给大家分享了一个小方法，可以让我们在自身条件有所不足的情况下，通过把潜质表达的更形象、生动的方法，来提升我们的说服力，达到我们的沟通目的。我今天的分享就到这里，谢谢大家！~\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1528900269000,"updated_at":1528900269000,"ria":true},{"id":5041,"topic":"如何劝服对方做出符合自己期望的行为","learn_goal":"能够熟练的运用今天讲的3个步骤，劝服对方。","remark":"","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"刘小惠","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"【自我介绍】大家好，我叫刘文惠，文化的文，贤惠的惠，如果你说我是一个既有文化又很贤惠的女子，我会很开心。同时呢，我也是一位二级拆书家，今天给大家带来的是TF3-2的过级带拆。\r\n【场景法介绍】\r\n【事件】想象一下你是一个非常爱干净整洁的人，喜欢把家里整整齐齐，而你的家人总是臭袜子乱扔、鞋乱摆，用了的东西随处放。\r\n【提问】这时你会怎么做，怎么说呢？会不会把心里愤怒的小恶魔放出来，披头盖脸的训斥对方一顿？\r\n【影响】如果长期以往对方都不能改变自己的行为，如果对方是你的爱人，争执训斥多了会影响双方的感情，也许你会认为和对方三观不合，甚至会觉得自己找错了对象开始嫌弃对方。\r\n【解决】那么如何更好的劝服他人做出你期望的行为呢？今天带领大家拆解《细节》这本书，这是一本实用型工具书，涉及职场沟通、员工激励、家庭生活、商业谈判等多个领域。\r\n我们今天拆解其中的一个片段，通过3步使他人做出你期望的行为可能最大化。","ratings_count":1,"texts":[{"id":8143,"quote":"\u003cp>\u003cstrong>\u003c/strong>【自测量表】：\u003c/p>\u003cp>&nbsp; &nbsp;首先我们通过一些自测题了解下自己，请大家阅读以下5个题目，按照1-6分的标准给自己打分，1代表完全不符合，6代表完全符合，请大家根据自己实际情况打分。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>当与他人做沟通要求做某事时，\u003cbr>\u003c/p>\u003cp>我总是会让对方做出口头承诺；\u003cbr>\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>当我和朋友约会聚餐时，我总是\u003c/p>\u003cp>会要求对方重述约会地点、时\u003c/p>\u003cp>间；\u003cbr>\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>当我发出会议通知时，我总是会\u003c/p>\u003cp>要求参会人员回复“好的或者收\u003cbr>\u003c/p>\u003cp>到”\u003cbr>\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>当对方向我允诺后，我总是会在\u003c/p>\u003cp>对方显眼的位置贴上提醒的话\u003c/p>\u003cp>语；\u003cbr>\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>当得到对方的承诺后，我总是会\u003c/p>\u003cp>想办法让更多的人知道对方承诺\u003c/p>\u003cp>的事情\u003cbr>\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp; &nbsp; &nbsp;总分\u003c/p>\u003cp>【自测表-量表解释】 1分钟\u003c/p>\u003cp>&nbsp; &nbsp;好了，大家已经做完了。那现在请总分在25分以上的朋友举下手，如果你的自评分在25分以上说明您在劝服他人做出你期望的行为这方面有自己的方法，成功率很高。那么今天呢可以再多学一种方法。11-24分之间的伙伴举下手，在这个分数之间的朋友在处理的时候没有详细的步骤，但在说服他人的成功案例也还是有的，那么通过今天的学习可以使自己的思路更加明朗。有没有10分以下的朋友？10分以下的话呢说明只是通知、告知或是要求了别人，但是执行的过程中没有提醒，没有完整的处理思路。没关系，今天你可以学到一个好方法。&nbsp;\u003c/p>\u003cp>接下来就一起来学习吧。首先给到大家1分钟的时间阅读原文片段内容。\u003c/p>\u003cp>【原文片段】：\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;社会影响的基本原理之一就是承诺和一致性之间的关系。这个原理说的是，咱们绝大多数人都有跟自己许下的承诺保持一致的强烈愿望，如果这个承诺是我们主动做出的、需要花力气参与而且被公之于众的，那就更是如此。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>","explains":"\u003cp>【学习目标】今天希望大家在跟随我用RIA拆解完此片段后，当你想让对方做出符合你期望的动作时【观察到的动作】能够熟练的运用今天讲的【具体内容】3个步骤，【完成程度】劝服对方。\u003c/p>\u003cp>&nbsp;&nbsp;【互动】读完片段，想问下大家这个片段讲了一个什么原理？嗯，简单说就是承诺一致性原理。举个例子大家理解下，\u003cstrong>\u003c/strong>【举例】比如我签署了节约办公室用纸的承诺书，那么在我打印文件的时候，我会下意识的尽量用双面打印。这就是行动跟自己许下的承诺保持一致性，那么也可以说许下承诺能在一定程度上可以影响和改变行为。这为如何劝服对方做出符合你期望的行为提供了很好的思路。\u003c/p>\u003cp>&nbsp;&nbsp;那么具体怎么做呢？通过对这个片段的拆解，我拆出了3个步骤，下面将带领大家通过一个例子来讲解。\u003cstrong>\u003c/strong>【举例】首先我们把刚刚节约办公室用纸的例子延展开来，假设你是个部门主管，行政部门提出因办公用品浪费严重导致资金支出庞大，急需要倡导员工更加积极地回收利用物品，且还要降低办公室的总能耗，你如何来执行呢？\u003c/p>\u003cp>&nbsp; &nbsp;\u003cstrong>第一步：要求做出具体的承诺。\u003c/strong>根据一致性原理，许下承诺可影响行为。要由浪费变成节约就是行为需要改变。【互动】那么我们进一步思考下这两种承诺，哪个会更有效果些“降低办公室总能耗”和“尽量双面打印”，嗯，非常棒，是第二个。为什么呢？因为第一个是宽泛的，第二个更具体，对行动更具有导向意义。【解答异议】当然你们可能会问，上司让下属做个承诺那肯定容易啦。这个的确是这样，主管和职员存在上下级关系。但承诺也可以是口头的，\u003cstrong>\u003c/strong>【举例】比如让对方复述一遍你的要求，比如你发了会议通知，让对方回个“收到”，比如你想邀请对方来听一个讲座，你可以让对方写一个在提问环节想问的问题，这就如同许下了个小小的承诺。当然，如果承诺是对方自发主动提出，那效果会更好。\u003c/p>\u003cp>&nbsp; &nbsp;\u003cstrong>第二步：设计提示。\u003c/strong>我们可以在小卡片上或者便利贴上写上提醒话语放在跟对方承诺相关的场景处。\u003cstrong>\u003c/strong>【举例】比如在打印机旁边贴上“请尽量选择双面打印”。这是为了强调加深印象，同时起到提醒的作用。提示的形式可以多样的，只要能起到提醒的作用都可以，比如闹铃提醒，短信提醒等等。\u003c/p>\u003cp>&nbsp; &nbsp;\u003cstrong>第三步：设计特殊身份。\u003c/strong>在这个节约办公用品的例子中，当员工已作出具体承诺后，可设计一个“节约小能手”奖章，张贴在办公桌最显眼的地方，这样其它同事都能看到。这样的作用是在向别人宣告，有这个奖章的人是做了承诺的。既有提醒功能，也能约束做出承诺的人。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;好，三个步骤讲完了，我们再一起回顾一遍，【互动】我想请一个朋友来复述一遍。嗯，非常棒，不仅说出了三个步骤，把步骤需要注意的一些细节也阐述的非常正确。我很高兴您有认真听，对我是个鼓励。其实第三步对场景是有要求的，更适合于一对多的沟通，效果比用于一对一好，比如例子中的一个主管对多个职员，这样才能更好的发挥约束的作用。\u003c/p>\u003cp>【适用边界】那么对于整个三个步骤来说，你劝服对方希望对方做出你期望的那个行为需要是对方力所能及的，如果是超出能力范围之外的，可能对方会直接跟你说“臣妾做不到哇”\u003c/p>","interaction":"\u003cp>【给出具体场景】\u003c/p>\u003cp>学是为了更好的做，接下来我们一起做一个演练。\u003c/p>\u003cp>人物角色是老婆和老公两人，老婆很嫌弃老公臭袜子乱扔、鞋子不摆放在鞋架上、充电器乱放后经常找不到等等，在老婆眼里，老公就是一个不爱干净，不爱整洁的人。老婆期望老公能将换掉的衣物放在待洗衣服的竹筐里，期望脱下来的鞋子能放在鞋架上......这一天，老公下班后一进门放飞自我一样将脚上的鞋子一甩，老婆实在是看不下去了，她准备试试从我这里学到的方法。\u003cbr>\u003c/p>\u003cp>场景我有讲清楚了吗？\u003c/p>\u003cp>分组\u003c/p>\u003cp>【给出清晰指令】\u003c/p>\u003cp>好，已经分成了两组。我会给到大家5分钟的时间进行讨论演练，5分钟后请一个小组来演绎，要有对话和肢体语言，不方便演绎的也可以有旁白。对话要能告诉我们你们是如何运用今天所学的方法来劝说老公做出老婆期望的行为，第二步和第三步比较偏向于动作，因为演练的目的是更好的熟悉今天所学和知道如何应用今天所学，所以在演练的时候可以老婆向老公提问确认的方式体现在对话中。比如老婆可以说：“老公，我担心你忙起来了容易忘记，所以想给你设定一个提醒卡片，你希望我上面写什么？”当然肢体语言也可以展现一下老公是如何放飞自我甩鞋子的。开始吧，放飞你们的演技吧。\u003c/p>\u003cp>【现场演练】\u003c/p>\u003cp>老公进门甩鞋子。\u003c/p>\u003cp>老婆：老公，你每天回来可以把鞋子放在鞋架上吗？\u003c/p>\u003cp>老公：我觉得这样比较舒服啊\u003c/p>\u003cp>老婆：你是舒服了，我每天收拾也挺辛苦的\u003c/p>\u003cp>老公：好，好，我捡起来。\u003c/p>\u003cp>老婆：以后你每次这样做可以吗？\u003c/p>\u003cp>老公：好，好，我下次继续这样做\u003c/p>\u003cp>老婆：我知道你工作挺忙的，我怕你忘记，我在鞋架上给你弄个提醒卡片吧。我写上“\u003c/p>\u003cp>请把鞋子放鞋架上”可以吗？\u003c/p>\u003cp>老公：好的。\u003c/p>\u003cp>老婆：你承诺了，且这么做了。我给你一个笑脸吧。\u003c/p>\u003cp>现场老婆通过肢体语言演绎设置提醒卡片和贴笑脸。\u003c/p>\u003cp>【拆书家反馈】\u003c/p>\u003cp>好，非常好。我们给这组小伙伴掌声鼓励。第一步要求做出具体的承诺并不一定要求对方\u003c/p>\u003cp>一字不差的复述原话，刚刚小组中的老公回复好的也是做出承诺的一种形式，因为不是你\u003c/p>\u003cp>训斥逼迫而做出的回复。第二步和第三步用对话的形式不是特别好体现，他们以问答的形\u003c/p>\u003cp>式，特别是有完整的肢体演绎，非常的棒。在最后还设置了笑脸的奖励。非常棒。\u003c/p>\u003cp>A2&nbsp;&nbsp; 1分钟\u003c/p>\u003cp>【布置作业-特定任务/分享/陪练】\u003c/p>\u003cp>今天跟大家在一起很开心。我们的拆书理念是学以致用。所以呢在这里给大家布置个作\u003c/p>\u003cp>业，在接下来的一周里，请留意并找出当你想劝说对方做出你期望的行为时的场景，比如\u003c/p>\u003cp>生活中你想让你的母亲大人炒菜时少放盐，比如工作中你很期望一个客户来参加你们公司\u003c/p>\u003cp>的展会等等，然后运用今天所讲的方法实践，欢迎大家在爱好者群里分享你是怎么做的。\u003c/p>\u003cp>或者也可以找朋友创造这么一个场景，运用今天的方法进行练习。\u003c/p>\u003cp>【伙伴分享】\u003c/p>\u003cp>丽丽分享:\u003c/p>\u003cp>我是一名初中语文老师，我希望我的学生能每天写日记\u003c/p>\u003cp>我下周一在课堂上可以这样做：\u003c/p>\u003cp>首先，我说明每天写日记的好处，然后跟大家说愿意参与每天写日记的同学来我这里签\u003c/p>\u003cp>个名。签名的行为也是他们做出承诺的一种方式。\u003c/p>\u003cp>然后，告诉刚刚做出承诺的同学写一个提醒语放在书桌上他们认为最显眼的位置来提醒自\u003c/p>\u003cp>己。\u003c/p>\u003cp>最后呢我给每个刚刚做出承诺的同学发放一个笑脸贴在他们的书桌上，这样其它同学就知\u003c/p>\u003cp>道他是每天要写日记的人，是做出承诺的。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>最后我们再回顾下今天的内容。\u003c/p>\u003cp>1.回顾知识点。我们今天学习了劝服别人使对方做出符合我们期望的行为的一种方法。第\u003c/p>\u003cp>一步是要求做出具体的承诺。承诺是具体的，不是宽泛的。承诺可以是书面的也可以是口\u003c/p>\u003cp>头的。第二步，设计提示。提示的形式有很多种，主要是能起到提醒的作用。第三步设计\u003c/p>\u003cp>特护身份，它也有提醒的作用，主要的是有约束做出承诺的人的作用。\u003c/p>\u003cp>2.适用边界：今天讲的这个方法有一个适用边界，就是在劝说对方做出符合你期望的行为\u003c/p>\u003cp>应该是对方力所能及的，如果是超出能力范围之外的，可能对方会直接跟你说“成妾做\u003c/p>\u003cp>不到哇”\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1524663746000,"updated_at":1524663991000,"ria":true},{"id":4699,"topic":"科学地设置目标","learn_goal":"用浮动数字范围的目标让自己或他人重新投入","remark":"你有没有过这样的情况：明明定了目标却没能坚持下来，好好的新年计划，却时常无疾而终……\r\n\r\n也许不是你的自制力不够，不是你的意志力不坚，而是你需要一个更加科学合理的目标。\r\n\r\n来吧，和小猫一起，从《细节》入手，更科学地设置目标，鼓起干劲重新上路~","level":"TF1-2","duration":13,"status":29,"type":0,"chaishujia":{"username":"邱小猫","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"大家好，我今天给大家带来的书是《细节：如何轻松影响他人》。\r\n 它的英文名叫《The Small Big》，生活中那些微小的发现与细节的改变可能会产生巨大的影响，而且它影响的巨大程度往往超过人们地想象。\r\n 所谓“四两拨千斤”，这本书用很多案例说了很多方法，告诉你怎样用最小的细节改变，带来最具成效的结果，并成功影响他人。\r\n 今天又恰巧是2018狗年第一拆，我相信大家可能在新的一年里可能会定制很多新年目标和新年计划，而今天要讲的就是如何科学地设置目标，这里就有一个小《细节》了。\r\n 请大家阅读拆页。","ratings_count":1,"texts":[{"id":7745,"quote":"\u003cp>按常理，当我们为自己或他人设定新目标的时候，经验总是告诉我们，要把目标设定得非常具体。比如，每周减掉2磅（约1.8斤）体重，1小时跑6英里（约9.6公里），或是每个月存下100美元作为来年的度假基金。但是，当我们说服自己或他人重拾目标的时候，这个常识是否正确呢？\u003c/p>\u003cp>营销学教授毛拉·斯科特和斯蒂芬·诺里斯认为，虽然人们在直觉上感到，在首次制定目标时，应当把它量化为单一而具体的数字，但是在重拾先前的目标时，这样做就未必最好了。相反，这两位学者认为，比起单一的具体数字（比如每周减掉3磅体重），把目标改成一个上下浮动的数字范围（但平均值和原先的数字一样，比如每周减掉2-4磅），会更加有助于人们鼓起干劲儿，重新投入。\u003c/p>\u003cp>对于那些小一点儿却依旧十分重要的、日常生活中的目标，比如多存一点儿钱，减掉几斤肉来说，最重要的是持续。既然某种行为的关键因素是帮助人们牢牢记住目标，那么这个小小的改变就足以造成巨大的影响。但它背后的原理是什么？\u003c/p>\u003cp>研究证明，让人们实现目标的重要因素有两个：挑战性和可实现性。目标应当让人感到有充分的挑战性，因为这会让人产生成就感，但前提得是它有实现的可能。面对单一数字型的目标，人们不得不挑选一个相对容易达成的、相对有挑战性的数字，或者是两者之间的这种，而浮动范围性的目标把这两个因素都包含在内。简单地说，他之所以能够促使人们重拾目标，是因为它能让人把可实现性和挑战性这两方面的成就感都占全了。\u003c/p>\u003cp>正如我们在这本书中不断提到的，小事也很重要。\u003c/p>\u003cp>当我们想调动自己或他人的积极性的时候，把制定目标的方式做一个小小的改变，就能得到巨大的成效。\u003c/p>","explains":"\u003cp>目标其实有很多种（一次性目标和重复性目标）\u003c/p>\u003cp>有些目标我称它为“一次性”目标，比如在某个时间点前完成某个项目。它是“逐步推进”的，可能有A、B、C多个不同的子任务，子任务可能各自不同，全部完成后，整体目标才算完成。\u003c/p>\u003cp>还有些目标我称它为“重复性”目标，它可能每次做的内容都差不多，但是它是通过时间的累积去“逐渐精进”的，需要你持续去做，重复多次。比如健身，比如练习钢琴。\u003c/p>\u003cp>这个拆页中所说的方法，其实比较适合那些“重复性”目标。\u003c/p>\u003cp>就像拆页第一段所说的“重拾目标”，如果是一次性目标其实谈不上“重拾”，只有重复性目标，需要你一次一次、一次一次的去练习和实施，它可能是单一、枯燥、无趣的，所以你才容易放弃，所以才需要重拾。\u003c/p>\u003cp>而拆页中所说的方法——方法其实很简单，就是用浮动范围的数字目标代替单一数字目标，而方法的最终目的，其实就是帮助调动积极性。\u003c/p>\u003cp>因为浮动范围数字目标可以同时提供两方面的成就感，1是可达成性，2是挑战性。\u003c/p>\u003cp>它不像单一数字目标，可能因为设得太难，导致经常达不到而最终自暴自弃；也不会因为设得太容易，导致觉得没有挑战性，无趣，最终不了了之。\u003c/p>\u003cp>另外，拆页中所说的方法还可以用于他人，特别是用来调动他人积极性的时候，如果你已为人父母，可以引导孩子制定一个浮动数字的目标，如果本来是计划每天阅读30分钟，可以改成20-40分钟的阅读。\u003c/p>\u003cp>或者，当你发现你的朋友因为使用单一目标未能坚持而放弃的时候，你也可以给他提出建议，改成浮动数字目标。（健身：每天跑2公里1-3公里/10-20分钟）\u003c/p>\u003cp>总结来说，也就是：对于重复性目标，用浮动范围数字目标代替单一数字目标，可以更大调动自己或他人的积极性，让人更容易重拾/坚持目标。\u003c/p>","interaction":"\u003cp>请大家回忆2017年有没有制定过什么重复性目标，是单一数字目标还是浮动范围目标？完成情况又是怎么样的呢？请大家讲述自己的故事，在小组内做分享。\u003c/p>\u003cp>今天学习了新的目标制定方法，请大家用1分钟时间写下一个新的重复性目标。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1519570154000,"updated_at":1519570154000,"ria":true},{"id":4348,"topic":"执行意向","learn_goal":"通过执行意向的应用计划帮助他人提高履行承诺的可能性","remark":"本书提供52个微小改变影响对方的实操训练，告诉你如何在这个信息量超载的时代用最小的细节改变成就结果上最大的差异，并成功影响他人。","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"Shirley雪莉","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"大家好，我是二级拆书家赵学丽，今天我拆的等级是3-1，拆的书是《细节》。\r\n场景：昨天跟几个朋友聚会，大家聊得很嗨。都说自己起得比鸡早，睡得比狗晚，操着卖白粉的心，赚着卖白菜的钱。看他们吐槽那么带劲，我憋了好久。最后实在没憋住，跟他们说：钱不好赚的原因是我们自身的能力不够，那这个时候应该把注意力放在自身能力的提高上面，而不是老在钱上面打主意。听完我的话，他们看着我，仿佛我是另外一个星球来的。那种表情让我突然明白了一个词：生无可恋。你能想到他们怎么对我说的吗？“你已经到了不该这样任性的年龄啦。”。。。提问：你是否也有过以为一腔热情就能帮助他人改变他人，却发现被人家当成了冷笑话。或者内心有着各种帮助他人获得成功的美好愿望，却发现甚至连身边的人都影响不了？ 影响： 缺乏影响力小到可以影响我们的日常生活比如家庭计划能否得以执行，大到可以影响工作成绩，事业上能否得到认可，甚至人生价值的实现。解决：那如何能够提高自己的影响力？本书用改变生活中微小细节的思路获得超乎想象的影响力。用了将近100个经典实例来讲述与分析影响力的提升技巧。教会我们在真实的生活中用上这些四两拨千斤的影响策略，帮助提升我们的影","ratings_count":0,"texts":[{"id":7348,"quote":null,"explains":"\u003cp>\u003cstrong>拆书目的：&nbsp;\u003c/strong>\u003c/p>\u003cp>通过今天的学习，大家能够用执行意向的三个步骤来设计一个应用场景，帮助他人做出履行承诺的具体计划，从而提高履行承诺的可能性。\u003c/p>\u003cp>请大家用1分钟阅读微信群里的片段，读完之后请举手示意我。\u003c/p>\u003cp>\u003cstrong>内容讲解：（\u003cstrong>6分钟\u003c/strong>）\u003c/strong>\u003c/p>\u003cp>片段中案例的反应现象在我们的生活中也是很普遍的对吧，我们也会经常遇到别人答应自己的事情实际上却没有做到的情况，这种时候我们一般会什么反应呢？\u003c/p>\u003cp>今天教给大家一个方法：执行意向。这个方法如果用好了，可以有效地帮助你说服他人履行承诺。\u003c/p>\u003cp>\u003cstrong>概念：什么是执行意向呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>举个例子：\u003c/strong>\u003c/p>\u003cp>昨天其中一个朋友小红很郁闷，因为他老公答应圣诞送礼物给她，后来却忘记了。我就问她老公当时是怎么承诺的。她回答说：我提议“老公，圣诞要送我礼物哦。”，然后我老公很爽快地就答应了：好啊，没问题。\u003c/p>\u003cp>那么“这个老公爽快地答应了”这个行为是一个“执行意向”吗？不是，因为只有对提议的意向，没有执行的具体计划。再举个例子，我约李磊来参加拆书帮的活动，她直接说拆书帮不好玩，不去。这算执行意向吗？更不是了，对吗？因为甚至她对我的提议都没有意向，更谈不上计划了。\u003cstrong>\u003cbr>\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>对比引出关键点：\u003c/strong>\u003c/p>\u003cp>根据这两个例子我们试着来一起归纳出执行意向的两个关键点：\u003c/p>\u003cp>第一：对提议有明确的意向。\u003c/p>\u003cp>第二：要有具体的行动计划。\u003c/p>\u003cp>\u003cstrong>适用边界：\u003c/strong>\u003c/p>\u003cp>执行意向这个方法的目的是帮助说服对方履行自己的承诺。适用于对某个提议已经表示同意的人和情况。没有意向的人或者对我反感的人是不适用的。\u003c/p>\u003cp>\u003cstrong>行动步骤：\u003c/strong>\u003c/p>\u003cp>根据前面的讲解，我们可以梳理出执行意向这个方法的步骤：\u003c/p>\u003cp>\u003cstrong>第一步、确认意向：\u003c/strong>确认对方同意你对某件事的提议。\u003c/p>\u003cp>\u003cstrong>第二步、制定计划：\u003c/strong>对方答应了这件事之后，我们就要帮助对方做一个细化的具体行动计划，比如时间，地点，场景，步骤等。（因为这一步的计划是帮助对方把意向变成行动计划，所以是根据承诺的内容来确定的。比如对工作完成情况的承诺重点可能会在，工作开始时间，时间阶段，工作完成程度，步骤设计等等；而资金拨款方面的承诺重点会在金额，到位时间，到位方式等内容上。）\u003c/p>\u003cp>\u003cstrong>第三步、下一步行动：\u003c/strong>与对方一起确定下一步该采取什么行动。\u003c/p>\u003cp>举例：\u003c/p>\u003cp>&nbsp; &nbsp; 昨天的聚会上了解到小红想让他老公补送她一个礼物，我告诉了她这个秘密武器：执行意向的三个步骤。然后让李磊扮演她老公，他们一起完成了下面的计划：\u003c/p>\u003cp>\u003cstrong>第一步：确认意向\u003c/strong>\u003c/p>\u003cp>小红对李磊扮演的老公说：“老公，圣诞礼物你忘记了，你会补送我一个吗？ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>老公说：好的，老婆，没问题。\u003c/p>\u003cp>\u003cstrong>第二步：具体计划\u003c/strong>\u003c/p>\u003cp>接下来小红就开始策划她的具体计划了：\u003c/p>\u003cp>小红：你准备什么时间送我呢？ 老公：元旦快到了，那就元旦吧。\u003c/p>\u003cp>小红：你准备送我什么呢？ &nbsp; &nbsp; &nbsp; 老公：你想要什么啊？\u003c/p>\u003cp>小红：送我比特币吧。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;老公：什么玩意儿？\u003c/p>\u003cp>小红：比特币就是一种数字货币，反正就是钱嘛。送我半个就可以啦，相当于￥50，000.00。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 老公：什么货币，咋这么贵啊？\u003c/p>\u003cp>小红：不贵，现在都什么时代了，比特币都代表爱情了，人家说了：&quot;比特恒久远，一枚永流传&quot;。\u003c/p>\u003cp>老公：既然永流传，那好吧，只要你喜欢。反正咱不差钱。\u003c/p>\u003cp>\u003cstrong>第三步：下一步行动：\u003c/strong>\u003c/p>\u003cp>小红不失时机地向她老公说：老公，那是不是接下来就该准备钱了呢？ 老公：放心吧，没问题，回去就转给你。\u003c/p>\u003cp>\u003cstrong>结果：\u003c/strong>小红对这个方法非常满意，她说回去就给她老公用这一招，相信说服她老公一定没有问题。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2：催化应用（9分钟）\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分步催化1：&nbsp;\u003c/strong>\u003c/p>\u003cp>请大家想想，将来一个礼拜或者一个月之内有没有可能出现某人答应了你某件事，但是你还是担心对方恐怕因为各种原因无法履行承诺？想象是一个什么事情和场景，记录下来。\u003c/p>\u003cp>\u003cstrong>分步催化2：\u003c/strong>\u003c/p>\u003cp>请根据你刚刚想到的场景，人物和事件，设计一个故事。如何运用今天学习的“执行意向”三个步骤说服剧中的人物更好地履行自己的承诺。然后把你设计的故事编成剧本，包括故事发生的时间，地点，人物，事件，起因，经过，结果，过程中有什么样的对话和动作等等。给大家5分钟的时间。等会我们请人起来讲给大家听。\u003c/p>\u003cp>\u003cstrong>学习者案例分享\u003c/strong>\u003c/p>\u003cp>\u003cstrong>案例1：加一的案例：\u003c/strong>\u003c/p>\u003cp>时间： 2017年12月31日\u003c/p>\u003cp>地址： 远见中心拆书帮现场\u003c/p>\u003cp>人物： 加一，佐江\u003c/p>\u003cp>事件： 让佐江尽快把年会颁奖词的事情落实下来\u003cbr>\u003c/p>\u003cp>起因： 因为年会快到了，而佐江负责的颁奖词还没见动静，所以加一打算跟佐江见一面，计划用执行意向的方法说服佐江来落实这件事。\u003c/p>\u003cp>经过：\u003c/p>\u003cp>加一约了明天跟佐江见面，并设计了与佐江的对话情景：\u003c/p>\u003cp>\u003cstrong>步骤一：确定意向\u003c/strong>\u003c/p>\u003cp>加一：佐江，可以早点把年会的颁奖词写出来吗？\u003c/p>\u003cp>佐江：不就是颁奖词吗? 很快就能搞定。\u003c/p>\u003cp>加一：我的要求是在年会之前要把奖状制作出来，所以颁奖词就得马上写好了。\u003c/p>\u003cp>佐江：还要把奖状制作出来，我把人选出来就ok了啊。\u003c/p>\u003cp>加一：可是我给你的人物是整个这个流程都要走完。\u003c/p>\u003cp>佐江：那好吧。\u003c/p>\u003cp>\u003cstrong>步骤二：具体计划\u003c/strong>\u003c/p>\u003cp>加一：那我们一起来把计划细化一下可以吗？\u003c/p>\u003cp>时间：是在年会召开的时间，也就是2018.1.13之前，所有的奖状要打印出来。\u003c/p>\u003cp>佐江：好的\u003c/p>\u003cp>\u003cstrong>步骤三：下一步行动\u003c/strong>\u003c/p>\u003cp>加一：那下一步行动应该是什么呢？\u003c/p>\u003cp>佐江：下一步是搜集颁奖词需要的奖项内容和素材，所以我们应该要马上发起投票环节，来选出确定奖项名词，内容和获奖者。\u003c/p>\u003cp>加一：好的，那就马上开始行动吧。\u003c/p>\u003cp>\u003cstrong>结果： \u003c/strong>面对加一的强势，佐江无奈地接受了，并马上开始打电话给他的团队布置投票的事情。加一也得到了满意的结果，并且有了接下来监督工作完成情况的依据。\u003c/p>\u003cp>\u003cstrong>案例2：佐江的案例\u003c/strong>\u003c/p>\u003cp>时间： 2018年1月4日\u003c/p>\u003cp>地址： 远见中心拆书帮现场\u003c/p>\u003cp>人物： 佐江和他的徒弟Sophie\u003c/p>\u003cp>事件： 让Sophie尽快按照她的承诺来拆书\u003cbr>\u003c/p>\u003cp>起因： 因为这段时间Sophie的拆书计划经常不能实现，几次说好了但是都拖着没有拆。所以佐江打算用执行意向的方法说服Sophie来落实这件事。\u003c/p>\u003cp>以下是佐江打算用这个方法说服Sophie的计划\u003c/p>\u003cp>经过：\u003c/p>\u003cp>\u003cstrong>第一步：确认意向\u003c/strong>\u003c/p>\u003cp>佐江：你确定下下周可以拆吗？\u003c/p>\u003cp>Sophie: 是的，一定可以（前面已经确认过，所以直接给出了Sophie的回答）。\u003c/p>\u003cp>\u003cstrong>第二步： 具体计划\u003c/strong>\u003c/p>\u003cp>佐江打算跟Sophie确认的具体计划：\u003c/p>\u003col>\u003cli>\u003cp>下周一到周二：确定1-2个片段\u003c/p>\u003c/li>\u003cli>\u003cp>下周二到周三：把I的逻辑，以及你打算怎么拆的思路讲给我听\u003c/p>\u003c/li>\u003cli>\u003cp>下周三到周五：写好预备表\u003c/p>\u003c/li>\u003cli>\u003cp>下周六周日：拿给我看，并进行修改\u003c/p>\u003c/li>\u003cli>\u003cp>下下周四之前：反复练习\u003cbr>\u003c/p>\u003c/li>\u003c/ol>\u003cp>\u003cstrong>第三步: 下一步行动：\u003c/strong>\u003cbr>佐江： 那接下来你就可以去寻找片段了。\u003c/p>\u003cp>结果：Sophie觉得有了这样的计划，她行动起来思路就清晰得多，并且非常乐意按照佐江的计划去做。\u003c/p>\u003cp>\u003cstrong>总时长：19分钟\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>观察家审核意见\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003cbr>\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1514707602000,"updated_at":1514707818000},{"id":4251,"topic":"为互助留出余地","learn_goal":"为互助留出余地","remark":"工作中，经常帮助别人完成工作得到大家的认可从而走向成功之路的人很多！你是否也在这么做？那你是否时常因为热心肠帮助别人而耽误了自己的工作呢？你知道如何在工作中把帮助别人这件事达到最大效益吗？","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"杨帅","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"大家好，我叫杨帅，我的三个标签第一个是帅，我说我不帅你们也不信啊；第二个标签是拆书帮翰林分舵新晋灵魂摄影师，我的摄影技能是得到大家的认可的哦；第三个标签是我的目标霸占舞台。\r\n接下来我要分享的片段来源于《细节：如何轻松影响他人》，本书是通过52个微小改变来影响其他人的训练，感兴趣的小伙伴可以阅读，下面给大家几分钟时间看一下原文片段，看完的小伙伴可以眼神示意我。（1分钟自我介绍及图书介绍）","ratings_count":0,"texts":[{"id":7240,"quote":"\u003cp>如果在工作中做一个豪爽大方的给予者能够为我们赢得较高的社会地位却同时也削弱了我们做分内工作的生产能力，我们应该怎么做才好？弗林的研究给出了确定的答案。这项研究发现了一个不起眼的指标，却能够同时增强助人者的社会地位和生产力。这个指标不是帮忙的次数，而是“互助”的次数，先是为对方提供有益的帮助，然后得到对对方回报过来的有益帮助，这会把给予的良好效益放大到最大程度——不但他们自己受益，有份参与的每个人都能受益，因为给予者的地位提高了，生产力也提高了。请记住，这个结果与互惠原理是高度一致的，互惠原理对所有成功的群体来说都至关重要，因为它促进了互助互利的行为。\u003c/p>\u003cp>这些成果给了我们明确的启示。首先，我们应该大方主动地在工作中帮助他人。要注意，最重要的一点就是你要第一个行动。第一个出手相助会激活互惠原理，并因此增加未来的互助次数——对于职场中的共同成功，这个因素至关重要。\u003c/p>\u003cp>第二，要把你提供的帮助或有价值的信息做个定位，把日后对方可以全力回报你的可能性凸显出来。这就需要我们把平素的反应，也就是听到对方感谢我们时，我们所说的话，做个微小却重要的调整。这个调整能为你的未来合作和影响行为带来惊人的巨变。以下就是我们推荐的三种应答方式，用它们来回应对方对你的感谢： \u003c/p>\u003cp>1、“能帮上你的忙我很高兴，因为我知道，当一个人需要帮忙的时候，别人的一双援手是多么有价值。\u003c/p>\u003cp>2、“不客气。同事之间理当如此”\u003c/p>\u003cp>3、“没关系。因为我知道，如果需要帮助的是我，你也会这么做的。”\u003c/p>\u003cp>总结一下，想要从职场中的给予行为中得到最大的益处，关键的做法就是“为互助留出余地”，这需要两个很小却至关重要的步骤：率先提供帮助、信息或服务；一定要在回应对方时，明确地为你提供的帮助定位——这是一个自然的、平等的互惠行为，这样你就为日后的互助留出了机会。\u003c/p>","explains":"\u003cp>我们大部分人都会认为在工作中，多多帮助同事，不仅在同事心中的地位回提高还能被领导关注，从而走向成功之路，但是你有没有发现，我们往往在帮别人完成任务的时候，自己的工作却需要加班完成，影响了我们自己的工作效率。那么我们怎样才能保证帮助他人的同时又不影响自己的事情呢？\u003c/p>\u003cp>书中给出了明确的答案——互助，只有互助才能使我们在帮助别人这件事上达到最大效益，既提高了地位又提高了效率。那么具体应该怎么做呢？书中给出了两步：\u003c/p>\u003cp>第一步：大方主动地在工作中帮助他人，并且要第一个行动，为互助打好基础；\u003c/p>\u003cp>第二步：给你提供的帮助做个定位，凸显对方全力回报你的可能性。比如，在收到感谢时调整回答方式给你未来合作带来惊人变化：\u003c/p>\u003cp>1、“能帮上你的忙我很高兴，因为我知道，当一个人需要帮忙的时候，别人的一双援手是多么有价值。\u003c/p>\u003cp>2、“不客气。同事之间理当如此”\u003c/p>\u003cp>3、“没关系。因为我知道，如果需要帮助的是我，你也会这么做的。”\u003c/p>\u003cp>当然了，我们的帮助和付出，肯定不是一定要得到回报的，所以这个片段是有适用边界的哦，&nbsp;也就是说在你有可能需要麻烦别人或者需要他人同样帮助的情况下，埋下一个伏笔，相当于买保险，我们不一定非要用到，但对我们说是个保障。\u003c/p>\u003cp>分享一个我自己的小故事：\u003c/p>\u003cp>上周末公司举办活动，本来我不用参加，但是同事突然有事，寻求我的帮助，我反正周末也没什么事就答应了，他看我这么痛快，特别的开心，一个劲的感谢我，因为当时有看过这个小片段，随即就说了句“没关系。因为我知道，如果需要帮助的是我，你也会这么做的。”他说，是啊是啊。\u003c/p>\u003cp>周一我们一起吃饭，聊起了我正在写的关于筹建的材料太细了弄起来特别浪费时间，他说他刚好也弄过，可以给我一个模版，照着填就行。有了他的帮助，我分分钟就完成了这项工作，不仅节省了我的时间提高了工作效率，还把我从烦闷中解救出来。\u003c/p>\u003cp>接下来请每人想一个你在工作或者生活中经历过的，你是否是主动去帮助他人的，他人感激你时你是怎么回答的，结果怎样？有没有小伙伴在主动帮助他人后却没有获得他人同样的帮助？在小组内分享，时间5分钟。\u003c/p>\u003cp>（2-3分钟讲解原文）\u003c/p>","interaction":"\u003cp>（A1）刘志学小伙伴分享了的案例是这样的，他有个朋友很慷慨的帮助他开发客户，后来又向他借钱的事，因为对方帮了他，他也帮助了别人，这位小伙伴的案例不太符合我们今天分享的为互助留出余地的内容。\u003c/p>\u003cp>接下来邀请琳琳小伙伴分享一下自己的失败案例：\u003c/p>\u003cp>（A1）琳琳的同事会经常跟琳琳借ppt看，还到处说是因为琳琳比较闲才跟琳琳借的。琳琳后期想跟这位同事借数据资料，同事却找各种借口推脱，没有分享给琳琳。\u003cbr>\u003c/p>\u003cp>（A2）那么接下来琳琳的计划是：在同事跟自己借PPT的时候，直接跟他说，你以后有同样的资料也要借给我，并且不能再到处说是因为我闲才找我借这种话。\u003c/p>\u003cp>也就是说给自己的帮助做个定位。\u003c/p>\u003cp>分享回顾：1、大方主动、第一个去帮助别人；2、给自己的帮助做个定位，在我以后要麻烦你的时候做个伏笔，也希望你能帮助我。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1513333993000,"updated_at":1516716773000,"ria":true},{"id":4229,"topic":"让你的建议更受欢迎，试一试“增强版主动选择”法","learn_goal":"清楚理解“增强版主动选择”两步法，有学习者在现场对A1经历做","remark":"在作选择时，大多数人都会根据自己的判断选择做或者不做，但同样我们也可以在这个环节中做一点小“手段”，来影响人们的选择，让人们更倾向去选择去“做”的选项，如何实现？今天的拆书内容我们一起学习。","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"刘天宇","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"今天拆解的这本书叫《细节-如何轻松影响他人》，这本书的作者是写出《影响力》的罗伯特·西奥迪尼，一个专门研究影响力和说服力的专家。这本书在国内也是非常畅销，仅仅是在《罗辑思维》平台，3个月就卖了10万册。与其他这种讲说服的书很多理论性很强不同的是，这本书中通过52个微小改变的实际案例来阐述“四两拨千斤”的小改变就可以大大提升影响的效果。书中的案例都是基于研究实验的结果，理论有理有据，通俗易懂，每个片段都相对独立，可以集中阅读，也可以利用零散时间阅读。通过阅读这本书，我们可以很轻松的掌握一些影响他人效果更好的一些小技巧。今天带来的这个片段是来自书的第17个片段，来看看在对方做决策时，我们如何利用损失规避原则，让对方更容易选择我们提出的方案","ratings_count":0,"texts":[{"id":7216,"quote":null,"explains":"\u003cp>我想各位不论是在工作中或者在生活总都会遇到希望说服对方按照你的建议去做的场合，对吗？很多时候我们会怎么做？\u003c/p>\u003cp>（1）可能苦口婆心的将道理，做这个有多好多好，你得听我的——说教式\u003c/p>\u003cp>（2）可能还有你不需要知道为什么，你必须去做的这种命令——强制的方式\u003c/p>\u003cp>（3）你选我们吧，我们有这样那样的优惠，好处——哄骗利诱式\u003c/p>\u003cp>以上提到的方法在不同的场景不同的人物关系时候会有一定效果，但很多时候是因为信息了解不全或者被迫选择，说服的效果并不理想，可能即使当时做出选择后续也不会再有更深入的下一步动作。所以片段给我们一个很简单但是很有效的2步法：\u003c/p>\u003cp>\u003cstrong>（1）构思两个选择，让受众从中主动挑一个。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（2）把你想让他们选的那个选项包装一下——向他们指出，如果不这么做的话就会损失什么\u003c/strong>\u003c/p>\u003cp>那有的伙伴可能也会问，我是部门领导或者家长，说教、强制的方式也很管用，我做销售的前面给客户各种画饼也能达到效果，为啥还要用片段的方法呢？不用这个方法有什么不好呢？\u003c/p>\u003cp>（1）如果第一步不是让对方主动选择，而是被动的选择，（比如只能这么做或者强制要求必须这么做），带来的结果很多时候就是效果不持续，很快就失去作用，又回到原来的状态，因为不是发自自己内心选择的——想想我们上学时候父母是如何阻止我们早恋的。而且久而久之会让接受者产生抵触叛逆的心理，产生得结果就是抵抗或者逃避，说服肯定就不成功了。\u003c/p>\u003cp>（2）为什么直接说会有什么好处不比说会损失什么更有效果。这其实是人的一种心理——损失规避。人们都有避免失去的强烈意向。——想一想我们看到电视广告 上说“错过今天，再等一年，赶快拿起手机订购吧”那种心理（如果确实有用的产品）\u003c/p>\u003cp>\u003cstrong>所以这个方法高明之处就在于让对方既参与进去感受到的是自己的选择，同时又利用了人的“损失规避”心理让对方更坚定的选择我们期望得到的结果。这个方法我们可以用在商务谈判、家庭沟通、产品设计等等很多的“说服”对方选择我们设定好的方案的场景。 这里补充说明一下，关于两个选择，可以是两个并列关系的选择。它也可以是针对一个动作的是否选择，一定是可以选，就是不做也可以，不能说不做就不行。\u003c/strong>\u003c/p>\u003cp>我想讲到这里伙伴们可能脑海中都浮现出一些场景和经历了。我讲一个我的案例。我最近的房子马上装修完了，接下来就要家电采购。迪迪本身就在家电零售企业，我就想说服他买有优惠的家电，我是这么说的：“你帮我们看看你们公司有没有打折的家电，家里要买电视冰箱洗衣机了，别忘了啊”。大家感受一下，作为听众，这样说对于自己来说没有选择必须要去做，也没有传达出来做不做有什么好处有甚么损失。所以当时我得到的答复就是：“我们的都比较高端的，打折也买不起”。如果用今天学习的方法，我可能会这样说：“咱们要买家电了，我们可以去你公司买，也可以去网上买，要是不去你们店买，又不能给你们贡献一点业绩，又可能比外面买的贵浪费钱，有这钱还能给你买几件衣服”。选择也有了，损失也有了。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>那接下来，我们已经分了2组，大家跟着我一起来回忆一下：最近一段时间，在公司或者在家里，是否发生过我们很耐心的试图说服对方接受我们的建议去做什么事，我们当时讲的手舞足蹈，声情并茂，当时对方也是聚精会神的听也回应了你，但之后却并没有真的去照做了的情况？\u003c/p>\u003cp>当时我们用了什么方式？我们每位伙伴先用1分钟自己在脑海中想一下有没有类似的场景，当时情况是怎样的，然后我们以小组为单位，互相分享一下当时的情况。\u003c/p>\u003cp>\u003cstrong>学习者1：我是一名软件销售，我的一个客户最近账号到期，我给客户打电话，跟他讲了很多软件续费的好处，还有现在续费的优惠，客户听完之后给我的回应是，我再看看吧，然后就没有下文了。\u003c/strong>\u003c/p>\u003cp>拆书家：在你的这个案例中，我们并没有给到客户选择题，就是要升级一个选项，而且我们也没有提出不升级的话会怎么样会损失什么，所以最后的说服结果也是不成功的。\u003c/p>\u003cp>\u003cstrong>学习者2：我的儿子最近正在学习围棋，但是回家之后总是拖延不去练习，我总是问：“儿子你什么时候去下棋啊”，他就说等一会儿，过一会还躺在沙发上还在看书，我继续问：“你看时间到了，你什么时候下棋呀？”\u003c/strong>\u003c/p>\u003cp>拆书家：其实对于孩子来讲，我们虽然用了一种相对温柔的提问的方式，但其实也只是一种选择，没得选，尤其还是多次提问，这样多次询问之后，其实会有可能让孩子有抵触情绪，更不愿意去下棋。\u003c/p>\u003cp>A1+：\u003c/p>\u003cp>通过前面两个案例，我们看到之前的说服看来当时我们的苦口婆心都白费了。大家都知道时间不能倒流，事情过去了就不能再挽回。但是如果，我们今天就有这么一个时光宝盒，可以让你有一次重来的机会，你会如何利用今天学习的方法，来让对方更加容易的做出这个决定呢？你会如何设置你的这两个步骤呢？\u003c/p>\u003cp>\u003cstrong>学习者1：我会给客户这样打电话说，现在的软件您也可以继续使用，基础功能都还可以用。新版本的软件增加了一些很实用的功能，那您也可以选择续费升级。如果您这段时间不升级的话，不但可能会失去续费优惠的福利，而且新的功能您在基础版上也没法使用了，您再考虑看看吧。\u003c/strong>\u003c/p>\u003cp>感谢学习者的分享，使用的非常好。我们说拆书学习最大的价值在于学以致用，希望今天我们在座的小伙伴今天结束学习之后可以继续找寻这个方法应用的场景并且多多实践，当然您可以选择实践，也可以选择今天有收获就够了，可是如果您不去实践的话，您可能就失去了让自己变得更有影响力的机会。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1513126527000,"updated_at":1514267082000},{"id":4201,"topic":"如何劝说他人做出有效承诺","learn_goal":"学习劝说他人做出有效承诺的方法","remark":"不管是学习、工作还是生活中，你是否会遇到这样的情况：\r\n●同学承诺从现在开始要好好学习，天天向上。第二天依然打游戏、刷剧；\r\n●老板承诺跟着他有肉吃，几年下来老板钱包越来越鼓，你依然一贫如洗；\r\n●男朋友承诺会对你好，可是一有点什么事就忘了你。\r\n为什么他们做出的承诺都像风一样，吹过就没了？如何才让他们做出有效的承诺？本周三翰林分舵，拆书家杨帅教你几招！","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"杨帅","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"大家好，我叫杨帅，三个标签帅、拆书帮城市之光分舵11月轮值主席、翰林分舵新晋灵魂摄影师。（1分钟）\r\n接下来用两分钟时间给大家介绍拆书和拆书帮分别是什么。拆书是一个学习的方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，要把知识关联到学习者的经验、规划具体的运用。分为个人学习法和组织学习法，个人学习法是指运用便签读书法阅读一本书相当于参加一场培训的效果。组织学习法是指拆书家通过一本书加工出一场现场学习，帮助学习者能够拆为己用。那么什么是拆书帮呢？拆书帮是学习者的社群，在全国各地均有分舵，拆书帮分舵的使命是帮助学习者成长成拆书家。（2分钟）","ratings_count":0,"texts":[{"id":7185,"quote":"\u003cp>研究者在加利福尼亚州的一家人气酒店里进行了为期一个月的实验。酒店请客人在办理入入住时做一个与环保有关的小承诺：有些情况下，这个承诺比较宽泛，客人要在一个“愿意在入住期间保护环境”的选项前打钩儿。另一些情况下，这个承诺更为具体明确，比如“愿意在入住期间重复使用毛巾。\u003c/p>\u003cp>除了做出宽泛或具体的承诺之外，有些客人还可以得到一个写着“地球之友”的别针徽章。作为对照，另一组在办理入住时无须做出环保承诺的客人也得到了这种徽章。\u003c/p>\u003cp>最后，另一个对照组以正常模式办理了入住：没有拿到徽章，也无须做出任何承诺。\u003c/p>\u003cp>结果如何呢？\u003c/p>\u003cp>研究者们发现，在办理入住时做出更加具体的承诺的客人，比那些做出宽泛承诺的更有可能重复使用毛巾（66%VS61%）。更为有趣的是，那些做出具体承诺，即愿意重复使用毛巾的客人也更有可能做出其他一些与承诺相一致的环保行为。例如，他们更加有可能在离开房间时关灯，在办理退房时关上空调和电视。这个发现多少有点儿违背直觉，毕竟，咱们都很容易认为，比起那些只答应要重复使用毛巾的人，许下更为宽泛的环保承诺的人应该会做出更多有利于环保事情吧。\u003c/p>\u003cp>此处的“四两拨千斤”启示是什么？任何一个想劝说他人做出多重并互相关联的行为改变的人，可以通过一个简单的两步法把成果最大化。第一步，确保最初的承诺是具体明确的。第二步，确保在实践该承诺的环境中，放置一个“提示”，这个提示应该完全符合第一步中的具体承诺，并且能够引发出另外一些与此承诺相关的、符合你期望的行为。\u003c/p>\u003cp>（实用类图书；拆页内容未超过2页图书内页）\u003c/p>","explains":"\u003cp>我们每天被各种承诺包围着，有的承诺兑现了，有的却不了了之，为什么他说会照顾我一辈子，后来却连送我上班都不愿意？为什么他说他一定会做个勤快的先生，后来却懒得什么都不做？为什么老板说你来加入公司未来发展可观，却工作了5年前途依然渺茫？为什么他们给你的承诺最终都没有兑现？\u003c/p>\u003cp>因为他给你的宽泛的承诺并没有什么卵用，只是说给你听而已，俗话说的，画个饼，就为了当时能让你相信他，但是却不足以起到提醒他自己去完成的作用，那么怎样劝说他人做出有效承诺，甚至更多行为改变呢？书中给出了2个步骤：\u003c/p>\u003cp>1、&nbsp;确保对方说出的承诺是具体明确的；\u003c/p>\u003cp>2、&nbsp;通过设置“提示”与具体承诺呼应，从而达到提示的效果，并做出更多与承诺相应的行为。\u003c/p>\u003cp>所以你不要跟我说你会一直对我好，你就直接说上班你愿不愿意送我就好了；你不要跟我说你会做个勤快的先生，你就说每天你会不会扫地就完了。\u003c/p>\u003cp>（用自己的话重述了原文知识点，清晰易懂）\u003c/p>","interaction":"\u003cp>我室友是一个比较懒散的人，不爱收拾屋子，也是因为平时太忙了，下班就想休息会，什么都不想动，屋子都是我自己收拾，上上周末看到我一个人收拾屋子，可能室友实在过意不去，她跟我说，你好勤快，每天也很累，还不忘把屋子收拾的那么干净，我得向你学习呀，我跟你承诺，我以后要做个勤快的姑娘，我感动的不得了，孺子可教也啊，然后当时她确实帮我一起打扫了，我俩一起很快就完事了。上周一周，我都没看到她收拾屋子，每天还是像原来一样，没事的时候窝在沙发上看书看剧，周末我实在受不了了，自己收拾起来，她看到我收拾屋子才说，啊，我给忘了，然后我就无语了。\u003c/p>\u003cp>现在我终于知道为什么她明明承诺了却没有做到，首先她并没有跟我说要怎么具体做来体现她的勤快，而是只是简单的说了要勤快，我就以为她要开始收拾屋子，还感动的不得了，其次，她少了一个提醒自己行动的提示，导致她一周都没行动，是因为她忘了。\u003c/p>\u003cp>（一个自己的具体经历，失败案例）\u003c/p>\u003cp>我打算今天再重新跟室友聊一下，引导她重新做一个承诺，设计的情景如下：\u003c/p>\u003cp>晚上下班后回到家，我先简单的收拾一下，等室友回来：\u003c/p>\u003cp>你是不是想做个勤快的人？那你觉得怎么做算是勤快的人？（引导室友自己说出勤快的人应该做什么事）\u003c/p>\u003cp>比如说：擦桌子、扫地、倒垃圾等\u003c/p>\u003cp>这些都是很简单的事啊，谁都会做，会做就能算勤快的人吗？\u003c/p>\u003cp>当然不是，要每天坚持做，才能算，我要像你一样每天下班回来后，擦桌子，扫地。倒垃圾，周末再一起做个大扫除。\u003c/p>\u003cp>那你怎样才能做到每天坚持呢？\u003c/p>\u003cp>1、&nbsp;&nbsp;&nbsp;用便签纸提醒自己，把便签纸放在桌子上，我每天下班都会喝水，一喝水就能看到，然后行动；\u003c/p>\u003cp>2、&nbsp;&nbsp;&nbsp;设置手机闹钟提醒（8：30-9：30），这样即使看不到便签纸也会想起来。\u003c/p>\u003cp>最后再跟室友确定，你是否愿意在每天晚上8：30-9：30之间做家务，收拾屋子，引导她承诺，这样的话，我想室友通过这次确定有效的承诺，她一定会成为你想要成为的做一个勤快的人。\u003c/p>\u003cp>以上就是我的全部分享，希望对你有所帮助，谢谢大家！\u003c/p>\u003cp>（总用时未超过15分钟）\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1512644313000,"updated_at":1520002690000,"ria":true},{"id":4081,"topic":"承诺要行动，要公开","learn_goal":"承诺要行动，要公开","remark":"","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"刘天宇","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"今天给大家带来的片段来自于这本书《细节—如何轻松影响他人》，这本书的作者之一罗伯特•西奥迪尼，他曾著有《影响力》，一本很畅销的书籍，这本书也是市场营销领域非常受欢迎的一本书，他通过52个微小改变的实际案例来提升效果的方法和原理，这本书曾有人说这本书是商家最不希望消费者看到的一本书，因为我本职工作就是做市场营销的，所以我也是一边阅读这本书，一边和大家来分享其中的片段，今天是我带来的这本书的第二个片段。","ratings_count":0,"texts":[{"id":7044,"quote":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;“\u003c/strong>\u003cstrong>承诺”+“提示”，让对方做出更多你希望的事\u003c/strong>\u003c/p>\u003cp>研究者在加利福尼亚州的一家人气酒店进行了为期一个月的实验。酒店请客人在办理入住时做一个与环保有关的小承诺：有些情况下，这个承诺比较宽泛，客人要在一个“愿意在入住期间保护环境”的选项前打钩。另外一些情况下，这个承诺更为具体明确，比如“愿意在入住期间重复使用毛巾”。\u003c/p>\u003cp>研究人员首先看多少比例的客人愿意许下承诺。（宽泛98%VS具体83%），结果初步看去，当你想要劝说某人许下承诺时，请他做一个较为宽泛（而不是更为具体）的承诺，你的成功率会比较大。\u003c/p>\u003cp>但是，在办理入住时做出更加具体承诺的客人，比那些做出宽泛承诺的更有可能重复使用毛巾（66%VS61%），更有趣的是，那些做出具体承诺，即愿意重复使用毛巾的客人也更有可能做出其他一些与承诺一致的环保行为。\u003c/p>\u003cp>任何一个想劝说他人做出多重并互相关联行为改变的人，可以通过一个简单的两步法把成果最大化。\u003cstrong>第一步，确保最初的承诺是具体明确的。第二步，确保在实践该承诺的环境中，放置一个”提示”，这个提示应该完全符合第一步中的具体承诺，并且能够引发出另外一些榆次承诺相关的、符合你期望的行为。\u003c/strong>\u003c/p>\u003cp>举个例子，比如你是办公室经理，你面对的问题是不仅要倡导员工更加积极地回收利用物品，还要降低办公室的总能耗。上述发现，你应该首先请员工们做出一个针对某项行为的具体承诺（比如每天晚上下班后把废止放进回收纸篓）。然后，你应该在一个能够提醒大家节约能源的地方放上一个“提示”（比如把回收纸篓放在电灯开关的附近）。这样做很可能会有一箭双雕的效果。如果你把一张写着“勿忘环保承诺，请随手关灯”的小卡片放在灯旁边，还能进一步取得更好的效果。\u003c/p>","explains":"\u003cp>不管是我们在工作上还是生活上，都会有很多希望对方按照我们想的去做的。但我们会发现，有时候对方并未按我们期望的结果去做，原因可能也有很多，可能是忘了，可能是觉得做不做没关系不重视，可能是对方不清楚这么做有什么好处等等。其实这些情况发生更多是只是我们单方面告诉别人，并没有得到对方的正式回应，也就是文中的“承诺”。为什么承诺重要呢，当我们承诺去做一件事时，相当于多了一分责任，一份提醒，所以更容易去完成。宽泛的承诺和具体的承诺，具体明确的信息更容易让人记住。片段中还告诉我们，当有了相应承诺后，在其承诺完成事情的环境中增加一些其他事情的小提示，也更容易让别人做更多。所以片段告诉我们这个两步的方法：第一步，要求对方做出具体的承诺；第二步，如果你希望的事情不只是一件具体的，可能是几件或者更多，原文中提到的小技巧就是在对方在执行你要求的事情的场合里，增加一些和承诺有关联的其他提示，更加容易让对方做到其他事情。\u003c/p>\u003cp>工作中我举个发生在我们部门的事：我们部门有一个同事专门负责公司的微信公众号运营，刚入职的头半年，不时出现错别字就是交代的工作拖了很久不去做，总之是经常出现不好的结果，每次开会都有问题，都要被说，效果也没有得到改善。后来有一次他又出现了错别字。然后我和他聊，咱们这件事怎么能改善呢，他自己主动说：“这样，我以后保障不出现错别字，发现一个字罚我50块”，我说好的，\u003cstrong>这是一个承诺\u003c/strong>。果然之后就几乎没出现错别字了。而且他还在\u003cstrong>工位上贴了一张小纸条提醒自己\u003c/strong>，每天检查微信内容3遍，不但如此，他在这个纸条上还写了关于微信运营的一些其他的每天必须做的事，其他事情做得也比之前积极一些，自发的提醒自己除了检查错别字还有其他的内容也要去做，结果也比之前好很多。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>那接下来，我邀请我们现场的伙伴，根据目前的分组情况，我们来小组内回忆一下，自己最近一年内，是否有发生过我们自己想让别人做某些事情但对方并没有做的情况，或者别人希望我们自己做什么事，我们最后没有做的事情？想一下当时具体的情况是则么样的，是什么原因没有做成？这一环节我们给大家4分钟时间讨论，讨论结束后我们会邀请一位伙伴分享她的经历。\u003c/p>\u003cp>学习者反馈1：拆书家艾丽斯电话里拜托我周末写一份之前的拆书的微信内容，我当时只说了好。但后来也没写。\u003c/p>\u003cp>拆书家反馈1：在这个场景里我们承诺了对方，但是中间过程没有提示，最终结果也没有达成。\u003c/p>\u003cp>学习者反馈2：老板让我做一个很庞大的事情，要研究透很多方面。当时我说好，但一直都没有进展。\u003cbr>\u003c/p>\u003cp>拆书家反馈2：老板的要求是一个很宽的方面，你的承诺是一个宽泛的承诺，所以最后没有达成，对吧。\u003c/p>\u003cp>刚才大家的反馈主要还是承诺不够具体的这一部分。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>那接下来，需要我们大家动动手，每个人发一张A2便签，我们来考虑一下，在接下来的半个月，12月前，我们有什么事情是你希望别人按照你的想法去做的？想到具体的事情后，大家再思考下，利用书中的方法，如何让对方可以更有可能的去做，并且做得更多？\u003c/p>\u003cp>学习者反馈：在本周日，让徒弟对拆书任务作出承诺，具体到预备提示表，内容的提交时间。\u003c/p>\u003cp>拆书家引导：那在这个过程中你还希望他做什么其他事嘛？可以用什么方法在准备拆书过程中提示他呢？\u003c/p>\u003cp>学习者反馈：希望他拆书后及时上传实录，那就在线下拆书评级的时候，在他的手册上贴一个便签，写上“马上传实录！”\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1511483925000,"updated_at":1511488792000,"ria":true},{"id":3976,"topic":"抓住TA心中的“非常态”，让语言更有说服力","learn_goal":"抓住TA心中的“非常态”，让语言更有说服力","remark":"","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"刘天宇","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"大家好，首先做一个自我介绍，我是老牛老刘，我的三个标签是：\r\n（1）本职工作上的——品牌总监\r\n（2）拆书帮的——深圳分舵宣传长老\r\n（3）生活上的——上午刚从集体户转成家庭户口的新深圳人\r\n今天我来抛砖引玉，通过我为大家带来的一个小片段为大家演绎一下拆书帮最基础的RIA读书法的具体使用方法。正式拆解之前，我首先要向今天新来的几位伙伴介绍一下什么是拆书，以及拆书帮是什么样的一个组织。\r\n拆书这个概念，源于赵周老师多年来对读书方法的一个总结，这个总结也有了一本书，叫《这样读书就够了》。拆书倡导的是读书不一定要看完整本书才能有收获，其实我们把书分成一个一个片段，其中很多片段都会让我们有一些收获和指导意义，收获在于能够引导我们解决自身的某些问题，指向的我们未来要做什么。拆书帮就是一群认可拆书理念，并且愿意把这种方法应用在自己的工作学习生活中的小伙伴，资源组织形成的一个公益的学习型组织。这个组织正式成立的时间是2013年的4月6日。上周末，我刚刚从拆书帮的年会回来，有一组数字可以分享给大家，拆书帮已经在全国有33个正式分舵，深圳是其中之一，拆书会员也已经超过1500人。","ratings_count":0,"texts":[{"id":6925,"quote":"\u003cp>把要传达的信息向受众指出，与他相似的一群人已经在按照你的想法行事了，你的提议或要求就能获得非常显著地收效。如果这群人与你的受众拥有同一种社会身份，同属一个族群，那么你的信息可能会更有说服力。但是，我们还有一个重要的方法，帮你再做一个微小的、却能大幅提升说服效果的改变：\u003cstrong>在遣词造句的时候，透露出你所倡导的那个行为有多么寻常或多么不寻常。\u003c/strong>人们都愿意与社会规范保持一致，可是，人们往往也喜欢强调自己的独特，彰显自我的个性。这句话的意思是，当有人引导他们去思考某个行为对自己的身份会造成什么影响的时候，一般来说，他们会更加在意违背（而不是顺应）社会规范的代价和好处。\u003cstrong>因此，如果你想影响他人的行为，那么，你就从违背他心目中的社会规范的角度去遣词造句，这样做的收效比顺应的角度更见效。\u003c/strong>\u003c/p>\u003cp>例如，如果你的朋友认为打喷嚏时捂上嘴是符合社会规范的，那么最有效的措辞方式就是强调违背这条规范的人有何负面特质。比如说：“那些打喷嚏时不捂嘴的人真是不负责任啊。”\u003c/p>\u003cp>相反，如果他认为打喷嚏时不捂嘴才是正常的，那么你要强调的就是捂嘴的人（违背他心目中的这条规范）有哪些正面特质，比如“那些打喷嚏时捂嘴的人都很负责任。”\u003c/p>\u003cbr>","explains":"我看我们的伙伴都已经阅读完了，刚才大家完成的就是RIA中的R部分。接下来，我们对片段的内容来说一下我的理解。我们来看，片段中讲到，我们如何更好的说服别人，他其实是有三个层次。第一个层次，就是告诉对方和他一类的人都在这么做，那么他相信你的概率就会大一点。打个比方，我记得小时候有一个赵本山的电视广告很流行，“某某品牌，地球人都知道！”作为受众看到之后的感受，我是地球人，大家都知道，我也应该知道，就会去看继续了解这个品牌。第二个层次，就是不但要告诉他们某一类人在做的这件事，还要告诉他们这样做会有多么不一样，或者是很好，或者是很不好，强调行为产生的效果。第三个层次，就是我们在说之前先判断清楚对方所持观点的立场，当你想要说服他引起他的重视，要尝试从他认知的角度的反方向切入，不这样的情况或有多么不一样，为什么这么说，是因为他认知的这个角度的事情他已经比较习惯，人们的潜意识中更容易关注与自己不一样的东西。","interaction":"A1:\u003cp>举两个例子：\u003c/p>\u003cp>(1)【营销上】大家对二手车买卖的认知是什么样的？一般都是有一个中间公司或这个人收车，然后修修改改，再卖给别人，中间会有很大的利润，对吧。但瓜子二手车网站广告，广告是这么说的：“没有中间商赚差价，车主多卖钱，买家少花钱”，首先向受众提出大家相反的立场“没有中间商赚差价”，价值是“多卖钱和少花钱”，这个广告就有运用到片段的方法，也确实吸引了很多人关注。\u003c/p>\u003cp>(2)【生活上】上小学时候，老妈总和我说：“按时完成作业，老师会表扬你。”作为好学生，我内心就是这么认知的，所以这些话对我也没什么感觉，如果说能让我更重视，她应该说：“你要是不按时完成作业，老师会批评你”\u003c/p>\u003cp>A 2:\u003c/p>\u003cp>接下来，我的妈妈就要搬过来和我们一起住，我要说服我的妈改掉一个习惯，就是冰箱里屯大量的食物。她和很多老人都觉得觉得冰箱就是用来储存食物，想吃什么拿什么的，方便也安心。但我们年轻人不这样认为，觉得吃多少存多少都吃新鲜的最好。\u003c/p>\u003cp>所以我会从冰箱少屯食物的好去试图说服他：“没有存满东西的冰箱可以让我们自己更灵活选择下一顿想吃什么”“没有装满东西的冰箱其实更省电一些”……等等，这就是我要用的方法。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1510119393000,"updated_at":1510119522000,"ria":true},{"id":3909,"topic":"运用“潜质打败现实”的策略，在先天弱势的情况下，取得成功。","learn_goal":"运用“潜质打败现实”的策略，在先天弱势的情况下，取得成功。","remark":"谈判、面试、宣传中，如果你的产品先天硬件条件不足，你的成就资源均不如对手，如何弱势逆袭、如何四两拨千斤呢？今天就让我们一起学习强大的触底反弹策略！","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"抗抗","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"大家好，我是抗抗，抗日战争的那个抗抗。\r\n我有3个标签：翰林分舵宣传长老，新手观察家，建筑师","ratings_count":0,"texts":[{"id":6851,"quote":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够运用“潜质打败现实”的策略，在先天弱势的情况下，通过强调自身潜质，成功引起面试官、宣传对象或被推荐者的兴趣，从而取得面试，推荐、谈判的成功。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>用学习者场景法介绍图书\u003c/strong>\u003cstrong>（1-2分钟）\u003c/strong>\u003cbr>\u003c/p>\u003cp>今天我想推荐给大家的书叫做：《细节：如何轻松影响他人》。\u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>十一之前我的同事雷工要去万达面试文旅部门的高管职位，在最终的面试环节，雷工意识到跟他一同竞争的几乎都是名校研究生毕业，工作年限8年以上的职场牛人。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>如果你是雷工，你会如何吸引面试官眼球，选择哪种策略在原本弱势的情况下争取胜出呢？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>如果没有找到有效的办法，只好让就业机会从指缝间溜走，很可能会影响雷工的自信心，从此在职场上一蹶不振。\u003c/p>\u003cp>\u003cstrong>解决：其实雷工进入最终面试是因为他在面试初试时表现出更好的团队合作意识。她可以在终面时强调自己具有这方面潜质。\u003c/strong>这本书就告诉我们一个弱势逆袭的策略，通过强调自身潜质来吸引面试官的眼球，从而打败那些更有经验和成绩的对手，最终在面试中大获成功。\u003c/p>\u003cp>\u003cstrong>R\u003c/strong>\u003cstrong>环节，\u003c/strong>\u003cstrong>为why或者what的内容，或原书一个完整的案例\u003c/strong>\u003c/p>\u003cp>《细节》\u003c/p>\u003cp>第20章\u003c/p>\u003cp>在后续的跟进研究中，托马拉发现了相同的结果：当受试者必须在两个条件相同，但在潜质与实际成就方面有差异的人选中挑一个的时候，他们总是选择有潜质的那一个。\u003c/p>\u003cp>原来，“潜质的说服力胜过现实”的现象不仅发生在招聘的时候。托马拉和同事们在一个更以消费者为主导的环境中也发现了这种情况。在该项研究中，Facebook的用户们看到了一些对一位喜剧演员的评语。一半人看到的评语强调的是这位喜剧演员的潜质，比如“这家伙能成为下一个大腕儿”，以及“到明年，人人都会谈论这位喜剧演员了”。另一半人看到的评论强调的是这个喜剧演员已经取得的成就，比如“评论家们说，他已经成为大腕儿了”“人人都在谈论这家伙”。\u003c/p>\u003cp>Facebook的用户们表现出了更重视潜质的倾向：当评论强调的是喜剧演员的潜质而不是实际取得的成就时，用户表现出更大的兴趣和喜爱之情。\u003c/p>\u003cp>但这是为什么呢?\u003c/p>\u003cp>研究者认为，为何潜质总是比现实更吸引人，一个潜在的原因就是现实已经发生了，完全是确定的。当人们在评估一个具备“潜质”的候选人时，虽然这两个字会为信息或沟通带来明显的不利意味，但它给人带来的那种不确定的感觉却是相当有利的因素，换句话说，它激起了人们的兴趣。\u003c/p>","explains":"\u003cp>\u003cstrong>I\u003c/strong>\u003cstrong>环节\u003c/strong>\u003c/p>\u003cp>\u003cstrong>讲解引导时，给出了具体行动建议或具体步骤。拆书家举出了案例，并通过概念与匹配例子之间的对比，引出知识点逻辑、 步骤和明确边界等。\u003c/strong>\u003c/p>\u003cp>这个片段，向我们阐述了“潜质的说服力胜过现实”这个现象。其原因就是潜质的不确定性更能引起人们的兴趣。\u003c/p>\u003cp>从而我们得到了一个技巧：当我们手头的现实不够充裕时，就用潜质吸引对方的注意力，从而取得成功。\u003c/p>\u003cp>\u003cstrong>（举出了案例，并通过概念与匹配例子之间的对比，引出知识点逻辑、步骤）\u003c/strong>\u003c/p>\u003cp>这里出现了两个平行比较的概念：潜质和现实，我们来对比一下。现实，在片段中引申为成绩、经验等已经获得的明确成就。现实更具体，更物化。潜质，同义词是潜力，在文中指的是内在的没有发挥出来的能力或潜在的素质，更虚一些，二者的区别在于是否明确的展现、是否有待发掘。\u003c/p>\u003cp>我们那雷工的案例来做一组判断题：1，跟雷工PK的职场大牛都拿着自己的各种证书，这就是在展示现实。这就叫展现了我的成就，叫展现现实。2，雷工自己的团队合作能力，有合作意识，有团队意识开发的潜质。小伙伴会问：这个能力已经有了呀？其实对于面试官来说，雷公的这个能力他并不知道，因为初面是人力资源面试，而终面才是老板面试。对于面试官来说，雷公的团队合作能力并不明确，是值得去发掘的潜质。3，我再问大家，如果雷工拿着一个最近合作奖去面试，这就是展现现实而非潜质了。\u003c/p>\u003cp>现在我们就能明确分辨，现实是指已经获得的物化的成就和经验；潜质是指有待发掘的能力。\u003c/p>\u003cp>\u003cstrong>（具体步骤）\u003c/strong>那么，如何更好的展示出你的潜质，使谈话更有说服力又不显得那么刻意呢？\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003cstrong>摆出你的潜质\u003c/strong>，如果是在面试或者推销中，要明确潜质是什么。\u003c/p>\u003cp>全球著名猎头给出了判断人的潜力的四个重要维度：好奇心（对新知识的渴求）、洞见（收集并准确理解新信息的能力）、参与（沟通、与人联系）、决心（面临挑战或受挫时，依旧能不懈努力）\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003cstrong>注意潜质的可信度\u003c/strong>以及来自什么渠道。\u003c/p>\u003cp>例如刚才关于面试的例子中，雷工就可以强调自己在初面中如何表现的，同样可以举例说明自己拆书帮时曾经组织过拆书帮年会，跟小伙伴合作的非常愉快，这是不是就非常可信，而不觉得夸夸其谈。\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003cstrong>强调潜质能给对方带来的好处\u003c/strong>，或者我们推销的产品能给对方带来什么好处。\u003c/p>\u003cp>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 如可以，\u003cstrong>进行场景化描述\u003c/strong>，增加真实感。例如原文中说：“到明年，人人都会谈论这位喜剧演员了”，仿佛这个场景历历在目，吸引人。\u003c/p>\u003cp>例如我之前买房，房产经纪推销给我一个非常破的二手房，他这么说：\u003c/p>\u003cp>1)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 这房子有改造的潜质啊，看着是一居室，其实能当两居室用。\u003c/p>\u003cp>2)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 楼上那家都改造好了，我回头带你去看看，这就增加了潜质的可信度。\u003c/p>\u003cp>3)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 等有孩子，孩子自己有个独立的卧室，明确的说出了这个潜质给我带来的好处。\u003c/p>\u003cp>4)&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 给出场景：回头孩子写作业，你们能在客厅看电视。\u003c/p>\u003cp>你看，这么一说，是不是这一居室还真值得买？\u003c/p>\u003cp>\u003cstrong>（明确边界）\u003c/strong>用潜质打败现实这个策略可以用在做推销、宣传、面试等情境中。尤其适用于自身条件先天不足的弱势情况，例如面试时你可能没那么多证书和经验；推销的产品没有那么高的硬件基础等等。\u003c/p>","interaction":"\u003cp>\u003cstrong>（\u003cstrong>学习者可以根据指令，设计出一个包含人物角色、有起因经过结果、有对话的故事。\u003c/strong>）\u003c/strong>\u003c/p>\u003cp>接下来让我们学以致用，\u003cstrong>请小伙伴来编一个小故事，或设想一个我们未来可能会遇到的一次面试、推销或者说服别人的对话场景\u003c/strong>，要有对话，还包括时间地点人物、起因经过结果，最重要的是运用刚刚学会的“用潜质打败现实”这个策略。\u003c/p>\u003cp>好，给大家5分钟时间，然后我会请小伙伴来讲讲你们的小故事。\u003c/p>\u003cp>学习者分享的面试场景：\u003c/p>\u003cp>面试者：我是一名快毕业的软件开发工程师，工作2年后读的研究生，在读期间帮老师做项目，现在来找工作。\u003c/p>\u003cp>面试官：我们的职位需要开发和技术支持的能力。你认为你的优势是？\u003c/p>\u003cp>面试者：我跟老师做项目也有开发经验，同时，我可以叫我的师弟师妹一起开发。另外，我现在宿舍楼的女生电脑维护都会找我，我都不敢回宿舍了。所以我的学习能力是很强的。\u003c/p>\u003cp>面试官：对于开发能力你在学校的项目能说一下吗？\u003c/p>\u003cp>面试者：例如杨浦区的物业公司，我们做一个物业管理项目。数据访问量很大。\u003c/p>\u003cp>面试官：周期呢？\u003c/p>\u003cp>面试者：半年多。\u003c/p>\u003cp>面试官：你提到了你如果被录用，可以直接带师弟师妹的团队加入，大概几个人？\u003c/p>\u003cp>面试者：4个，有保研的，有经验，我们4人团队很精干。\u003c/p>\u003cp>面试官：我很中意你，我会向上反馈，你等通知。\u003c/p>\u003cp>拆书家反馈：\u003c/p>\u003cp>拆书家：你认为对方打动你的潜质是什么？\u003c/p>\u003cp>面试官：开发能力，这个职位最重要的是这个潜质\u003c/p>\u003cp>印象最深的是他说他自己有一个杨浦的小项目，我不是很信任，但是他后来说出了项目规模，比较可信。第三点就是他谈到了他可以带来团队，这个好处对我来说是一个吸引力。\u003c/p>\u003cp>拆书家：两位分享的非常棒，让我们为他们鼓掌！\u003c/p>\u003cp>\u003cstrong>总结（\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>分钟\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>接下来我来总结一下，今天我们学习了“用潜质打败现实”这个策略。适用于先天弱势的情况。有4个应用步骤：摆出潜质、增加可信度、强调好处、场景化描述。\u003c/p>\u003cp>最后，谢谢大家的倾听！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1508898287000,"updated_at":1508898287000,"ria":true},{"id":3627,"topic":"如何在帮助他人时，拔高定位，为互助留有余地。","learn_goal":"完成TF2-2定级","remark":"","level":"TF2-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"徐雪艳","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"晚上好，感谢大家今天一起来现场学习。我叫徐雪艳，用我们拆书帮的三个标签法介绍我自己，标签一，互联网产品经理，来厦门有十二年了，一直在一家公司做产品经理；标签二，国际注册会计师，这是我的过去，是我用来缅怀过去的标签; 标签三，改变，这是我的未来，我想要让自己站在更大的舞台上去正向影响别人，所以我来这里学习。","ratings_count":0,"texts":[{"id":6526,"quote":"\u003cp>今天我要完成的是TF2-2。 为方便一会儿的讨论，我们先分一下组。&nbsp;\u003c/p>\u003cp>今天的学习片断来自《细节》这本书。&nbsp; \u003c/p>\u003cp>F特征：《细节》是关于如何提升影响力的一本书，讲的是如何用经济高效又符合伦理的方法来影响和说服他人。&nbsp; \u003c/p>\u003cp>A 优势： 本书作者之一罗伯特.西奥迪尼，也是《影响力》一书的作者。这本书在2016年1月第一次出版，与时俱进，讲述50多条崭新的说服策略，其中绝大多数都来自过去这几年间社会心理学，行为经济学，说服科学等领域的研究成果。&nbsp; \u003c/p>\u003cp>B 利益： 如果你读过《影响力》一书，你一定知道“互惠原理”是怎样影响人们的日常行为。如果你想知道如何更好地利用”互惠原理“，使自己更成功；如果你乐于助人却发现助人太多，牺牲了自己的时间，降低了自己的生产力，想要找到解决办法；如果你想知道怎样可以更好地在帮助别人的时候，除了相信和期望自己终有一天也会得到别人的帮助，有什么技巧可以更好地催化互助的出现，那跟我一起读一下今天的片断吧。今天的主题来自于《细节》一书的“如何为互助留出余地”。\u003c/p>\u003cp>摘自《细节》P177-178，请大家阅读原文，两分钟时间，读完的小伙伴请举手示意我。&nbsp; \u003c/p>\u003cp>我们该从中汲取什么经经验教训？如果在工作中做一个豪爽大方的给予者能够为我们赢得较高的社会地位，却同时也削弱了我们做分内工作的生产能力，我们应该怎么做才好？弗林的另一项研究给出了确定的答案。这项研究发现了一个不起眼的指标，却能够同时增强助人者的社会地位和生产力。这个指标不是帮忙的次数，而是“互助”的次数。先是为对方提供有益的帮助，然后得到对方回报过来的有益帮助，这会把给予的良好效益放大到最大程度--不但他们自己受益，有份参与的每个人都能受益，因为给予者的地位提高了，生产力也提高了。请记住，这个结果与互惠原理是高度一致的，互惠原理对所有成功的群体来说都至关重要，因为它促进 互助互利的行为。&nbsp; \u003c/p>\u003cp>这些成果给了我们明确的启示。首先，我们应该大方主动地在工作中帮助他人。要注意，最重要的一点就是你要第一个行动。第一个出手相助会激活互惠原理，并因此增加未来的互助次数--对于职场中的共同成功，这个因素至关重要。&nbsp; \u003cbr> \u003cbr> \u003c/p>\u003cp>第二，要把你提供的帮助或有价值的信息做个定位，把日后对方可以全力回报你的可能性凸显出来。这就需要我们把平素的反应，也就是听到对方感谢我们时，我们所说的话，做个微小却重要的调整。这个调整能为你的未来合作和影响行为带来惊人的巨变。以下就是我们推荐的三种应答方式，用它们来回应对方对你的感谢：&nbsp;\u003c/p>\u003cp>1、“能帮上你的忙我很高兴，因为我知道，当一个人需要帮忙的时候 ，别人的一双援手是多么有价值。” \u003c/p>\u003cp>2、“不客气。同事之间理当如此。” \u003c/p>\u003cp>3、 “没关系。因为我知道，如果需要帮助的是我，你也会这么做的。”&nbsp; \u003c/p>\u003cp>总结一下，想要从职场中的给予行为中得到最大的益处，关键的做法就是“为互助留出余地”，这需要两个很小却至关重要的步骤：率先提供帮助、信息或服务；一定要在回应对方时，明确地为你提供的帮助定位--这是一个自然的、平等的互惠行为，这样你就为日后的互助留出了机会。\u003c/p>","explains":"\u003cp>【学习主题】\u003c/p>\u003cp>如何在帮助他人时巧妙地激活互惠原理，增加互助的可能\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够更好地认识帮助别人的好处，并且在收到别人的感谢时更好地回应，给自己的乐于助人做出定位，为互助留出余地，让自己更成功。\u003c/p>\u003cp>（What)这个片断介绍的内容是非常鼓舞人心的，它讲的知识点是对互惠原理的一个增强。它告诉我们，善于利用互惠原理，对成功至关重要。职场中我们应该大方主动地帮助别人，并且在回应对方时把你提供的帮助做个定位，这有利于激活互惠原理，增加未来互助的可能和次数。&nbsp; \u003c/p>\u003cp>(Why)组织心理学研究表明，帮助别人可以收获很多好处，比如社会地位上升，收获好人品，好人缘。但是，一味的付出，会影响助人者的生产力。同样的组织心理学研究表明，从个人生产力的8个指标看，最乐于助人的那些员工的生产力明显比不上其他同事。所以，为了让助人形成良性循环，应该巧妙地激活互惠原理，助人也得到别人的帮助。 \u003c/p>\u003cp>&nbsp;(How)那怎么做才能更好地激活互惠原理呢？这个片断告诉我们，关键是要为互助留出余地。两个至关重要的步骤： 一，率先提供帮助 二，在回应对方的感谢时，明确地为你提供的帮助做出定位， 也就是为自己的行为作出界定，将它拔高为助人的境界并清晰地表达出来让对方明白。片断中给出了三个如何回应的建议。我举个我们拆书帮的例子，拆书帮是一个公益性青年自组织，每一位长老都在奉献，每一位成员也是互助的关系。这充分体现了“率先提供帮助”的精神。这种对别人不吝赐教的精神如果在一次次的互相回应中给出定位，会帮助这种公益精神的传播。我们每一个人乐于率先对别人伸出援手，别人感谢我们的时候，可以这么回应以作出定位：能帮助你我很高兴，这是拆书帮的互助精神，我相信你也会对别人施与援手的。&nbsp; \u003c/p>\u003cp>（边界）互惠原理很多人都明白，但是这个为互助留出余地的技巧却可能很多人没有注意到。我认为只要是提供帮助的行为都用得上，适用性非常广，不仅仅是职场上的。当然了，可能婚姻关系，亲人关系中是不求回报的，可以不用。&nbsp; \u003c/p>\u003cp>（异议预防）你可能会说，这样是不是会显得虚伪，不是说做好事不留名吗？我认为做好事是应该适当留名的，如果是为了正能量的传播，为什么不留名呢？你也可能会说，我就算做了定位，也不一定能从对方得到回报。这确实有可能，一个是回报的时间问题，可能是遥远的将来。也有可能你的能力远超对方，你就权当是做对方的贵人，不求他给你回报，但是这样的定位同样能点醒对方，或许，他可以去回馈给需要他帮助的人，也是一个正向的传递。\u003c/p>","interaction":"\u003cp>【A2】 催化应用 （分步催化1）\u003c/p>\u003cp>拆书家提问设计(逐字稿）：请大家跟着我设想一下，你在什么情境下比较可能对别人伸出援手。工作中为同事提供帮助？业余的学习组织里帮助小伙伴学习？育儿方面为新手爸妈们提供建议？朋友间两肋插刀？或者其它情境。请大家思考一下，想出自己的一个情境。&nbsp; 学习者案例记录： \u003c/p>\u003cp>情境1：学习者，鹏华\u003c/p>\u003cp>鹏华：在我的工作中，有时候会看到一些同事感到迷茫或者无助的时候，我会主动问他有没有什么需要帮助\u003c/p>\u003cp>拆书家：好的，所以是工作中为同事提供帮助的情景？\u003c/p>\u003cp>鹏华：对\u003c/p>\u003cp>情境2：学习者，小白\u003c/p>\u003cp>小白：我也是一样的工作中为同事提供帮助的情景。在我们银行工作中，因为工作岗位的原因，换班是一件不容易的事情。有时候我同事跟我说家里有点事情想跟我换班，我第一时间会说，可以啊，我来上。同事要把这一天还给我的时候，我如果不急着休假，会问他，你这周事情处理完了吗，如果没有，那不用急着还，下次再还。\u003c/p>\u003cp>【A2】 催化应用 （分步催化2）\u003c/p>\u003cp>拆书家提问设计(逐字稿）：我们今天的知识点讲到，为互助留出余地，首先要率先提供帮助，然后，要在回应对方的时候为自己的行为作出定位。在你这个情境下，你可以怎样更好地为互助留出余地呢？&nbsp; 学习者案例记录： \u003c/p>\u003cp>案例1： 学习者，鹏华\u003c/p>\u003cp>鹏华：在我的工作情景中，第一步，率先提供帮助，在我看到同事比较困惑，有无助大吃一惊的时候，我可以主动上去问他是不是遇到什么困难了，有没有什么我可以帮助他的。 第二步，为帮助行为作出定位，同事对我的帮助表示感谢的时候，通过今天的学习，我会说，我能帮上你的忙我很高兴，因为我知道每个人都会遇到困难，这个时候别人伸出援手就是一场及时雨，我相信你也会帮助别人的。\u003c/p>\u003cp>拆书家：哇，我觉得太棒了。所以你的第一步率先提供帮助的方式是，你会主动去观察别人是否需要帮助，而不是等到他来请求你帮忙。这本书后面还有一章讲到，率先提供帮助很重要，它还告诉我们一个秘诀，出其不意的率先帮助效果会更加好。\u003c/p>\u003cp>案例2：学习者，小白\u003c/p>\u003cp>小白：按照这两个步骤，第一步是率先提供帮助，根据我刚才那个情景，如果发现我同事要跟领导请假的时候，我可以主动问他，你周几要请假是吧，我那天刚好休息，我可以先替你上，这是第一步。第二步，当他说谢谢并且要把假还给我的时候，我可以说，你先看一下你事情处理完没有，如果没有你就先处理，假以后还给我就可以了，是第二步，通过这两个步骤把这件事情结束。\u003c/p>\u003cp>拆书家：所以你是认为同事之间有人不方便的时候互相帮助这是一件很好的事情\u003c/p>\u003cp>小白：对，理所应当的事情\u003c/p>\u003cp>拆书家：对，那你回应的时候是不是可以这样作出定位：我知道每个人都有不方便的时候，同事之间互相帮助是理所应该的，我相信我需要帮助的时候你肯定也会帮助我的。这样就会对未来互助埋下可能。\u003c/p>\u003cp>好，那今天我们的学习就先告一段落，感谢大家积极参与，可以看出来我们都有一颗助人的心，希望大家以后可以在工作生活中助人的时候能用上今天的知识，让我们的工作和生活更加成功，顺利。谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1504918696000,"updated_at":1504918927000,"ria":true},{"id":3562,"topic":"学习后，学习者能运用先发制人和精确细节2步，提高谈判掌控力","learn_goal":"学习后，学习者能运用先发制人和精确细节2步，提高谈判掌控力","remark":"跟领导谈加薪？\r\n跟客户谈合约？\r\n跟同事谈合作？\r\n怎么才能更有效？\r\n怎么才能更专业？\r\n怎么才能不被对方牵着鼻子走？\r\n周三晚我们一起，轻松运用2个有效的小技巧，瞬间变身谈判专家！\r\n","level":"TF3-2","duration":25,"status":0,"type":0,"chaishujia":{"username":"抗抗","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"自我介绍和书籍介绍（（2分钟）\r\n大家好，我是抗抗，抗日战争的那个抗抗。\r\n我有3个标签：一级注册建筑师，翰林分舵品牌宣传长老，三月轮值主席","ratings_count":0,"texts":[{"id":6452,"quote":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够运用先发制人和精确细节2个步骤，在谈判中提高掌控力，使立场更有说服力，从而占据更大优势。\u003c/p>\u003cp>\u003cstrong>用学习者场景法介绍图书\u003c/strong>\u003cstrong>（1-2分钟）\u003c/strong>\u003cbr>\u003c/p>\u003cp>今天我想推荐给大家的书叫做：《细节：如何轻松影响他人》。\u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>大家有没有发现生活中这样一些细节：春节时候收到的拜年短信如果前面加了你的名字，你会非常开心并且会回复，但是那些明显群发的消息，你就没那么上心了。同样当你给客户发邮件短信时，如果在开头加上了对方的名字，尊敬的某某某，往往会得到更快更好的反馈。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>这些细节你之前注意到了么？你是怎样看待它们的呢？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>其实这些看似很小的细节，会造成难以估量的巨大影响力，不仅会让事情发展到一团糟，会使你的个人形象变差，甚至会让你的职业发展走下坡路\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>这本书就从52个细节入手。手把手教会我们选礼物可以早早问问对方，说服别人可以反着说，这类影响力法则。每个法则均已案例为切入点，实操性极强。很多读者在读完之后感慨：这52个细节，就是52个套路啊。在这个套路满天飞的社会，我们不学点套路防身么？即使我们不套路别人，也能预防被套路。\u003c/p>\u003cp>今天就让我们来学点有效且专业的谈判套路，通过今天的学习，能让我们在谈判中占据更大优势！\u003c/p>\u003cp>\u003cstrong>A1\u003c/strong>\u003cstrong>环节，请大家进行量表自测（\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>分钟） \u003c/strong>\u003c/p>\u003cp>\u003cstrong>环节的量表题清晰设置了多个选项，学习者通过自测可以了解在某一种情况下自己的表现\u003c/strong>\u003c/p>\u003cp>面对日常工作生活中的“谈判”情形，你都是如何应对的呢？请你做一个简单的测试。\u003c/p>\u003cp>以下5个题目，请按照1～6分的标准给自己打分，1代表完全不符合，6代表非常符合。请仔细阅读下面表格中的每句话，根据自己的实际情况为自己打分，并计算出你的总分（1表示很不符合，6表示非常符合）。\u003c/p>\u003cp>1.&nbsp;我在和上司谈判加薪问题时，会等他说出数目，因为我实在不愿张口。\u003c/p>\u003cp>2.&nbsp;团队中，进行工作分配时，我总是等大家先选，之后再确定自己的工作。\u003c/p>\u003cp>3.&nbsp;我在跟新公司谈工资时，我会提出一个很高的数目，然后准备被他砍下一半。——那才是我真实期望的数字。\u003c/p>\u003cp>4.&nbsp;在私人小店铺买东西时，老板报价后，我总是会以这个价格为基础进行砍价。\u003c/p>\u003cp>5.&nbsp;我让同事晚上一起加班两个小时完成工作，可她说她晚上有事，既然她这么说了，我会自己加班把工作做完。\u003c/p>\u003cp>6.&nbsp;在买卖二手货时，如果对方象征性的去掉个零头，以一个整数的价格报价，我会觉得这个价格更合理。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>I环节，（1分钟）解释一下你刚才让大家自测的量表题的意义\u003c/strong>\u003c/p>\u003cp>这个自测题是测试大家面对 “谈判”时，你的敏感程度和掌控程度如何。\u003c/p>\u003cp>总分9分以下，说明你有高超的洞察力，正是传说中的谈判专家。\u003c/p>\u003cp>9-19分，说明你谈判能力较强，能够迅速把握谈判的关键。\u003c/p>\u003cp>20-29分，说明你只会在某些方面，例如工作中坚持你的原则，而在另外的方面则会忽视谈判技巧。 \u003c/p>\u003cp>30分以上，就说明你在谈判时往往会迷失自我，非常需要阅读一下我们的拆页了。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>R环节，（1分钟）\u003c/strong>\u003c/p>\u003cp>《细节》\u003c/p>\u003cp>第35章\u003c/p>\u003cp>根据社会心理学家亚当·加林斯基和托马斯·慕思韦乐(Thomas Mussweiler)的研究，在谈判中，先出招的效果要好得多。这个改变虽然小，但它能带来很大的回报。当然，你先开的这个价格要符合现实才行，不能超出界限。\u003c/p>\u003cp>当然，我们知道，你不一定每次都能先发制人。如果对手先开价了，你该怎么做?幸运的是，加林斯基和慕思韦乐提出并测试了一个相当简单却好用得让人难以置信的策略，帮你绕开这个心理陷阱:把心思放在你自己的理想价格上。这样一来，你就会自动去思考那些跟对手的锚点不相符的信息了。\u003c/p>\u003cp>参加谈判时，不但要在脑子里记着你想要的理想价格，你还应该把它合理的原因列成清单写下来。就算在谈判中你没能让每个人都明白这些理由，单是把它摆在眼前，就足以提醒你去对抗心中自动涌起的质疑，不会去想为什么你最初的判断不准确了。\u003c/p>\u003cp>我们讨论了谈判中的率先报价能够形成锚点，影响对手后续的报价和还价。行为科学家玛利亚·梅森(Malia Mason )认为，要想取得更好的谈判结果，除了率先开价之外，还应该把价格定成一个精确的数字。接到精确报价的一方，更加容易认为报价方必定花了时间和心思来准备谈判，所以他们必定有充足的理由来支持这个精确数字。\u003c/p>","explains":"\u003cp>\u003cstrong>I环节，有体现出和学习者的简短互动，还要有举例子（5-7分钟）\u003c/strong>\u003c/p>\u003cp>说到谈判，很多小伙伴会感叹：多高深且正式的名词，这跟我这种屌丝且逗逼的人生明显格格不入啊。但是大家可能不知道，据沃顿商学院统计：每个人每周要用25个小时进行谈判。那么每天就是大概3.57个小时。\u003c/p>\u003cp>\u003cstrong>（与学习者互动）\u003c/strong>这个片段中提到了2个简单却有效的谈判技巧，大家能告诉我，是哪两个技巧吗？学习者A回答：先出招；学习者B防备先出招；学习者C：精确细节；学习者D：精确报价。一个是“先出招”，一个是“精确报价”\u003c/p>\u003cp>别小看这两个简单的技巧，如果我们没有很好的运用，就会在谈判的一开始就处于劣势，之后又会被对方牵着鼻子走。最终偏离我们最初的意愿。\u003c/p>\u003cp>首先，我们先说第一个技巧：“先出招”，先发制人\u003c/p>\u003cp>\u003cstrong>（与学习者互动）\u003c/strong>在刚才的测试中，那些小伙伴再跟老板谈加薪的时候，是坐等老板开价的？请举手，几乎半数学习者举手，拆书家反馈：看到有小伙伴举手了。那么请大家回想，最后你加了多少薪水？是不是与老板最开始的开价非常接近？\u003c/p>\u003cp>这就是锚定效应在作怪，当老板先报出了一个价格，就相当于抛出了一个锚，你的思想就会被固定在上面，不易挣脱。\u003c/p>\u003cp>这时我们就要做到先发制人，也就是先把立场摆出来，如果对方先出招了，那就要不停地提醒自己，我们的初心是什么，一旦对方跑偏，迅速把对方拉回来。如果服装店的店主拿着一件棉布T恤张口就要800块，我们一定要火速拉回80块。\u003c/p>\u003cp>如何避免自己被对方牵着鼻子走呢，可以把立场摆出来，或者把支持这个立场的原因摆出来。\u003c/p>\u003cp>过完年我找领导谈加薪，我就把自己最近的工作业绩单和公司的打卡记录放在老板面前，之后开出我想要的加薪数额，然后时不时瞟一眼业绩单，当时老板就被我震慑住了，最后我拿到了我们团队最高比例的加薪。\u003c/p>\u003cp>其次，我们来说说第二个技巧：“精确报价”，也可以延展为“精确细节”\u003c/p>\u003cp>\u003cstrong>（与学习者互动）\u003c/strong>在刚才的测试中，那些小伙伴在谈工资时候，会给一个很高的价格，然后等着减半的？个别学习者举手，拆书家反馈：大家几乎都没有选的，说明大家都非常专业。其实这在正规场合会给对方很不专业的表现。而且往往第一次你这么做了，那么在第二次对方就会直接减半。\u003c/p>\u003cp>大家还记的我在2分钟前提到的，我们每天要用3.57个小时进行谈判。你当时听到的感受是什么？是不是觉得特别专业，因为我故意将数字说的很精确。\u003c/p>\u003cp>当然这个精确的数字不是胡诌出来的，是有理论依据的，这时候小伙伴会质疑：我不是处女座，商量的事儿也不是什么买房买车买国家的大事儿，没有这么精确地依据怎么办？其实哪怕有时候这个依据不够专业，只要你能自圆其说，还是会让对方更加信服。\u003c/p>\u003cp>\u003cstrong>（举例子）\u003c/strong>例如在跟同事安排工作时，如果这么说：大家要在今天下午5点05分前汇总给我，之后我要用20分钟汇总并审核，在用5分钟上传邮件发给对方，最后在5：30下班前把邮件发出，那么同事一定不怎么好意思拖延了吧，其实真相是我也不确定汇总审核工作到底要不要20分钟，我只是预估一下。\u003c/p>\u003cp>先发制人、精确细节；这两个步骤更多地适用于职场，尤其是在相对正式的谈判场合，这会使我们在技巧上以及心理上占据了绝对优势，大大提高了谈判的成功率。\u003c/p>","interaction":"\u003cp>\u003cstrong>A3\u003c/strong>\u003cstrong>环节，给出一个预先设计好的案例场景，请大家在小组内讨论演练，\u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>最后邀请一组做当众表达或角色扮演。（\u003c/strong>\u003cstrong>8-12\u003c/strong>\u003cstrong>分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>给出了一个非常具体、确定的场景，学习者可在此场景中演练或讨论或应用新学技能。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论、应用知识点并形成一个解决方案，或是应用知识点进行组内角色扮演。\u003c/strong>\u003c/p>\u003cp>接下来，咱们来学以致用一下，请大家以小组为单位，从下面给出的2个场景中选择一个你感兴趣的场景进行角色扮演，把我们刚刚学到的两个谈判技巧应用起来。给大家5分钟的时间。待会我会请小伙们来表演。\u003c/p>\u003cp>场景一：人物：房东王美丽、租户王大锤\u003c/p>\u003cp>租户王大锤想在国贸地段租个一居室，之前中介开价要6k多一个月，太贵了，王大锤想找个便宜点的，一天他在街边电线杆上看到了房东王美丽自己贴的小广告：一居室出租，价格面议。王大锤会怎么跟王美丽面谈呢？\u003c/p>\u003cp>场景二：人物：老板王美丽、求职者王大锤\u003c/p>\u003cp>老板王美丽是5家连锁健身房的老板，最近想开一家新健身房，手续及场地都找好了，想要找一名管理健身房的主管，但是初期给不了高工资，自己旗下几个健身房主管的工资是每月1w底薪+10%办卡提成，王美丽会怎么跟求职者王大锤谈条件呢？\u003c/p>\u003cp>分享非常棒，让我们为他们鼓掌！\u003c/p>\u003cp>\u003cstrong>第一组：场景二\u003c/strong>\u003c/p>\u003cp>王美丽：我是五家健身房的老板，欢迎你加入我们。我们对新来的员工都是一视同仁，5K底薪，3.6K的绩效奖金。\u003c/p>\u003cp>王大锤：我觉得不太合理，我看到招聘信息是1万+10%的提成。您打对折，不知道贵公司怎么想的？\u003c/p>\u003cp>王美丽：我们人力资源在这块弄错了，因为我们行业最近不景气。鉴于您新来的，我最多给您加10%的办卡提成\u003c/p>\u003cp>王大锤：据我了解，其他五个做得比较好的主管，底薪在1万以上，我作为同级别的员工，为什么才几千？\u003c/p>\u003cp>王美丽：您的消息有错误，薪酬是我定的，现在的情况是，底薪加提成，也就1万\u003c/p>\u003cp>王大锤：对，我的朋友在您公司，他们是主管级别，薪酬都大于1万\u003c/p>\u003cp>王美丽：他们工龄高。\u003c/p>\u003cp>王大锤：我的工作经验也不低于他们\u003c/p>\u003cp>王美丽：那也是可以根据办卡提成，把薪酬适当提高。\u003c/p>\u003cp>王大锤：说到工作内容，我的工作量会比较大，您不觉得现在给我的薪资不合理吗？\u003c/p>\u003cp>王美丽：不是这样的，只需要您做销售管理，不需要别的工作。不需要员工管理。\u003c/p>\u003cp>王大锤：那您对我的业绩如何要求？\u003c/p>\u003cp>王美丽：……\u003c/p>\u003cp>王大锤：跟其他店相比呢？您开个工资价格吧\u003c/p>\u003cp>王美丽：考虑到您在别的店有经验，那就跟别的主管一视同仁。1万+10%的提成，\u003c/p>\u003cp>摘要点评：王美丽先发制人，告诉求职者，我给你开的工资由哪几部分构成，还下了个圈套，这时我们的王大锤特别清醒，及时的拉回了报价。而王美丽也及时的自圆其说，承认错误，反应机敏。\u003c/p>\u003cp>真诚赞美：发现两位都是谈判高手，同时运用了我们这两个步骤，并且还反串的非常棒。\u003c/p>\u003cp>我们再次感谢这两位小伙伴，号召鼓掌。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003cstrong>环节，给学习者布置一个回去之后要完成的具体任务。（1分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>环节指令清晰，学习者可以根据指令，写出自己未来的一个具体的要做的应用（比如：某个特定任务、和人分享、事后复盘或找人陪练）\u003c/strong>\u003c/p>\u003cp>接下来我想给大家布置一个小任务：在接下来的2-3周里，你有没有要跟人进行的谈判，工作上的或者生活中的，请你运用我们刚刚学习到的2个方法。设想一下你准备怎么先发制人，同时你又准备给出一个怎样的精确细节，这个精确的细节有没有理论依据。请大家把这个计划写在桌上的便签上，在谈判之后，希望大家再拿出之前写好的便签，进行复盘，看看是否学以致用。并欢迎大家把你的计划发到我们的官方群里与大家分享。\u003c/p>\u003cp>学习者分享：准备下周跟客户谈，希望他能同意我们推迟1周供货，要先给对方打电话，不要等对方来询问工作进度，之后列出我们的工作进度表，跟客户讲清楚工作时长与之前预计的长，精确给出具体排班表格和时间流程，尝试跟客户讨论能否多给7天时间准备，并说明这7天是包含周六日的，我们周六日加班。\u003c/p>\u003cp>\u003cstrong>总结（\u003c/strong>\u003cstrong>0.5分钟\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>好，大家可以现在写着，我来做个总结：谈判无处不在，成为谈判专家，我们可以从2步开始，1，先发制人，时刻提醒自己初心何在。2，精确细节，让对方无从反驳。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1504357788000,"updated_at":1504357855000,"ria":true},{"id":3429,"topic":"如何在重拾目标后干劲儿更足","learn_goal":"通过将单一具体的数字改成一个上下浮动的范围，重新全心投入","remark":"【F】大家一定都听说过畅销全球的书籍《影响力》。这本书就是《影响力》的作者罗伯特·西奥提尼的又一力作。这是一本提供了一套能够“四两拨千斤”的工具的致用类书籍【A】里面包含了52个改变细节的小工具，可以说是套路满满，因此这本书在3个月内就达到了近10W册的销量，【B】如果说《影响力》为我们影响他人和改变自己提供了理论指导。那这本书就是《影响力》的实操训练手册，你可能因为出租车司机主动的问候认可他的服务，你曾经因为附赠的漂亮赠品买了一个根本没打算买的商品，这些都是被细节影响的结果，那如何做好更多的细节以及识别细节的陷阱的，这本书你一定不要错过。","level":"TF2-1","duration":18,"status":0,"type":0,"chaishujia":{"username":"马子喻","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我是马文丽，欢迎大家参加我今天TF2-1的拆书分享。在跟随我完成本次RIA现场学习后，学习者能够学会重拾目标后干劲儿更足，而不是重拾目标后落地目标的坚持还不如从前。\r\n今天我要拆的片段来自这本书《细节：如何轻松影响他人》，【F】这本《细节》作者是罗伯特·西奥迪尼、史蒂夫·马丁、诺厄·戈尔茨坦3个知名说服力与影响力研究权威共同完成，书里讲了52个“四两拨千斤”改变细节的套路。\r\n【A】这是一本令人惊奇、强大、具有深刻内涵的实用型人生工具书，完整且细致地揭示了失败和成功之间存在着的细节差别，3个月内就达到了近10W册的销量，并获得英国皇家学会奖。\r\n【B】 如果你设立了小目标在执行的过程中中断，重拾目标后仍然没有干劲儿，那这本书就从一个微小的细节改变可以让你在重拾目标后干劲儿更足。同时在职场沟通、员工激励、商业谈判、家庭教育等各个工作和生活领域对你产生持续且深远的超级影响力\r\n【分组】现在我们按座位就近2-3人一组\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":0,"texts":[{"id":6294,"quote":"\u003cp>书目：《细节》作者：史蒂夫·马丁，诺厄·戈尔茨坦，罗伯特·西奥迪尼\u003c/p>\u003cp>页码：P98-P99\u003c/p>\u003cp>1919年，在《堪萨斯城星报》（Kansas City Star）画政治漫画的沃尔特·迪士尼（Walt Disney）被解雇了，报纸编辑的话是：“他不是太有创意。”\u003c/p>\u003cp>2012年，英国生物学家约翰·戈登爵士（Sir John Gurdon）因对生理学和药学的杰出贡献获得了诺贝尔奖。可当年他在伊顿公学的校长却在成绩单上这样写道：“我相信戈登想当个科学家，可照他现在的表现看，这想法颇为荒谬。”\u003c/p>\u003cp>好莱坞有个传说，弗雷德·阿斯泰尔（Fred Astaire）去雷电华影业（RKO Pictures）试镜时，一个制片经理把他刷了下来，理由是：“（他）不会表演，不会唱歌，有秃顶迹象，会跳一点儿舞。”\u003c/p>\u003cp>令人欣慰的是，这些早期的挫折都没能阻拦他们追求自己的目标。上述三人全部获得了惊人的成就。但有些时候，人们的确会分心，会忘记目标——不是未来的诺奖得主和好莱坞偶像心目中那种宏伟的、一辈子只有一次的、梦工厂式的目标，而是虽然小一点儿却依旧十分重要的、日常生活中的目标，比如多存一点儿钱，减掉几斤肉，还掉信用卡，或是达到这个月的销售目标。\u003c/p>\u003cp>人们往往需要重新拾起之前为自己设定的目标。同样，管理者、团队带头人、老师甚至是父母，有时候也需要帮助员工、学生和孩子鼓起干劲儿，再次为了原先的目标而努力。按常理，当我们为自己或他人设定新目标的时候，经验总是告诉我们，要把目标设定的非常具体。比如，每周减掉2磅（约1.8斤）体重，1小时跑6英里（约9.6公里），或是每个月存下100美元，作为来年的度假基金。但是，当我们说服自己或他人重拾目标的时候，这个常识是否正确呢？\u003c/p>\u003cp>营销学教授毛拉·斯科特（Maura Scott）和斯蒂芬·诺里斯（Stephen Nowlis）认为，虽然人们在直觉上感到，在首次制订目标时，应当把他量化为单一而具体的数字，但是，在重拾先前的目标时，这样做就未必最好了。相反，这两位学者认为，比起单一的具体数字[比如每周减掉3磅（约2.7斤）体重]，把目标改成一个上下浮动的数字范围[但平均值跟原先的数字一样，比如每周减掉2-4磅（约1.8~3.6斤）]，会更加有助于人们鼓起干劲儿，重新投入。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; 好，大家都看好了，内容不多，且非常容易理解。我们都有那些虽然小一点却依旧十分重要的、日常生活中的目标。首次在设定目标的时候，经验总是告诉我们，把目标量化为一个具体的数字，但在目标执行落地的过程中，我们往往需要重拾目标，这种时候，想要重新投入后更加有干劲儿，要怎么办呢？第一步保证平均值和原先一样，第二步把目标改成一个上下浮动的数字范围，这样会有助于我们鼓起干劲儿，重新投入。\u003c/p>\u003cp>\u003cstrong>【不做这么做的坏处】\u003c/strong>如果不这么做的话，在我们执行这些虽然小但是很重要的目标的过程中，目标一旦中断，我们还按照以前的具体的数字重拾目标时，会越来越没有干劲儿，不但丢掉了这些虽然小但很重要的目标，而且还会产生负面情绪，影响自己的生活和工作。\u003c/p>\u003cp>【A1】\u003c/p>\u003cp>这里分享一个自己的经历。半年前，我和一个伙伴约定好，每周跑步3次，坚持了快一个月的时间，这个习惯就彻底丢掉了。本着爱美和健康的目标，没过多久，我们再次约定好，重拾目标，重新开始行动，结果情境几乎和之前一模一样，坚持了还不到一个月就再次丧失了跑步的干劲儿，而且两个人甚至要开始自我怀疑，产生了负面情绪。\u003c/p>\u003cp>【A1+】\u003c/p>\u003cp>直到我遇到了这个拆页，在读了《细节》这本书的这个拆页以后，我和伙伴重拾之前的目标，第一步在平均值和之前的数字一样的前提下，保持平均值是每周3次，第二步，我们把目标改成一个上下浮动的数字范围，调整为每周2-4次的目标。就这样，我们重拾目标，每周跑步2次的这个小目标，很轻松的就达到了，每周跑步4次，在偶尔两个人工作都不太忙的阶段也能实现。不论是跑2次，3次还是4次，因为都属于在目标范围内，可以都算作是我们实现了当周的目标，我们比之前更加干劲十足的重新投入到了目标中。现如今，我们调整目标以后，已经执行了新的目标快两个月的时间，而且热情丝毫不减。\u003c/p>\u003cp>正如拆页的建议中所说，生活中这些虽然小但仍然十分重要的小目标，在重拾目标时，在平均值和原来的数字一致的情况下，把一个具体数字的目标调整为一个上下浮动的范围的目标，可以让我们更加有干劲儿。\u003c/p>","interaction":"\u003cp>【A1激活经验（显像提问）】：\u003c/p>\u003cp>拆书家提问设计（逐字稿）：下面请大家回忆一下，你有没有遇到这类似工作或生活的场景，例如：你曾经设立了每天背20个单词的小目标、每天步行1W步、每天写工作日志等，但是发现坚持了没几天就又没有了干劲儿？\u003cbr>\u003c/p>\u003cp>请把曾经设定了具体的目标，但是执行过程中，重拾目标后来干劲不足这样的场景简单地写到便签上，1分钟时间，写好的请举手示意。好，现在开始&nbsp;\u003c/p>\u003cp>【学习者案例记录】：\u003c/p>\u003cp>仇玉娟：6月底7月初，天刚热的时候，大家也知道男的也想减肥，女的也想瘦身。我和我老公计划减肥，怎么办呢，健身房不方便，于是在手机上下载了APP，keep健身，根据自己的体型和工作时间，去下载了适合自己的运动，一开始我还蛮好的，每天在手机上坚持20分钟就可以了，在室内不需要器械的运动。结果他坚持了一个星期多，我坚持了四五天就放弃了。然后APP每天提醒我，但是提醒我我也是无视它。\u003c/p>\u003cp>【A1+，反思加工】\u003c/p>\u003cp>拆书家提问设计（逐字稿）：好，感谢这位伙伴的分享，那现在的话呢，如果让你乘坐时光机，穿越回刚刚提到的A1重拾目标的场景，根据刚才拆页的建议，最好怎样设定刚刚大家写下的曾经的目标？1分钟的时间给大家书写，写好后给大家3分钟时间在小组内分享一下你们的案例。\u003c/p>\u003cp>（4分钟后）好，时间到，我们请一位伙伴进行一下目标调整后的分享。\u003c/p>\u003cp>【学习者案例记录】：\u003c/p>\u003cp>李朋三：以前我背单词，后来就停下来了，原来定的单一而具体的目标是100个，现在觉得50个比较合适，后来定了50个，有时候因为时间关系坚持不了，于是定了45-60之间，这个比较适合我。\u003c/p>\u003cp>秦琰旻：我以前给自己定的目标每天走一万步，像我今天就没有完成，然后学了这个拆页，我想可能我可以把目标订成平均的一个状态，今天没有完成，明天可以多走一点，，接下来我会这样调整。\u003c/p>\u003cp>好，感谢两位伙伴的分享，那生活中我们经常设立一些虽然小但很重要的目标，我们往往把这个目标设立为具体的数字，在重拾目标的时候，有些时候我们会经常没有干劲儿。第一步保证平均值和原先一样，第二步我们把目标改成一个上下浮动的数字范围，这样会有助于我们鼓起干劲儿，重新投入。\u003c/p>\u003cp>今天我的TF2-1拆书分享就到这里，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1502708817000,"updated_at":1558687604000,"ria":true},{"id":3286,"topic":"《细节：如何轻松影响他人》为互助留有余地","learn_goal":"《细节：如何轻松影响他人》为互助留有余地","remark":"","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"孟君婷","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"大家好，我是今天的新手拆书家孟君婷。在正式拆书前，我先介绍一下我自己。我的职业是一名律师，兴趣爱好有很好，读书、旅游是最喜欢的两项。工作之外，我最常做的事就是跟家人一起在书店或者图书馆读书。下面我就给大家介绍一下我所了解的拆书法和拆书帮。\r\n“拆书法”是由赵周老师在《这样读书就够了》中提出，目的是解决成人学习的三大问题：没时间、记不住、看不下去。也就是说，拆书法是一种成人学习的方法，这种方法以学习者为核心，以书为工具，通过拆解书籍中的片段而使学习者达到学以致用的目的。\r\n拆书法具体分为两个层面：一个是个人层面，由学习者个人通过使用三张便签，将书籍中的片段进行拆解，从而将片段中的知识内化，并最终改变自己的行为，也就是我们通常说的RIA便签法。一个是组织层面，即由一个拆书家对所拆解的书籍片段进行讲解，然后通过一定的设计，引导学习者联系自己的经历反思，并应用片段中的知识规划自己未来的行动，拆书帮的学习就属于这一类。所谓拆书帮就是一群拆书爱好者组成的公益性青年自组织，使命是帮助更多的拆书学习者成长为拆书家，表现形式为各地的分舵。","ratings_count":0,"texts":[{"id":6130,"quote":"\u003cp>主题：为互助留有余地\u003c/p>\u003cp>原文：《细节·如何轻松影响他人》P178-179\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 这些成果给了我们明确的启示。首先，我们应该大方主动地在工作中帮助他人。要注意，最重要的一点就是你要第一个行动。第一个出手相助会激活互惠原理，并因此增加未来的互助次数——对于职场中的共同成功，这个因素至关重要。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 第二，要把你提供的帮助或有价值的信息做个定位，把日后对方可以全力回报你的可能性凸显出来。这就需要我们把平素的反应，也就是听到对方感谢我们时，我们所说的话，做个微小却重要的调整。这个调整能为你的未来合作和影响行为带来惊人的巨变。以下就是我们推荐的三种应答方式，用它们来回应对方对你的感谢：\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; 1、“能帮上你的忙我很高兴，因为我知道，当一个人需要帮忙的时候，别人的一双援手是多么有价值。”\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; 2、“不客气。同事之间理当如此。”\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; 3、“没关系。因为我知道，如果需要帮助的是我，你也会这么做的。”\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; 总结一下，想要从职场中的给予行为中得到最大的益处，关键的做法就是“为互助留出余地”，这需要两个很小却至关重要的步骤：率先提供帮助、信息或服务；一定要在回应对方时，明确地为你提供的帮助定位——这是一个自然的、平等的互惠行为，这样你就为日后的互助留出了机会。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 这个研究也给了我们另一个重要启示。弗林指出，作为正式绩效评估的一部分，许多组织都要求管理人员在诸多方面对员工打分，其中一项指标就是员工乐于助人的程度。弗林建议，管理人员不仅应该评估员工帮助别人的次数，也应该统计他们向同事们求助的频率。管理层应当把这两个指标解释给员工听，告诉大家为什么这两个行为都很重要。在组织上下倡导互助互利的行为，会对生产力最大化极有帮助。\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 我们今天在坐的大多数小伙伴应该都有过几年的工作经历了。在职场中，我们肯定都见过这样的两类人：首先，他们都乐于助人，但区别在于第一类是单向的付出，仅仅是提供帮助，而被他帮助过的人很少有回过来主动帮助他的；而第二类则是双向的来往，帮助别人也被别人帮助，互助互利。长期来看，第二类情况显然更加有益，无论是对于个人，还是对于整体，它的生产力都会高于第一类情况。\u003c/p>\u003cp> &nbsp; &nbsp; &nbsp; &nbsp;那么，我们要怎么做，才能达到像第二类人一样呢?今天，我给大家分享的这个片段来自于这本书《细节·如何轻松影响别人》，其中就给我们提供了这样的一个方法，叫做“为互助留有余地”。具体操作分两步：&nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; \u003cstrong>第一步：主动及时地提供帮助。\u003c/strong>(1) &nbsp;这一点不需要我多说，只要大家心怀善意，在自己力所能及的范围内主动及时地给别人提供帮助就可以了。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003cstrong>第二步为帮助行为明确定位。\u003c/strong>(2)&nbsp;这一步是我这里要重点讲的。大多数被帮助的人都会对提供帮助的人表示感谢，这个时候，我们就要在回应中为我们的帮助行为明确定位。那么大家就要问了，我要怎么通过回应来明确定位呢?\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;片段中给我们提供了三种参考方式，我们一起来看一下：1、“能帮上你的忙我很高兴，因为我知道，当一个人需要帮忙的时候，别人的一双援手是多么有价值。” 2、“不客气。同事之间理当如此。”&nbsp;3、“没关系。因为我知道，如果需要帮助的是我，你也会这么做的。” 读到这里，我们就可以发现，这三种方式无一例外，都包括了两个部分，第一部分主要是表明善意，我是主动自愿提供的帮助(2-1)；第二部分就是前面所说的定位：我帮助\u003c/p>\u003cp>你，是因为我相信在我需要帮助的时候，你也会伸出援手(2-2)。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 这样既说明了原因，也暗示了期待，凸出将来互助的可能性。\u003c/p>","interaction":"\u003cp>分享【A1】便签\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;上周，我的同事因为工作冲突，原定日期的法律咨询值班去不成了。这个时候，他向我提出请求，希望我能帮他去一下。我看了一下自己的工程表，发现可以调配。于是，答应了他的请求。事后，他就此事向我表达了感谢。当时我的回应只有七个字：没关系，不用客气。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;当时还没觉得什么，读了这个片段之后，我才恍然大悟，发现我有两个方面的问题需要改善：第一，在意识到他可能有困难时，反应有些迟缓；第二，在回应对方感谢时，缺失了定位那一环。这两个问题的存在，会大大降低将来互助的可能性。\u003c/p>\u003cp>分享【A2】便签\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;最近，我的一位同事压力比较大，除了一些手头的案件以外，还有很多事务性的工作需要处理，有时候会有一些忙不过来。比如，到法院交材料、取文书、接待咨询的值班等等，而这些很多时候并不一定要承办律师亲自过去处理，是可以由所里的其他人代办的。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;下周，我有案子需要去法院交材料，如果说他正好有一些材料需要交过去的话，我会\u003cstrong>帮他一起带过去(1\u003c/strong>\u003cstrong>)\u003c/strong>。如果他就此事向我表达感谢，我会这样回复他：\u003cstrong>没关系(2-1)，我相信如果换作\u003c/strong>\u003cstrong>是\u003c/strong>\u003cstrong>我\u003c/strong>\u003cstrong>遇到困难，你也一定会这样做的(2-2)。\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1500908219000,"updated_at":1500911752000,"ria":true},{"id":3198,"topic":"如何提高说服他人改变某些行为的可行性","learn_goal":"能运用所拆解的三个步骤提高说服的他人改变某些行为的可行性","remark":"","level":"TF2-3","duration":25,"status":0,"type":0,"chaishujia":{"username":"刘小惠","city":"长沙"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"【自我介绍】各位拆书帮的小伙伴们，大家晚上好，我叫刘文惠，文化的文，贤惠的惠。我已经是一名一级拆书家了，很高兴今天能和大家一起学习。\r\n【 F】我今天所要拆解的片段来自于《细节》这本书，它是一本实用型人生工具书，它完整且细致地揭示了失败和成功之间存在着的细节差别，描述了可以影响他人并逆转自我人生的级具创造力和科学性的影响力法则。\r\n【 A】 在同类书中他最大的优点是每一个细节都有对应的实验案例进行讲述和分析，更真实，更立体。\r\n【 B】 如果你想了解如何更好的激励下属，或者想达成一场完美的商业谈判，又或者你想知道怎么样做好家庭教育等，你都可以从《细节》这本书中找到方法。","ratings_count":0,"texts":[{"id":6026,"quote":"\u003cp>\u003cstrong>&nbsp;&nbsp; 这个研究成果表明，如果你希望别人马上改变某个行为，而且你确信会遭到拒绝，那么你就换个方式，让对方答应在未来的某个时段做出改变。这样你的胜算会更大。例如，假设你是一名管理者，需要说服员工们改用一个新的工作系统或流程，这对每个人都有好处。但是，由于之前推行的变革都没能如预期般成功，所以你估计这次也会遇上障碍。你可以做的一个小改变就是，开头的时候先让大家同意，在\u003c/strong>\u003cstrong>3\u003c/strong>\u003cstrong>个月之内做出改变。这样一来，比起让他们立即就改，你很可能会赢得更多先期的认同和支持，日后大家兑现承诺的可能性也会更大。\u003c/strong>\u003c/p>","explains":"\u003cp>首先要强调一下我们今天的学习目标\u003cbr> 【 学习目标】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者在说服他人改变某些行为时，不再仅仅只是苦口婆心的劝说，而是能够运用明确行为-设定时间-记录承诺这三步来说服他人。\u003c/p>\u003cp>【 细化原文行动建议的步骤】 \u003c/p>\u003cp>那么有时候，无论我们多么用心良苦，无论我们对高效说服他人的技巧掌握得多么娴熟，结果还是有可能失败，这里面的原因可能有几十个。今天我们不是分析原因，是拆解一个方法，为了提高你要求别人改变某个行为时的胜算的方法。原文片段中提到的行动建议是“让对方答应在未来的某个时段做出改变”，那么为使大家更能拆为己用，我将行动步骤进行了细化：\u003c/p>\u003cp>第一步：明确行为。这一步大家需要注意两个方面，首先说明需要改变的具体行为是什么，其次可陈述为什么要这样改变，改变的好处或者是不改变的坏处。比如这是对大家有益的事情，比如这是能节省时间或者提高效率的方法等\u003c/p>\u003cp>第二步：设定时间。这个时间不能是现在或者明天，必须是未来时间段。这样可使对方压力感变弱，心理得到缓冲，更易接受。比如可设定为两个星期后，一个月后，时间根据事情的大小来定。\u003c/p>\u003cp>第三步：记录承诺。第三步能促动行为的改变，是一个双保险的动作，它可以是文字，录音或者视频。\u003c/p>\u003cp>下面我用一个例子来更好的说明这三步的运用，这是我看到这个片段后就对我老公使用了。我老公肚子越来越大了（真实情况），因为他总是坐在电脑面前运动少，还爱吃零食。我想让他出去运动跟小区的篮球队一起打篮球。第一步我说“肥胖会导致高血压，高血糖，高血脂，为了以后老了我们可以一起游山玩水，多去打篮球至少把肚子减下去点吧。”为了他自己健康和以后老年生活这是他应该做的。第二步我说“不用每天去，也不用明天马上就去，我帮你重新买好鞋子配好篮球服，把装备弄齐了再去吧，一个星期之后了”，说到这里，我老公就已经答应了。第三步我说“我怕到时候我忘了提醒监督你，我要录音还要在手机上设置个提醒”就这样搞定了。今天还在关注卖家有没有发货。\u003c/p>","interaction":"\u003cp>好，我们刚刚学习了如何用三个步骤来提升说服对方改变某些行为的可行性，那么我们现在要一起做一个演练\u003c/p>\u003cp>【 给出具体场景】 请大家认真听一下要演练的场景：女儿小芳在大城市工作，收入可观，每个月7号妈妈都会来看她，她总是跟她妈妈说明天我带你去做个全面的体检吧，我们同事推荐的医院，服务可好了。每次被妈妈以费用高，我身体挺好的为由拒绝了。今天是7号，小芳想我应该说才能提高说服妈妈答应去体检的胜算呢？小芳很是苦恼。\u003c/p>\u003cp>【 给出清晰指令】 场景我都讲清楚了吗？那么现在请每两人一组，进行演练。一个人扮演女儿小芳，一个人扮演小芳的妈妈。扮演女儿的小芳要用今天所学的三个步骤来想自己的说辞，提高说服妈妈答应去体检的胜算。\u003c/p>\u003cp>现在给大家8分钟左右的演练时间，8分钟后我会选取一个小组现场分享他们的演练，看他们是如何运用今天学到的三个步骤的。演练的过程中可以角色互换。需要强调的是大家不需要绞尽脑汁去想我一定要去解决这个问题，一定要说服妈妈，最重要的是要学会运用今天拆解的三个步骤。\u003c/p>\u003cp>（设计与演练）\u003c/p>\u003cp>\u003cbr>【 解决方案：角色扮演演练/小组讨论分享】\u003c/p>\u003cp>唐波(女儿）：妈，我跟你说一个事，我一同事的妈之前身体一直挺好的，前段时间突然被检查出重大疾病，直接就晚期了，现在都过世了。所以说体检还是很重要的，有些病看不出来的，一到发现就晚了，你还是答应我去体检吧。\u003c/p>\u003cp>吴坤英（妈妈）：恩，确实好恐怖的啊。\u003c/p>\u003cp>唐波(女儿）：那这样吧，下个月7号你再过来的时候，我带您去体检，服务很好很专业的一家医院。\u003c/p>\u003cp>吴坤英（妈妈）：恩，恩，好呢。还是早点检查下。\u003c/p>\u003cp>唐波(女儿）：那我现在就预约主任医师了，预约需要交预约费的，到时候你不去这钱可是不会退的哦，我也跟我领导请个假，下个月7号陪你一天。\u003c/p>\u003cp>吴坤英（妈妈）：现在就提前预约啦，这预约费可不能白交了，会去的。而且你都请假了。到时候记得提醒我啊。\u003c/p>\u003cp>感谢两位小伙伴的分享，把今天所拆解的三个步骤运用的非常到位。第一步明确行为，有提到去体检，也说到了不去体检的坏处，非常好。第二步设定时间，唐波把时间设定在下个月妈妈来的时候，未来的时间容易接受。第三步记录承诺，通过预约交预约费和向领导请假的举动做记录，给妈妈答应去体检上了双保险，非常聪明啊。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1500093412000,"updated_at":1500093412000,"ria":true},{"id":3023,"topic":"从容通过反面劝说他人","learn_goal":"通过TF2-1","remark":"","level":"TF2-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"徐雪艳","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"晚上好，向下雨天坚持学习的小伙伴致敬。我叫徐雪艳，我今天要完成的是TF2-1。\r\n今天我要跟大家一起学习的片断来自《细节》这本书。\r\nF特征：《细节》是关于如何提升影响力的一本书，讲的是如何用经济高效又符合伦理的方法来影响和说服他人。\r\nA 优势： 本书作者之一罗伯特.西奥迪尼，也是《影响力》一书的作者。这本书在2016年1月第一次出版，与时俱进，讲述50多条崭新的说服策略，其中绝大多数都来自过去这几年间社会心理学，行为经济学，说服科学等领域的研究成果。\r\nB 利益：说服别人采取行动，改变行为，是不是挺头疼的一件事？想让你身边的人改变一些讨厌的行为你是不是不知道怎么开口才不伤害感情？是不是有时候跟别人讨论问题明明对方的建议会导致你更苦更累做更多事情，你却默默地同意他的建议，事后才觉得自己怎么这么傻？这本书里有答案。书中讲了50多个说服策略，教人们怎么做到事半功倍，四两拨千斤。今天，我们只学习如何不吵架，悄无声息地说服对方。","ratings_count":0,"texts":[{"id":5819,"quote":"\u003cp>片断摘自《细节》P20-21，请大家阅读原文，一分钟时间，读完的小伙伴请举手示意我。\u003c/p>\u003cp>我们还有一个重要的方法，帮你再做一个微小的、却能大幅度提升说服效果的改变：在遣词造句的时候，透露出你所倡导的那个行为有多么寻常或多么不寻常。让我们来看个例子：\u003cbr>\u003cbr>设想一下，你的朋友有一个讨厌的坏习惯：打喷嚏时从来不捂嘴。那么，你是应该强调打喷嚏时捂上口鼻的诸多好处呢，还是应该强调不捂的坏处？\u003cbr>\u003cbr>心理学家哈特.布兰顿（Hart Blanton)和同事们认为，哪些措辞能够见效，要看你的朋友对关于这个行为的社会规范（social norm)有何看法。正如我们在早先提到的，人们都愿意与社会规范保持一致。可是，人们往往也喜欢强调自己的独特，彰显自我的个性。这话的意思是，当有人引导他们去思考某个行为对自己的身份会造成什么影响的时候，一般来说，他们会更加在意违背（而不是顺应）社会规范的代价和好处。因此，如果你想影响他人的行为，那么，你就从违背他心目中的社会规范的角度去遣词造句，这样做的收效比顺应的角度更见效。\u003cbr>\u003cbr>例如，如果你的朋友认为打喷嚏时捂上嘴是符合社会规范的，那么最有效的措辞方式是强调违背这条规范的人有何负面特质。比如说：”那些打喷嚏时不捂嘴的人真是不负责任啊。” 相反，如果他认为打喷嚏时不捂嘴才是正常的，那么你要强调的就是捂嘴的人（违背他心目中的这条规范）有哪些正面特质，比如“那些打喷嚏时捂嘴的人都很负责任。”\u003c/p>","explains":"\u003cp>【学习目标】\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够在劝说别人的时候更从容地从反面去阐述行为对对方的社会身份会带来什么影响，从而更愉快地达成共识。\u003c/p>\u003cp>（What)说服别人的方式有很多种。这个片断讲的方法是，如果你想劝说他人，在思考如何措辞之前，可以先完成一个很小却十分重要的任务：先考虑一下受众对相关社会规范的认知状况，然后说明违背这认知的人有什么特质，这样你更容易开口，说服力也会更强。\u003cbr>\u003cbr>(Why)人们往往喜欢给自己塑造有个性的形象，当你想要他改变行为时，他们会更加在意不这么做会给自己带来什么坏处或者好处。这是反着他的认知去说的。很多人自带抵触情绪，如果你直接告诉对方你要怎么做怎么做，对方会直接用抵触情绪对抗，把你的建议拒之门外，或者与你诡辩，最终你白说了，他也损失了你的好建议，还会影响你们的心情和关系。\u003cbr>\u003cbr>(How)所以，怎么做更容易让对方接受呢，开口之前，\u003cbr>第一步，明确你想要说服对方什么\u003cbr>第二步，弄清楚对方对这个行为相关的社会规范的认知\u003cbr>第三步，想一想违背他这个认知的人有什么特质\u003cbr>第四步，告诉对方，违背他认知的这个社会规范的人有什么特质\u003cbr>\u003cbr>原文片断给我们举了个非常好的例子。我联想到我自己的经历。我老公不喜欢做家务，我试图改变他这种毛病，都没能成功。典型的场景是，我上了一天班，疲惫地回到家看到地板又脏又乱，我吼他帮忙。\u003cbr>我说：今天你来拖地，男人在家里也应该帮忙。\u003cbr>他回答：拖地是男人干的事情吗？做家务的男人都是没出息的。\u003cbr>我接着很鄙视地说：没文化的人才这么说，现在什么年代了，你还这么大男子主义！\u003cbr>\u003cbr>每当这种情况发生，我感到又沮丧又生气。显然他不听我的，并且抵触情绪上来，还狡辩。我们不是陷入吵架，就是陷入冷战，最终，家务还是归我。以前我没学过我们今天讲的这个反面说服的技巧，而是直接告诉他要怎么做，导致失败的沟通，影响融洽的关系。\u003cbr>\u003cbr>当我学习了今天这个知识点，我可以按照步骤思考一下怎么措辞。\u003cbr>分解一下，第一步，明确目标，我想要他帮忙做家务，第二步，获得他的认知，我知道他认为男人是不做家务的；第三步，找出违背他这个认知的人有什么特质，比如，做家务的男人顾家，有责任心，事业更成功。\u003cbr>\u003cbr>所以我可以这么说：能做家务的男人很顾家，有责任心，有责任心的男人事业更成功哦。\u003cbr>\u003cbr>这么说不伤感情，给他台阶下，我更容易开口，他也更容易接受。\u003cbr>\u003cbr>（边界）当然，这个办法不是什么情况下都用得上的，如果你面对的是完全不了解的人，就无法获知他的认知。或者，如果对方是一个不管别人看法的人，那也没用。最重要的，这个办法很委婉，如果你们俩很熟，有一说一有二说二会更加自然的话，那也不要这么费劲。\u003c/p>","interaction":"\u003cp>【A1 激活经验】\u003c/p>\u003cp>接下来，请你们回想一下，在你试图说服身边的人的经历里，下面这些词哪一个可以更好地形容你有过的心情：沮丧？生气？绝望？尴尬？ 失望？愤怒？请你把这个词写下来。你当时是怎么跟对方说的，请你把当时的对话记录在便签纸上，两分钟时间，等一下我请小伙伴分享。\u003c/p>\u003cp>现场小伙伴在纸上写下了自己有过的心情，我请两位学习者做了分享，以下是学习者案例记录。\u003cbr>\u003cbr>学习者案例记录：\u003cbr>学习者1：愤怒，生气。&nbsp;\u003cbr>女朋友有一个坏习惯，喜欢在给手机充电的时候玩手机，劲说无效。\u003cbr>学习者：插着电玩手机是很危险的\u003cbr>女朋友：（不回答）\u003cbr>学习者：你怎么说不听呀\u003cbr>女朋友：（继续不说话）\u003cbr>学习者：你告诉我你脑袋到底在想什么？ 你不说话是什么意思\u003cbr>女朋友：（还是不说话）\u003cbr>学习者：（愤怒，直接把充电线拔掉）你这样不行\u003cbr>女朋友：干吗干吗啊，还给我还给我\u003cbr>学习者：你电死吧，不管你\u003cbr>拆书家追问：所以最终没有达到说服的效果，你的心情怎么样\u003cbr>学习者：很生气，很愤怒，感觉对她很无语\u003cbr>\u003cbr>\u003cbr>学习者2：\u003cbr>学习者2建议妹妹平时多学习，妹妹不懒，她很失望。\u003cbr>学习者：有一次我妹妹说他工作中碰到了一个问题，我说我有资源你可以去学习\u003cbr>妹妹回答：哎呀，还要学习啊，太麻烦。\u003cbr>学习者：难怪你碰到的问题你都解决不了，因为你都不爱学习。\u003cbr>妹妹回答：那有空再说吧，反正学不学也没办法一下子提升上来。\u003cbr>拆书家追问：所以你也是直接告诉她你要学习\u003cbr>学习者确认：对\u003cbr>拆书家确认：她也不听\u003cbr>学习者：对，就是当我给她忠告的时候她不理会，好像这个事情可有可无，也没太大用处，整个过程让我觉得她是很不爱学习，也不好沟通的人\u003cbr>拆书家确认：所以你会很失望\u003cbr>学习者：对\u003c/p>\u003cp>【A1+ 反思加工】\u003c/p>\u003cp>谢谢大家的分享。那今天我们一起学习的是从反面去阐述的说服方法。如果时间能够回到过去，用今天拆页的知识点，重来一次，你可以怎么措辞，达到更愉快的说服效果呢？请大家回到自己的经历，重新写下你会怎么做。三分钟时间，一会儿我请小伙伴们分享。\u003cbr>\u003cbr>学习者反思加工，记录在纸上，我请一位学习者做了分享，以后是学习者反思记录。\u003cbr>\u003cbr>学习者案例记录：\u003cbr>学习者1反思：\u003cbr>学习者：我知道你很喜欢看电视，不喜欢我打扰你，可是如果你知道玩手机的时候不要插着充电我会更放心，不会担心你。\u003cbr>拆书家追问：所以你的目标是想要说服她充电的时候不要玩手机\u003cbr>学习者：对\u003cbr>拆书家追问：那你觉得她认为充电的时候玩手机是正确还是不正确的\u003cbr>学习者：他觉得没问题啊\u003cbr>拆书家提醒：所以她的认知是充电的时候玩手机是可以的，那你觉得违反她这种认知的人有什么特质\u003cbr>学习者：哦，那可以这么说，我知道你不喜欢我打扰你，可是，懂得不边充电边玩手机的人更有责任心，因为她知道她男朋友会担心她。\u003cbr>拆书家：好的，这样说她也会明白你是为了你们更融洽的关系，她想要成为一个更有责任心的人的话就会听你的建议。\u003c/p>\u003cp>录音结束后现场意犹未尽，继续讨论了几个案例，加深从反面去说服别人的套路的理解。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1498319751000,"updated_at":1498722672000,"ria":true},{"id":2911,"topic":"关于口头承诺的约束力","learn_goal":"用口头承诺提高对方对承诺的执行","remark":"生活中那些微小的发现与细节的改变所产生的巨大影响力往往能够超乎人们的想象，《细节：如何轻松影响他人》将通过对近百例经典实例的讲述与分析，带你探秘那些微小却重大的影响力提升技巧，告诉你如何在如今这个信息量超载的时代用最小的细节改变成就结果上最大的差异变化，并成功影响他人。同时，本书所罗列出的那些改变事情走向的“四两拨千斤”的影响策略也正真实存在于我们生活的方方面面，并将在提升个人品质、解决生活难题、打造企业品牌等各个领域帮助...","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"帅气的叶叔叔","city":"宁波"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是今天定级1-1的新手拆书家叶柯敏，我给自己贴三个标签，一、理工大三学生，目标是毕业前成为三级拆书家。二、健身爱好者，一周六天、雷打不动，健身房、骑车、游泳、跑步轮番上阵，目标是2017年下半年能参加一场triathlon， 即铁人三项（游泳1.5千米、骑行40千米、跑步10千米）。三、烤鸭（考雅），即雅思考试筹备者。\r\n拆书拆书简单的字面理解为将书拆成数个部分。而每个部分都有它各自的实际意义，此时我们就要通过RIA便签法将其拆为己用。通过R(Reading),截取文章片段，I(Interpretation) 用自己的话复述所截取的片段内容，A(Appropriation) 字面意思为挪用，我们可以将其理解成转化。 Appropriation分为两部分，A1为过去发生的相关经历，指向过去，A2为对未来发生类似情景的再现（即若有类似的事件发生我们该怎么做），指向未来。\r\n通过这三步骤，将书中的知识内化为自己的行动，才算是成功的一拆。\r\n拆书帮：拆书帮是一个社群，存在的意义是吸引更多的人解读书籍并内化，分享知识传播拆书理念，吸引更多爱好者踏上成为拆书家的旅程。","ratings_count":0,"texts":[{"id":5696,"quote":"\u003cp>本段落来自《细节》﻿\u003c/p>\u003cp>社会影响的基本原理之一就是承诺和一致性之间的关系。这个原理说的是，咱们绝大多数人都有跟自己许下的承诺保持一致的强烈愿望，如果这个承诺是我们主动做出的、需要我们花力气参与而且被公之于众的，那就更是如此。﻿﻿\u003c/p>\u003cp>在病人打进常规的预约电话，约好了日期和时间之后，工作人员请他们马上大声念出这些预约细节，然后再挂上电话。这个微小的改变产生的成效不算大：我们统计后续的爽约时，发现这个数字不过降低了3％。乍一看，这算不得太显著，可如果考虑到两个重要因素，意义就不同了。首先，这个方法无须成本，只需在交流时多花上一两秒钟。其次，虽然以3％的比率降低看起来很小，但基数一大的话数字就相当可观了。如果总体损失有10亿美元，降低3％就意味着节省3000万美元。﻿﻿\u003c/p>\u003cp>这个方法背后的含义很清晰。在繁忙的生活中我们太容易把谈话或交流缩短，好把注意力移向下一件事。可是，没有获得口头承诺就结束沟通，其实是浪费了机会——即便这个机会带来的结果可能并不起眼。例如，如果在团队会议结束时，经理让每个人把要做的工作复述一遍，那么切实的执行就更有望实现。如果在临睡时，父母能获得孩子的口头承诺，然后再放孩子多玩一个游戏或是多听一个事，多看一会儿电视，那么待会儿哄孩子上床时就不会那么费劲儿了。\u003c/p>","explains":"\u003cp>what:承诺并与之保持一致性是大多数人想要遵守的一种强烈意愿，尤其是在公众场合。因此在与对方达成某项约定时，不要着急结束沟通，用几秒钟做口头承诺来降低违约率，尽管只降低3%。\u003c/p>\u003cp>why:绝大多数人都不愿背弃自己说出的话和做出的承诺，特别是在公开场合做出的承诺，我个人推测这可能与颜面有关。\u003c/p>\u003cp>how:在约定达成后，花几秒钟各自确认约定中的己方内容。\u003c/p>\u003cp>在这里，要求自己承诺时：可以对着镜子将自己想要达成的内容复述三遍。\u003c/p>\u003cp>而在要求对方承诺时，我们可以这么说：“我们再来把我们刚才约定过的/安排好的内容过一遍吧，很简单，复述下自己要做到的内容及要求，检查下是否还有遗漏的地方。”\u003c/p>","interaction":"A1：\u003cbr>\u003cp>清明节4月1号那天，我和小伙伴约定从宁波骑车回老家温州，途径宁海时被小轿车撞伤，后走保险程序，因此没能在现场得到赔偿，对方虽然满口答应得到保险赔款时会主动通知我并打我卡上，但我还是有些不放心。理由有以下几点：1、几位关心我的朋友说，宁海老赖很多，这也是我最担心的。2、我不可能因为这事专程来宁海再找肇事司机一次，对方的违约风险低。\u003c/p>\u003cp>如果我在那时，拆过这个片段。我会让对方在在场的交警，事故双方(我和他)，保险公司职员，我父亲及朋友，对方当事人朋友和我的小伙伴面前做一个公开承诺，那么我可能会稍稍安心些。\u003c/p>\u003cp>当然，结果也是非常好的，肇事的叔叔也主动按时将钱打入我的卡中。\u003c/p>\u003cp>A2：\u003c/p>\u003cp>我们这学期有门课程叫《商务英语沟通》，期末大作业为用英语宣传一件商品，表现形式不限，因此我们组决定用表演加PPT的方式，来展现商品的独特性。由于这份作业难度高，要用纯英文对话的演艺的形式展现；内容复杂，要写剧本、翻译、制作ppt，表演，每个成员可能要身兼数职，如何防止组员有拖沓和偷工减料的行为，做为组长的我可以利用这份拆页学习到的内容，在本周日晚的小组讨论、任务分配环节后，让每位成员复述一遍她各自的承担的内容及完成的截止时间，我可以这么说：“OK, 今晚大家讨论的都差不多了，剧本内容编写及翻译、角色选定、PPT内容查找及制作这些大家都清楚了吗，为了我们能按时进行第一次彩排。我们来过一遍自己承担的内容及提交时间吧，查漏补缺，看看有没有遗漏什么。从我开始，我的工作是XXX，周一中午12点前搞定。”\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1497343035000,"updated_at":1497343158000,"ria":true},{"id":2878,"topic":"如何促进行动的落实","learn_goal":"通过对自己或者他人做出承诺，提高责任感，促进行动的落实。","remark":"你是否觉得自己或者你身边的人执行力很弱？你是否想要增强自己或团队责任感？这里有一种简单的方式可以让你提高执行力，不把事情拖延到最后一秒。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"阿柒lsh","city":"宁波"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是今天参加1-1定级的新手拆书家阿柒，很高兴在这里和大家分享。我用三个标签来介绍下我自己，这三个标签分别是：读书、青年公益、改变。\r\n读书：今天参加读书计划的第380天，各方面的书都会看，在书中学到很多，也开始学会使用拆书的方式进行学习，提高掌握知识的能力。\r\n青年公益：热衷参与各种青年公益项目，比如雷励中国等，希望挑战自己提升自己，通过自己去影响他人，共同成长。\r\n改变：一直追求着改变，想要去尝试没有接触过的东西，跳出自己的舒适圈，越害怕越想去尝试，如果因为害怕而不敢去触碰，那些永远会是我的恐惧圈。\r\n以上是我的自我介绍，接下来我来介绍下关于拆书以及拆书帮：\r\n拆书是一种高效的成人学习方式，他是将书本中的内容拆解出来，转化为自己的能力，要把书本内的知识关联到学习者之前的经验，并且将新学习的内容运用到之后的生活中去，拆书又分为个人和组织学习，个人学习就是应用RIA 便签法，组织学习的应用就像现在这样，由一位拆书家在现场带领引导大家进行拆书。拆书帮是基于拆书学习爱好者的社群，在全国各城市都会有自己的分舵，他的存在是为了帮助更多学习爱好者成长为拆书家。","ratings_count":0,"texts":[{"id":5656,"quote":"\u003cp>\u003cstrong>节选自《细节》\u003c/strong>\u003c/p>\u003cp>社会影响的基本原理之一就是承诺和一致性之间的关系。这个原理说的是，咱们绝大多数人都有跟自己许下的承诺保持一致的强烈愿望，如果这个承诺是我们主动做出的、需要我们花力气参与而且被公之于众的，那就更是如此。\u003c/p>\u003cp>在病人打进常规的预约电话，约好了日期和时间之后，工作人员请他们马上大声念出这些预约细节，然后再挂上电话。这个微小的改变产生的成效不算大：我们统计后续的爽约时，发现这个数字不过降低了3％。乍一看，这算不得太显著，可如果考虑到两个重要因素，意义就不同了。首先，这个方法无须成本，只需在交流时多花上一两秒钟。其次，虽然以3％的比率降低看起来很小，但基数一大的话数字就相当可观了。如果总体损失有10亿美元，降低3％就意味着节省3000万美元。\u003c/p>\u003cp>这个方法背后的含义很清晰。在繁忙的生活中我们太容易把谈话或交流缩短，好把注意力移向下一件事。可是，没有获得口头承诺就结束沟通，其实是浪费了机会——即便这个机会带来的结果可能并不起眼。例如，如果在团队会议结束时，经理让每个人把要做的工作复述一遍，那么切实的执行就更有望实现。如果在临睡时，父母能获得孩子的口头承诺，然后再放孩子多玩一个游戏或是多听一个故事，多看一会儿电视，那么待会儿哄孩子上床时就不会那么费劲儿了。\u003c/p>","explains":"\u003cp>当我们对自己或者他人许下承诺时，特别是将承诺公之于众的情况下，我们内心的责任感会增强，提高行动力，使承诺更容易去被兑现，增强行动与承诺的连接性。\u003c/p>\u003cp>日常应用：\u003c/p>\u003cp>1-如果对某件要做的事没有什么完成的把握时，不要轻易做出承诺，否则你的可信度会大大降低。\u003c/p>\u003cp>2-如果没什么问题或者有实现性，要主动进行口头承诺或者书面承诺，如果情况允许，可以让更多人知道你所作出的承诺，比如告知几位朋友我的承诺，这份承诺是具体化的，比如我会在某个时间完成什么事，该如何行动，也可以同时大声念出来，增强自己的印象，这样可以增强自己的责任意识，提高自己的行动力。\u003c/p>","interaction":"\u003cp>A1\u003cbr>\u003c/p>\u003cp>关于拆书定级，两星期前就有计划开始准备，然后找了几天晚上看了拆书手册，之后就一直没时间也没特意找时间去把这个事做好，等到周二晚上，离拆书定级还有不到一周时间，察觉到不能再拖延下去了，但是晚上7点开始写拆书，一直拖延了三小时，玩玩手机，3小时过去了也没写多少内容，在我自我意识中我是要一个说到做到的人，我对自己缺少一份承诺，\u003c/p>\u003cp>（然后就在22点时候在读书群分享读书感悟的时候在感悟中写了这么一段话：意识到之后不一定会去改变，不能再拖下去了，立个flag ，今晚不准备好定级，不睡了。这样群里10几个人都可以看见我对这件事做出的书面承诺，增强责任意识，为了兑现承诺，今晚终于把材料准备好了。﻿）\u003c/p>\u003cp>A2\u003c/p>\u003cp>在确定下参与准备下次定级分享时间的时候，我会在拆书帮定级群内对18位小伙伴做出承诺，在群内写明 我会在定级分享一周之前（前一个周日晚上之前）把定级资料准备好，并发送给大叔和教育长老审查，而且留出一周的时间来准备定级资料，就是一共提早两周准备定级，这样也可以留出充分的时间进行修改，做好充分准备，提高过关的几率，这样可以增强内心的责任感，提高行动力，提高定级准备的效率。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1497181333000,"updated_at":1500015455000,"ria":true},{"id":2749,"topic":"如何快速取得对方的支持和信任","learn_goal":"能陈述找到与他人的共同点，成为“同类”的方法","remark":"当你进入一个新的部门是否想快速与领导和同事愉快相处？你是否追求某个女生追求了很久人家却对你不理不睬呢？这些都只需一步就可以达到。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"刘小惠","city":"长沙"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我叫刘文惠，文化的文，贤惠的惠，取既有文化又很贤惠之意。我的三个便签，第一个与我的工作性质有关，商务，主要负责客户服务中订单处理这块内容，第二个标签，拆书帮会员，拆书便签学习法的爱好者。第三个标签，考研，再学习其实也是为了使自己的知识更体系化。那么什么是“拆书”什么是“拆书帮”呢？“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。分为个人学习的拆书法和组织学习的拆书法：以个人学习的应用是便签法，可以自己看书时进行片段拆解，并贴在页面上。让人读一本书就能达到参加同主题培训的效果；组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。“拆书帮”是基于拆书法的学习爱好者社群。拆书帮分舵是公益性青年自组织，其使命是帮助更多学习爱好者成长为拆书家。","ratings_count":0,"texts":[{"id":5500,"quote":"\u003cp>所选片段来自《细节》P039\u003c/p>\u003cp>即便是在最为极端的情况下，依然有些东西能把我们联结在一起，而不是分开。\u003c/p>\u003cp>莱文先请一群英国足球迷—刚好是曼联队的死忠粉—填写一张问卷，内容是写下他们喜欢曼联的哪些方面。填好问卷之后，球迷们需要走到校园里的另一幢楼里去，参加下一阶段的研究。往那幢楼走的路上，曼联球迷们会看到一个慢跑的人(其实是工作人员假扮的)拌了一跤，而且看上去受伤了。第一种情况下，慢跑的人穿着一件没写字的白上衣；第二种情况下，他穿着一件曼联队的球衣；第三种情况下，他穿的是曼联队的死对头—利物浦队的球衣（在我们看来，此举相当勇敢）。\u003c/p>\u003cp>观察员们拿着记录板在隐蔽的地方观察，记下有多少曼联队球迷会出手相助。结果是，要是你出去跑步，而且很倒霉地受了伤，你能否得到帮助跟你穿的上衣有很大关系。在研究中，当慢跑者穿的是素白T恤的时候，大约三分之一的曼联球迷停下来帮助了。当他们看到伤者穿的是曼联球衣，说明此人是他们中的一员的时候，绝大多数都帮忙了。\u003c/p>\u003cp>可是，当慢跑者穿着死对头利物浦队的球衣时，情况如何呢？停下来帮忙的曼联球迷非常少。这是一个非常有说服力的证据，说明人们最愿意帮助自己的“同类”。\u003c/p>","explains":"\u003cp>原文片段非常的好懂。片段通过一个实验得出一个结论“人们最愿意帮助自己的“同类”也就是与自己有相似性的人。第二种情况，慢跑者得到了绝大多数的人帮忙是因为他们有共同点：都穿曼联队的球衣，是曼联队的球迷。\u003c/p>\u003cp>\u003cstrong>在工作和日常生活中，我们可以通过找寻与他人的共同之处来达到化敌为友、快速拉近彼此之间的关系取得对方的支持和信任\u003c/strong>。如果管理者希望形成团队内部合作和支持的氛围，可以通过找寻团队成员们的共同点并进行关联。当一个男生想追一个女生，每次聊天女生都只回复恩，哦，这样如果连彼此的共同话题都没有那么成功几率也就微乎其微了。\u003c/p>\u003cp>How:\u003cstrong>在工作和日常生活中，我们可以通过找寻与他人的共同之处来达到化敌为友、快速拉近彼此之间的关系取得对方的支持和信任\u003c/strong>。\u003c/p>","interaction":"\u003cp>A1:&nbsp;\u003c/p>\u003cp>今年年初进PMC部之前，与部门领导有过一次面谈，面谈的时候领导给人的感觉比较严肃，不爱笑，所以面谈过后我得出的结论是性格上不算和我合得来的人。但是为了讨好领导，刚进部门为了更能摸准领导的性子平常也尽量保持着一定的沟通，就是逮着什么说什么，有时候对方都不怎么接话，很犯尴尬癌。有一天中午和部门同事一起在公司食堂吃饭，一同事边刷手机边吃饭，突然很赞叹的说：“哈尔滨的冰雕配上色彩多样的灯光简直美的让人窒息啊。”我连忙凑过去瞅瞅，也跟着说：“哇，这是我现在最想去的地方了，本来去年尾的时候打算去，一直没找到合适的时间。”这时我领导说：“我也很想去一直没去。”\u003cstrong>于是就这个话题我们就展开聊了一中午。后来我跟领导闲暇时间或在工作不忙的时候相互说自己去过的城市，分享旅途过程中遇到很有意思的人和一些开心地或者很倒霉地事情，后来慢慢的还会分享心得体会。因为我们有了共同的话题，在沟通中加深了对彼此的了解和信任，我们已经成为了好朋友\u003c/strong>，即使现在不在一个部门，有事的时候会相互通气，遇事也经常向她请教学习。\u003c/p>\u003cp>A2：\u003c/p>\u003cp>以前的一个小学同学来长沙工作了，小学的时候我们是很要好的朋友，后来不在一个学校后也一直没怎么联系，现在想和她再建立以往亲密关系。我需要重新找与她的共同点：\u003c/p>\u003cp>&nbsp; 1.关注她的朋友圈，发现她很喜欢环境优雅的书店\u003c/p>\u003cp>&nbsp; 2.那么平常谈话中可以多谈谈最近看了什么书，哪里有开了新的书店\u003c/p>\u003cp>&nbsp; 3.周末节假日可以相约去书店看书交谈\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1496058817000,"updated_at":1499059208000,"ria":true},{"id":2522,"topic":"如何让会议更高效？会前三步不能少","learn_goal":"能使用会前信息共享三步骤，来做好会前准备，提升会议效率","remark":"","level":"TF3-1","duration":25,"status":0,"type":0,"chaishujia":{"username":"王任映","city":"长沙市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"各位拆书帮的小伙伴们，大家晚上好。我是二级拆书家豆子，是一名高校的老师，同时也是一名职业生涯规划师。今天给大家带来的书，叫《细节》，是一本从心理学角度来解释生活、工作中各类细节对我们的影响的佳作。\r\n【场景法介绍】【事件】大家讨厌冗长又低效率的会议嘛？会议的主导者给大家通报的信息，有很多都是在重复以往的数据和信息；讨论没有条理，一不留神已经离题万里，而这时时间已经过去大半；到了会议快结束的时候，仍不能及时达成一直意见，或者仍没有一个定论，最后只能说一句“大家回去再想想”。【提问】遇到这样的会议大家是怎么对待的呢？无奈的参与？还是边抱怨边慢慢习惯了？【影响】其实，这样冗长又低效率的会议室我们每一个人都非常厌恶的，不但浪费时间和精力，而且对于项目、工作的推动毫无益处，甚至拖大家的后腿。\r\n【解决】那么，我们能采取什么措施来确保大家都畅所欲言又同时大大提升会议效率呢？书中给出了一个“四两拨千斤”的方法——请参加会议的人在会议开始前提交信息。让我们一起来看看这个神奇的方法吧。","ratings_count":0,"texts":[{"id":5236,"quote":"\u003cp>他们发现，人们在开会的时候，有相当多的时间都浪费在听别人讲那些人人都知道的事情上。更让人郁闷的发现是，真的带着新信息的人（而且只有他们知道这些信息）往往无法提醒其余的参会者去了解这些信息。\u003c/p>\u003cp>结果就是：这种情况下做出的决策，往好里说是“还凑合”，往坏里说就是“相当糟糕”。\u003c/p>\u003cp>【原文案例】\u003c/p>\u003cp>更多近期的研究证实了他们的发现。例如小詹姆斯·拉森（James Larson Jr.）和同事们所做的一项实验：他们给一群医生看了两个诊疗录像。看录像时，医生们被分成了小组，但他们不知道的是，每个小组看到的录像都有一点儿差异。此外，有些医生得到了两个患者的个人信息。结果就是所有的医生都了解到了两位患者的部分信息，但没有一位医生掌握全貌。\u003c/p>\u003cp>&nbsp; &nbsp;看完录像之后，医生们需要跟另一个小组讨论病例，商量出一个诊疗方案。研究者对实验的设定很聪明：只有当所有医生都把自己知道的消息分享出来的时候，才能做出最准确的诊断和治疗方案。然而研究者发现，信息的共享程度极少能达到最准确诊断的要求。因此，不那么理想的决策就导致了没那么好的治疗方案。简言之，结果不好。\u003c/p>","explains":"\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>今天我要拆解的片段来自本书第21章“把会议开得更高效”。希望大家在跟随我用RIA拆解完这个片段后，【可观察到的动作】在组织一次会议前，能使用“收集信息-列信息清单-共享信息”三步骤，【具体内容】来完成信息共享，【完成程度】以提升会议效率。\u003c/p>\u003cp>\u003cbr>\u003cstrong>I：\u003c/strong>\u003c/p>\u003cp>大家看完这个片段有什么想法？有没有一种躺枪的感觉？我当时看完这个片段脑子里就冒出三个字“悲剧啊！”我们这些年浪费了多少时间精力在低效率甚至是毫无成果的会议上！【类似概念】那是因为我们只做了“信息分享”！【类似概念的例子】也就是我们只是把信息发给了大家，比如在会上由领导念出来，比如在开会时人手发上一份文件。而要解决会议效率低下的问题，光“信息分享”是远远不够的，【概念提出】我们需要做到的是文中提到的“信息共享”。\u003c/p>\u003cp>那什么是信息共享呢？【概念讲解】说的简单一点，就是在不同层次、不同部门之间，把信息这种重要资源与相关人员共同分享，以便更加合理地达到资源配置，节约成本，创造更多利润的目的。显而易见，信息共享非常重要。【概念难点】但是在会议中，往往由于强势的领导、不清晰的流程、失控的争执等等各种原因，使得这么重要的一环做不到位。那如何保证信息共享做到位？信息又是怎样一步步共享到位的呢？我们一起来看一个好方法：在会议前就完成信息共享！\u003c/p>\u003cp>我们来看一个做好了信息共享的会议的例子。\u003c/p>\u003cp>【举出案例】\u003c/p>\u003cp>在我还在某互联网教育公司做产品开发的时候，有一次关于学习平台迭代升级的会议，就让我印象深刻。提前一天，我就收到了产品总监的邮件，在邮件中说明了本次会议的主题，以及参与各方，并邀请大家整理关于目前学习平台现况的相关信息，从上线的课程内容，到现在平台的功能、平台的使用情况，用户的反馈等等，并注明需要当天下班前回邮件给他。伙伴们，产品总监的这封邮件是在做什么工作呢？是的，他在提前收集项目相关信息，【概念步骤how】也就是我们实现信息共享的第一步：收集信息。而这一步，也实现了可以完成信息共享的第一个阶段：【类似概念】部分信息共享。\u003c/p>\u003cp>接下来，我们收到邮件的各位同事，都从自己的角度提供了关于目前学习平台的相关信息，并及时提交给了产品总监。【概念重点】重点来了，在第二天的上午9点，也就是大概会议开始前5个小时，我们又收到了产品总监关于这次会议的第二封邮件。在这封邮件里，我看到了从开发部、课程中心到销售部、市场部门等相关部门汇集到底所有的有关学习平台的信息，并且产品经理还在特别需要大家注意的信息上做了标记，比如开发部提出的目前没有办法实现的功能。大家可以看到，产品总监在大家提交信息后，花时间对零散的信息进行了整理和分层级，可以帮助参与人迅速全方位的了解信息，并且get到重点和关键点。【概念步骤how】这也就是会议前信息共享的第二步，“列信息清单”。\u003c/p>\u003cp>而产品总监提前5小时把这个清单发给每一个参与者，让大家有足够的时间在开会之前来获取、消化相关信息，则是信息共享的落地一步，【概念步骤how】也就是第三步，“共享信息”。而到这里，完成了信息共享的第二个阶段：【类似概念】重点信息共享。\u003c/p>\u003cp>事实证明，那次的会议确实十分高效，大家在预计的时间内迅速形成了一套可行的学习平台升级方案，最后平台开发出来投入市场的反响也很不错。可见通过前面的信息共享与积累，大家最终在会议时间，高效的实现了信息共享的最后一个阶段，【类似概念】即所有信息的全貌共享，并基于全貌信息得到了最合适的解决方案。\u003c/p>\u003cp>大家是否已经get到，为了能够提高会议效率，咱们在会前进行信息共享的三个步骤呢？【概念步骤how】那我来总结一下：第一步，收集信息；然后列信息清单，最后，跟大家共享信息。别小看这会议前的三步，更不要觉得这样做有点浪费时间。这可是提升会议效率“四两拨千斤”的好办法哦！【异议讲解】当然这个方法适合绝大部分有准备时间的会议，大家看到例子里，产品总监是提前了一天就在做准备的，所以那些临时的紧急会议还是不太适用的。【适用边界】另外，信息的共享也分对象，像例子中，大家的层级差不多，都是各个部门的负责人，大家信息共享效率就很高；想法，如果层级差很多，就会有类似上层某些信息需保密，或者下层get不到上层信息如何用的情况。关于会议前信息共享的方法，大家都了解了嘛？\u003c/p>","interaction":"\u003cp>\u003cstrong>A2：\u003c/strong>\u003c/p>\u003cp>光听不练，那方法再好也是书上的。所以我现在想请大家分组来编一个关于开会之前做信息沟通的小故事。\u003c/p>\u003cp>（给大家分组）\u003c/p>\u003cp>请两个组的伙伴共同合作编一个关于会前做信息沟通的小故事。这个故事需要包含：\u003c/p>\u003cp>1.会议的背景介绍与角色分工\u003c/p>\u003cp>2.在会前完成“收集信息-列信息清单-共享信息”三个步骤\u003c/p>\u003cp>3.可以设置1-2个在过程中会遇到的困难或障碍，通过对话的形式进行解决。\u003c/p>\u003cp>我会给大家5分钟的时间准备，最后请一个组来给我们做展示。大家清楚了嘛？\u003c/p>\u003cp>【伙伴展示】\u003cbr>\u003c/p>\u003cp>\u003cstrong>会议背景：\u003c/strong>安排公司员工（工作满5年的）出去旅游，要讨论活动的细节安排。\u003c/p>\u003cp>\u003cstrong>人物角色：\u003c/strong>HR，（工作满5年的）员工小王，其他工作满5年的员工\u003c/p>\u003cp>\u003cstrong>故事内容：\u003c/strong>\u003c/p>\u003cp>首先，在会议前一天，设计一份电子邮件，发给全公司工作满5年的员工，调查大家的旅游目的地倾向。\u003cstrong>（收集信息）\u003c/strong>\u003c/p>\u003cp>邮件内需要员工提供信息的选项包括：是否愿意参加活动、想去的地方（大区域，比如是想去游山“大围山”还是玩水“桃花源”，还是想在城区玩）、更倾向的时间（周末或小长假）以及，是否愿意在活动中承担一些服务工作（活动设计、活动组织、主持、采购物料等）\u003c/p>\u003cp>接下来，收集到信息后，根据大家的反馈进行整理。\u003cstrong>（列信息清单）\u003c/strong>然后把不同选项的调查结果，通过电子邮件反馈给大家。其中，时间和地点需要重点提示大家（如果这个时间/地点自己不能参与，需要提前告知）；同时，提醒“愿意承担活动中服务工作”的同事，下午需要跟人事一起开会。\u003cstrong>（共享信息）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>遇到的困难（对话设计）：\u003c/strong>\u003cbr>\u003c/p>\u003cp>HR看到小王没有提交信息，于是找到小王问情况。\u003c/p>\u003cp>HR：小王，咱们组织老员工旅游，我看到你没有反馈信息表。是在忙吗没来得及？\u003c/p>\u003cp>小王：不是的。我对这个没什么兴趣。\u003c/p>\u003cp>HR：啊，没兴趣吗？是对旅游没兴趣嘛？\u003c/p>\u003cp>小王：我喜欢旅游。是给出的几个选项，我没什么兴趣。\u003c/p>\u003cp>HR：这些地方都不喜欢吗？\u003c/p>\u003cp>小王：都是省内的景点，没啥意思。\u003c/p>\u003cp>HR：我明白了。但是咱们公司最近业务比较忙，如果要出省去比较远的地方，来回路上时间会花费比较多，可能需要等到业务淡季，但是那时候的天气又不如现在好。\u003c/p>\u003cp>小王：唉，我也知道是这样的。\u003c/p>\u003cp>HR：你看，虽然忙，我们还是希望能让大家出去走走，调节下忙碌的将诶走。\u003c/p>\u003cp>小王：其实，去趟大围山也还可以。虽然去过好几次了，那边空气不错。我们部门几个同事好像也想去。\u003c/p>\u003cp>HR：好的。那，麻烦你把想法通过反馈表发给我，可以吗？\u003c/p>\u003cp>小王：好的，我马上去填。\u003c/p>\u003cp>\u003cstrong>故事的结果：\u003c/strong>因为目的地时间都很明确，大家在随后的会议上很快的进行了分工，并对可能出现的问题进行了预案准备。活动得以顺利进行，而且大家的参与度很高。\u003c/p>\u003cp>【给出反馈】感谢我们这个组的精彩的展示！我们可以看到，不但会议效率变高，活动的效果和参与度也得到了极大的提升啊！\u003c/p>\u003cp>【结语】所以，为了告别“冗长又低效”的会议，为了让我们的工作时间更高效，我们以后都来尝试在会前使用“收集信息-列信息清单-共享信息”，来提升会议效率，好嘛？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1493733774000,"updated_at":1493965251000,"ria":true},{"id":2521,"topic":"如何送出一份完美礼物？","learn_goal":"能通过“分析需求、确认需求、投其所好”的步骤，来传情达意","remark":"","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"王任映","city":"长沙市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"各位拆书帮的小伙伴们，大家晚上好。我是冲向二级的准一级拆书家豆子，我有三个身份，高校讲师、生涯规划师，以及心理咨询师。【F】大家一定还记得我之前给大家推荐过的一本书——《影响力》，因为作者有着“心理学教授”的背景和功底，所以从人的本质心理模式层面来解读影响力的建立和应用，感觉好读又实用。那今天我带来的这本书就是《影响力》作者西奥迪尼教授的新作《细节》。\r\n【A】不同于一些纯粹讲理论的书籍，这本书不但完整且细致地揭示了失败和成功之间存在着的细节差别，它还会通过52个细节法则，手把手教会你掌握职场沟通、员工激励、商业谈判、家庭教育等各个工作和生活领域的影响力建立方式！\r\n【B】俗话说，细节决定成败！那些被我们忽视的小细节，时间上是早一点儿好还是晚一点好？谈话场景用主场还是客场？如何抛砖引玉？如何改动一个小小的顺序而引来更多的生意机会？这些看似不起眼的细节往往却有着一锤定音的效果。就像我们今天要聊的这个话题一样，通过一份礼物，对方是否能感受到我们的心意？这还真是个让人头疼的问题啊！不妨跟我一起来走进有关送礼物的“细节”吧。","ratings_count":0,"texts":[{"id":5234,"quote":"\u003cp>全美零售联合会（National Retail Federation）于2008年做的一项调查显示，大约有50%的美国人希望每年至少能退还一件节日礼物，这清楚地表明，接受礼物的人并不像送礼的人设想的那般珍惜这些东西。注意到这个颇为震惊的数据之后，研究人员弗朗西斯卡·吉诺（Francesca Gino）——出色的《分心》（Sidetracker）一书的作者——和弗兰克·弗林（Frank Flynn）对这个问题产生了兴趣：对于礼物的品质和实用性，为什么送礼的人和收礼的人总是想不到一块儿去？他们还认为，【拆页how】这事有个简单的解决方法：想要送礼物的人在买东西之前应该先问问朋友、家人和同事，请他们把想要的东西列个单子，然后从这张清单上选一样送给他们。\u003c/p>","explains":"\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>今天我们要拆解的第一个片段就来自本书第30章“完美礼物哪里找”。希望大家在跟随我用RIA拆解完这个片段后，【可被观察到的行为】在为他人准备礼物前，学会利用“请对方列完美礼物清单”的方式，来精准挑选礼物。\u003c/p>\u003cp>\u003cstrong>I：\u003c/strong>\u003c/p>\u003cp>估计大家跟我一样，被这个调查报告的结果给惊到了，居然有一半的人对自己收到的礼物是不满意的！可是回想一下，我们收到的每一份礼物自己都满意吗？我想问问在坐的伙伴们，大家有收到过跟自己家里摆设完全不搭的摆件嘛？或者，收到过颜色辣眼睛的钱包？甚至，我听说还有人收到过自己曾经送出去的礼物，是的，兜了一圈，礼物又回到了自己的手上。情侣或夫妻间好像也不会好多少，比如我前任，在连续第三个重要节日仍然送的是我不喜欢的花时，咳咳，他就变成了我的前任。\u003c/p>\u003cp>回想完这些让我们“莫名其妙”的或者“失望透顶”的礼物，这时候咱们再来想想，我们伤透脑筋给朋友、亲人送上的礼物，对方是否也会“莫名其妙”或者“失望透顶”？【更贴近实际的例子】比如，我曾经提前一个月为闺蜜的生日准备礼物，又是查淘宝上的“礼物推荐”，又是各种百度搜索，独独就是没有去问问闺蜜想要什么。结果，当我在生日趴体上拿出为她特别挑选的拍立得相机，才郁闷的发现，这也正是她自己送给自己的礼物。好吧，我们这也太默契了。\u003c/p>\u003cp>在跟我协商后，我退回了拍立得的相机，为她换了漂亮的相纸和相簿，这下跟她新买的相机就完美搭配了。试想一下，如果我在准备礼物时问问她想要什么，就能省去大量查找礼物的时间直接给她带来心仪的相机，也能免去后来退换货的麻烦。\u003c/p>\u003cp>&nbsp; &nbsp;【预防异议的讲解】当然，你可能会问，礼物不是越惊喜越好么？这样直接请对方列清单是不是会让对方觉得自己不重视？事实上，书中后面的段落有说到，实验和数据表明，大家更关心礼物是不是自己想要的，而非是不是惊喜。或许，还会有伙伴想问，如果对方就是不告诉我们想要什么，那又怎么办呢？【点出两个片段之间的逻辑关系——递进】别担心，在随后的第二个片段的拆解中，我也会给到大家解决方法哦。所以大家不用担心，大胆的问问对方，什么是他心仪的礼物吧。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：\u003c/strong>\u003c/p>\u003cp>那现在我想请大家回忆下，我们的一次送礼物送失败的经历。【显像提问法】比如，给父母送的保暖内衣尺寸不合适？比如给朋友送的小摆设从未见他用过？比如送给同事的书，很久后问起他支支吾吾的明显没看？有类似经历的伙伴与我们分享一下可以吗？\u003c/p>\u003cp>【伙伴分享】\u003c/p>\u003cp>美林：\u003cbr>\u003c/p>\u003cp>在刚刚过去的这个年节，我给我的公公婆婆准备礼物。我给公公买了一身南极人的保暖内衣。当时我觉得料子不错，还好的是尺寸我也问过了，大小都还合适。唯一不好的是，我老公的二姐，也买了这么一身。其实，当时我公公是想要一个马甲，结果我和二姐买重了。而且当时也没法退了，我公公就只能是，换着穿了。要是我当时问一下他，问一下二姐就好了。\u003c/p>\u003cp>海带：\u003c/p>\u003cp>前段时间我朋友生日，我就给她准备了两本书，然后直接寄到她那儿去。在我问她要地址的时候，她好奇问我是什么书，这会儿才发现，我给她买的两本书，她都看过了。我说，啊，那怎么办。她还安慰我说，没事，我可以借给别人看。好尴尬啊！所以我就想，如果以后我再给她买书，一定要先问她，最想看什么书。&nbsp;\u003c/p>\u003cp>谢谢美林和海带的分享。礼物都出现了大撞车啊，何况美林的公公确实还有更需要的东西。【A1+指令】那现在请大家想一想，我们如果是美林或者海带，这个送礼物的过程重来一次，我们会怎么做呢？\u003c/p>\u003cp>【伙伴分享】&nbsp;\u003c/p>\u003cp>美林：“爸爸，正好我们朋友公司商品打折，是员工内部价，特别便宜。然后公司为了鼓励消费，还给我们发券了。这券还不能兑现金，所以必须买，要不就浪费”（打消老人想省钱的观点）“他们公司有西服、保暖内衣、羽绒服、马甲，我把照片给你拍过去，你列一下，看最喜欢哪些。”&nbsp;\u003cbr>\u003c/p>\u003cp>\u003cstrong>A2：\u003c/strong>\u003c/p>\u003cp>好的，大家的设计都很棒哇！我想问问大家，最近是否有需要送礼物的计划呢？如果有的话，不妨设计一个方式，来问问对方想要怎样的礼物，可以吗？也就是请对方列出“完美礼物清单”。请大家把想到的方式写在便签上哦。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":5235,"quote":"\u003cp>&nbsp;&nbsp;对礼物的喜爱程度是一个重要的决定因素，这不但会影响收礼人日后的回报热情，也会影响他的开心程度。所以，这项研究对我们与他人的沟通有着重要的提示价值。它告诉我们，送礼物的时候，应该想办法摸清对方真正想要什么，不要自己瞎猜。这个小小的改变是个双赢的做法，人人都满意。【原文how】一个办法是，给收礼物的人一沓即时贴，让他们把杂志上想要的东西标出来，作为以后的礼物备选。另一个方法是，看看随时放在家里的购物型名录上有哪些页面被折角做了标记。\u003c/p>\u003cp>在工作中也是一样，例如，请客户吃饭的时候，应该带人家去那个他们提了好多次的新餐馆，而不是你最喜欢的那一家。【原文how】无论怎样，从对方的清单上挑选（而不是从你的），这个小小的改变，能让对方的感激程度发生很大的变化。这个方法还会有以下好处：确保你送出去的礼物不会沦落到礼品处理网站上或者垃圾桶里——或许更糟的是，出现在明年你收到的那堆礼物中。\u003c/p>","explains":"\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>接下来我们要拆解的片段仍然来自本书第30章“完美礼物哪里找”。希望大家在跟随我用RIA拆解完这个片段后，【可观察到的行为】能通过“分析需求—&gt;确认需求—&gt;投其所好”三个步骤，来传情达意（如挑选礼物）。\u003c/p>\u003cp>\u003cstrong>I：\u003c/strong>\u003cbr>\u003cbr>\u003c/p>\u003cp>通过这个片段的解释，我相信大家可以非常清楚的了解到，如果我们能投其所好的送给对方他喜欢的礼物，而不是以我们自己的喜好为出发点，会是个双赢的结果。【更贴近实际的例子】【不这么做的坏处-负面一般做法】比如曾经我有一个朋友就找我抱怨说，她老公在她生日时，给她送的礼物是一套XBOX的家庭游戏机，【不这么做的坏处-这样做的坏处】事实上，她一点也不喜欢，反倒是她老公简直爱不释手，甚至会因为太投入打游戏而有点忽略她。可想而知她对这份生日礼物有多失望。\u003c/p>\u003cp>那用咱们片段中介绍的方式，我朋友她老公应该怎么做呢？【不这么做的坏处-拆页行动建议+变成正面例子】第一步，应该是分析老婆的需求。根据片段中给我们列举的方法，套用到我们的生活中，比如，他可以去看看老婆淘宝购物车中收藏了哪些宝贝？大家一定都听说过“豪气老公为老婆买空购物车”的故事哈！各种羡慕嫉妒啊~同时，如果他够细心的话，也可以好好观察下老婆最近在谈论什么感兴趣的东西，是一支阿玛尼的口红，还是一次浪漫的旅行；或许，他也会注意到他老婆曾经在一条丝巾前“流连忘返”。做完第一步，可能我们有了一个大致的范围，但是如何确定到底买哪一件呢？所以，第二步就是“确认需求”。再说回我朋友家的事儿哈，她老公可以把选中范围内的礼物列个清单发个老婆，再来两句甜言蜜语，比如“亲爱的，我想为你的生日送上最好的祝福，你看看这些礼物里有没有特别喜欢的？”当老婆看到他的清单中的礼物清单中真的有自己特别中意的礼物时，一定会非常欣喜，对嘛？那第三步就水到渠成，直接投其所好为老婆最心仪的礼物下单就好啦！【强调两个片段的逻辑——递进】还记得刚刚在上一个片段我们留的一个尾巴吗？如果对方不愿意提供想要的礼物清单怎么办？那现在大家看看，【细化原文行动建议步骤】利用这三个步骤“分析需求—&gt;确认需求—&gt;投其所好”，是不是就可以很好的解决了呢？对方不愿意提供礼物清单，一方面可能是不好意思，另一方面还有可能是他们自己也不知道要啥。如果清单由我们提供，他们只需要选择，事情会好办很多哦。\u003c/p>\u003cp>&nbsp; &nbsp;当然，这个步骤的用途远不止买礼物这么简单，就如同片段中说得一样，从生活中到工作中，我们都可以尽情使用这个步骤，从对方的需求出发，来为自己传情达意。比如挑选与客户共同进餐的餐厅时，比如选择家庭旅游的目的地时，比如组织员工活动时等等，在这些我们要表达敬意、表达温情、表达感谢等情意的时刻，我们都可以利用这三个步骤“分析需求—&gt;确认需求—&gt;投其所好”，来用最恰当的方式表达我们的感情。\u003c/p>","interaction":"\u003cp>\u003cstrong>A3：\u003c/strong>\u003cbr>\u003c/p>\u003cp>接下来，【给出具体场景】我想请大家设想这样一个场景：你的一位关系很好的老同学要从外地来长沙出差，你想请他吃饭接风。你们有4-5年没有见面了，所以你很想选择一家能让老同学满意的餐厅。\u003c/p>\u003cp>现在，【行动指令】请大家找身边的一位小伙伴组成搭档，来设计一下如何通过“分析需求—&gt;确认需求—&gt;投其所好”这三步来完成餐厅的选择。我会给到大家10分钟时间。大家讨论过程中，如果发现问题，可以随时停下来对之前的设计进行修正。大家清楚了嘛？如果没有问题，就请与我们的搭档开始设计和演练吧。\u003c/p>\u003cp>（设计与演练，大概10min）\u003c/p>\u003cp>好的，大家讨论的很激烈啊！现在，我想请两位朋友来演练一下，其中一位伙伴来扮演你的老同学，与他进行需求的确认，并完成餐厅的选择。可以吗？\u003c/p>\u003cp>【现场演练】\u003c/p>\u003cp>文惠介绍\u003cstrong>分析需求\u003c/strong>部分：首先，我们在分析需求的时候，有两种方式：一种是看老同学的朋友圈，是否有分享她喜欢的美食，看她喜欢哪一系列的食物，包括喜欢什么菜啊、餐厅环境啊，看她有些什么偏好。第二个方式呢，我去套话。比如我会这么跟她说：\u003c/p>\u003cp>\u003cstrong>演练部分：\u003c/strong>\u003c/p>\u003cp>文惠（我）：美林（假设人在深圳），我听说你们深圳那边有蛮多好吃的，有哪些好吃的你最近在吃的，可以给我介绍一下？\u003c/p>\u003cp>美林（老同学）：深圳的粤菜还是很多的，但是我们当地人都吃腻了。不过，最近附近新开了一家“蛙来哒”，以蛙为主题，口味偏辣，我还没去吃过。\u003c/p>\u003cp>\u003cstrong>继续介绍：\u003c/strong>\u003c/p>\u003cp>文惠（我）：就是如上这样，通过套话，我就发现她最近想吃辣的。那正好，来了长沙就带她去吃湘菜。接下来就\u003cstrong>确认需求\u003c/strong>了。\u003cbr>\u003c/p>\u003cp>\u003cstrong>演练部分：\u003c/strong>\u003c/p>\u003cp>我：美林啊，我选了三家店，有偏辣的，也有兼顾你清淡口味的，装修风格都还挺不错的（都符合她朋友圈常发的装修风格），你来选一下。\u003c/p>\u003cp>老同学：既然我好多年没回来了，那我们正好选我们学校附近的，这样我们吃完饭后正好可以去学校逛一下。还可以回顾下学生时代餐馆的味道。\u003c/p>\u003cp>\u003cstrong>（投其所好）\u003c/strong>我：好的，那我现在就去把它定下来。我订好位子，你一到，我们就直接可以过去啦！等着跟你接风哦。&nbsp;\u003c/p>\u003cp>【拆书家反馈】拆书家：哇，特别棒啊！我们掌声给到他们！过程中对三个步骤把握很到位，而且印象深刻的是需求分析阶段，无论是看朋友圈，还是套话，都非常用心哦。\u003c/p>\u003cp>\u003cstrong>A2：\u003c/strong>\u003c/p>\u003cp>非常感谢几位小伙伴的演示。大家在演练中是否已经感受到“分析需求—&gt;确认需求—&gt;投其所好”的妙用了呢？可以用到这个方法的场景真的很常见啊！【分步催化-未来会遇到的场景】我想问问，大家接下来的一周是否就有需要表达自己情意的事情要做？【提问中包括场景】比如我们刚刚谈到很多的要送出礼物？或者要请人吃饭？或者要为员工组织一场活动？甚至是为员工订制一场主题培训？有这样的需要吗？可以分享一下吗？\u003c/p>\u003cp>【伙伴分享】\u003cbr>\u003c/p>\u003cp>心愿：我最近接到一位重要客户，平时联系不多，我也不是那种很会送礼物去迎合他的。但是这次的项目很重要也很大，我很想表达一下我对他的尊重，所以想给他送一份礼物。\u003c/p>\u003cp>感谢大家的分享，在刚刚的分享中，我们有听到啊，无论在工作中还是生活中，我们经常会遇到需要表达自己情意的时候。【分步催化-学习者加工未来场景中的应用】接下来，我想请各位就我们刚刚分享中的某一个情境，去设想一下，我们怎么利用“分析需求—&gt;确认需求—&gt;投其所好”来做出完美选择？，我们先想一想，想好的朋友可以先来分享。\u003c/p>\u003cp>【伙伴分享】\u003c/p>\u003cp>心愿：我正好手上有《我是歌手》票。【分析需求】看她发朋友圈好像蛮想去的。【确认需求】我拿票去问问她看，【投其所好】如果她有时间，就把票送给她。\u003c/p>\u003cp>【拆书家反馈】拆书家：心愿这么有心的礼物，尤其现在《我是歌手》的票还蛮宝贵的啊，有钱都不一定弄得到。相信一定会让客户感受到我们的诚意的！\u003c/p>\u003cp>【强有力的总结】结语：\u003c/p>\u003cp>恭喜大家已经get到了新技能——用“分析需求—&gt;确认需求—&gt;投其所好”三步法来帮我们完成一系列的选择，从选择礼物、餐厅，到选择活动主题、培训主题等。正如片段中说的，“无论怎样，从对方的清单上挑选（而不是从你的）”，这个方法就是帮助我们学会站在对方的角度来思考，用对方更喜欢的方式来表达我们的情意。\u003c/p>\u003cp>&nbsp; &nbsp;“分析需求—&gt;确认需求—&gt;投其所好”，下一个挑选礼物的高手，会是你嘛？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1493733481000,"updated_at":1493733481000,"ria":true},{"id":2067,"topic":"巧用“未来绑定法”，有效说服别人","learn_goal":"巧用“未来绑定法”，有效说服别人","remark":"有时候，无论我们多么用心良苦，无论我们对高效说服他人的技巧掌握得多么娴熟，结果还是有可能失败；\r\n和抗抗一起，巧用“未来绑定法”，来避免那些一定会被拒绝的情况发生！","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"抗抗","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"大家好，我是抗抗，抗日战争的那个抗抗。\r\n我有3个标签：一级注册建筑师，翰林分所二级拆书家，二把刀的画家\r\n学习目标：\r\n在跟随我完成本次RIA现场学习后，学习者能够运用“未来绑定法”，有效说服别人。","ratings_count":0,"texts":[{"id":4704,"quote":"\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够运用“\u003cstrong>未来绑定法\u003c/strong>”，有效说服别人。\u003c/p>\u003cp>\u003cstrong>用学习者场景法介绍图书\u003c/strong>\u003cstrong>（1-2分钟）\u003c/strong>\u003c/p>\u003cp>今天我想推荐给大家的书叫做：《细节：如何轻松影响他人》。\u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>大家有没有发现生活中这样一些细节：春节时候收到的拜年短信如果前面加了你的名字，你会非常开心并且会回复，但是那些明显群发的消息，你就没那么上心了。同样当你给客户发邮件短信时，如果在开头加上了对方的名字，尊敬的某某某，往往会得到更快更好的反馈。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>这些细节你之前注意到了么？你是怎样看待它们的呢？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>其实这些看似很小的细节，会造成难以估量的巨大影响力，不仅会影响到事情的发展，会影响到你的个人形象，甚至会影响到你的职业发展，\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>这本书就从52个细节入手。手把手教会我们可以影响他人、逆转自我的极具创造力的影响力法则。每个细节均已案例为切入点，实操性极强。很多读者在读完之后感慨：这52个细节，就是52个套路啊。在这个套路满天飞的社会，我们不学点套路防身么？即使我们不套路别人，也能预防被套路。\u003c/p>\u003cp>今天就让我们来学点实用的套路！\u003c/p>\u003cp>《细节》\u003c/p>\u003cp>第14章\u003c/p>\u003cp>\u003cstrong>未来绑定法\u003c/strong>\u003c/p>\u003cp>社会心理学家所做的研究显示，“不远的将来”和“遥远的未来”在人们心目中的感觉是不一样的。想到离眼前不远的事，人们会想得十分具体，可是，想到那些在很久以后才会发生的事，人们更容易把它想得更为抽象。例如，如果你想请同事们在某个周末去当地收容所里做一次义工服务，那么，是这个周末就去，还是8个月后的某个周末再去，他们的反应很可能大不一样。如果你希望他们这个周末就去，他们的关注点很可能会放在某些具体的代价上，比如，去做义工就没法去购物了，再不然，就是没法睡懒觉了。\u003c/p>\u003cp>但是，如果你希望大家8个月之后的某个周末再去，他们就更有可能从更为宽泛的层面上评估你的请求，例如这个请求与他们的总体价值观、道德观和意识形态有何关联。当他们发现，伸出援手的义工行为符合自己的价值观的时候，他们就会更容易答应你的请求，并且遵守承诺。行为科学家托德·罗杰斯与马克斯·巴泽曼把这个承诺策略叫作“\u003cstrong>未来绑定法\u003c/strong>”。\u003c/p>","explains":"\u003cp>通过这个片段，我们了解到了一个有效的说服策略：未来绑定法。\u003c/p>\u003cp>未来绑定法应用的前提是说服内容与被说服者的价值观、道德观、意识形态是一致的，就像片段中给出的例子：义工行为是符合同事们的价值观的，所以当作者把同事们的关注点从当下转移到遥远的未来，就更容易说服对方。\u003c/p>\u003cp>\u003cstrong>（举出了案例，并通过概念与匹配例子之间的对比，引出知识点逻辑、步骤）\u003c/strong>这时，我就想问大家，如果我想说服我爸戒烟，可以应用这个方法么？可以，因为戒烟对健康有利，是符合对方价值观的。\u003c/p>\u003cp>这时有的小伙伴会问，价值观太抽象了？那么还有一个判断标准就是，说服对方答应的这个事件本身是不是在对方的认同或者期望范围之内，或者是是不是对他有利。\u003c/p>\u003cp>我想问大家，如果我想说服我的男友帮我“清空购物车”，可以应用这个方法么？当然不可以，显然“买买买”的剁手行为对于他来说是不能被认同的。\u003c/p>\u003cp>\u003cstrong>（具体步骤）\u003c/strong>所以，我们从原文的例子以及应用的前提，能够归纳出“未来绑定法”的步骤：\u003c/p>\u003cp>首先，\u003cstrong>判断\u003c/strong>说服事件本身是否符合对方的价值观或者在对方的认同或者期望范围之内。\u003c/p>\u003cp>其次，如果对方没有意识到你想说服他的事与他的价值观一致或者在他的认同范围内，那么\u003cstrong>引导\u003c/strong>对方，让对方意识到这是一个对他们有好处的事。\u003c/p>\u003cp>最后，\u003cstrong>从未来入手\u003c/strong>，让对方在之后的某个时间段内兑现在这个承诺。\u003c/p>\u003cp>\u003cstrong>（明确边界）\u003c/strong>此外“未来绑定法”特别适用于那些失败可能性极大的情况，能够缓解短时间内的尖锐矛盾。\u003c/p>\u003cp>例如作为管理者，我想说服员工改用一个更高效新软件，这个决定，一定是已经进行过\u003cstrong>判断\u003c/strong>，是对整个团队有利的。这就完成了第1步。然而，实际情况是：通常大家都会觉得要花时间来熟悉新软件，会影响正常工作，往往不会接受，于是管理者先告诉员工新软件可以提高工作的效率，\u003cstrong>引导\u003c/strong>大家意识到这与大家的期望相一致，这就完成了第2步。最后\u003cstrong>从未来入手\u003c/strong>，告诉员工在接下来的一个月内，可以学习新软件，旧软件也同时应用，一个月后，将全部改为新软件，这样大家的反对意见就不会那么大了。\u003c/p>","interaction":"\u003cp>接下来，让我们学以致用，请小伙伴一小组为基础，来编一段说服别人的小故事，或设想一个你会遇到的说服别人的对话场景，要求有对话，还包括时间地点人物、起因经过结果，最重要的是运用刚刚学会的“未来绑定法”，最终说服成功了。\u003c/p>\u003cp>这个场景可以是你说服家人改掉一些对健康不利的坏习惯；也许是你在工作中说服合作伙伴对工作方法的一些改进；\u003c/p>\u003cp>好，给大家5分钟时间，然后我会请小伙伴来讲讲你们的小故事。\u003c/p>\u003cp>分享者一：\u003c/p>\u003cp>编一个我跟儿子的对话，晚上10点了，要睡觉了，他已经看ipad半小时了，我想让他关掉。\u003c/p>\u003cp>我会跟他说：你已经看了半小时了，妈妈觉得你应该关掉，休息一下眼睛。\u003c/p>\u003cp>儿子可能会说：不嘛，我还想看。\u003c/p>\u003cp>我告诉他：你按我说的，关掉ipad，睡前可以多讲一个故事，而且妈妈不会马上关掉ipad，再过10分钟，咱们就关掉。\u003c/p>\u003cp>他可能觉得愿意有一个缓冲的过程，愿意接受这个方法。\u003c/p>\u003cp>拆书家回应：这个10分钟，对他来说其实时间以及比较久了。而且把兑现承诺的情况放到了未来，而且你也提到了再看ipad对眼睛不好，其实你是告诉他了，减少看ipad的时间是对孩子有利的，是符合他的认知的，就是在引导他。\u003c/p>\u003cp>分享者二：\u003c/p>\u003cp>编一个把我的朋友带入拆书帮，，首先他对学习非常认同，对他有好处。我会给他看咱们现场的照片，给他讲案例。我会跟他说：你看最近又这么多活动，你看看周末是不是有时间可以参加，或者周五晚上可以来感受。\u003c/p>\u003cp>拆书家回应：你给了他一个选择，周末或者周五，就很好。而且你把你参加活动的感受一起告诉他，是另一种引导，更有说服力了。\u003c/p>\u003cp>总结\u003c/p>\u003cp>刚才这位小伙伴分享非常的好，让我们来感谢他们！\u003c/p>\u003cp>接下来我来总结一下，今天我们学习了“未来绑定法”，适用于符合对方价值观，对对方有利，但是又极有可能失败的情况，有3个应用步骤：判断，引导，放到未来。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1488359240000,"updated_at":1504866127000,"ria":true},{"id":2065,"topic":"把握神奇的细节，敦促对方履行承诺","learn_goal":"让学习者学到一些细节的处理，从而敦促对方履行承诺","remark":"如何让人员众多的会议更高效？\r\n如何提高自己组织的活动的上座率？\r\n如何让下属被安排的工作按时有效的完成？\r\n如何让老板“涨工资放长假”的承诺不成为一句空话？\r\n如何让亲友约好的饭局，不出现临时放鸽子的情况？\r\n只要把握住一些“神奇的”细节，就能有效提高对方履行承诺可能，增强履行承诺的力量。——这些“神奇的”细节，有个时髦的叫法：套路。\r\n在这个充满“套路”的时代，就算没学会如何四两拨千斤地“套路”别人，至少应该能聪明地识破别人的“套路”。","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"抗抗","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":null,"ratings_count":0,"texts":[],"created_at":1488354866000,"updated_at":1488354866000},{"id":2063,"topic":"把握神奇的细节","learn_goal":"有效提高对方履行承诺可能","remark":"如何让人员众多的会议更高效？\r\n如何提高自己组织的活动的上座率？\r\n如何让下属被安排的工作按时有效的完成？\r\n如何让老板“涨工资放长假”的承诺不成为一句空话？\r\n如何让亲友约好的饭局，不出现临时放鸽子的情况？\r\n只要把握住一些“神奇的”细节，就能有效提高对方履行承诺可能，增强履行承诺的力量。——这些“神奇的”细节，有个时髦的叫法：套路。\r\n在这个充满“套路”的时代，就算没学会如何四两拨千斤地“套路”别人，至少应该能聪明地识破别人的“套路”。\r\n","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"抗抗","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"我有三个标签，第一个标签，我是国家一级注册建筑师，第二个标签，拆书帮二级拆书家。第三个标签，感悟型设计狗，我一直觉得我们听到什么，看到什么都远远没有感悟到什么重要，我立志做一只鼻子最灵敏的设计狗！\r\n今天我想推荐给大家的书叫做：《细节：如何轻松影响他人》。\r\nF特征:\r\n这本书是罗辑思维的推荐书目之一，它的作者一共有3位，其中之一是著名书籍《影响力》的作者]罗伯特•西奥迪尼。\r\nA优势: \r\n与《影响力》不同，这本书从52个细节入手。手把手教会我们可以影响他人并逆转自我人生的极具创造力和科学性的影响力法则。每个细节均已案例为切入点，实操性极强。每一个细节占用的篇幅都很短，非常适合睡前阅读。\r\nB利益: \r\n通过这本书的阅读，能够帮助我们提升个人品质、解决生活难题、打造企业品牌，最终更易获得最后的成功。很多读者在读完之后感慨：这52个细节，就是52个套路啊。在这个套路满天飞的社会，我们不学点套路防身么？即使我们不套路别人，也能预防被套路。\r\n今天就让我们来学点实用的套路！","ratings_count":0,"texts":[{"id":4699,"quote":"\u003cp>\u003cstrong>片段一：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习目标：通过片段学习，让学习者学会说服别人的方法——从违背社会规范的角度去进行阐述。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【主题】\u003c/strong>\u003cstrong>&nbsp; \u003c/strong>\u003cstrong>如何说服别人\u003c/strong>\u003cbr>\u003c/p>\u003cp>心理学家哈特·布兰顿和同事们认为，哪种措辞能够见效，要看你的朋友对关于这个行为的社会规范(social norm)有何看法。这话的意思是，当有人引导他们去思考某个行为对自己的身份会造成什么影响的时候，一般来说，他们会更加在意违背(而不是顺应)社会规范的代价。因此，如果你想影响他人的行为，那么，你就从违背他心目中的社会规范的角度去遣词造句，这样做的收效比顺应的角度更见效。\u003c/p>\u003cp>这个实验提供了清晰的示范做法:首先，告诉人们关于某个行为的社会规范是什么，然后描述那些违背这个规范的人具备什么特质。\u003c/p>","explains":"\u003cp>我想请大家设想这样一个问题：假如在上下班高峰的地铁上，身边有个可能感冒的人一直打喷嚏不捂嘴，你想提醒他，怎么说最有效呢？你会简单说：请捂一下嘴！还是顺便强调捂嘴的好处：请您注意卫生，捂一下嘴！再或者：强调不捂嘴的坏处：请捂一下嘴，否则容易传染别人。\u003c/p>\u003cp>实验证明：强调坏处最有效。因为人们的潜意识中对于批评更在意，也就是会对违反社会规范所造成的代价更加敏感。\u003c/p>\u003cp>\u003cstrong>(强调不那么做的坏处)要是你不这么反着说，只是一味地顺着说：应该怎样啊，应该怎样啊，是不是没什么威慑力、还仿佛催你穿秋裤的老妈附身，特别招人烦呢。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（\u003c/strong>\u003cstrong>细化行动步骤）那么我们再来梳理一下片段中给出的技能点：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.&nbsp;&nbsp; 搞清楚对方对于某个行为的社会规范是什么？例如：公共场所不应该吸烟。这就是显而易见的社会规范。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2.&nbsp;&nbsp; 描述那些违背规范的人具备什么特质，或要付出什么代价。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（预防性讲解）这时候小伙伴一定会问：如果我找不到社会规范怎么办？或者这根本不是社会规范，只是我们内部的一些规定，我还要用这个方法么？这时，你就先告诉对方规范是什么，或者大家通常怎么做。\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>3.&nbsp;&nbsp; \u003cstrong>要注意措辞\u003c/strong>，不要让对方感觉你是在威胁他。\u003c/p>\u003cp>\u003cstrong>（预防性讲解）小伙伴会质疑：我怎么觉得反着说服别人，会有咄咄逼人的感觉啊？那是因为这个技能是有适用范围的。适用范围是“很熟的人和不熟的人”\u003c/strong>\u003cbr>\u003c/p>\u003cp>很熟的人包括你的爸妈、爱人、孩子，他们不会对你有太多的芥蒂，如果你在反着说服对方的时候再带着点玩笑的口吻，就更好了。例如老爸又当着大家的面儿抽烟了，你可以说：公共场所抽烟的人真是不厚道啊！北京今天PM2.5,40，我往你身边一站，400！！\u003c/p>\u003cp>不熟的人就包括偶遇的陌生人，或者打着官腔的工作场合。例如：如果你想让新来的同事注意文件及时销毁，你就可以这样告诉他：咱们公司要求所有文件作废后必须销毁，万一被上级部门查到，会对全组通报批评的。\u003c/p>","interaction":"\u003cp>请大家跟我一起想想最近这两周你有没有试图说服别人而不见效果的情况，上下班的时候有没有遇到一些不遵守公共秩序的路人？工作中有没有遇到一些不按照规范操作的同事？或者你的爸妈，孩子，有没有忍不住跟他们唠叨的情况呢？当时的情形是怎样的呢？如果再给你一次机会，按照刚才的几个步骤，你会怎么说服对方呢？\u003c/p>\u003cp>给大家5分钟的时间，在小组内分享一下自己的失败案例，并且尝试用刚才的方法想想,再给你一次机会，你会怎么说会？之后我会请小伙伴来分享。\u003c/p>\u003cp>分享者一：爸爸做了心脏搭桥，需要避免熬夜，我跟他说：你没有机会再搭桥了，熬夜对身体不好啊，反复说，他虽然说：好好好，但是有时候还是不能避免\u003c/p>\u003cp>拆书家回应：如果我们反着说：如果你再不注意休息，再次住院的话，不只是对你自己不好，我也要请假，陪床，对我也会有很大的影响，作为父亲，他出于对子女的爱，会更加注意自己的身体。\u003c/p>\u003cp>分享者二：高铁上有人带小孩的乘客放动画片声音非常大，旁边的小伙子说：阿姨能不能声音小一点，您影响到我休息了。阿姨反驳：关你什么事啊，就不听，小伙子只能拿出ipad吧声音放的更大。\u003c/p>\u003cp>拆书家回应：对方是知道他的行为是违背社会规范的，这个小伙子在描述代价的时候还说的不够严重和深刻，如果从反着说：你这样的话，我们整个车厢都休息不好，对方就可能有所收敛。\u003c/p>\u003cp>\u003cstrong>过渡：（1分钟）\u003c/strong>\u003c/p>\u003cp>通过学习这个片段，大家是不是发现转换一种说服别人的角度，不仅能够更轻松的达到效果，还能避免让对方觉得自己是个唠叨的老太婆。\u003c/p>\u003cp>那么如果你的说服成功了，对方答应了你会如何如何做，你要怎么敦促对方遵守他的承诺，并且坚持下去呢？让我们来学习第二个套路。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":4702,"quote":"\u003cp>\u003cstrong>片段二：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习目标：通过片段学习，让学习者学会敦促别人遵守承诺并坚持下去的方法。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>R\u003c/strong>\u003cstrong>，请大家阅读我复印好的原书拆页（1分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【主题】如何敦促别人遵守承诺并坚持下去\u003c/strong>\u003c/p>\u003cp>要是把所有爽约事件的成本累加在一起，那数目能让人膛目结舌。的确有一些说服方法可以让人如约前来，说得更广些就是遵守承诺。你只需对原来的做法做出几个小小的、无需成本的改动，就可以获得相当惊人的效果。\u003c/p>\u003cp>社会影响的基本原理之一就是承诺和一致性之间的关系。这个原理说的是，咱们绝大多数人都有跟自己许下的承诺保持一致的强烈愿望，如果这个承诺是我们主动做出的、需要我们花力气参与而且被公之于众的，那就更是如此。\u003c/p>\u003cp>事实上，在兑现承诺这件事上，还有两点也很关键：这个承诺是否以行动为导向；该组织或个人做承诺时的公开程度如何。\u003c/p>","explains":"\u003cp>\u003cstrong>原文例子：\u003c/strong>举个例子，研究者曾扮成海滩游客，把一条浴巾和一个收音机放在某个正在晒太阳的人身旁，然后下海去游泳。一种情况下，研究者会请那位晒太阳的人(其实是受试对象)帮忙照看一下收音机。绝大多数人都同意了，并且很友善地做出了口头承诺:“没问题。”第二种情况下，研究者没有请晒太阳的人照看物品就径直游泳去了。此时，真正的实验开始了。另一个研究人员假扮成顺手牵羊的小贼，跑过来一把抓起收音机就跑。获得对方口头承诺的小小举动对结果(瞧见这一幕的晒太阳的人是否会起身去追)造成了巨大影响。在研究者没有要求口头承诺的情况下，20个人里只有4人阻止;在研究者提出请求的情况下，20个人里有19个都采取了行动。为什么?因为他们已经答应要遵守承诺，起身追小偷是完全符合刚才那个口头承诺的。\u003c/p>\u003cp>\u003cstrong>（意译实例）湖南卫视曾经有一档恶搞路人的节目，其中一期就恶搞了那些围在广场四周，看大妈跳舞的大爷们， 漂亮的女编导会把自己的橘红色的外套脱下来放在大爷身边，示意他们帮忙看着，然后上场去跟着大妈一起跳，跳了一阵之后，会有穿着一身绿西装的男编导从旁边路过，穿上橘红色的女式外套穿上转身就走，看大爷和其他路人的反应。几组镜头下来，大家会发现这样一个神奇的细节，如果女编导跟大爷说一句：麻烦您帮我看一下，大爷回应了，那么当有人来拿走外套的时候大爷一定会奋不顾身的追出去，而那些只是默默的把外套放在大爷身边的情况，大爷一般不会管这个闲事。\u003c/strong>\u003c/p>\u003cp>这就是这个片段主要阐述的核心技巧：想让对方履行承诺，就要让他口头答应下来。\u003c/p>\u003cp>可能大家会觉得这个技巧太简单，其实这里暗藏了强大的心理暗示：绝大多数人都有跟自己许下的承诺保持一致的强烈愿望，所以当大爷口头承诺了会帮忙看着外套，则无异于在内心强化了愿望，把责任担当起来，他自己就会不自觉的去执行承诺。\u003c/p>\u003cp>粗看这个技巧简单，也似乎不那么有效，是因为这个技巧还有一些补充技能没有开启。它包括了以下几个步骤：\u003c/p>\u003cp>1.&nbsp;&nbsp; \u003cstrong>让对方口头、笔头做出承诺。\u003cbr> \u003c/strong>\u003cstrong>(预防性讲解)有人问，怎么笔头，写个保证书？当然不是。例如一些国际知名企业在给客户发邮件时，除了使用电子邮件中“已读回执”这个功能之外，还要请对方回复一封邮件，哪怕只有两个字：好的或者收到，这就是一种笔头承诺。\u003c/strong>\u003c/p>\u003cp>2.&nbsp;&nbsp; \u003cstrong>把承诺说的再是明确且具体一些，\u003c/strong>不要出现含糊的承诺。例如现在很多人吐槽说大家每次寒暄都会说：有时间咱们聚聚啊，结果就是永远也不会聚。如果我们马上确定了聚会是具体时间，会更有效。\u003c/p>\u003cp>3.&nbsp;&nbsp; \u003cstrong>尽量把这个承诺公开。\u003c/strong>想想为什么有些微课或者活动你报了名之后会要求你把报名连接转发朋友圈？除了起到宣传作用之外，也是要敦促你来参加活动。\u003cstrong>(预防性讲解)有的小伙伴会问：让对方公开是不是在要求别人，很难实现。其实这里的公开不只是对方主动的到处宣扬，也可以是在公共场合做出这个承诺，例如：你的老公或老婆励志要开始运动减肥，你就鼓励他加入一些打卡健身的组织；也可以在朋友聚会上主动引导他说起自己减肥的承诺。\u003c/strong>\u003c/p>\u003cp>1) \u003cstrong>承诺公开还可以这样：在实践该承诺的环境中，放置一个“提示”，\u003c/strong>你会发现这个提示不仅仅让对方履行了之前具体的承诺，往往还会引发一些与承诺相关的行为。想想那些酒店里放置的环保提示牌：如果您的床单需要更换，请将这张卡片放在枕头上。是不是每次也看到这个，你也会注意减少要求更换浴巾的次数呢？\u003cstrong>这个方法对于需要坚持的承诺非常有效。\u003c/strong>\u003c/p>\u003cp>2) \u003cstrong>而且承诺一旦公开，你就可以给对方一些奖励，以保持对方的积极性。\u003c/strong>大家都还记得小时候每周发给表现好的小朋友的小红花吧。就是这个道理。\u003c/p>","interaction":"\u003cp>\u003cstrong>A2\u003c/strong>\u003c/p>\u003cp>\u003cstrong>催化步骤一：\u003c/strong>请大家想想在今后的一周，或者过年期间，你有没有想要敦促别人遵守承诺的情况呢？比如你的上司曾经说过年前不会再让你加班了，你如何提示他呢？你的孩子答应在过年前把寒假作业提前完成，你如何敦促他呢？\u003c/p>\u003cp>下面给大家1分钟时间，在原文的空白处写下一个自己想要敦促别人遵守的承诺，然后我想请小伙伴来给大家做个简短的分享。\u003c/p>\u003cp>分享者一：准备敦促老公，今年办理一张健身卡，认真健身。\u003c/p>\u003cp>分享者二：敦促好朋友，尽快把公开课做出来，在3月初，要做分享。\u003c/p>\u003cp>\u003cstrong>催化步骤二：\u003c/strong>好，小伙伴说出了自己的想法，我再重述一下刚刚我们学习的这5个步骤：口头笔头承诺、把承诺阐述的具体一些、公开这个承诺、在承诺的环境中放置一个提示、给点奖励。\u003c/p>\u003cp>按照这5个步骤，你会如何敦促对方遵守他的承诺，并坚持下去呢？给大家6分钟时间，在组内分享一下自己想要怎么做。然后我会请小伙伴做分享。\u003c/p>\u003cp>分享者一：敦促我在北京上学的表弟上心学习，提高他的学习动力，给他压力。我的做法：\u003c/p>\u003cp>1.&nbsp;&nbsp; 帮助表弟交学费，表弟承诺毕业之后每月还500元学费，要求表弟把保证书写在交学费的收据后面。希望表弟有意识找工作，养活自己。\u003c/p>\u003cp>2.&nbsp;&nbsp; 在公开场合还要再提示他一下\u003c/p>\u003cp>3.&nbsp;&nbsp; 奖励还没想好，如果他能做到前面的几部，奖励他自己能收获到。\u003c/p>\u003cp>分享者二：家里小孩上幼儿园大班，马上要上学了，要敦促他按时睡觉，才能早起。从二月中旬就准备开始做，养成晚上早睡，早上早起的行为习惯。\u003c/p>\u003cp>1.&nbsp;&nbsp; 先跟他讨论，晚上几点睡，让他自己确定自己睡前的时间安排\u003c/p>\u003cp>2.&nbsp;&nbsp; 把时间安排图示化，画一个钟，每个时间段都写清楚。挂在客厅和小卧室\u003c/p>\u003cp>3.&nbsp;&nbsp; 可以在家庭成员面前进行公开讨论。\u003c/p>\u003cp>4.&nbsp;&nbsp; 有别的小朋友来家里，可以把自己小孩的这个安排说给别的小朋友听。或者去别的小朋友家玩儿的时候，也可以分享给别的小朋友。借助小朋友的比较和交流来敦促他。\u003c/p>\u003cp>5.&nbsp;&nbsp; 晚上要睡觉前，有个倒计时，让他自己有意识要睡觉了\u003c/p>\u003cp>6.&nbsp;&nbsp; 奖励就是如果做到了，就抱一抱，举一举，多一些精神奖励\u003c/p>\u003cp>现在大家是不是觉得敦促对方遵守他们的承诺，变成了一个有条理的事情。\u003c/p>\u003cp>接下来，咱们来学以致用一下，请大家以小组为单位，从下面给出的3个场景中选择一个你感兴趣的场景，讨论一下怎么说服对方，然后怎么敦促对方遵守承诺，要应用到刚刚我们所学的步骤，给出一个解决方案。待会我会请小伙伴来讲述你们的解决方案，或者请组内小伙伴一起分头扮演场景中的两个人物，把解决方案表演出来。给大家6分钟的时间。\u003c/p>\u003cp>\u003cstrong>场景一：\u003c/strong>\u003c/p>\u003cp>马上要过年了，年前王美丽会比较忙，所以她想让他老公（王大锤）在除夕前先把玻璃擦干净或者把厨房清理干净，减少集中打扫卫生的时间，王美丽会怎么说，怎么做呢？\u003c/p>\u003cp>人物：老婆王美丽、老公王大锤\u003c/p>\u003cp>\u003cstrong>场景二：\u003c/strong>\u003c/p>\u003cp>作为财务部门的负责人，王美丽想让其余部门员工尽量在每个月月底前把报销单据整理好，算出总数，再上交给她。尤其是出差较多的市场部主管王大锤，王美丽会怎么说，怎么做呢？\u003c/p>\u003cp>人物：财务部王美丽、市场部老公王大锤\u003c/p>\u003cp>\u003cstrong>场景三：\u003c/strong>\u003c/p>\u003cp>王美丽的孩子（王小宝）刚上一年级，她想敦促小宝每天晚上睡前把自己的小书包收拾好，这样才不会在第二天一早慌慌张张忘带东西。王美丽会怎么说，怎么做呢？\u003c/p>\u003cp>人物：妈妈王美丽、儿子王小宝\u003c/p>\u003cp>分享者（场景一）：\u003c/p>\u003cp>说服：可以跟老公说：要过年了，按照年俗要做打扫，要是不打扫，节后有人来家里玩看到环境这么脏，差，让他想想这个后果，让他从意愿上接受打扫这个行动。\u003c/p>\u003cp>敦促：跟老公商量，表示知道他年前很忙，让他自己确定什么时候做清扫工作。让老公自己做一个口头承诺，比如他答应大年29才能做，这就比较明确。之后在大年26,27时候，家里吃饭的时候给他一个公开的提示，提醒他29号还有家务要做。如果他能按时完成，就给她一个拥抱奖励或者小礼物做奖励。\u003c/p>\u003cp>拆书家回应：小伙伴分享的非常棒。我们回看这些敦促的步骤，如果我们不把他们梳理出来，可能没有这么的清晰。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>总结（\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>分钟\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>我来总结一下今天学习的内容。\u003c/p>\u003cp>首先，我们学习了说服别人有效又不唠叨的技巧，我总结为三个字：\u003cstrong>反着说！\u003c/strong>\u003c/p>\u003cp>其次，当别人承诺了他会做某事，我们可以通过几个步骤来敦促他遵守承诺并坚持下去。我把这几个步骤总结为两句诗：\u003cstrong>两头一具体，公开得奖励！\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1488347320000,"updated_at":1488347320000,"ria":true},{"id":1975,"topic":"潜质的说服力","learn_goal":"学习运用潜质的说服力说服他人","remark":"","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"洋洋得意","city":"重庆市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"各位小伙伴，大家好，我是二级拆书家阳义，这次拆书的学习目标是在跟随我完成RIA的现场学习后，学习者能够使用潜质的说服力来说服他人。","ratings_count":0,"texts":[{"id":4590,"quote":"\u003cp>【图书介绍】2分钟\u003cbr>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>事件场景：\u003c/strong>我们在工作中经常会面临需要说服他人的任务，例如：你希望说服新的客户和你达成交易，或者希望在招聘面试或者升职选拔中说服面试官脱颖而出，或者你希望说服你的上司同意你的提议和方案。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003cstrong>提问：\u003c/strong>这个时候你要做什么才能更有效地说服他人呢？有哪些方法可以帮助我们提高说服的成功率呢？&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>如果我们没有办法更好地说服他人，我们在工作和生活中都将失去很多机会，这将直接影响我们能否顺利实现我们的职场目标和生活目标。&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>《细节》这本书告诉了我们经过大量调查研究发现的说服他人的50多个有效的心理学规律，运用这些规律我们只需要做一些细节上的调整就可以成倍的提高我们说服他人的成功率，实现轻松影响他人。\u003c/p>\u003cp>【R】阅读拆页 2分钟\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003cp>【I】引导促进 4分钟\u003cbr>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>这个拆页我们看到了一个心理学现象，潜质的说服力胜过现实，也就说是说你在说服他人，推销自己想法的时候，讲将来能够得到的好处比讲过去的经验更容易说服对方。这主要是因为过去的经验是确定的，而未来的潜质是不确定的，而心理学研究表明人们往往对不确定的东西更感兴趣。\u003c/p>\u003cp>\u003cstrong>【举例对比讲解概念】\u003c/strong>按照这个原理，是不是说没有工作经验的人在找工作的时候只用讲他将来能够做好这份工作就可以胜过有经验的应聘者？现实显然并非如此。在说服他人的时候，潜质的内容不是仅仅包括单纯的好处，还包括支撑潜质发挥作用的证据。我们没有工作经验的应聘者之所以很难找工作，是因为他们往往没办法去提供足够的证据来说明他干这个工作给雇主带来的好处。也就是没有提供完整的潜质。我们拆页里举例的没有管理经验的应聘者能胜过有管理经验的应聘者，就是因为他提供了一份让人信服的领导力潜力评估报告，这份报告说明了他具备管理潜质，支撑了他胜任岗位的潜质，所以潜质的说服力充分发挥了出来。【\u003cstrong>明确适用边界】\u003c/strong>其实这个拆页所指的潜质的说服力要发挥作用是有适用条件的，关键在于要讲的潜质必须能提供有足够证据做支撑。\u003cstrong>【给出HOW】\u003c/strong>所以要使这个心理学规律发挥作用，我们需要把握两个细节：第一，对于找得到现实经验的人来讲，在推销自己想法的时候，要先讲潜质，再讲经验，不能只强调经验，不讲潜质。在拆页中我们有管理经验的应聘者只提供了过去的领导力成就报告，而没有提供领导力潜质报告，也就是他只讲了经验，没有提潜质，所以没有能够引起他人的重视。第二，对于找不到现实经验的人来讲，在推销自己的想法时候，就要把重点放在未来能给对方带来的好处上，并且在提出将来能够带来的好处后，要立即提供支撑这个好处实现的依据，例如：类似的经验、相关的经验、相关的证据或者评估报告等等。举个例子，如果你要说服你的老板同意你开展一项工作，如果这项工作过去已经开展过，你在推销的时候，要先讲开展这项工作会带来的好处，再讲这项工作过去已经产生的效益，不能只讲这项工作过去产生的好处，这样比只讲经验更有说服力。如果这项工作过去没有开展过，你在推销的时候，要把重点放在这项工作将来能带来的好处上，并且要提供支持这个好处的证据，例如类似企业的做法、相关的报告等等。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003cp>【A2】催化运用 10分钟\u003cbr>\u003c/p>\u003cp>拆书家提问设计：刚才我们学习了如何运用潜质的说服力在来说服他人，现在大家想一想，在接下来的工作或生活中，你会遇到哪些需要说服他人，推销自己的情况，例如说服他人采纳自己的建议，推销自己的业务、竞争一个岗位。在这种情况下，我们怎么样来运用潜质的说服力来说服他人。大家可以两个人为一组，相互演练一下。然后把要完成的说服任务、对话双方的人物身份、预计的对话过程、当时的动作、预计会出现的结果这些内容写成提纲记在便签上，形成一个有起因、经过、结果的小故事，也就是你在什么情况下要说服他人，是怎么说的，当时的对话过程，以及对话的结果，每个人是5分钟，写完后，我们请一位小伙伴来和大家分享一下他的故事。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>代宝：我要说服一位朋友小李加入拆书帮，我和他开展了对话，小李开始说：你喜欢的东西我未必喜欢，而且我平时也没有时间看书。我说：你加入拆书帮后能在很短的时间看到很多不同的书，而且还能交到很多好朋友，像我啊，从30拆开始，起码接触到了30多本书的精华内容吧，还交到了很多很好的朋友，交际圈扩大了很多。小李听了后就很兴奋了，就说：那我下次也跟你去看看吧“。我就是先讲的好处，吸引他的注意力，然后提供经验佐证，通过强调潜质说服了小李。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1487417018000,"updated_at":1487417573000,"ria":true},{"id":1972,"topic":"峰终效应","learn_goal":"学会创造峰点，找到并放大","remark":"","level":"TF3-2","duration":25,"status":0,"type":0,"chaishujia":{"username":"洋洋得意","city":"重庆市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是二级拆书家阳义，今天的学习目标是在跟随我完成RIA的现场学习后，学习者能够运用“峰终体验”原理来设计提升满意度的经历","ratings_count":0,"texts":[{"id":4587,"quote":"\u003cp>【图书介绍】2分钟\u003cbr>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>事件场景：\u003c/strong>在与他人打交道的过程中，我们都希望他人对我们所做的事情有好的印象，例如我们为客户提供了一次服务，或者组织朋友们开展一次聚会活动 &nbsp; ，我们都希望所提供的服务或者组织的这一次聚会，他人能有一个满意的评价。&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>除了认真准备，精心策划之外，有没有一些技巧能帮助我们提高他们的满意度呢？&nbsp; 在提升他人满意度方面有没有一些关键的诀窍呢？&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>如果让他人觉得我们所做的事情不靠谱，不仅影响到对我们工作成果的评价，而且也会直接影响到他人对我们个人的评价，甚至影响我们的职业发展和人生道路。&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>这本书告诉了我们经过大量调查研究发现的52个心理学规律，很多心理学规律都是诺贝尔奖的研究成果。运用这些规律我们只需要做一些细节上的改变，运用今天所学习拆页的内容，我们就能轻松获得更高满意度评价，给他人和给自己创造良好的体验。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【A1】请大家自测\u003cbr>\u003c/p>\u003cp>下面请大家做一下我们的自测题，根据自己的实际情况为自己打分。1表示很不符合，6表示非常符合。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1.在和他人打交道过程中，我非常在乎第一印象。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2.一件事要想让他人满意，我认为每个细节都不能出错。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3.我喜欢用“非常浪费时间”向别人描述某件事情的缺点。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4.如果组织一个活动，我不会专门去设计这个活动的结尾。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5.如果一件事情不愉快的经历所占比重超过愉快的经历，我认为这件事一定不会让人满意。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【I】解释自测题 1分钟\u003cbr>\u003c/p>\u003cp>这个自测题是从不同角度测试大家对峰终效应的认识程度。5个题目如果达到15分以上，就说明你非常需要阅读一下我们的拆页。\u003c/p>\u003cp>【R】阅读拆页 2分钟\u003c/p>","explains":"\u003cp>【I】引导促进 5分钟\u003c/p>\u003cp>\u003cstrong>【简短互动】\u003c/strong>大家看了这个拆页，这个拆页有两个关键词特别重要。大家能告诉我，是哪两个关键词吗？一个是“峰终体验”，一个是“时长忽视”。“峰终体验”告诉我们，我们对一件事情是否满意只取决于这件事情两个点上的体验，一个是巅峰时刻的体验，一个是结束时刻的体验。“时长忽视”告诉我们，之所以出现“峰终体验”的现象，是因为一位诺贝尔奖的心理学家发现我们的大脑在回忆一件事的时候，不会管这件事情好与不好的比重，也不会管好与不好发生的时间长短，只会记录情绪高峰点的体验和结束点的体验。我们做事情可以从三个方面运用“峰终体验”来获得好的评价。第一步我们要创造峰点。峰点是这件事情过程中让人感觉最好的点。这个点我们需要结合他人的需求来寻找和创造，不能我们自己拍脑袋。而且针对峰点，我们要投入比其他环节更多的资源或者精力，将这个峰点的效应最大化。第二步我们要精心设计终点。终点很好找，就是事情要结束的时候。针对终点，我们要特别做一些他人喜欢的事情，让人到达终点时满意而去。第三步，如果可能的话，将峰点放在终点，也就是将最好的留到最后，就像拆页里面讲的歌手们总将最受欢迎的歌曲留到演唱会结束时。那就会营造一个完美体验了。举个例子，拿我们拆书活动举例，可以说我们现在拆书帮活动总体上是遵循了“峰终体验”这个规律的。首先寻找峰点。这个活动的峰点是什么呢？一般是学习者互动的环节。我们拆书家要争取在互动环节给予学习者更多的互动时间，并且提高互动的质量。终点是什么时候呢？我们结束的时候不是就这么结束了，我们要照相。最早我们是结束的时候要收钱，那现在我们把收钱取消了，这样在结束时就给了大家一个很好的感觉。\u003c/p>","interaction":"\u003cp>【A3情景演练】 10分钟\u003cbr>\u003c/p>\u003cp>拆书家提问设计：大家已经学习了“峰终体验”的概念。现在给大家一个场景，请大家以小组为单位演练一下。场景是这样的，假设你的老板给了你一个任务，给了你一笔经费，要求你在工作之外，接待好一位贵宾，这位贵宾是喜欢美食还有旅游的。你怎么运用峰终体验来让这位外宾满意而归？请大家先小组讨论出一个方案。这个方案要包括你们对峰点和终点的安排，安排要有一些细节说明，以及你们这么安排的原因，时间是5分钟。然后我们请一个小组分享一下他们的方案设计。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>Shirley组：首先我们设计峰点。我们的峰点有2个。一个是接机，我们会派美女、鲜花接机，会有很好的体验，第二个是我们会安排两江游船上观重庆夜景，吃重庆火锅，既有美景又有美食，这会成为最大的峰点。其次我们设计一个终点，我们在客户离开时会送他一个光盘，光盘中会有在重庆期间全程的录影经常片段剪辑，这样就将峰点在终点重放了一遍。相信能创造一个不一样的终点。通过峰终点的设置实现一个完美的接待。\u003c/p>\u003cp>【A2催化未来运用】1分钟\u003c/p>\u003cp>拆书家提问设计：“峰终体验”不仅可以运用于提升他人的满意度，也可以提升我们自己的体验，让自己的工作、生活、学习都有更满意的体验。请小伙伴们想一想，选择一项自己的事情或者和他人打交道的一件事情，运用峰终体验改进一下这件事情带来的体验。想好后写在便笺上交给我。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>【学习者案例记录】\u003c/p>\u003cp>书静：周末提升体验，设计峰点是外出欣赏美景，终点是聚餐后结束。\u003c/p>\u003cp>林莉：下次带孩子出去过生日，峰点是玩她喜欢的东西，终点是结束时送她一个礼物。\u003c/p>\u003cp>代宝：下次拆书在结束时讲个笑话或者发吃的，把终点体验搞好。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1487400519000,"updated_at":1487400519000,"ria":true},{"id":1892,"topic":"如何才能化干戈为玉帛","learn_goal":"学习者能破解在和自己立场不一样或者处于对立的关系人的合作","remark":"","level":"TF3-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"王小琦","city":""},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"欢迎大家来参加我3-1的分享。先跟大家介绍一下我自己：我叫王小琦，现在在一家互联网创业公司做开发兼产品。我给自己的三个标签是逆生长，分享达人，电子书达人。【目的】我要分享的主题是如何化干戈为玉帛。我这次分享的目的是为了通过分享让学习者能解决在和自己立场不一样或者处于对立的关系的人合作的时候出现僵局的问题。【介绍图书】我分享的这个主题出自《细节》这本书，我为什么要分享这本书呢？ 场景：我们在平时总会遇到一些困扰，比如你要和一些跟你很不一样的人或者是你的竞争对手合作，或者你发起的一些聚会或者讨论什么，总是有人放你鸽子\r\n提问：遇到这些事情我们是怎么处理的呢？\r\n影响：这些事情看起来好像不是那么重要，但实际上如果处理不好，非常影响我们和其他人的关系，以及削弱我们的影响力\r\n解决：而《细节》这本书就提供了很多的上手快成本低的方法帮助我们在这些场景中通过一些细节的改变提高我们的影响力。","ratings_count":0,"texts":[{"id":4497,"quote":"\u003cp>对抗与竞争是体育运动的常态。差不多每个球迷都有这种体会，那种对抗的感觉势同水火，而且代代相传。\u003c/p>\u003cp>如果双方的对抗达到了这种程度，那很难想想他们会愿意在任何事情上展开合作。但是，英国心理学家马克。莱文所做的出色研究表明，即使是在最为极端的情况下，依然有些东西把我们联接在一起，而不是分开。\u003c/p>\u003cp>莱文先请一群英国足球迷---刚好是曼联队的死忠粉---填写一张问卷，内容是写下他们喜欢曼联的哪些方面。填好问卷后，球迷需要走到校园里的另一栋楼里去，参加下一阶段的研究。往那栋楼走的路上，曼联球迷们也会看到一个慢跑的人拌了一跤，而且看上去受伤了。第一种情况下，慢跑的人穿一件没写字的白上衣；第二种情况下，他穿着一件曼联队的球衣；第三种情况下，他穿的是曼联队的死对头--利物浦队的球衣。\u003c/p>\u003cp>观察员们拿着记录板在隐蔽的地方观察，记下有多少曼联球迷会出手相助。在研究中，当慢跑者穿的是素白T恤的时候，大约三分之一的曼联球迷停下来帮忙了。当他们看到伤者穿的是曼联球衣，说明此人是他们中的一员的时候，绝大多数帮忙了。可是当慢跑者穿着死对头利物浦球衣时，停下来帮忙的曼联球迷非常少。这是一个非常有说服力的证据，说明人们最愿意帮助自己的“同类”。\u003c/p>\u003cp>让人欣慰的是，只需对情境做一个小小的改动，人们就会更加愿意敞开自己的心怀。在相同的实验中，当曼联球迷率先填写的那张问卷问的是“你为什么喜欢当个足球迷”的时候，愿意帮助穿着对手的慢跑者的人数翻了倍。\u003c/p>","explains":"\u003cp>这个拆页告诉我们什么呢？人们都是喜欢和同类交流。关于这个大家或多或少都有体会吧。我们在一个陌生的环境和陌生人聊天，我们如果想迅速跟陌生人熟悉起来会怎么做呢？一般是不是都是问一些基本的问题，比如你是哪的人啊，你平时喜欢些什么啊？从这些基本的问题中找到彼此之间有没有相似的点？是不是属于同类的人。比如在一个人生地不熟的地方突然发现对方跟自己是同一个地方的人，或者在一个大家都在用IPONE的地方突然发现他也跟你一样用锤子手机，这距离一下子就拉近了不是。所以如果能在短时间内找到属于彼此之间比较独特的，又能激起一定情感共鸣的点，就能和对方很好的沟通下去。\u003c/p>\u003cp>可有些时候，我们又容易忽略掉这个原理，特别是在一些谈判或者争论中，我们经常不自觉地把彼此对立起来，比如我们在和女生争论什么问题的时候，经常会听到这样的话：“你们这些男生是不会懂的了”。这样的话就会给对话的氛围建立了一种对立的关系。那么我们需要如何做来重新成为对方眼中的同类呢？四步骤：1.暂停对话：从当前的对立的氛围跳出来 2. 审视彼此：迅速在脑子里过一遍，看看彼此有什么共同点 3. 确定同类：找到一个相对比较独特的共同点突破 4. 引导提问：\u003c/p>\u003cp>举个我工作中的例子，我们互联网公司内部很容易出现对立的局面。比如研发部门周期性的发布版本，而运营部门持续性的反馈从用户那边过来的新需求。我作为研发部门的负责人，主要职责当然是保证产品的正常发布，而运营部门的人的想法就是既然有需求就要马上满足用户。所以就很容易对立起来。如果我们都是这么僵持下去，很容易撕逼，不利于团队和谐。那么如何做呢？我可以尝试上面四个步骤：1. 暂停对话：我一旦发现局面有点失控就要主动停下来，跟对方说暂停一下再继续 2. 审视彼此：迅速想一想我们有些什么共同点，比如：都是成都人，都喜欢小米手机，都是这个产品组的重要一员。3. 确定同类：我会发现这么多共同点里，产品组的一员这个类别更适合当前场景 4. 引导对方：我会在一个适当的时候向对方提问：小明同学，我们都是这个产品组的，那么我们都站在这个产品的角度想一想当前这个局面，这个产品最需要的是产品按时的发布，还是说要满足用户的所有需求，就算拖延发布周期也可以呢？这样通过这样一个问题让对方意识到，我和他实际上都有相同的立场和诉求，我们都希望做对产品本身来说最正确的事情。\u003c/p>","interaction":"\u003cp>那么现在请大家编写一段小故事,设计出任务、情节和当时的对话、动作等。这个小故事主要描述你和你的同事进行某方面的谈判，谈判陷入了僵局，你如何通过这四个步骤引导对方了解到你们是同类，缓和当前僵化的气氛，并形成良好的沟通的，请把摘要写在一张纸上。时间五分钟。写完后请一个小伙伴来分享一下：\u003c/p>\u003cp>分享者甲：\u003c/p>\u003cp>案例场景：销售员培训的时候，销售人员没有请假就不来参训。我跟他们的部门领导进行沟通。这种谈话很容易互相推诿陷入僵局。\u003c/p>\u003cp>采用的解决步骤：\u003c/p>\u003col>\u003cli>\u003cp>暂停对话：先把这件事情想清楚\u003c/p>\u003c/li>\u003c/ol>\u003cp>然后我就找到对方来进行沟通\u003c/p>\u003cp>【审视彼此】“你看我们都是在一个公司，这次培训对你和我都很重要，这是我的工作，对你的业绩也是有很大的影响的。”\u003c/p>\u003cp>【确定同类】“我们都是要把事情做好的人，对吧。”\u003c/p>\u003cp>【引导提问】“那么您看，如果大家都希望把这件事情做好，面对现在您的下属没有经过沟通就缺席培训这件事情，我们应该做些什么呢？”\u003c/p>\u003cp>对方领导听了后，觉得确实有做的不妥的地方，承诺我会和那位下属谈谈。这件事情也就得到妥善解决\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1485219135000,"updated_at":1485219662000,"ria":true}]};